(window.GIM_TUR_P=window.GIM_TUR_P||{})["SEH.4"]={"from":169,"s":[["\u0003הלכות חליצה\u0004\nמִצְוַת חֲלִיצָה בְּג' דַּיָּנִים יִשְׂרְאֵלִים, וְשֶׁלֹּא יִהְיוּ קְרוֹבִים זֶה לָזֶה וְלֹא לַיָּבָם וְלַיְבָמָה. \u0005 וַאֲפִלּוּ שְׁנַיִם נְשׂוּאִין שְׁתֵּי בְּנוֹת אַחִין, לֹא יִהְיוּ זֶה עִם זֶה. אֲבָל שֵׁנִי בִּשְׁלִישִׁי, כָּשֵׁר \u0006 \u0005(ת\"ה סִימָן רכ\"ו)\u0006. וַאֲפִלּוּ הֵם הֶדְיוֹטוֹת, \u0010c0\u0011 רַק שֶׁיֵּדְעוּ לְהַקְרוֹת אֶת הַיָּבָם וְהַיְבָמָה. וְאִם חָלְצָה בִּפְנֵי עַמֵּי הָאָרֶץ שֶׁאֵינָם יוֹדְעִים לְהַקְרוֹת, כְּשֵׁרָה:\nנִמְצָא אֶחָד מֵהֶם \u0010c1\u0011 קָרוֹב אוֹ פָּסוּל, אוֹ גֵּר, פָּסוּל. \u0010c2\u0011 וַאֲפִלּוּ הָיָה אָבִיו גֵּר וְאִמּוֹ יִשְׂרְאֵלִית, פָּסוּל, עַד שֶׁיְּהֵא אָבִיו וְאִמּוֹ מִיִּשְׂרָאֵל. \u0005 וְיֵשׁ אוֹמְרִים שֶׁאִם אָבִיו מִיִּשְׂרָאֵל, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. וּמִיהוּ, חֲלִיצָה פְּסוּלָה מִיהָא הָוְיָא לְפָסְלָהּ עַל הָאַחִים, אֲפִלּוּ בֵּינוֹ לְבֵינָהּ. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִקַּח שָׂכָר מֵחֲלִיצָה, דְּהַנּוֹטֵל שָׂכָר לָדוּן דִּינָיו בְּטֵלִין \u0006 \u0005(ר\"י מִינְץ וּמהרא\"י)\u0006, \u0005 וְכֵן נִרְאֶה בְּעֵינַי. בַּחֲלִיצוֹת, יֵשׁ לִזָּהֵר שֶׁלֹּא יֵשֵׁב בִּשְׁלשָׁה דַּיָּנִים שֶׁיּוֹשְׁבִים לַחֲלֹץ מִי שֶׁנּוֹטֵל שָׂכָר, דַּהֲרֵי בָּעִינָן בֵּית דִּין כָּשֵׁר מִדְּאוֹרָיְתָא, וְעַיֵּן בְּחשֶׁן הַמִּשְׁפָּט סִימָן ט' אֵיזֶה שָׂכָר מֻתָּר לַדַּיָּן לְקַבֵּל. וַאֲפִלּוּ בָּזֶה נִרְאֶה לִי לְהַחֲמִיר אִם נוֹטֵל שָׂכָר מִן הַחֲלִיצָה, מִשּׁוּם מַרְאִית הָעַיִן, כְּמוֹ שֶׁמַּחֲמִירִין לְעִנְיַן קְרוֹבִים וּבִשְׁאָר דְּבָרִים לְעִנְיַן בֵּית דִּין שֶׁל חֲלִיצָה, יוֹתֵר מִבִּשְׁאָר בֵּית דִּין. וְרָאִיתִי וְשָׁמַעְתִּי שֶׁהָרַב נוֹטֵל שָׂכָר הַרְבֵּה מִן הַחֲלִיצָה, וְסוֹמֵךְ עַצְמוֹ בַּמֶּה שֶׁמּוֹכֵר לוֹ סַנְדָּל שֶׁל חֲלִיצָה; וְקֻלָּא גְּדוֹלָה הִיא בְּעֵינַי, וְשׁוֹמֵר נַפְשׁוֹ יִרְחַק מִזֶּה. וְלֹא דָּמֵי לְמַה שֶּׁעֵדֵי הַגֵּט נוֹטְלִין שָׂכָר מִטַּעַם שֶׁכָּתַבְתִּי לְעֵיל סִימָן ק\"ל, גַּם הָרַב הַמְסַדֵּר הַגֵּט כְּמוֹ שֶׁכָּתַבְתִּי לְעֵיל בְּסֵדֶר הַגֵּט סָעִיף ד', כִּי אוֹתָן הַטְּעָמִים אֵינָם שַׁיָּכִים בַּחֲלִיצָה \u0006 \u0005(הַכֹּל \u0010c3\u0011 דַּעַת עַצְמוֹ)\u0006:\nלְכַתְּחִלָּה מִצְוָה שֶׁיּוֹסִיפוּ שְׁנַיִם עַל הַג', וַאֲפִלּוּ הַשְּׁנַיִם הֵם עַמֵּי הָאָרֶץ. \u0005 חָלְצוּ בְּג' חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0005 וְאֵלּוּ הַשְּׁנַיִם שֶׁמּוֹסִיפִים, לֹא יִהְיוּ קְרוֹבִים \u0006 \u0005 וּפְסוּלִים; וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד כָּשֵׁר \u0006 \u0005(ב\"י)\u0006:\nצְרִיכִים \u0010c4\u0011 הַדַּיָּנִים לְכַתְּחִלָּה לִקְבֹּעַ מָקוֹם לוֹמַר: נֵלֵךְ לִמְקוֹם פְּלוֹנִי לַחֲלֹץ. \u0005 מִיהוּ, אִם חָלְצָה בְּלֹא קְבִיעוּת מָקוֹם, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006:\nיֵשׁ קֹבְעִים מָקוֹם בּוֹ בַּיּוֹם, וְיֵשׁ אוֹמְרִים לִקְבֹּעַ בַּיּוֹם שֶׁלְּפָנָיו:\nאֵין חֲלִיצָה כְּשֵׁרָה אֶלָּא בַּיּוֹם. חָלְצָה בַּלַּיְלָה, חֲלִיצָתָהּ פְּסוּלָה:\nאֵין חוֹלְצִין בְּשַׁבָּתוֹת וְלֹא בְּיָמִים טוֹבִים; וּמִיהוּ, בְּחֹל הַמּוֹעֵד, שַׁפִּיר דָּמֵי. \u0005 וְיֵשׁ אוֹמְרִים דְּאֵין לַחֲלֹץ בְּעֶרֶב שַׁבָּת וְעֶרֶב יוֹם טוֹב, וְכֵן נוֹהֲגִין: \u0006\nצָרִיךְ שֶׁיַּכִּירוּ שֶׁהוּא אֲחִי הַמֵּת, וְשֶׁהָיָה בְּעוֹלָמוֹ, וְזֹאת הִיא אֵשֶׁת הַמֵּת; וַאֲפִלּוּ אֵין כָּאן אֶלָּא עֵד אֶחָד שֶׁמֵּעִיד עֲלֵיהֶם, אוֹ אֲפִלּוּ קָרוֹב אוֹ אִשָּׁה אוֹ עֶבֶד אוֹ שִׁפְחָה אוֹ קָטָן שֶׁהוּא מַכִּיר וְנָבוֹן, נֶאֱמָן בְּכָךְ:\nצָרִיךְ שֶׁיֵּדְעוּ הַדַּיָּנִים שֶׁיֵּשׁ צ' יוֹם מִשֶּׁמֵּת הַבַּעַל, חוּץ מִיּוֹם שֶׁמֵּת בּוֹ וְיוֹם שֶׁחוֹלֶצֶת בּוֹ:\nצָרִיךְ שֶׁיֵּדְעוּ שֶׁהַיָּבָם \u0010c5\u0011 בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, וְהַיְבָמָה בַּת י\"ב שָׁנָה וְיוֹם אֶחָד, וְשֶׁהֵבִיאוּ שְׁתֵּי שְׂעָרוֹת אַחַר שֶׁהִגִּיעוּ לִזְמַנִּים אֵלּוּ. וְאִם יֵשׁ לַיְבָמָה \u0010c6\u0011 דַּדִּים גְּדוֹלִים, אֵין צָרִיךְ לִבְדֹּק אַחַר הַשְּׂעָרוֹת. וְכֵן אִם הַיָּבָם \u0010c7\u0011 נִתְמַלֵּא זְקָנוֹ, אֵין צָרִיךְ לִבְדֹּק אַחַר הַשְּׂעָרוֹת. וּמִשְׁפָּט שְׁתֵּי הַשְּׂעָרוֹת וּבְדִיקָתָן, נִתְבָּאֵר בְּסִימָן קנ\"ה \u0005(סָעִיף ט\"ו)\u0006:\nאֵין סוֹמְכִין בְּמִנְיַן הַשָּׁנִים לֹא עַל פִּי קְרוֹבִים וְלֹא עַל פִּי נָשִׁים, אֶלָּא עַל פִּי עֵדִים כְּשֵׁרִים לְהָעִיד. \u0010c8\u0011 וְיֵשׁ אוֹמְרִים שֶׁאִם הֻחְזַק בְּעֵינֵי הַשְּׁכֵנִים, שֶׁלֹּא עַל פִּי הָאָב, שֶׁבָּא לִכְלַל שָׁנִים, אוֹ שֶׁיָּצָא עָלָיו קוֹל שֶׁבָּא לִכְלַל שָׁנִים, נֶאֱמָנִים לְהַחֲזִיקָן בִּגְדוֹלִים, אִם בְּדָקוּם וּמָצְאוּ לָהֶם שְׁתֵּי שְׂעָרוֹת, \u0005 אֲבָל לֹא מְהַנֵּי שֶׁרָאוּ אוֹתוֹ שֶׁעָלָה לְסֵפֶר תּוֹרָה אוֹ שֶׁהָיָה שְׁלִיחַ צִבּוּר \u0006 \u0005(מָרְדְּכַי פֶּרֶק מִצְוַת חֲלִיצָה)\u0006. וַאֲפִלּוּ בְּלֹא חֶזְקַת הַשְּׁכֵנִים, אִם יֵשׁ לָהֶם רִבּוּי שְׂעָרוֹת, אוֹ שֶׁהֵם אֲרֻכּוֹת כְּמוֹ שֶׁרְגִילוֹת לְאִישׁ גָּדוֹל וּלְאִשָּׁה גְּדוֹלָה, חֲזָקָה שֶׁבָּאוּ לִכְלַל שָׁנִים, וְחוֹלְצִים. \u0010c9\u0011 וְעַל זֶה סוֹמְכִים שֶׁלֹּא לִבְדֹּק אִם יֵשׁ גֻּמּוֹת בַּשְּׂעָרוֹת, מֵאַחַר שֶׁיֵּשׁ רִבּוּי שְׂעָרוֹת אוֹ שֶׁהֵם אֲרֻכּוֹת. וְאִם הֵם גְּדוֹלִים בְּקוֹמָה, יֵשׁ לִסְמֹךְ שֶׁהֵם גְּדוֹלִים, אֲפִלּוּ לֹא הֵבִיאוּ כִּי אִם שְׁתֵּי שְׂעָרוֹת. \u0010c10\u0011 \u0005 וְאִם יֵשׁ לַיְבָמָה בָּנִים, הֲרֵי הֵם כְּסִימָנִים \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּיבָמוֹת)\u0006:\nיֵשְׁבוּ הַדַּיָּנִים כְּמוֹ שֶׁצְּרִיכִים לֵישֵׁב בְּדִין, וְיַעַמְדוּ לִפְנֵיהֶם הַיָּבָם וְהַיְבָמָה, \u0010c11\u0011 שֶׁמִּצְוַת חֲלִיצָה לְכַתְּחִלָּה, מְעֻמָּד. \u0005 הַגָּה: אֲבָל בְּדִיעֲבַד, אִם חָלְצָה מְיֻשָּׁב, כָּשֵׁר (טוּר)\u0006. וְכֵן חוֹלֶה שֶׁלֹּא יוּכַל לַעֲמֹד, יוּכַל לַחֲלֹץ מְיֻשָּׁב, דְּכָל דָּבָר שֶׁאֵין לוֹ תַּקָּנָה חָשׁוּב דִּיעֲבַד \u0005(פִּסְקֵי מהרא\"י סִימָן ק\"צ)\u0006. \u0005 וְעַיֵּן לְקַמָּן סָעִיף ס\"ד בְּפֵרוּשׁ סֵדֶר חֲלִיצָה: \u0006\nמֵאַחַר שֶׁמַּסְכִּים הַיָּבָם לַחֲלֹץ, יֹאמְרוּ לוֹ לְבַטֵּל כָּל מוֹדָעוֹת שֶׁמָּסַר, כְּמוֹ גַּבֵּי גֵּט; שֶׁאִם מָסַר מוֹדָעָא תְּחִלָּה, הַחֲלִיצָה פְּסוּלָה. \u0005 הַגָּה: וְכֵן אִם כָּפוּ אוֹתוֹ לַחֲלֹץ, דִּינוֹ כְּמוֹ בְּגֵט. וְעַיֵּן לְעֵיל סִימָן קל\"ד. וְאַף עַל גַּב דְּיֵשׁ אוֹמְרִים מִצְוַת חֲלִיצָה קוֹדֵם, וְאִם כֵּן כָּל כְּפִיָּה הִיא בַּדִּין, מִכָּל מָקוֹם אֵין לָכֹף אֶלָּא בְּמָקוֹם שֶׁנִּתְבָּאֵר סִימָן קס\"ה: \u0006\nלְכַתְּחִלָּה צָרִיךְ לָתֵת לַיָּבָם מִנְעַל הַחֲלִיצָה בְּמַתָּנָה. וְיֵשׁ אוֹמְרִים שֶׁיְּהַלֵּךְ בּוֹ מְעַט, כְּדֵי שֶׁיְּהֵא נִרְאֶה כְּשֶׁלּוֹ. \u0005 וְאִם לֹא נָתְנוּ לוֹ, כָּשֵׁר \u0006 \u0005(טוּר)\u0006:\nהַמִּנְעָל צָרִיךְ שֶׁיִּהְיֶה כֻּלּוֹ שֶׁל עוֹר. לְפִיכָךְ, צָרִיךְ לְתָפְרוֹ \u0005 כָּל תְּפִירוֹתָיו \u0006 בְּעוֹר לְכַתְּחִלָּה. \u0005 וְכֵן נוֹהֲגִין; \u0010c12\u0011 וְיֵשׁ פּוֹסְלִין אַף בְּדִיעֲבַד \u0006 \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006. \u0005 דְּלֹא כְּיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה שֶׁכָּל הַמִּנְעָלִים תְּפוּרִין בְּפִשְׁתָּן צָרִיךְ לִהְיוֹת תָּפוּר בְּפִשְׁתָּן \u0006 \u0005(בְּסֵדֶר ר\"י מִינְץ בְּשֵׁם ר' שְׁמַרְיָה)\u0006. \u0010c13\u0011 אֲבָל רְצוּעוֹתָיו אֵין צָרִיךְ שֶׁיִּהְיוּ מֵעוֹר. \u0005 וְיֵשׁ אוֹמְרִים דְּגַם רְצוּעוֹתָיו מֵעוֹר \u0006 \u0005(נִמּוּקֵי יוֹסֵף)\u0006, \u0005 וְכֵן \u0006 \u0005 נוֹהֲגִין: \u0010c14\u0011 \u0006\nצָרִיךְ לְכַתְּחִלָּה שֶׁיְּהֵא הָעוֹר קָשֶׁה קְצָת, שֶׁיְּהֵא דּוֹמֶה קְצָת לְסַנְדָּל. וְיֵשׁ אוֹמְרִים שֶׁהַתְּפִירָה תִּהְיֶה מִבַּחוּץ. יֵשׁ אוֹמְרִים מִבִּפְנִים, כְּדֵי שֶׁיְּהֵא דּוֹמֶה לְסַנְדָּל. וְיֵשׁ אוֹמְרִים שֶׁלֹּא יְהֵא בֶּגֶד אוֹ עוֹר מִבִּפְנִים וְתָפְרוֹ בּוֹ. וְיֵשׁ אוֹמְרִים שֶׁעוֹשִים אוֹתוֹ מֵחֲתִיכָה אַחַת, כְּדֵי שֶׁיְּהֵא דּוֹמֶה גַּם בָּזֶה לְסַנְדָּל. \u0005 הַגָּה: אֲבָל נָהֲגוּ לַחֲלֹץ לְכַתְּחִלָּה בְּמִנְעָל שֶׁהוּא תָּפוּר מִבַּחוּץ, וְגַם שֶׁהוּא מִשְּׁנֵי חֲתִיכוֹת, דְּהַיְנוּ שֶׁהַתַּחְתּוֹן שֶׁלּוֹ שֶׁקּוֹרִין שׁול\"א הוּא חֲתִיכָה אַחֶרֶת. וְגַם הָרְצוּעוֹת הֵם חֲתִיכָה אַחֶרֶת תְּפוּרִין בּוֹ. וְיִזָּהֲרוּ שֶׁלֹּא תִּהְיֶה הָעוֹר שֶׁל הַסַּנְדָּל מְשׁוּחָה בְּשֶׁמֶן \u0006 \u0005 לְרַכְּכוֹ \u0006 \u0005(בִּסְדָרִים)\u0006:\nיֵשׁ אוֹמְרִים שֶׁלְּכַתְּחִלָּה עוֹשִׂין אוֹתוֹ מֵעוֹר בְּהֵמָה טְהוֹרָה. \u0005 גַּם הָרְצוּעוֹת וְהַקְּרָסִים שֶׁבּוֹ, גַּם רְצוּעוֹת הַתְּפִירָה \u0006 \u0005(כ\"כ בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006, \u0005 וְכֵן נוֹהֲגִין: \u0010c15\u0011 \u0006\nיִהְיוּ בּוֹ שְׁתֵּי רְצוּעוֹת לְקָשְׁרוֹ בָּהֶם, אַחַת בְּצַד זֶה וְאַחַת בְּצַד זֶה. וְיֵשׁ אוֹמְרִים שֶׁרְצוּעוֹת אֵלּוּ יִהְיוּ לְבָנוֹת. \u0005 וְגַם רְצוּעוֹת הַתְּפִירָה יִהְיוּ לְבָנִים. אֲבָל הַשְׁאָר, הַכֹּל שָׁחוֹר מִבַּחוּץ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּיבָמוֹת)\u0006, \u0005 וְכֵן נוֹהֲגִים. אֲבָל מִבִּפְנִים, אֵין לָחוּשׁ. וְאִם הֻשְׁחֲרוּ הָרְצוּעוֹת מֵחֲמַת זִקְנָה, אֵין לְהַקְפִּיד \u0006 \u0005(פִּסְקֵי מהרא\"י סִימָן ר\"ה)\u0006, \u0005 וְכֵן נוֹהֲגִין. וְיִהְיוּ הָרְצוּעוֹת אֲרֻכּוֹת, שֶׁיּוּכַל לִכְפֹּל כָּל אַחַת שְׁתֵּי פְּעָמִים \u0006 \u0005(כָּל בּוֹ)\u0006:\nיַעֲשׂוּ בּוֹ כְּמִין קֶשֶׁר, שֶׁקּוֹרִים חֻמַרְתָּא, בַּצַּד הָאֶחָד, שֶׁיִּכָּנֵס בַּנֶּקֶב שֶׁבַּצַּד הָאַחֵר כְּדֵי לְהַדְּקוֹ יָפֶה. וְיֵשׁ אוֹמְרִים שֶׁיַּעֲשׂוּ שְׁלשָׁה קְשָׁרִים בְּעִנְיָן זֶה, וּלְפָחוֹת שְׁתַּיִם. \u0005 הַגָּה: וְנוֹהֲגִים לַעֲשׂוֹת שְׁלשָׁה. וְלֹא יִהְיוּ הַקְּשָׁרִים מִן הַמִּנְעָל עַצְמוֹ, אֶלָּא רְצוּעָה אַחֶרֶת מְחֻבֶּרֶת בְּרֹאשׁ הַמִּנְעָל. וְכֵן יַעֲשֶׂה הַקְּרָסִים שֶׁבַּצַּד הַשֵּׁנִי \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006 \u0005 וְכֵן נוֹהֲגִין. וְיִתְפֹּר אֵלּוּ הַלּוּלָאוֹת וְהַקְּרָסִים \u0006 \u0005 מִבַּחוּץ, וְלֹא מִבִּפְנִים, וְכֵן נוֹהֲגִין: \u0006\nיֵשׁ אוֹמְרִים שֶׁלֹּא יִהְיֶה לוֹ לָשׁוֹן כְּמוֹ שֶׁרְגִילִים לַעֲשׂוֹת בְּמִנְעָלִים, \u0010c16\u0011 כְּדֵי שֶׁלֹּא יְהֵא מֵעַל דְּמֵעַל. \u0005 הַגָּה: יֵשׁ אוֹמְרִים לִתְפֹּר שָׂפָה סְבִיב הַמִּנְעָל לְמַעְלָה \u0006 \u0005(ר\"י מִינְ\"ץ בְּשֵׁם ראבי\"ה)\u0006, \u0005 וְלֹא נָהֲגוּ כֵּן. וְיִזָּהֵר לְתָפְרוֹ בִּתְפִירוֹת תְּכוּפוֹת זוֹ לָזוֹ \u0006 \u0005(בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006. \u0005 וְעוֹשִׂין אָזְנֵי הַמִּנְעָל קְצָרִים, שֶׁלֹּא יִהְיוּ הַלּוּלָאוֹת וְהַקְּרָסִים עַל הַמִּנְעָל, רַק עַל הָרֶגֶל, שֶׁלֹּא יִהְיֶה מֵעַל דְּמֵעַל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006:\nיְהֵא עָשׂוּי לְצוּרַת רֶגֶל יְמָנִית, וְיִנְעֲלוֹ בְּרַגְלוֹ הַיְמָנִית; וְיִהְיֶה לְמִדַּת רַגְלוֹ, שֶׁלֹּא יְהֵא גָּדוֹל עַד שֶׁאֵין רָאוּי לֵילֵךְ בּוֹ, וְלֹא יִהְיֶה קָטָן עַד שֶׁאֵינוֹ מְכַסֶה רֹב הָרֶגֶל. וְלֹא יִהְיֶה קָרוּעַ עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ:\nחָלְצָה בְּסַנְדָּל שֶׁל עֵץ אוֹ שֶׁל שַׁעַם \u0010c17\u0011 שֶׁאֵינָם מְחֻפִּים עוֹר, אוֹ בְּרֶגֶל שְׂמֹאל, אוֹ שֶׁהָיָה מִנְעָל גָּדוֹל עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, אוֹ קָטָן שֶׁאֵינוֹ מְכַסֶה רֹב רַגְלוֹ, אוֹ קָרוּעַ שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, אוֹ בְּסַנְדָּל \u0010c18\u0011 שֶׁאֵין לוֹ עָקֵב, אוֹ \u0010c19\u0011 בְּאַנְפִּלְיָא שֶׁל בֶּגֶד, חֲלִיצָתוֹ פְּסוּלָה. \u0010c20\u0011 \u0005 הָיָה שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אוֹ שֶׁבֶּגֶד פִּשְׁתָּן תָּפוּר בִּפְנִים, אוֹ שֶׁחָלַץ בְּמִנְעָל שֶׁל שְׂמֹאל בְּיָמִין, כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006: \u0010c21\u0011\nמִנְעָל שֶׁל עוֹבְדֵי אֶלִילִים שֶׁמַּנִּיחִים אוֹתוֹ לְרַגְלֵי הַצּוּרָה וּמְהַלְּכִין אוֹתָהּ בּוֹ, לֹא תַּחֲלֹץ בּוֹ; וְאִם חָלְצָה, חֲלִיצָתָהּ כְּשֵׁרָה. אֲבָל בְּשֶׁל \u0010c22\u0011 תִּקְרֹבֶת עֲבוֹדָה זָרָה, אוֹ שֶׁל עִיר הַנִּדַּחַת, אוֹ שֶׁנַּעֲשֵׂית לְתַכְרִיכֵי הַמֵּת, אִם חָלְצָה, חֲלִיצָתָהּ פְּסוּלָה:\nשׁוֹלֵט בִּשְׁתֵּי רַגְלָיו, וְכֵן הִיא בִּשְׁתֵּי יָדֶיהָ, יַעֲשׂוּ בְּשֶׁל יָמִין. \u0005 וְאִם הִיא אִטֶּרֶת יָד, תַּעֲשֶׂה בְּיָמִין דִּידַהּ, שֶׁהוּא שְׂמֹאל כָּל אָדָם \u0006 \u0005(טוּר בְּשֵׁם י\"א)\u0006:\nאִטֵּר בְּרַגְלוֹ, \u0010c23\u0011 יֵשׁ אוֹמְרִים שֶׁחוֹלֵץ בִּשְׁתֵּיהֶם, בְּמִנְעָל שֶׁל יָמִין בְּיָמִין, וּבְמִנְעָל שֶׁל שְׂמֹאל בִּשְׂמֹאל. וְיֵשׁ מִי שֶׁנִּסְתַּפֵּק לוֹמַר שֶׁאֵין לוֹ תַּקָּנָה. \u0005 וְנָהֲגוּ כַּסְּבָרָא הָרִאשׁוֹנָה, וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף מ': \u0006\nיִנְעַל הַמִּנְעָל עַל רַגְלוֹ כְּשֶׁהוּא יָחֵף, וְלֹא עַל בָּתֵּי \u0010c24\u0011 שׁוֹקַיִם, שֶׁלֹּא יְהֵא מֵעַל דְּמֵעַל. וּמִטַּעַם זֶה יֵשׁ מְדַקְדְּקִים שֶׁלֹּא יְהֵא טִיט דָּבוּק בַּמִּנְעָל מִבִּפְנִים, וְגַם מִטַּעַם זֶה יֵשׁ מַצְרִיכִים לִרְחֹץ רַגְלוֹ הַיְמָנִית יָפֶה יָפֶה:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהַיָּבָם קוֹשֵׁר כְּנַף הַמִּכְנָסַיִם לְמַעְלָה מִשּׁוֹקוֹ, \u0005 כְּדֵי שֶׁיִּרְאוּ הַדַּיָּנִים הֵיטֵב שֶׁאֵין דָּבָר בֵּין רַגְלוֹ וּבֵין מִנְעָלוֹ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006:\nיִנְעַל הַמִּנְעָל וְיִכְרֹךְ הָרְצוּעוֹת סָבִיב לַמִּנְעָל בְּרַגְלוֹ, וְיִקְשֹׁר שְׁנֵיהֶם יַחַד שְׁנֵי קְשָׁרִים זֶה עַל זֶה, \u0005 וְאַל יְהַדֵּק קֶשֶׁר הַשֵּׁנִי בְּחֹזֶק, כְּדֵי שֶׁתּוּכַל לְהַתִּירוֹ בְּיָמִין \u0006 \u0005(כֵּן עָשָׂה מַהֲרִי\"ל וְכֵן מַשְׁמַע בַּסְמַ\"ג)\u0006, וַעֲנִיבָה עֲלֵיהֶם. וְצָרִיךְ שֶׁיִּהְיֶה הַקֶּשֶׁר עַל בְּשַׂר שׁוֹקוֹ, וְלֹא עַל אָזְנֵי הַמִּנְעָל, לְכָךְ צָרִיךְ שֶׁיַּחְתֹּךְ בַּמִּנְעָל לְפָנָיו וּלְאַחֲרָיו כְּמוֹ פְּגִימָה, כְּדֵי שֶׁתְּהֵא הָרְצוּעָה הַחוֹזֶרֶת דְּבוּקָה מַמָּשׁ עַל רַגְלוֹ יָחֵף. וִיסַבֵּב הָרְצוּעוֹת פַּעֲמַיִם סָבִיב לַשּׁוֹק, עַד שֶׁיָּשׁוּבוּ רָאשֵׁי הָרְצוּעוֹת \u0005(עַל הַשּׁוֹק לְפָנִים)\u0006 \u0005 מִמַּעַל לְאָזְנֵי הַמִּנְעָל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006, \u0010c25\u0011 עַל הַשּׁוֹק עָרֹם. וְיִהְיוּ הַקְּשָׁרִים עַל פְּנֵי הַשּׁוֹק וְלֹא מֵאֲחוֹרָיו. וְיַכְנִיס הַקְּשָׁרִים \u0005(שֶׁבְּאָזְנוֹ)\u0006 בַּנְּקָבִים שֶׁבְּאָזְנוֹ \u0010c26\u0011 הַשְּׁנִיָּה:\nמְלַמְּדִין אוֹתָהּ וְאֶת הַיָּבָם לִקְרוֹת, עַד שֶׁהוּא וְהִיא יִהְיוּ רְגִילִים, וְתִהְיֶה יְכוֹלָה לִקְרוֹת \"לֹא אָבָה\" \u0010c27\u0011 \u0005(דְּבָרִים כה, ז)\u0006 בִּנְשִׁימָה אַחַת. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁצָּרִיךְ גַּם כֵּן שֶׁהוּא יִהְיֶה יָכוֹל לוֹמַר: \"לֹא חָפַצְתִּי\" \u0005(דברים כה, ח)\u0006 בִּנְשִׁימָה אַחַת. וְיִקְרְאוּ אוֹתָהּ, וְהִיא מְעֻמָּד, בִּלְשׁוֹן \u0010c28\u0011 הַקֹּדֶשׁ: \"מֵאֵן יְבָמִי לְהָקִים לְאָחִיו שֵׁם בְּיִשְׂרָאֵל לֹא אָבָה יַבְּמִי\" \u0005(דְּבָרִים כה, ז)\u0006 וְיִקְרְאוּ אוֹתוֹ, וְהוּא מְעֻמָּד; לֹא חָפַצְתִּי לְקַחְתָּהּ \u0005(דְּבָרִים כה, ח)\u0006 \u0005 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ שֶׁיְּדַקְדְּקוּ עִמָּהּ שֶׁהִיא תִּקְרָא: \"לֹא אָבָה יַבְּמִי\", בִּנְשִׁימָה אַחַת \u0006 \u0005(טוּר)\u0006. \u0005 וְכֵן הוּא הַמִּנְהָג. גַּם בְּ\"לֹא חָפַצְתִּי לְקַחְתָּהּ\". וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ס\"ו: \u0006\nיַעֲמֹד אֵצֶל כֹּתֶל אוֹ אֵצֶל עַמּוּד וְיִשָּׁעֵן בּוֹ, וְיִדְחֹק רַגְלוֹ בַּקַּרְקַע, וְתַתִּיר קִשְׁרֵי הַמִּנְעָל, וְאַחַר כָּךְ הַקְּרָסִים, הַכֹּל בְּיָדָהּ הַיְמָנִית, וְתִתְפֹּס רַגְלוֹ בְּיָדָהּ הַשְּׂמָאלִית, וְתִהְיֶה שׁוֹמֶטֶת הַמִּנְעָל מִן הָעָקֵב בְּיָדָהּ הַיְמָנִית, וְתַחֲלֹץ כָּל הַמִּנְעָל גַּם בְּיָדָהּ הַיְמָנִית, וְכָל זֶה בְּלִי סִיּוּעַ יָד שְׂמָאלִית. וּבְכָל זֶה לֹא תִּהְיֶה יוֹשֶׁבֶת, וְלֹא עַל בִּרְכֶּיהָ, אֶלָּא תִּהְיֶה מְעֻמָּד, וְתָכֹף עַצְמָהּ. וּמַשְׁלֶכֶת הַמִּנְעָל לָאָרֶץ. \u0005 חָלְצָה בְּיָדָהּ הַשְּׂמָאלִית אוֹ בְּשִׁנֶּיהָ, כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006:\nגִּדֶּמֶת, חוֹלֶצֶת \u0010c29\u0011 בְּשִׁנֶּיהָ:\nיֵשׁ אוֹמְרִים, שֶׁאִם לֹא דָּחַק רַגְלוֹ בַּקַּרְקַע, חֲלִיצָתָהּ פְּסוּלָה:\nהִתִּיר הוּא הַקֶּשֶׁר, וְשָׁמְטָה הִיא הַמִּנְעָל מֵרַגְלוֹ; אוֹ שֶׁהִתִּירָה הִיא, וְשָׁמַט הוּא, חֲלִיצָתָהּ פְּסוּלָה. \u0005 הַגָּה: \u0010c30\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁאֵינוֹ יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה; אֲבָל אִם יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה, וְחָלְצָה אוֹתוֹ, הַחֲלִיצָה כְּשֵׁרָה אַף עַל פִּי שֶׁהוּא הִתִּיר הַקֶּשֶׁר \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006:\nהָיְתָה רַגְלוֹ עֲקֻמָּה לְאָחוֹר, אוֹ הֲפוּכָה עַל צִדָּהּ, אוֹ שֶׁמְּהַלֵּךְ עַל אֶצְבְּעוֹת רַגְלָיו, אֵינוֹ חוֹלֵץ:\nחָלְצָה מִן הָאַרְכֻּבָּה וּלְמַטָּה, חֲלִיצָתָהּ כְּשֵׁרָה. \u0010c31\u0011 מִן הָאַרְכֻּבָּה וּלְמַעְלָה, חֲלִיצָתָהּ פְּסוּלָה. וְיֵשׁ אוֹמְרִים דְּאַקְּשִׁירָה קָאֵי, שֶׁאִם הָיָה הַקֶּשֶׁר לְמַעְלָה מֵהָאַרְכֻּבָּה, פְּסוּלָה. אֲבָל אִם נִקְטְעָה רַגְלוֹ, אֲפִלּוּ מִן הָאַרְכֻּבָּה וּלְמַטָּה, \u0010c32\u0011 אֵינוֹ חוֹלֵץ. \u0005 וְעַל כֵּן לֹא יִהְיֶה הַמִּנְעָל אָרֹךְ עַד לְמַעְלָה מִן הָאַרְכֻּבָּה \u0006 \u0005(מָרְדְּכַי רֵישׁ מִצְוַת חֲלִיצָה)\u0006. \u0010c33\u0011 וְיֵשׁ אוֹמְרִים דִּבְנִקְטְעָה רַגְלוֹ מַיְרֵי, שֶׁאִם נִקְטְעָה לְמַטָּה מֵהָאַרְכֻּבָּה וְנִשְׁאַר כָּל כָּךְ מִשּׁוֹקוֹ שֶׁיָּכוֹל לְהַכְנִיס בּוֹ הַמִּנְעָל \u0010c34\u0011 וּלְקָשְׁרוֹ לְמַטָּה מֵהָאַרְכֻּבָּה, חוֹלֵץ: \u0010c35\u0011\nקָרְעָה הַמִּנְעָל מַעַל רַגְלוֹ, אוֹ שֶׁשְּׂרַפְתּוֹ, פְּסוּלָה:\nהָיָה לָבוּשׁ שְׁנֵי מִנְעָלִים, \u0010c36\u0011 וְחָלְצָה הָעֶלְיוֹן, אַף עַל פִּי שֶׁקָּרְעָה הַתַּחְתּוֹן עַד שֶׁנִּתְגַּלֵּית רַגְלוֹ, חֲלִיצָתָהּ פְּסוּלָה. \u0005 אֲבָל אִם חָלְצָה \u0006 \u0005 שְׁנֵיהֶם, חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006:\nתַּעֲמֹד נֶגֶד הַיָּבָם, וְתִירַק בָּאָרֶץ כְּנֶגֶד פְּנֵי הַיָּבָם, רֹק הַנִּרְאֶה לַדַּיָּנִים כְּשֶׁיֵּצֵא מִפִּיהָ \u0010c37\u0011 עַד שֶׁיַּגִּיעַ לִפְנֵי הַיָּבָם. וְאִם לֹא רָאוּ הַדַּיָּנִים כְּשֶׁיָּצָא הָרֹק מִפִּיהָ, \u0010c38\u0011 כְּשֵׁרָה:\nרָקְקָה וּקְלַטְתּוֹ הָרוּחַ קֹדֶם שֶׁהִגִּיעַ נֶגֶד פָּנָיו, כְּגוֹן שֶׁהִיא אֲרֻכָּה מִמֶּנּוּ, \u0010c39\u0011 צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. אֲבָל לְאַחַר שֶׁהִגִּיעַ הָרֹק נֶגֶד פָּנָיו, אֲפִלּוּ לֹא הִגִּיעַ לָאָרֶץ, כְּשֵׁרָה. לְפִיכָךְ, אִם הוּא אָרֹךְ וְהִיא קְצָרָה, קָרֵינָן בֵּהּ שַׁפִּיר \"בְּפָנָיו\" \u0005(דְּבָרִים כה, ט)\u0006:\nיְבָמָה שֶׁרָקְקָה דָּם, \u0010c40\u0011 אֵינָהּ צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. וְיֵשׁ אוֹמְרִים דְּדַוְקָא בְּמוֹצֶצֶת, מִשּׁוּם דְּאִי אֶפְשָׁר לָהּ בְּלֹא צִחְצוּחֵי רֹק:\nאָכְלָה שׁוּם אוֹ גַּרְגֵּר וְכַיּוֹצֵא בּוֹ, מִדְּבָרִים הַמַּרְבִּים \u0010c41\u0011 רֹק, וְהָיָה רֹק זָב מִפִּיהָ, אֵינוֹ כְּלוּם. וְנָהֲגוּ לְמָנְעָהּ מִלֶּאֱכֹל כְּלוּם. \u0005 וְכֵן לִשְׁתּוֹת, וּתְמַעֵט בְּדִבּוּר, כְּדֵי שֶׁיָּבֹא הָרֹק מֵעַצְמוֹ. גַּם לֹא תְּנַקֵּר שִׁנֶּיהָ, כְּדֵי שֶׁלֹּא תִּרֹק דָּם \u0006 \u0005(כ\"ז בִּסְדָרִים)\u0006:\nאַחַר כָּךְ מַקְרִין אוֹתָהּ מְעֻמָּד: \"כָּכָה יֵעָשֶׂה לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו, וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל\" \u0005(דְּבָרִים כה, ט י)\u0006. וּמִצְוָה לְכָל הָעוֹמְדִים לוֹמַר: \"חֲלוּץ הַנַּעַל\", \u0010c42\u0011 שָׁלשׁ פְּעָמִים. וְיֵשׁ אוֹמְרִים שֶׁגַּם הַיְבָמָה תֹּאמַר כֵּן:\nנִמְצָא סֵדֶר הַחֲלִיצָה: קוֹרְאָה \"מֵאֵן יְבָמִי\" \u0005(דְּבָרִים כה, ז)\u0006, וְקוֹרֵא \"לֹא חָפַצְתִּי לְקַחְתָּהּ\" \u0005(דְּבָרִים כה, ח)\u0006, וְחוֹלֶצֶת, וְרוֹקֶקֶת, וְקוֹרְאָה \"כָּכָה יֵעָשֶׂה לָאִישׁ\" \u0005(דְּבָרִים כה, ט י)\u0006 וְאֵין הַסֵדֶר מְעַכֵּב. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ לֹא קָרְאָה וְלֹא רָקְקָה, אֶלָּא שֶׁחָלְצָה בִּלְבַד, הַחֲלִיצָה כְּשֵׁרָה. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיוּ יְכוֹלִים לְדַבֵּר, שֶׁהֲרֵי הֵם רְאוּיִם לִקְרוֹת. אֲבָל אִלֵּם וְאִלֶּמֶת וּקְטַנָּה, אֵינָם חוֹלְצִין, וְאִם חָלְצוּ, חֲלִיצָתָן פְּסוּלָה; וְאֵינָהּ כְּשׁוֹטֶה וְקָטָן, שֶׁלֹּא עָשׂוּ כְּלוּם, שֶׁאֵינָהּ נִפְסֶלֶת לָאַחִים וִיכוֹלָה לְהִתְיַבֵּם לָהֶם אוֹ לוֹ. \u0010c43\u0011 וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין לַחֲלִיצַת חֵרֵשׁ וְחֵרֶשֶׁת שֶׁאֵינָהּ כְּלוּם. וְיֵשׁ אוֹמְרִים שֶׁחֲלִיצָתָן פְּסוּלָה, כְּמוֹ שֶׁל אִלֵּם וְאִלֶּמֶת:\nצָרִיךְ שֶׁיְּכַוְּנוּ הַיָּבָם וְהַיְבָמָה שֶׁתְּהֵא מֻתֶּרֶת לְזָר בַּחֲלִיצָה זוֹ. \u0010c44\u0011 נִתְכַּוֵּן הוּא וְלֹא הִיא, אוֹ הִיא וְלֹא הוּא, לֹא הֻתְּרָה; אֲבָל חֲלִיצָה פְּסוּלָה הִיא לְפָסְלָהּ עַל הָאַחִים. לְפִיכָךְ, יְבָמָה שֶׁגָּדְלָה בֵּין הָאַחִים, וְרָאִינוּ שֶׁחָלְצָה נַעֲלוֹ שֶׁל אֶחָד מֵהֶם, אֲסוּרָה לְהִתְיַבֵּם, שֶׁמָּא כִּוְּנוּ לְשֵׁם חֲלִיצָה; וּצְרִיכָה חֲלִיצָה כְּשֵׁרָה, לְהַתִּירָהּ לְזָר; אֲבָל כָּל זְמַן שֶׁלֹּא רָאִינוּ שֶׁחָלְצָה לְאֶחָד מֵהֶם, מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵין חוֹשְׁשִׁין שֶׁמָּא חָלְצָה:\nוְכֵן אִם רָקְקָה לִפְנֵי הַיָּבָם \u0010c45\u0011 בִּפְנֵי בֵּית דִּין, נִפְסְלָה \u0010c46\u0011 מִלְּהִתְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי כְּשֶׁרָקְקָה רֹק, אֲבָל אִם רָקְקָה דָּם, וְאֵין רֹק מְעֹרָב בּוֹ, אֵינָהּ נִפְסֶלֶת בְּכָךְ:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁיֵּשׁ לִזָּהֵר שֶׁלֹּא תִּירֹק הַיְבָמָה לִפְנֵי הַיָּבָם קֹדֶם חֲלִיצָה, כְּדֵי שֶׁלֹּא תְּהֵא חֲלִיצָה פְּסוּלָה וּתְהֵא צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים:\nאִם קָרְאָה לְבַד, לֹא נִפְסְלָה בְּכָךְ \u0010c47\u0011 מִלְּהִתְיַבֵּם:\nהַסוּמָא, אֵינוֹ חוֹלֵץ לְכַתְּחִלָּה. וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵין אָח אֶלָּא הוּא, חוֹלֶצֶת לְכַתְּחִלָּה, \u0005 כְּדֵי שֶׁלֹּא תִּתְעַגֵּן \u0006 \u0005(ב\"י מ\"כ)\u0006. \u0005 וְלֹא מִקְּרֵי סוּמָא, אֶלָּא בִּשְׁתֵּי עֵינָיו \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006:\nקְטַנָּה שֶׁחָלְצָה לְגָדוֹל, \u0010c48\u0011 חֲלִיצָתָהּ פְּסוּלָה וְנִפְסְלָה עַל כָּל הָאַחִים. \u0005 וּכְשֶׁתַּגְדִּיל, תַּחֲלֹץ מֵאֶחָד מֵהֶם, \u0010c49\u0011 וְאֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים: \u0006\nחֲלִיצָה מֻטְעֵת, שֶׁאוֹמְרִים לוֹ: חֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לְךָ מָאתַיִם זוּז, הַחֲלִיצָה כְּשֵׁרָה, אֲפִלּוּ אֵינָהּ נוֹתֶנֶת לוֹ כְּלוּם, וַאֲפִלּוּ כָּפַל הַתְּנַאי. \u0005 וַאֲפִלּוּ אָמַר לָהּ בִּשְׁעַת הַחֲלִיצָה: \u0010c50\u0011 עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לְאִישׁ, וְכָפַל תְּנָאוֹ, אֵינוֹ כְּלוּם \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל נ\"ב)\u0006. וְאַף עַל פִּי שֶׁהַחֲלִיצָה כְּשֵׁרָה אַף אִם לֹא תִּתֵּן לוֹ, מִכָּל מָקוֹם חַיֶּבֶת לִתֵּן לוֹ, כִּשְׁאָר שְׂכַר שָׂכִיר לַעֲשׂוֹת מְלַאכְתָּן. \u0010c51\u0011 אֲבָל אִם יֵשׁ טַעֲנָה שֶׁאֵינָהּ חֲפֵצָה בּוֹ מִפְּנֵי שֶׁאֵינוֹ הָגוּן לָהּ, וְהוּא חַיָּב לַחֲלֹץ אֶלָּא שֶׁאֵינוֹ רוֹצֶה, וְהִטְעוּהוּ שֶׁיַּחֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז, אֵינָהּ חַיֶּבֶת לִתֵּן לוֹ כְּלוּם. \u0010c52\u0011 \u0005 אֲבָל אִם נָתְנָה לוֹ הַמָּעוֹת אוֹ הִשְׁלִישָׁה לוֹ \u0006 \u0005 הַמָּעוֹת, אֵינָהּ יְכוֹלָה לַחֲזֹר \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א אֶלֶף ר\"מ)\u0006. \u0005 וְעַיֵּן לְעֵיל רֵישׁ סִימָן קס\"ה: \u0006\nאָמְרוּ לוֹ: חֲלֹץ לָהּ וּבְכָךְ אַתָּה כּוֹנְסָהּ, אוֹ שֶׁאָמְרוּ לֵהּ: חֲלֹץ לָהּ שֶׁזּוֹ מִצְוָה הִיא וְאֵינָהּ מַפְסֶדֶת עָלֶיךָ כְּלוּם, וְאִם תִּרְצֶה אַחַר כָּךְ לְיַבֵּם, תְּיַבֵּם, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, אֵינָהּ חֲלִיצָה לְהַתִּירָהּ, כֵּיוָן שֶׁלֹּא נִתְכַּוֵּן לְהַתִּירָהּ, אֲבָל נִפְסְלָה בְּכָךְ מִלְּהִתְיַבֵּם, וְכוֹפִין אֲפִלּוּ בְּשׁוֹטִים לַחֲלֹץ לָהּ חֲלִיצָה כְּשֵׁרָה:\nאָמְרוּ לוֹ: הָאִשָּׁה הַזֹּאת אֵינָהּ רוֹצָה בְּךָ דֶּרֶךְ יִבּוּם, אֶלָּא חֲלֹץ לָהּ וַעֲקֹר זִקָּתָהּ הֵימֶנָּה וְהִיא נִשֵּׂאת לְךָ דֶּרֶךְ \u0010c53\u0011 נִשּׂוּאִין, יֵשׁ מִי שֶׁאוֹמֵר שֶׁחֲלִיצָתָהּ כְּשֵׁרָה:\nדִּין חֲלִיצָה מְעֻשֵּׂית עַל יְדֵי יִשְׂרָאֵל אוֹ עַל יְדֵי עכו\"ם, דִּינָהּ כְּדִין גֵּט מְעְשֶּׂה, שֶׁנִּתְבָּאֵר בְּסִימָן קל\"ד. \u0005 וְעַיֵּן לְעֵיל סִימָן זֶה סָעִיף י\"ג: \u0006\nֹ מָסַר מוֹדָעָא עַל הַחֲלִיצָה, אֵינָהּ חֲלִיצָה בְּטֵלָה, אֶלָּא \u0010c54\u0011 חֲלִיצָה פְּסוּלָה הִיא:\nחֲלִיצָה פְּסוּלָה פּוֹסֶלֶת עַל כֹּל הָאַחִים, וּפוֹסֶלֶת לִכְהֻנָּה, וְאוֹסֶרֶת עָלָיו כָּל קְרוֹבוֹתֶיהָ, וְאֵינָהּ נִשֵּׂאת לְזָר עַד שֶׁתַּחֲלֹץ חֲלִיצָה כְּשֵׁרָה. עָבְרָה וְנִשֵּׂאת לְזָר קֹדֶם שֶׁתַּחֲלֹץ, חוֹלֵץ לָהּ חֲלִיצָה כְּשֵׁרָה וְהִיא תַּחַת בַּעְלָהּ, וְאֵין מוֹצִיאִין אוֹתָהּ מִמֶּנּוּ, מִכָּל מָקוֹם מַפְרִישִׁין אוֹתָהּ מִבַּעְלָהּ עַד שֶׁיַּחֲלֹץ לָהּ הַיָּבָם:\nלְאַחַר שֶׁחָלְצָה, \u0010c55\u0011 כּוֹתְבִין לָהּ בֵּית דִּין שֶׁחָלְצָה בִּפְנֵיהֶם, גֵּט חֲלִיצָה. וְאִם לֹא כְּתָבוּהוּ לָהּ, כָּל שְׁנַיִם שֶׁרָאוּ הַחֲלִיצָה יְכוֹלִים לְכָתְבוֹ, אַף עַל פִּי שֶׁאֵינָם מַכִּירִים לֹא הַיָּבָם וְלֹא הַיְבָמָה; שֶׁבֵּית דִּין לֹא חָלְצוּ בִּפְנֵיהֶם אִם לֹא הָיוּ מַכִּירִים. וּצְרִיכִין לְשַׂרְטְטוֹ, מִפְּנֵי מִקְרָאוֹת שֶׁבּוֹ. \u0005 וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ל\"ה: \u0006 \u0005(אָמַר הַמַּגִּיהַּ גַּם פֹּה בְּסֵדֶר חֲלִיצָה כָּל מָקוֹם שֶׁלֹּא נִזְכַּר בַּהַגָּהוֹת שֵׁם אוֹמְרָהּ, סְתָמָן כְּפֵרוּשָׁן שֶׁהֵם לְקוּחִים מֵהַסְדָרִים וּבִפְרָט מִסֵדֶר מהר\"י מַרְגָּלִיוֹת)\u0006:",[],["\u0003רק שידעו להקרות\u0004. עיין בפירוש סדר החליצה שהביא שם דעת הנ\"י שצריכין להיות דיינין אבל מומחין א\"צ להיות גם מ\"ש אם א\"י להקרות כשר ע\"ש פירושו:","\u0003קרוב\u0004. הטעם משום חליצה נקרא דין לכן קרוב פסול אף על גב בדין מהני אם קבלו בעלי הדינין הקרובים כאן לא מהני עיין בת\"ה סימן רכ\"ז:","\u0003ואפי' היה אביו גר\u0004. וקי\"ל בעלמא הורתו ולידתו בקדושה ישראל מעליא הוא מ\"מ כאן בחליצה צריכין להיות הדיינים שחולצת בפניהם שיהיה אביהם מישראל ולא מהני בדיינים הורתו ולידתו בקדושה דילפינן מקרא בישראל דהקפידה התורה שיהא אביהם מישראל ולא מהני בזה הורתן ולידתן בקדושה ועיין תוס' פ' מ\"ח דף ק\"א ובכתובות דף מ\"ד:","\u0003מצוה ושיוסיפו שנים\u0004. הטעם כדי לפרסם ופרש\"י ונ\"י לפ\"א לפרסם שתהא חלוצה ואסורה לכהן לפ\"ז אם היא גרושה כבר אין צריך חמשה אבל לפי' השני צריך ה' כדי דליתי אנשי ולקפצו עליה ובאלו שנים אין קפידא אם נוטלין שכר הרבה ד\"מ, וכן אם הם קרוביו קורבה שאין פסול ע\"פ הדין אלא מצד חומרא כמ\"ש בסי' ס\"ח ובנ\"י כ' אם הזמינו ג' לב\"ד בפי' וקראו שנים למילוי אז אפי' גרים אפי' פסולים כשרים באלו שנים והא דפוסל בש\"ס לרב ושמואל שהיו בן גר למילוי שנים היינו דשם כל החמשה היה עושה חיבור א' שאין זה כבודו של ר\"ש להקצות מן השלשה וכ\"כ בא\"ז דאין קפידא בשנים הנוספים אם אינם כשרים והיינו נמי בכה\"ג לפי המנהג דאין עושין חיבור א' ואלו שנים יושבין נמשכין מן הג' אז אין קפידא כלל ובזה מיושב מה שהקשה בת\"ה סי' רכ\"ו על הא\"ז מעובדא רב ושמואל בזה ניחא דל\"פ כלל הפוסקים ומה שמדייקי' מרמב\"ם וטור דס\"ל דיש קפידא באלו שנים שאל יהיו קרובים היינו דס\"ל כל החמשה יושבין בכנופי' חדא כדמשמע שם שלא כתבו דיושבין רחוק מן הג', גם מה שמדייק הת\"ה מן הגמיי' אין מוכרח וגר שאמו מישראל פסול לכתחלה להיות תוך שנים כשעושין כנופי' אחת כמ\"ש בש\"ס בעובדא רב שמואל בר יהודא ובדיעבד כשר הואיל ואלו שנים רק כדי לפרסם הדבר:","\u0003לקבוע מקום\u0004. עיין בפי' ס\"ח ועיין ב\"ח ואין קובעין בשבת מאחר דצריך קביעות הוי כמכין משבת לחול ועיין בד\"מ וקביעות מקום היינו משום פרסום לכן צריך להיות בגובה שבעיר ואם יש פרסום בלא זה עיין בתשובת ר\"י לבית הלוי סי' יו\"ד:","\u0003בן ג' שנים ויום א'\u0004. עיין סי' קנ\"ה שם כתבתי באריכות דינים הללו:","\u0003דדים גדולים\u0004. כתב בד\"מ בשם המרדכי דכתב בשם התרומה בדיקה זו צריך להיות ע\"י אנשים ובדיקה אם יש לה ריבוי שערות בודקים ע\"י נשים וכ\"כ ב\"ח בשם הסמ\"ק בדיקות דדים צריך להיות ע\"י אנשים אא\"כ הוחזקה גדולה בשנים אז בודקים ע\"י נשים כי החזקה מסייע מסתמא אחר יב\"ש הביאה סימנים א\"כ בדיקת שערות הוא אפי' לא הוחזקה בשנים והקשה הד\"מ א\"כ למה מהני בדיקות נשים ותירוץ משום דהוא מילתא דעבידא לגלויי לא משקרי והא אין נשים נאמנים על ב' שערות כשלא הוחזקה בשנים ולא אמרי' מלתא דעבידא לגלויי משום בשני שערות לאו מלתא דעבידא לגלויי הוא כ\"כ דהא מהאי טעמא כ' בה\"ת דאין ממאנין בזמן הזה דאין אנו בקיאין לבדוק כל הגוף אם יש לה שערות מיהו קשה דדין נמי הוא מלתא דעבידא לגלויי וא\"ל דדין לא עדיף מב' שערות דדין מהני משום א\"א לבוא סימן עליון בלא תחתון מ\"ה כשהיא לא הוחזקה בשנים אין בודקים נשים א\"כ מה מהני בדיקת אנשים וצ\"ל דד\"מ לא תירץ זאת אלא לסברת המ' דס\"ל באמת בדיקת דדין הוא ע\"פ נשים, ולבה\"ת דס\"ל דל\"מ ע\"פ נשים צ\"ע למה מהני רבוי שערות ע\"פ נשים:","\u0003נתמלא זקנו\u0004. עיין בב\"י בח\"ה ר\"ס ל\"ה:","\u0003שאם הוחזק או שיצא קול וכו'\u0004. נאמנים להחזיקן כגדולים היינו אפי' על בדיקת נשים סמכינן בחזקה פשיטא סמכינן על בדיקת נשים מה לי חזקה הנ\"ל או חזקה זו ויש לדחות דשם מיהו על שנים יש עדים וכן קול מהני כמו חזקה סמכינן עליהן:","\u0003וע\"ז סומכין שלא לבדוק וכו'\u0004. עיין סי' קנ\"ה שכתב הטור בשם הבע\"ת דאין אנו בקיאין לבדוק גומות א\"כ לפ\"ז לכאורה קשה כל בדיקות אחר השערות אפי' ע\"י אנשים ל\"מ דקי\"ל שערות בלא גומא ל\"מ ואין אנו בקיאין וכן הק' ב\"ח וע\"ש מ\"ש ולדידי' לא נתיישב לפסק הלכה מנ\"ל למיקל נגד דעת הבה\"ת וכן הטור הביא דעתו בפשיטות בלי שום חולק אבל לכאורה נ\"ל דלק\"מ בודאי על בדיקות גומות כשאין שערות בכל הגוף אין אנו בקיאין מ\"ה החמיר שם שלא תמאן אבל לבדוק אם יש גומא תחת השערות פשיטא בקיאין אנו בבדיקה זו וכן משמע מלשון המחבר שכתב ע\"ז סומכין שלא לבדוק משמע דאנו יכולים לבדוק, שוב ראיתי גם בט\"ז בסימן קנ\"ה כתב כן:","\u0003ואם יש ליבמה בנים\u0004. עיין סי' קנ\"ה שם הבאתי סוגי' פ\"ק דיבמות לרב ספרא בנים הם כסימנים אפי' אם הולידה בקטנותה הרי הם כסימנים אחר יב\"ש כן ס\"ל להג\"מ זה ולא כתשובת מ\"ב סימן ו' ע\"ש והרמב\"ם פוסק כר\"ס לפ\"ז שפיר פסק זה מיהו מהרי\"ף והרא\"ש משמע דס\"ל כרב זביד דאין בנים בלא סימנים היינו דאין בנים מצוי' בלא סימנים לפ\"ז לא מהני לענין חליצה ותימה על הרב רמ\"א דפוסק בפשיטות כהג\"מ וכבר כתבתי בסי' קנ\"ה דדוקא אחר יב\"ש מהני בנים לרמב\"ם:","\u0003שמצות חליצה מעומד\u0004. משום דדמיא לדין ואם יבם חלש או זקן נותנין לו מקל בידו לסמוך עליו, ולרמב\"ם ונ\"י בשם הרבה פוסקים אפילו לכתחלה חליצת המנעל מות' בישיבה וא\"ל להני פוסקים דס\"ל לכתחלה מצוה בעמידה הוא וס\"ל גם כן הא דאמר אמימר צריך למדחסי כרעיה היינו צריך לכתחלה ובדיעבד אין עיכוב אם כן מה מקשה שם על אמימר מברייתא בין עומד ובין יושב וס\"ד כשיושב לא מדחי' כרעיה ומה ק\"ל הא יש לומר הברייתא איירי בדיעבד וכן הקשה בנ\"י, וצ\"ל דס\"ל ע\"כ הברייתא איירי לכתחלה מדקתני בין עומד אם כן ע\"כ מה דתני בברייתא יושב ומוטה נמי לכתחלה וס\"ד כשמוט' לא מדחסי כרעיה וא\"ל איך ס\"ד יושב לכתחלה דהא מצות חליצה לכתחלה מעומד ויש לומר דסבר אף על גב לכתחלה בעינן שיעמדו היינו משום דהוי כדין וצריכים שיעמדו מחמת שהיא גובאת כתובה הוי כדין, אבל משום מצות חליצ' אפי' לכתחלה מותר וכן אם הדיינין עמדו כשר דחד טעם הוא:","\u0003ויש פוסלין\u0004. כ\"כ הרמב\"ם פ\"ד וטור בשם הרמ\"ה ולדעת הרא\"ש כשר וכתב הטעם משום הדרוש מתחש שצריך להיות משל עור אינו אלא אסמכתא, וא\"ל לפ\"ז למה אנפלאות של בגד פסול וצ\"ל דס\"ל כתוס' שכתבו שם אנפלאות לא חשיב מנעל כיון דאין רגילין לעשות מבגד ותליא הכל אם דרך לעשות מנעל כזה ודרוש תחש אינו אלא אסמכתא ושל עץ פסול גם כן מטעם דאין דרך לעשות מנעל של עץ כמ\"ש בתוס' שם, ורש\"י פי' למ\"ד אנפלאות כשר לא דייק הקרא תחש ש\"מ דס\"ל גם כן כי\"א אלו, ותוס' שם משמע נמי דס\"ל דרוש תחש לאו אסמכתא היא אלא צריך ישוב למה כתבו בפלוגתא בקב הקיטע ובאנפלאות דרבנן פסלו משום דאין דרך לעשות מנעל כזה ת\"ל דס\"ל הדרוש תחש דרוש גמור הוא וצ\"ל כמ\"ש בסמוך כשעשוי מצמר דבא מעור אין ממועט מתחש בזה ניחא מ\"ש באנפלאות מיהו מ\"ש בקב הקיטע דהיינו עץ כתבו הטעם דדרך עשוי מנעל ולא כתבו הטעם דר\"מ אינו מדייק תחש, ואפשר מדמוכרחי' לפרש באנפלאות משום דאין דרך לעשות מנעל משום דאין ממועט מתחש תו א\"צ לפרש בקב הקיטע לר\"מ דאינו מדייק תחש דהא אף דאינו מדייק תחש מ\"מ כיון דאין דרך לעשות ממנם /מהם/ מנעל למה כשר אלא ע\"כ צ\"ל טעם הנ\"ל ולפסק הלכה עיקר כי\"א אלו דהם דעת רש\"י ותוס' ורמב\"ם ורמ\"ה והרשב\"א כמ\"ש המגיד בשמו וכ\"פ הש\"ג לפ\"ז גם מ\"ש הטור אם חלץ במוק כשר היינו לטעמו מה שדרך לעשות מנעל כשר ותחש לאו דרשה גמורה היא אבל להפוסקים הנ\"ל דרשה גמורה היא אז אף במוק פסול מיהו י\"ל אף על גב תחש דרשה גמורה היא מ\"מ מוק העשוי מצמר הבא מעור אינו ממועט מתחש אף על גב העשוי משער פסול מ\"מ מוק כשר דאפשר דנקרא מנעל והעשוי משער לא נקרא מנעל אלא קורק' ולרש\"י ורשב\"א דפירשו אנפלאות של בגד ממועט מתחש אף על גב דעשוי מצמר הבא מעור כמו שער א\"כ קשה בסוגיא דבעיי' ליה הוא של עור ותרסיותיו של שער מהו א\"ל מי לא קרינא ביה תחש א\"ל א\"ה כולי נמי ההוא קורקא ואם בגד של צמר ממועט מתחש א\"כ שער נמי ול\"ל הטעם ההוא קורקא נקרא ולמה לא ממעט מתחש וי\"ל:","\u0003אבל רצועותיו א\"צ שיהיה מעור\u0004. כ\"כ הטור והב\"י הבין דהטור חולק על הנ\"י דכתב דלא מכשירין ברצועות אלא של שער שבא מעור ולא שאר מינים, ולהטור כשר אפילו בשאר מינים וכן ס\"ל לרמ\"א וי\"א שהביא דס\"ל גם רצועותיו מעור היינו דבר הבא מעור ואין מוכרח לומר כן אלא י\"ל דל\"פ אלא כוונת הטור דא\"צ להיות של עור אלא של שער הואיל שהוא בא מן העור כשר וכ\"כ ב\"ח ונראה דמוכח כן מש\"ס דאי ס\"ד אם הרצועות אפי' של שאר מינים כשר א\"כ קרא תחש לא קאי אלא על גוף הסנדל א\"כ מה הקשה שם א\"ה כולו של שער נמי מנ\"ל של שער נקר' תחש דלמ' של שער לא נקר' תחש אלא דלא אכפת לן אם הרצועות של שאר מינים, ומנעל של שער פסול כי של שער לא נקר' מנעל וכן אם הרוב מנעל של שער פסול כמ\"ש בש\"ג ואם התפירה של שער י\"ל ג\"כ דפסול כמ\"ש בש\"ג שם הטעם של פשתן פסול משום הכל הולך אחר המעמיד א\"כ הוי כאלו כולו של שער מיהו י\"ל דכשר דאף אם כולו של שער הוי כאלו הוא של עור אלא דפסול משום דלא נקרא נעל אבל אם היא של עור אלא התפירות הם של שער נקרא נעל וכשר ואם המנעל הוא שיכול להלוך בלא קשירה אז נראה לכ\"ע כשר אם הרצועות הם של שאר מינין כמ\"ש לקמן בשם הרא\"ש וע\"ש:","\u0003צריך לכתחילה שיהא עור קשה\u0004. הטעם פלוגת' משום דאית' בש\"ס אין חולצין במנעל לכתחלה ובזה\"ז דאין שכיח סנדל ואז ע\"פ הדין היה מותר לחלוץ במנעל אלא הפוסקים כתבו אף בזה\"ז לכתחילה טוב לעשות בסנדל ואית' כמה פירושי' מה בין מנעל לסנדל ומזה יצא כל הדיעות שהבי' כאן, אלא מה שהבי' כאן בשם י\"א שהתפירה תהיה בפנים א\"י מי הי\"א דהא הסמ\"ג וסמ\"ק כתבו להדי' סנדל תפירות מבחוץ:","\u0003יהיו בו ב' רצועות\u0004. ואם המנעל הוא שיכול להלוך בלא קשירה אז כשר החליצה אפילו שאין בו רצועות וקשרים כ\"כ הרא\"ש ועיין ס\"ק כ\"ה:","\u0003כדי שלא יהא מעל דמעל\u0004. היינו לכתחילה המצוה כך אבל בדיעבד אין חשש מאחר דחולץ שניהם כמ\"ש בסעיף ל\"ז כ\"כ הב\"י ובש\"ס משמע אף לכתחלה אין חשש משום מעל דמעל דאל\"כ למה לא אמר במנעל אין חולצין לכתחלה מטעם מעל דמעל כמ\"ש בש\"ס דלמא פנתא מעל וארקת' מעל דמעל, ועיין ב\"ח ופרישה אפילו לכתחלה אין כאן חשש אלא דרך חומר' בעלמ' כתבו הפוסקים כן:","\u0003שאינם מחופים עור\u0004. כבר כתבתי ה\"ה של מוק אם אין מחופה עור פסול וכ\"כ בדרישה וב\"ח אלא בד\"מ לא משמע כן אבל עיקר כמ\"ש וכ\"כ רי\"ו מוק פסול:","\u0003שאין לו עקב\u0004. כתב הנ\"י כל דבר המעכב הרגל במנעל נקר' עקב שצריך שאל יוצי' הרגל חוץ למנעל:","\u0003באנפליא של בגד חליצתו פסולה\u0004. עיין פ' כל הגט שם פליגי ר' אליעזר ושמואל, ולשמואל כל מקום דתני חליצה פסולה אסורה היא לאחין ולר\"א באנפלאות וקטן אינו חליצה כלל ומותרת לאחין אף על גב ברקקה לבד פסולה לאחין מ\"מ ברקק' וחלצה אנפלאות גרע טפי כמ\"ש במ', אבל באנפלאות החליצה בטילה, ורמב\"ם פוסק כר\"א והמחבר השמיט כאן דעת הרמב\"ם ובסעיף ג' בקטן פסק דאינה חליצה כלל ואינה נפסלת מאחין משום לפי גירסת תוס' פ' כל הגט איתא בפ' מ\"ח דף ק\"ה אמר שמואל חליצת קטן לרבנן אינה חליצה כלל ש\"מ דיש חילוק בין אנפלאו' לקטן, כי באנפלאות לא אמר שמואל דחולקין בזה ר\"מ ורבנן אם פסולה אז בטל לגמרי כן הוא דעת המחבר וכן פסק הרשב\"א כשמואל וכן משמע בתשוב' ריב\"ש שהביא בכ\"מ פ\"ד מה' יבום, ובזה מיושב תמיה' ב\"ח ורמב\"ם פוסק כר\"א באלו שניהם אין פוסלת כלל, אלא על המגיד קשה למה טרח להמציא טעם לדברי הרמב\"ם ולא כתב הטעם דפוסק כר\"א:","\u0003היה של עץ וכו'\u0004. כשרה משמע דוקא בדיעבד כשר וכן משמע בש\"ס וברמב\"ם וכן הוא להדיא בנ\"י וצריך ישוב על הרא\"ש דהביא כרש\"י סנדל התפור בפשתן היינו בגד פשתן תפור בפנים והקשה דלא גרע מסנדל של עץ ומחופה בעור מה קושיא דהא לפירוש הרא\"ש סנדל התפור בפשתן בדיעבד כשר א\"כ דילמא ג\"כ לפרש\"י אם תפור בפנים בגד פשתן באמת בדיעבד כשר ולא גרע מסנדל של עץ ומחופה בעור וצ\"ל משום דרש\"י פירש דאין חולצים בסנדל התפור דכתיב נעל ובפלוגתא דר\"מ בקב הקיטע מוכח לרש\"י דס\"ל דרשה דנעל לאו אסמכתא הוא ודרשה גמורה היא כמ\"ש בס\"ק י' משמע לרש\"י אף בדיעבד פסול מ\"ה הקשה מ\"ש למה גרע מסנדל של עץ, שוב ראיתי בב\"ח סעיף ז' מיישב בע\"א ודין זה מחופה בעור נלמד מאוקימתא דאבוה דשמואל כמ\"ש שם דף ק\"ג וא\"י למה כ' המגיד דלמדו מאוקימתא דאביי ע\"ש:","\u0003מנעל של ע\"א\u0004. עיין בתו' שם אם הוא ע\"א של ישראל או עכו\"ם והפקיר ובא ליד ישראל אז הוי כע\"א של ישראל ואין לו ביטול ומכתת שיעורי' אלא איירי בע\"א של עכו\"ם והפקיר וכוונתו שלא לקנות המנעל או ע\"ז של גוי ולא הפקיר אז לא קנה הישראל ב\"ח, לפ\"ז אסור לחלוץ בו מטעם שאין שלו המנעל ולר\"ת איירי בע\"א של עכו\"ם ובטלו:","\u0003תקרובת\u0004. פי' המגיד אם המנעל הוא תקרובת ליכא איסור דקי\"ל דאין תקרובת אלא המשתפך כעין פנים אלא איירי שזבח הבהמה לפני ע\"א ועשה מעורה מנעל וכן הוא בש\"ס פ' ר\"י ובכל הפוסקים כמ\"ש בי\"ד סי' קל\"ט, וצריך לדחוק בלשון רש\"י לכוין כוונתו ג\"כ מ\"ש שהקריב ומסרהו לע\"א קאי על הבהמה ולא על המנעל:","\u0003י\"א שחולץ בשתיהם\u0004. אף על גב דכתב בסמוך אם היא אטרת דחולצת בימין דידה מ\"מ ביבם מחמירין משום דאי' גזירה שוה דצריך דוקא ימין ממש ובפי' חליצה כ' לחלוץ בשני רגליו בפעם א' תחלוץ ביד א' מרגל א' ובידה שניה מרגל שני דאם תחלוץ זה אח\"ז הוי חליצה פסולה, וב\"ח כ' דמנהג הוא לחלוץ זה אח\"ז ויכוונו היבם והיבמה לחלוץ בזה שע\"פ הדין הוא לחלוץ:","\u0003שלא יהא מעל דמעל\u0004. ובדיעבד הוי חליצה פסולה ואם חולץ גם הבתי שוקיים כשר כ\"כ הרא\"ש וכן מוכח בש\"ס אבל מה שמדקדק לרחוץ רגליו לבדוק שלא יהא שום דבר דבק במנעלו אינו אלא חומרא בעלמא לכתחלה:","\u0003על השוק ערום\u0004. וז\"ל הלבוש ויכרוך הרצועות סביב הרגל ג\"כ מן הארכובה ולמטה היינו במקום שמנעל פתוח מאחורי הרגל שתי חורים ובין החורים הוא שלם יכרוך הארוכות בין הלולאות עד שיגיע באחורי הרגל בחור עליון ויניחם ג\"כ שם מכוונות זה אצל זה ואח\"כ יכרוך הרצועות פעם ג' סביב הרגל ועד שיגיעו למעלה מן הלולאות על גב הרגל שקורין בל\"א שינביי\"ן דעל שינביי\"ן נמי מעל רגלו נקרא, ועיין פרישה הטעם משום שבמקום שפוגעים בו שני הרצועות האריכות מלפניו ולאחריו כופלין אותו זה ע\"ז מחשב כקשר מ\"ה צריך שיהיה אותו הכפילה במקום בשר שוקו אבל מה שמשם והלאה מונח הרצועה על עור המנעל אין קפידא דאינו דומה לקשר כלל:","\u0003מלמדין אותה וכו'\u0004. לימוד זה קאי על הקרא כולו שתהיה רגילה לקרות ואח\"כ קאמר ותהיה יכולה לקרות ולא אבה בנשימה אחת אפילו לא קראה בנשימה א' דקי\"ל כל הראוי לבילה אין בילה מעכבת ויש מי שאומר הוסיף דהוא ג\"כ יהיה רגיל לקרות לא חפצתי אלא בפי' החליצה ס\"ק ס\"ו מדייק הרמב\"ם דכתב מלמדין אותה ואת היבם וכו' דקאי על לא חפצתי לפ\"ז א\"י מה מוסיף היש מי שאומר:","\u0003בנשימה אחת\u0004. ולא יפסיק בין תיבת לא לתיבת אבה דלא אתי למימר לא קאי על תחלת הקרא דאמרה מאן יבמי להקים לאחיו שם בישראל לא כלו' לא מאן אלא אבה יבמי, ולי\"א דצ\"ל ג' תיבות בנשימה אחת שלא תאמר לא אבה זאת היינו המיאון אלא יבמי אף על גב קריאה לא מעכב היינו כשלא קראו כלל משא\"כ בכה\"ג דאתי למטעי גרע טפי ולדעת הרי\"ף ורמב\"ם נראה הא דקריאה אין מעכב היינו כשראוי לקרות כדין אבל אם א\"י לקרות בנשימה אחת ולא קראה מעכב וב\"ח מדייק דא\"צ ליתן ריווח בין האלפי\"ן של לא אבה ואם הוא ערל שפתים ולא יכול לדבר מותר לחלוץ הואיל ואנו יודעין שלשונו כך הוא מהרי\"ק סי' ט\"ו:","\u0003מאן יבמי וכו'\u0004. וכתב בתשובת הרא\"ש והרשב\"א והטור אפי' אם היא מאלו שחולצות ולא מתיבמות או שהוא חפץ לייבם ולא היא מ\"מ קרינן מאן יבמי מאחר לסוף מתרצה לחלוץ:","\u0003י\"א שאם לא דחק וכו'\u0004. כ\"כ הטור בשם הרי\"ף ורמב\"ם דס\"ל המצוה כך הוא שצריך לדחוק רגליו מ\"ה ל\"ש כאן למימר הואיל וראוי לדחוק כשר דהא אכתי לא עביד המצוה והוי כאלו לא חלץ כלל ופסול אף שראוי לחליצה וכ\"כ רי\"ו וכן בש\"ג שם פוסל אם לא דחק רגלו בקרקע:","\u0003וי\"א דוקא שא\"י להלוך\u0004. כבר כתבתי לעיל בשם הרא\"ש דס\"ל כל שיכול להלוך במנעל אין עיכוב בקשירות וכן בסמוך אם קושר למעלה מארכובה כשר לדידיה אם יכול להלוך במנעל ובאמת לא מצינו שום פוסק אשר חולק עליו אף שסתמו דבריהם י\"ל לדינא מודים לדבריו:","\u0003מן הארכוב' ולמעלה\u0004. היינו מה שבין השוק לקוליות ולא מה שבין הארכובה הנמכר עם הראש והשוק וכל השוק נקרא מעל רגלו:","\u0003אינו חולץ\u0004. למ\"ש בכ\"מ וב\"י לדעת הרי\"ף ורמב\"ם לא הוי חליצה כלל ואין פוסלת מיהו לא נ\"מ לדינא דהא לכמה פוסקים חולצין בנקטע רגלו א\"כ בודאי פוסלת:","\u0003וי\"א דבנקטעה רגלו\u0004. איירי אף על גב רגלו עקומה קי\"ל חליצה פסולה משום דשם גרע טפי מאחר דרגל הפוך א\"כ השוק לא נקרא מעל רגלו משא\"כ כשהיה רגל ישרה אז נקרא השוק מעל רגלו מ\"ה אף בנחתך ממנו עדיין נקרא השוק מעל רגלו כ\"כ רש\"י לפ\"ז אם נברא כך ג\"כ חליצה פסולה, מיהו למ\"ש הרא\"ש בשם הראב\"ד הטעם ברגל הפוך כשחולץ הוא חולץ מעל כף רגלו ולא מעל רגלו א\"כ קוטם אף שהוא נברא כך כשר החליצה וכתב הרשב\"א כשנקטעה ליבם רגלו צריך לדחוק בשוקו בקרקע וכן הוא בתוס':","\u0003ולקשרו למטה מארכובה\u0004. אבל אם הקשרים למעלה מארכובתו פסול לפירוש הירושלמי המחלק בין אם הקשרים למטה מארכובה לבין אם הקשרים למעלה מארכובה איירי שנחתך הרגל אבל אם הרגל שלם ומנעל טוב לו ויכול להלוך בו, אז אפילו אם הקשרים למעלה מארכובה כשר ונראה לפ\"ז אפי' אם נחתך הרגל ונשאר משוקו שיכול לנעול מנעול ויכול לקיים כך בשוקו בלי קשירה אף אם קושר למעלה מארכובה כשר כמו אם רגלו שם אלא איירי בענין שנשאר משוקו דבר קטן שא\"י לעמוד בלא קשירה, ועיין תשובת מהר\"א בן ששון סימן קמ\"ב קמ\"ג ביבם שעקום ומהלך בצד רגליו ולפעמים דוחה עקבו בארץ דחולץ ועמ\"ש בשם מהרשד\"מ מאן דמסגי אלחתא חולץ אם אין אח אחר ועיין תשובת רש\"ך ח\"ב סימן נ\"ב דק\"ל בשמיטת רוב עקב הוי חליצה לכן אם נקרע הנעל בצד עקב אף על פי שיכול להלוך בו חליצה פסולה ועיין נ\"י ר\"פ מ\"ח:","\u0003קרעה המנעל וכו'\u0004. פסולה דכתיב וחלצה ואם קרעה כשיעור חליצה כגון רוב עקב אף שחלצה אח\"כ המנעל ל\"מ ועיין תשובת רש\"ך הנ\"ל:","\u0003וחלצה העליון\u0004. הנה לגירס' שלנו מבואר אם חלצה העליון וקם התחתון אז הוי מעל דמעל ולכאורה נראה מעל דמעל הוי חליצה פסולה ופוסלת לכן מ\"ש הרא\"ש והביא בהג\"ה בסמוך אם חולצת שניהם כשירים נראה דאיירי בחולצת שניהם יחדיו בפ\"א דאל\"כ בחולצת העליון הוי מעל דמעל והוי ח\"פ וצריכה לחזור על כל האחים ואם קרע' העליון מ\"מ קם ומחמת הקריעה יכולה לשלוף התחתון לא אפשטה הבעיי' והוי חליצה פסולה ומשמע אפי' קרעה לעליון רוב עקב או רוב המנעל שא\"י להלוך בו מ\"מ כיון דקם וליכא גילוי רגלו קמבעי' ליה דהא אף בנקרע רוב המנעל קי\"ל דהוי חליצה ופוסלת אם כן בכה\"ג יש לומר דהוי כאלו יש כאן מנעל העליון ועיין תשובה הנ\"ל ולרמב\"ם האבעיי' בש\"ס בחלצה העליון וקרעתה לתחתון א\"כ הוי חליצה גילוי כרעא ואפי' עשתה הכל בפ\"א נראה מ\"מ מבעיי' ליה כיון דחליצה היה בעליון, מיהו אם קרעת' לעליון לגמרי וחלצה התחתון הוי חליצה מעלייתא, וכתב המגיד וב\"י דהיה לרמב\"ם גירס' אחרת מיהו באמת יש ללמוד מגירס' שלנו ג\"כ הדין של הרמב\"ם:","\u0003עד שיגיע לפני היבם\u0004. ובתוס' אית' מצוה מן המובחר עד שיגיע לארץ:","\u0003כשרה\u0004. אף אם לא רקקה כלל כשרה אלא קמ\"ל דלא תימא שתרוק עוד אלא די ברקיק' זו, ונראה אף לענין לפסול מן האחין היינו דלא עשתה שום דבר רק רקקה לפני ב\"ד ולא ראו פסולה מן האחין, ותוס' כתבו שם בברייתא החולצת מן הסומא כשרה והקשו מהיכא ס\"ד למעוטי סומא ותירצו מדכתיב לעיני הזקנים וה\"א ה\"ה לעיני היבם א\"נ דכתיב וירקה בפניו הוי כמו לעיני קמ\"ל וב\"ח דייק מדברי תוס' דס\"ל אם הדייני' לא ראו הרוק פסול דהא כתיב לעיני הזקנים ול\"ד כי בוודאי לכ\"ע דרשת דרבא דדיינים צריכים לראות הרוק אינו אלא אסמכתא דהא וירקה קאי על בפניו ולא קאי אלעיל לעיני הזקנים וכוונת התוס' בתירוץ הראשון דה\"א מדכתיב לעיני הזקנים החליצת המנעל ה\"א ה\"ה לעיני היבם ופסול מחמת דלא ראו חליצת המנעל קמ\"ל ולתירוץ ב' ה\"א מדכתיב בפניו הוי כאלו כתיב וירק' לעיניו ואי הוי כתיב וירקה לעיניו פשיטא מעכב אבל בהדיינים דלא כתיב בהו שירקה לעיניהם פשיטא אין עיכוב וא\"ל לתוס' מהיכא ס\"ד לפסול כשהוא סומא מחמת שלא ראה הרקיקה דהא קי\"ל רקיקה אין מעכב וצ\"ל דצריך להיות ראוי לבילה וראוי לראות הרוק ומשמע מתוס' אלו דס\"ל אם היבם סומא אין חולץ לכתחלה ועיין בסעיף מ\"ח מבואר שם לדעת הרמב\"ם וראב\"ד היבם ג\"כ צריך לראות הרוק וכן משמע בתוס' אלו:","\u0003צריכה לרוק\u0004. פ\"א בש\"ס איתא לא עשה ולא כלום וכ\"כ הרמב\"ם משמע דאין פוסל כלל בכה\"ג וכ\"ש בש\"ג ברקקה מחמת שאכלה שום או שאר דברים שמרבים רוק דהני ג\"כ לא עשה ולא כלום דאין פוסל אבל למ\"ש רי\"ו אם נתפזרו והלכו להם כשרה נראה דפוסל מיהו אפילו לא הלכו:","\u0003א\"צ לרוק פ\"א\u0004. כ\"כ הראב\"ד והרא\"ש במקום חליצה א\"צ לרוק פ\"א ומה שקאמר בש\"ס דוקא במוצצת מהני היינו אם רקקה שלא במקום חליצה לענין שתהיה פסולה על האחין כמ\"ש בסעיף מ\"ה וי\"א דוקא במוצצת כ\"כ הרמב\"ם, ואם רקקה בלא מוצצת ולא שותת לא מהני כ\"כ הרשב\"א:","\u0003והיה רוק זב\u0004. כ\"כ הרמב\"ם ומשמע דוקא בזב אבל אם לא זב אפילו לא מוצצת מהני ולא משמע כן משאר פוסקים אלא כיון שהרוק בא מחמת דבר אחר לא הוי רקיקה אפי' לא זב, מיהו במוצצת י\"ל ג\"כ מהני לכ\"ע וכתב בש\"ג אם רקקה מחמת דבר אחר לא הוי רקיקה כלל ולא נפסלת על האחים:","\u0003ג\"פ\u0004. חלוץ הנעל כאבל חלוץ הנעל כמנודה חלוץ הנעל כמורד במצות סיני:","\u0003וי\"א דה\"ה לחליצת חרש\u0004. כן הוא דעת הרמב\"ם דחרש דינו כקטן בכל מקום ועיין במגיד שכתב באריכות ליישב הסוגיא לפי' הרמב\"ם דהא אין ממעט שמאל אלא חליצת קטן דאינו כלום משמע חליצת חרש פוסלת, ועיין בתוס' שכתבו וחרש וחרשת אינן פסולים מחמת דלאו בני דיעה נינהו כיון דהב\"ד עומד ע\"ג ומורה להם וכן קי\"ל בגט אם כתבו וגדול עומד עליהם כשר ואינן פסולים אלא משום דאינן באמר ואמרה לכן דינן כאלם ואלמת ופוסל חליצתם, אבל בדבר שאין הב\"ד עומד ע\"ג ומורה להם אין מעשיו כלום, ובקטן אפי' עומדים ע\"ג אינו כלום איש כתוב בפרשה וכן בשוטה ולא מהני אפי' עומדים ע\"ג כמ\"ש בתוס', ולרמב\"ם בחליצה אפי' עע\"ג לא מהני מעשיו ואין פוסלת כלל ואין להקשות למה בגט אם עומדים ע\"ג מהני לכן פוסק שם אם חש\"ו כתבו התורף והב\"ד עמדו ע\"ג כשר מדאורייתא כמ\"ש בסי' קכ\"ג דאל\"כ היה לו לגזור טופס אטו תורף אם התורף פסול מדאורייתא אלא וודאי בגט כשר מדאוריית' וי\"ל משום דלא נפישי מילי כמו בחליצה גם בגט מוכח דכותב לשמה דהא כותב שמו ושמה וכ\"כ תוספות:","\u0003נתכוין הוא ולא היא וכו'\u0004. עיין בהרא\"ש שם דהקשה למה דקי\"ל יבמה שרקקה תחלוץ למה דחקו בש\"ס למצוא דרך שתהא היבמה אסורה ליבם למה לא אמרו לה שתרוק לפניהם ואז אסורה ליבם, ותירץ משום עובדא דש\"ס היה שהיבם רצה לייבם ואין כוונתו לחלוץ מ\"ה אף אם רקקה לא תפסול את עצמה עליו והביא ראייה מחליצת המנעל לא' מן האחי' דחשש הוא שמא נתכוונו שניהם אבל אם א' לא נתכוין ליכא חשש ומשמע לכאורה מדמדמה שני דינים אלו להדדי ורקיקה איירי בב\"ד א\"כ ה\"ה אם חלצה בב\"ד המנעל ותו לא עשתה כלום נמי בעינן דוקא כשנתכוונו שניהם ונראה מדבריו שם ע\"כ לא אמר בש\"ס אם נתכוין א' מהם הוי חליצה לחומר' אלא דוק' בחליצה גמור' כמ\"ש בש\"ס חלוץ ובכך אתה כונסה והוי חליצה גמורה אלא הוא לא נתכוין אז ק\"ל דהוי חליצה לחומרא אבל בחליצת מנעל לבד או רקיקה אפי' בב\"ד אם נתכוין א' מהם והשני בוודאי לא נתכוין לא הוי חליצה כלל ומותרת לאחים, אלא כשאין ידוע לנו חיישינן שמא כיוונו שניהם ובזה שפיר הגירסא בטור שמא כיוונו לשם חליצה מ\"ה בעובדא דש\"ס הנ\"ל אף אם היתה רקקה לפני ב\"ד וכיוונה היא לחליצה לא הוי חליצה כלל ומותרת לאחים, וכן נראה מפי' תוס' בסוגיא זו דחיישינן שמא כיוונו שניהם וקושי' המקשן והתני' בין התכוון הוא ובין התכוונה היא חליצה פסולה עד שנתכוונו שניהם פירושו עד שידוע לנו שכיוונו שניהם וכאן חיישינן שמא כיוונו ע\"ז תירץ התרצן לחומרא חיישינן שמא כיוונו אבל להתיר לעלמא אינה מותרת עד שידוע לנו שכיוונו ואיירי כל הסוגיא בחשש שמא כוונו שניהם אבל אם ידוע לנו דאחד מהם לא כיוון מותרת לאחים ועיין מ\"ש ב\"ח על הטור ול\"ד אבל למ\"ש בנ\"י איירי הסוגיא דחיישי' שמא כיוונה היא והקשה והתניא עד שנתכוונו שניהם ותירץ לחומר' חיישינן אפי' אם כיוון א' מהם הוי חליצה לחומר' אף דא\"י לנו שאחד מהם התכוין חיישי' שמא אחד כיוון א\"כ אפילו אחד מהם בוודאי לא נתכוון מ\"מ בחליצת המנעל פסולה לאחים אפילו שלא בב\"ד וליישב קושית הרא\"ש למה לא אמרו לה שתרוק ותתכוון לחליצ' ותהא אסורה ליבם יש לומר דס\"ל ברקיקה לא מהני כוונת א' מהם אלא בחליצת מנעל אז חששו חז\"ל דפסולה לאחים אלא לפ\"ז קשה למה ליה להוכיח שם דרקיק' מה שרוקקת בין האחים לא מהני אפי' למפסל דהא אף בב\"ד לא מהני בכוונת א' מהם ומכ\"ש בין האחים וע\"כ בין האחים ליכא חשש שמא כיוונו שניהם דהא כל שקל' וטרי' בש\"ס שמא כיוונה היא אבל על כוונת שניהם ליכא חשש כלל, ודברי הרי\"ף ורמב\"ם פ\"ד דגיטין למ\"ש הנ\"י שכתבו חיישינן שמא נתכוונו, ומ\"ש המחבר שמא כיוונו לשם חליצה משמע דוקא כשיש חשש דכיוונו שניהם נראה שכתב שלא בדקדוק נמצא למדין אם חלצה המנעל שלא בפני ב\"ד וא' מהם לא כוון לחליצה קמפלגי פוסקים הנ\"ל ואם רקקה בב\"ד והוא לא נתכוין להרא\"ש לא מהני כלל ואפשר דשאר פוסקים ג\"כ מודים לזה, ואם חלצה מנעל בב\"ד בלא כוונה כתבתי לדעת הרא\"ש ג\"כ לא מהני אא\"כ במקום חליצה גמורה, מיהו זאת יש לדחות קצת ולומר דכוונת הרא\"ש לדמו' רקיקה בב\"ד בלא נתכוון אחד מהם לחליצת מנעל שלא בב\"ד בלא נתכוון אחד מהם אבל חליצת מנעל בב\"ד אפי' בלא כוונה פוסל:","\u0003בפני ב\"ד\u0004. הטעם הוא משו' רקיקה לית' אלא בסוף יאמרו דכבר חלץ לה מ\"ה דוקא אם רקק' בפני ב\"ד נפסלה מלהתייבם ואם נתכוונו שניהם י\"ל דנפסלה לדעת הרא\"ש ושאר פוסקים אפי' בנתכוונה היא י\"ל דנפסלה וכ\"כ בד\"מ בהגהות פרישה:","\u0003ויש מי שאומר\u0004. דה\"מ בשרקקה רוק לכאורה תמוה דמשמע הפוסקים חולקים ע\"ז ואינו דהא כאן איירי לענין אם היא פסולה לאחים ופשיטא לדעת הפוסקים היינו י\"א בסעיף מ' דס\"ל אפי' במקום חליצה אם לא מצצה לא מהני פשיטא אינה אסורה לאחין ברקקה דם ולא מצצה אפי' לדיעה קמייתא שם הא מבואר לשיטת הר\"ש /הרא\"ש/ דאבוה דשמואל איירי דוקא לעניין פסול לאחים אז בעינן מעורב רוק משא\"כ במקום חליצה אפי' ברקקה דם א\"צ לרוק פעם אחרת א\"כ בדין זה ליכא פלוגתא כלל:","\u0003הסומ' אינו חולץ\u0004. דעת הרמב\"ם וראב\"ד צריך היבם לראות הרוק מ\"ה לכתחלה אינו חולץ אלא לדעת הראב\"ד אם אין אח אלא הוא הוי כדיעבד מאחר שאין תקנה לדבר כמ\"ש בהג\"ה סעיף י\"ב, וצריך ישוב למה בעי שא\"י לעמוד פוסק בפשיטו' דחולץ מיושב וכאן הביא דעת הראב\"ד בשם יש מי שאומר ואפשר בחולה א\"י לייבם ג\"כ וכאן אפשר לייבם ומ\"ש ואם חלץ כשרה כתב המגיד הטעם משום דקי\"ל רקיקה אין מעכב ואין נראה דהא בעינן ראוי לבילה כמ\"ש לעיל בענין קריאה אלא נראה משום דרוש זה דצריך לראות הרוק אינו אלא אסמכתא בעלמא דהא כתיב וירקה בפניו ולא כתיב לעיניו ובפניו היינו נגד פניו אף שהוא אינו רואה עיין בנ\"י ס\"פ מ\"ח דכתב סומא חולץ לכתחלה דא\"צ לראות הרקיקה ונראה בעניין ראיית הרקיקה יש להחמיר לכתחלה וכן אם יש אח אחר יחלוץ האחר ואם אין לו אח אחר יחלוץ זה כדעת הראב\"ד:","\u0003חליצתה פסולה\u0004. הנה במתני' זו יש גירס' מוחלפת לפי גירס' שלנו תנא קטנה שחלצ' תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ודייקו תו' מזה כיון דתני פסולה למה תנא תחלוץ משתגדיל אלא דלא תימא חליצה פסולה מדרבנן להכי תנא תחלוץ משתגדיל יתור לשון לאשמעי' דחליצת קטנה אין כלום כמו חליצת קטן ומזה נשמע למה דקי\"ל בחליצת קטן אין פוסלת כן היא בחליצת קטנה אף על גב דאתמר בש\"ס וחכמים אומרי' איש כתיב בפרשה ולא מקשינן אשה לאיש מ\"מ לפסק הלכה לא קי\"ל כחכמי' לפי המסקנא דרבא אמר שם הלכתא עד שתביא שתי שערות היינו דלא קי\"ל כחכמים בזה וכן הוא בסמ\"ג דף קל\"ז ע\"א והרא\"ש תופס גירס' זו לעיקר מ\"ה מוכח מדבריו דחליצת קטנה אין כלום ואין פוסלת והיינו מ\"ש הטור בשם הרא\"ש דהשוה חליצת קטנה לקטן והיינו נמי כוונת הב\"י לדייק מתו' הנ\"ל דס\"ל חליצת קטנה אינה פוסלת, אף על גב דתוס' כתבו כן לדברי ר\"מ דס\"ל אף חליצת קטן פוסלת מ\"מ מהר\"מ נשמע לחכמים דקי\"ל כוותייהו בזה דחליצת קטן אין פוסל א\"כ בקטנה נמי אין פוסלת דהא נשמע מיתור מתני' דהיקש זה דמקשינן קטנה לקטן הוא מדאורייתא בזה נחו שקטו כל תמיהו' ב\"ח ודרישה על הב\"י וניחא נמי מ\"ש הטור בשם הרא\"ש, והב\"י נמי הבין כן אלא תמיהתו דלא מצינו כן בהרא\"ש מבואר ולהרי\"ף הגירס' אם לא חלצה משתגדיל כשרה ולחכמים דאומרים דלא מקשינן איש לאשה אז אפי' לכתחלה חולצין לקטנה, ומה שמסיים שם והלכתא עד שתבוא שתי שערות היינו לכתחלה ורמב\"ם שכתב חליצתה פסולה נראה דתפס גירס' שלנו ולא כמגיד וליישב קושית תוס' למאי תנא תחלוץ משתגדיל י\"ל בענין אחר אף על גב דהיקש מזה מדרבנן מ\"מ צריכה חליצה אחרת משתגדיל לפ\"ז יש בזה ג' דיעות לשיטת התוס' לחכמי' אין חליצה כלל ואינה פוסלת, ולהרי\"ף בדיעבד כשרה, ולהרמב\"ם פוסלת וצריכה חליצה אחרת אבל מ\"ש המגיד אף לגירסת הרי\"ף למסקנא שם והלכתא עד שתביא ב' שערות היינו אף בדיעבד פוסל' נראה דוחק גדול הוא מאחר לר\"מ ולרבנן חליצה כשרה ואיך יפסוק רבא לא כמאן ועל רמב\"ם לכאור' קשה דפוסק בחרש וחרשת דחליצת' אינה כלום ואין פוסלת וכ' המגיד הטעם משום דקי\"ל בכל התורה חש\"ו שווים מ\"ה אף בחליצה שוים ואין פוסלת כמו בחליצת קטן א\"כ למה חליצת קטנה פוסלת ואי ההיקש אשה לאיש רק מדרבנן א\"כ אף חליצת חרשת פוסלת, צ\"ל איירי בקטנה דיש לה דעת ואז הפסול מדכתיב איש בפרשה ולא קטן אפי' יש לו דעת והיקש אשה לאיש אינו אלא מדרבנן מ\"ה פוסלת משא\"כ חרש וחרשת ושוטה דאין להם דעת מ\"ה אין פוסלים חליצת' כמ\"ש הרמב\"ם שם דין י\"ג בחרש וחרשת שאינן בני דעת, וקטן אפי' יש לו דעת אינו פוסל דתורה מיעטו מדכתיב איש שוב ראיתי בת\"ה סי' רכ\"ה שכתב ג\"כ דגירס' הרמב\"ם כגירסא שלנו:","\u0003וא\"צ לחזור ע\"כ האחין\u0004. הטעם מבואר בת\"ה הואיל לפי גירס' שלנו חליצתה אינו כלום ואין פוסלת א\"כ לא הוי חליצתה פסולה ולגירס' הרי\"ף חליצת קטנה כשירה אף לכתחלה רק טוב לחלוץ משתגדיל מ\"ה א\"צ לחזור ע\"כ האחים כיון ע\"פ הדין חליצה כשרה היא אלא לדעת הרמב\"ם חליצה פסולה היא ודבר דרבנן אזלינן אחר הפוסקים:","\u0003ע\"מ שלא תנשאי\u0004. וא\"ל אף על גב מדין תנאי לא הוי כדבסמוך מכל מקום כיון שהוא סבר שהתנאי קיים נמצא שלא התכוון להתירה וכל שלא התכוון להתירה לא הותר' וי\"ל הוא סובר שהחליצ' זו מתירת' להנשא ולכך התכוון ואינה נאסרת לפי דעתו אלא לפי תנאי והתנאי באמת בטל כיון דא\"י להיות ע\"י שליח כמ\"ש בשם בדק הבית:","\u0003אבל אם יש טענה וכו'\u0004. כתב בד\"מ בשם א\"ז דוק' במקום שיבום קודם והוא הטעתו שיחלוץ לה צריכה ליתן שכרו אבל במקום שחליצ' קודם ואינו רוצה אז אפי' שכר טירח' אין לו, לפ\"ז אם יש לו אשה אז לכ\"ע מ\"ח קודם אין לו אפי' שכר טירח' כמ\"ש בסימן קס\"ה לכאורה נראה לפי פלוגתת הפוסקים אם מצות יבום קודם או מ\"ח כמ\"ש שם א\"כ מחמת הספק הדין לחלוץ א\"כ לעולם אין לו כלום אפי' שכרו דהא לעולם צריך לחלוץ אלא מדברי הטור והמחבר לא משמע כן דהא הביאו פלוגת' זו בסימן קס\"ה מכל מקום כותבין כאן דוק' כשיש לה טענה שצריך לחלוץ משמע אבל משום פסיק' דדינ' דצריך לחלוץ יכול לומר קום לי כהני פוסקים דמ\"י קודם וצריך ליתן שכרו:","\u0003אבל אם נתנה לו מעות\u0004. אבל אם חייבה את עצמה בשטר או בקנין אין מוציאין מיד האשה תשובות רשב\"א שם אף על גב דקי\"ל אם נתן כתב לחבירו א\"י לפטור את עצמו בטענת השטאה כמ\"ש בת\"ה סימן פ\"א ש\"ה דהא ידוע לנו העסק דחייב זה לחלוץ בחנם ומהיכ' תיתי לומר דיתחייב את עצמו בחנם משא\"כ שם דאמרי' מסתמ' אמת הוא שחייב לו כאשר נתן לו כת\"י עליו:","\u0003יש מי שאומר שחליצתה כשרה\u0004. כתב המגיד הרמב\"ם שכתב חלוץ לה שזו מצוה היא וכו' כמ\"ש בסעי' הקודם חולק על זה והמחבר ס\"ל דזה עדיף דאמרי' לו בפי' שיעקור הזיקה משא\"כ שם שסובר בזה יכול לכנוס גם מ\"ש לו ואם תרצה לייבם תייבם עדיין הזיקה קיימת:","\u0003חליצה פסולה הוא\u0004. אף על גב בגט אם מוסר מודעה אז הגט בטל ואין פוסל כלל כמ\"ש בסימן קל\"ד מ\"מ חליצה פוסלת ועיין הטעם בתשובת ריב\"ש סימן תפ\"ב והובא בכ\"מ פ\"ד:","\u0003כותבין לה ב\"ד\u0004. עיין מ\"ש בסי' קל\"ה וכתב זה צריכין לקיים לכ\"ע אף מי שסובר בגט א\"צ קיום משום חומר' שהחמרת בסופו משא\"כ כאן עיין תשובות ריב\"ש:"],"\u0003הלכות חליצה\u0004\n\u0010g0\u0011 מִצְוַת \u0010t0\u0011 חֲלִיצָה בְּג' \u0010g1\u0011 \u0010r0\u0011 דַּיָּנִים יִשְׂרְאֵלִים, \u0010r1\u0011 וְשֶׁלֹּא יִהְיוּ \u0010g2\u0011 קְרוֹבִים זֶה לָזֶה וְלֹא לַיָּבָם וְלַיְבָמָה. \u0010r2\u0011 \u0005 וַאֲפִלּוּ שְׁנַיִם נְשׂוּאִין שְׁתֵּי בְּנוֹת אַחִין, לֹא יִהְיוּ זֶה עִם זֶה. \u0010r3\u0011 אֲבָל שֵׁנִי בִּשְׁלִישִׁי, כָּשֵׁר \u0006 \u0005(ת\"ה סִימָן רכ\"ו)\u0006. \u0010g3\u0011 וַאֲפִלּוּ הֵם \u0010t1\u0011 הֶדְיוֹטוֹת, \u0010c0\u0011 \u0010g4\u0011 רַק שֶׁיֵּדְעוּ לְהַקְרוֹת אֶת הַיָּבָם וְהַיְבָמָה. \u0010g5\u0011 \u0010r4\u0011 וְאִם חָלְצָה בִּפְנֵי עַמֵּי הָאָרֶץ שֶׁאֵינָם יוֹדְעִים לְהַקְרוֹת, כְּשֵׁרָה: \u0010r5\u0011\nנִמְצָא אֶחָד מֵהֶם \u0010c1\u0011 קָרוֹב אוֹ פָּסוּל, \u0010r6\u0011 אוֹ גֵּר, \u0010t2\u0011 פָּסוּל. \u0010c2\u0011 \u0010g6\u0011 וַאֲפִלּוּ הָיָה אָבִיו \u0010t3\u0011 גֵּר וְאִמּוֹ יִשְׂרְאֵלִית, פָּסוּל, עַד שֶׁיְּהֵא אָבִיו וְאִמּוֹ \u0010t4\u0011 מִיִּשְׂרָאֵל. \u0010r7\u0011 \u0005 וְיֵשׁ אוֹמְרִים שֶׁאִם אָבִיו מִיִּשְׂרָאֵל, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם \u0010g7\u0011 סְמַ\"ג)\u0006. \u0010g8\u0011 \u0010r8\u0011 וּמִיהוּ, חֲלִיצָה פְּסוּלָה מִיהָא הָוְיָא לְפָסְלָהּ עַל \u0010g9\u0011 \u0010r9\u0011 הָאַחִים, אֲפִלּוּ בֵּינוֹ לְבֵינָהּ. \u0005 הַגָּה: \u0010r10\u0011 יֵשׁ אוֹמְרִים דְּאָסוּר לִקַּח שָׂכָר מֵחֲלִיצָה, דְּהַנּוֹטֵל שָׂכָר לָדוּן דִּינָיו בְּטֵלִין \u0006 \u0005(ר\"י מִינְץ וּמהרא\"י)\u0006, \u0005 וְכֵן נִרְאֶה בְּעֵינַי. בַּחֲלִיצוֹת, יֵשׁ לִזָּהֵר שֶׁלֹּא יֵשֵׁב בִּשְׁלשָׁה דַּיָּנִים שֶׁיּוֹשְׁבִים לַחֲלֹץ מִי שֶׁנּוֹטֵל שָׂכָר, \u0010r11\u0011 דַּהֲרֵי בָּעִינָן בֵּית דִּין כָּשֵׁר \u0010r12\u0011 מִדְּאוֹרָיְתָא, וְעַיֵּן בְּחשֶׁן הַמִּשְׁפָּט סִימָן ט' אֵיזֶה שָׂכָר מֻתָּר לַדַּיָּן לְקַבֵּל. וַאֲפִלּוּ בָּזֶה נִרְאֶה לִי לְהַחֲמִיר אִם נוֹטֵל שָׂכָר מִן הַחֲלִיצָה, מִשּׁוּם מַרְאִית הָעַיִן, כְּמוֹ שֶׁמַּחֲמִירִין לְעִנְיַן קְרוֹבִים וּבִשְׁאָר דְּבָרִים לְעִנְיַן בֵּית דִּין שֶׁל חֲלִיצָה, יוֹתֵר מִבִּשְׁאָר בֵּית דִּין. וְרָאִיתִי וְשָׁמַעְתִּי שֶׁהָרַב נוֹטֵל שָׂכָר הַרְבֵּה מִן הַחֲלִיצָה, וְסוֹמֵךְ עַצְמוֹ בַּמֶּה שֶׁמּוֹכֵר לוֹ סַנְדָּל שֶׁל חֲלִיצָה; וְקֻלָּא גְּדוֹלָה הִיא בְּעֵינַי, וְשׁוֹמֵר נַפְשׁוֹ יִרְחַק מִזֶּה. וְלֹא דָּמֵי לְמַה שֶּׁעֵדֵי הַגֵּט נוֹטְלִין שָׂכָר מִטַּעַם שֶׁכָּתַבְתִּי לְעֵיל סִימָן ק\"ל, גַּם הָרַב הַמְסַדֵּר הַגֵּט כְּמוֹ שֶׁכָּתַבְתִּי לְעֵיל בְּסֵדֶר הַגֵּט סָעִיף ד', כִּי אוֹתָן הַטְּעָמִים אֵינָם שַׁיָּכִים בַּחֲלִיצָה \u0006 \u0005(הַכֹּל \u0010c3\u0011 \u0010g10\u0011 דַּעַת עַצְמוֹ)\u0006:\nלְכַתְּחִלָּה מִצְוָה שֶׁיּוֹסִיפוּ שְׁנַיִם עַל \u0010t5\u0011 הַג', \u0010g11\u0011 \u0010r13\u0011 וַאֲפִלּוּ הַשְּׁנַיִם הֵם עַמֵּי הָאָרֶץ. \u0010r14\u0011 \u0005 חָלְצוּ בְּג' חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0010r15\u0011 \u0005 וְאֵלּוּ הַשְּׁנַיִם שֶׁמּוֹסִיפִים, לֹא יִהְיוּ קְרוֹבִים \u0010t6\u0011 \u0006 \u0005 וּפְסוּלִים; \u0010r16\u0011 וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד כָּשֵׁר \u0006 \u0005(ב\"י)\u0006: \u0010g12\u0011\nצְרִיכִים \u0010c4\u0011 \u0010t7\u0011 הַדַּיָּנִים לְכַתְּחִלָּה לִקְבֹּעַ מָקוֹם לוֹמַר: נֵלֵךְ לִמְקוֹם פְּלוֹנִי \u0010r17\u0011 לַחֲלֹץ. \u0005 מִיהוּ, אִם חָלְצָה בְּלֹא קְבִיעוּת מָקוֹם, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006: \u0010g13\u0011\nיֵשׁ קֹבְעִים מָקוֹם בּוֹ בַּיּוֹם, \u0010g14\u0011 \u0010t8\u0011 \u0010r18\u0011 וְיֵשׁ אוֹמְרִים לִקְבֹּעַ בַּיּוֹם שֶׁלְּפָנָיו: \u0010g15\u0011\nאֵין חֲלִיצָה כְּשֵׁרָה אֶלָּא בַּיּוֹם. חָלְצָה בַּלַּיְלָה, חֲלִיצָתָהּ פְּסוּלָה: \u0010g16\u0011\nאֵין חוֹלְצִין בְּשַׁבָּתוֹת וְלֹא בְּיָמִים טוֹבִים; \u0010g17\u0011 \u0010r19\u0011 וּמִיהוּ, בְּחֹל הַמּוֹעֵד, שַׁפִּיר דָּמֵי. \u0010g18\u0011 \u0010r20\u0011 \u0005 וְיֵשׁ אוֹמְרִים דְּאֵין לַחֲלֹץ בְּעֶרֶב שַׁבָּת וְעֶרֶב יוֹם טוֹב, וְכֵן נוֹהֲגִין: \u0010g19\u0011 \u0006\nצָרִיךְ שֶׁיַּכִּירוּ שֶׁהוּא אֲחִי \u0010t9\u0011 הַמֵּת, \u0010r21\u0011 וְשֶׁהָיָה בְּעוֹלָמוֹ, \u0010r22\u0011 וְזֹאת הִיא אֵשֶׁת הַמֵּת; וַאֲפִלּוּ אֵין \u0010g20\u0011 כָּאן אֶלָּא עֵד אֶחָד שֶׁמֵּעִיד עֲלֵיהֶם, \u0010r23\u0011 אוֹ אֲפִלּוּ קָרוֹב אוֹ \u0010t10\u0011 אִשָּׁה \u0010r24\u0011 אוֹ עֶבֶד אוֹ שִׁפְחָה אוֹ קָטָן \u0010g21\u0011 שֶׁהוּא מַכִּיר וְנָבוֹן, נֶאֱמָן בְּכָךְ: \u0010g22\u0011 \u0010r25\u0011\nצָרִיךְ שֶׁיֵּדְעוּ הַדַּיָּנִים שֶׁיֵּשׁ צ' יוֹם מִשֶּׁמֵּת הַבַּעַל, חוּץ מִיּוֹם שֶׁמֵּת בּוֹ וְיוֹם שֶׁחוֹלֶצֶת בּוֹ: \u0010g23\u0011 \u0010r26\u0011\nצָרִיךְ שֶׁיֵּדְעוּ \u0010g24\u0011 שֶׁהַיָּבָם \u0010c5\u0011 \u0010r27\u0011 בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, \u0010r28\u0011 וְהַיְבָמָה בַּת י\"ב שָׁנָה וְיוֹם אֶחָד, \u0010r29\u0011 וְשֶׁהֵבִיאוּ שְׁתֵּי שְׂעָרוֹת \u0010r30\u0011 אַחַר שֶׁהִגִּיעוּ לִזְמַנִּים אֵלּוּ. \u0010g25\u0011 \u0010r31\u0011 וְאִם יֵשׁ לַיְבָמָה \u0010c6\u0011 דַּדִּים גְּדוֹלִים, אֵין צָרִיךְ לִבְדֹּק אַחַר \u0010t11\u0011 הַשְּׂעָרוֹת. \u0010g26\u0011 \u0010r32\u0011 וְכֵן אִם הַיָּבָם \u0010c7\u0011 נִתְמַלֵּא זְקָנוֹ, אֵין צָרִיךְ לִבְדֹּק אַחַר הַשְּׂעָרוֹת. וּמִשְׁפָּט שְׁתֵּי הַשְּׂעָרוֹת וּבְדִיקָתָן, נִתְבָּאֵר בְּסִימָן קנ\"ה \u0010g27\u0011 \u0005(סָעִיף ט\"ו)\u0006:\nאֵין סוֹמְכִין בְּמִנְיַן הַשָּׁנִים לֹא \u0010t12\u0011 עַל פִּי קְרוֹבִים וְלֹא עַל פִּי נָשִׁים, \u0010r33\u0011 אֶלָּא עַל פִּי עֵדִים כְּשֵׁרִים לְהָעִיד. \u0010c8\u0011 \u0010g28\u0011 \u0010r34\u0011 וְיֵשׁ אוֹמְרִים שֶׁאִם הֻחְזַק בְּעֵינֵי הַשְּׁכֵנִים, שֶׁלֹּא עַל פִּי הָאָב, שֶׁבָּא לִכְלַל שָׁנִים, \u0010r35\u0011 אוֹ שֶׁיָּצָא עָלָיו קוֹל שֶׁבָּא לִכְלַל שָׁנִים, נֶאֱמָנִים לְהַחֲזִיקָן בִּגְדוֹלִים, \u0010r36\u0011 אִם בְּדָקוּם וּמָצְאוּ לָהֶם שְׁתֵּי שְׂעָרוֹת, \u0010r37\u0011 \u0005 אֲבָל לֹא מְהַנֵּי שֶׁרָאוּ אוֹתוֹ שֶׁעָלָה לְסֵפֶר תּוֹרָה אוֹ שֶׁהָיָה שְׁלִיחַ צִבּוּר \u0006 \u0005(מָרְדְּכַי פֶּרֶק מִצְוַת חֲלִיצָה)\u0006. \u0010g29\u0011 וַאֲפִלּוּ בְּלֹא חֶזְקַת הַשְּׁכֵנִים, \u0010g30\u0011 אִם יֵשׁ לָהֶם רִבּוּי שְׂעָרוֹת, \u0010r38\u0011 אוֹ שֶׁהֵם אֲרֻכּוֹת כְּמוֹ שֶׁרְגִילוֹת לְאִישׁ גָּדוֹל וּלְאִשָּׁה גְּדוֹלָה, חֲזָקָה שֶׁבָּאוּ לִכְלַל שָׁנִים, וְחוֹלְצִים. \u0010c9\u0011 וְעַל זֶה סוֹמְכִים שֶׁלֹּא לִבְדֹּק אִם יֵשׁ גֻּמּוֹת בַּשְּׂעָרוֹת, מֵאַחַר שֶׁיֵּשׁ רִבּוּי שְׂעָרוֹת אוֹ שֶׁהֵם \u0010g31\u0011 אֲרֻכּוֹת. וְאִם הֵם גְּדוֹלִים בְּקוֹמָה, יֵשׁ לִסְמֹךְ שֶׁהֵם גְּדוֹלִים, אֲפִלּוּ לֹא הֵבִיאוּ כִּי אִם שְׁתֵּי שְׂעָרוֹת. \u0010c10\u0011 \u0010r39\u0011 \u0005 וְאִם יֵשׁ לַיְבָמָה בָּנִים, הֲרֵי הֵם כְּסִימָנִים \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי \u0010g32\u0011 דִּיבָמוֹת)\u0006: \u0010g33\u0011 \u0010r40\u0011\nיֵשְׁבוּ \u0010t13\u0011 הַדַּיָּנִים כְּמוֹ שֶׁצְּרִיכִים לֵישֵׁב בְּדִין, \u0010r41\u0011 וְיַעַמְדוּ לִפְנֵיהֶם הַיָּבָם וְהַיְבָמָה, \u0010c11\u0011 שֶׁמִּצְוַת חֲלִיצָה \u0010g34\u0011 \u0010t14\u0011 לְכַתְּחִלָּה, מְעֻמָּד. \u0005 הַגָּה: \u0010r42\u0011 אֲבָל בְּדִיעֲבַד, אִם חָלְצָה מְיֻשָּׁב, כָּשֵׁר \u0010g35\u0011 (טוּר)\u0006. \u0010r43\u0011 וְכֵן חוֹלֶה שֶׁלֹּא יוּכַל לַעֲמֹד, יוּכַל \u0010r44\u0011 לַחֲלֹץ מְיֻשָּׁב, דְּכָל דָּבָר שֶׁאֵין לוֹ תַּקָּנָה חָשׁוּב דִּיעֲבַד \u0005(פִּסְקֵי מהרא\"י סִימָן ק\"צ)\u0006. \u0005 וְעַיֵּן לְקַמָּן סָעִיף ס\"ד בְּפֵרוּשׁ סֵדֶר \u0010g36\u0011 חֲלִיצָה: \u0006\nמֵאַחַר שֶׁמַּסְכִּים הַיָּבָם לַחֲלֹץ, יֹאמְרוּ לוֹ לְבַטֵּל כָּל מוֹדָעוֹת שֶׁמָּסַר, כְּמוֹ גַּבֵּי גֵּט; \u0010r45\u0011 שֶׁאִם מָסַר מוֹדָעָא תְּחִלָּה, הַחֲלִיצָה פְּסוּלָה. \u0005 הַגָּה: \u0010r46\u0011 וְכֵן אִם כָּפוּ אוֹתוֹ לַחֲלֹץ, דִּינוֹ כְּמוֹ בְּגֵט. וְעַיֵּן לְעֵיל סִימָן קל\"ד. \u0010r47\u0011 וְאַף עַל גַּב דְּיֵשׁ אוֹמְרִים מִצְוַת חֲלִיצָה קוֹדֵם, \u0010r48\u0011 וְאִם כֵּן כָּל כְּפִיָּה הִיא בַּדִּין, \u0010r49\u0011 מִכָּל מָקוֹם אֵין לָכֹף אֶלָּא בְּמָקוֹם שֶׁנִּתְבָּאֵר סִימָן קס\"ה: \u0010g37\u0011 \u0006\nלְכַתְּחִלָּה צָרִיךְ לָתֵת לַיָּבָם מִנְעַל הַחֲלִיצָה \u0010t15\u0011 בְּמַתָּנָה. \u0010g38\u0011 \u0010r50\u0011 וְיֵשׁ אוֹמְרִים שֶׁיְּהַלֵּךְ בּוֹ מְעַט, כְּדֵי שֶׁיְּהֵא נִרְאֶה כְּשֶׁלּוֹ. \u0005 וְאִם לֹא נָתְנוּ לוֹ, כָּשֵׁר \u0010g39\u0011 \u0010g40\u0011 \u0006 \u0005(טוּר)\u0006:\nהַמִּנְעָל צָרִיךְ שֶׁיִּהְיֶה כֻּלּוֹ שֶׁל עוֹר. \u0010r51\u0011 לְפִיכָךְ, צָרִיךְ לְתָפְרוֹ \u0005 כָּל תְּפִירוֹתָיו \u0006 בְּעוֹר לְכַתְּחִלָּה. \u0005 וְכֵן נוֹהֲגִין; \u0010c12\u0011 \u0010r52\u0011 וְיֵשׁ פּוֹסְלִין אַף בְּדִיעֲבַד \u0006 \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006. \u0005 דְּלֹא כְּיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה שֶׁכָּל הַמִּנְעָלִים תְּפוּרִין בְּפִשְׁתָּן צָרִיךְ לִהְיוֹת תָּפוּר בְּפִשְׁתָּן \u0006 \u0005(בְּסֵדֶר ר\"י מִינְץ בְּשֵׁם ר' שְׁמַרְיָה)\u0006. \u0010c13\u0011 \u0010r53\u0011 אֲבָל רְצוּעוֹתָיו אֵין צָרִיךְ שֶׁיִּהְיוּ \u0010t16\u0011 מֵעוֹר. \u0010r54\u0011 \u0005 וְיֵשׁ אוֹמְרִים דְּגַם רְצוּעוֹתָיו מֵעוֹר \u0010t17\u0011 \u0006 \u0005(נִמּוּקֵי יוֹסֵף)\u0006, \u0005 וְכֵן \u0006 \u0005 נוֹהֲגִין: \u0010c14\u0011 \u0010g41\u0011 \u0010r55\u0011 \u0006\nצָרִיךְ \u0010r56\u0011 לְכַתְּחִלָּה שֶׁיְּהֵא הָעוֹר קָשֶׁה קְצָת, שֶׁיְּהֵא דּוֹמֶה קְצָת לְסַנְדָּל. \u0010g42\u0011 \u0010r57\u0011 וְיֵשׁ אוֹמְרִים שֶׁהַתְּפִירָה תִּהְיֶה מִבַּחוּץ. \u0010g43\u0011 \u0010r58\u0011 יֵשׁ אוֹמְרִים מִבִּפְנִים, כְּדֵי שֶׁיְּהֵא דּוֹמֶה לְסַנְדָּל. \u0010g44\u0011 \u0010r59\u0011 וְיֵשׁ אוֹמְרִים שֶׁלֹּא יְהֵא בֶּגֶד אוֹ עוֹר מִבִּפְנִים וְתָפְרוֹ בּוֹ. \u0010g45\u0011 \u0010r60\u0011 וְיֵשׁ אוֹמְרִים שֶׁעוֹשִים אוֹתוֹ מֵחֲתִיכָה אַחַת, כְּדֵי שֶׁיְּהֵא דּוֹמֶה גַּם בָּזֶה לְסַנְדָּל. \u0005 הַגָּה: \u0010r61\u0011 אֲבָל נָהֲגוּ לַחֲלֹץ לְכַתְּחִלָּה בְּמִנְעָל שֶׁהוּא תָּפוּר מִבַּחוּץ, וְגַם שֶׁהוּא מִשְּׁנֵי חֲתִיכוֹת, דְּהַיְנוּ שֶׁהַתַּחְתּוֹן שֶׁלּוֹ שֶׁקּוֹרִין שׁול\"א הוּא חֲתִיכָה אַחֶרֶת. \u0010r62\u0011 וְגַם הָרְצוּעוֹת הֵם חֲתִיכָה אַחֶרֶת תְּפוּרִין בּוֹ. וְיִזָּהֲרוּ שֶׁלֹּא תִּהְיֶה הָעוֹר שֶׁל הַסַּנְדָּל מְשׁוּחָה בְּשֶׁמֶן \u0010t18\u0011 \u0006 \u0005 לְרַכְּכוֹ \u0006 \u0005(בִּסְדָרִים)\u0006: \u0010g46\u0011 \u0010r63\u0011\nיֵשׁ אוֹמְרִים שֶׁלְּכַתְּחִלָּה עוֹשִׂין אוֹתוֹ מֵעוֹר בְּהֵמָה טְהוֹרָה. \u0010r64\u0011 \u0005 גַּם הָרְצוּעוֹת וְהַקְּרָסִים שֶׁבּוֹ, גַּם רְצוּעוֹת הַתְּפִירָה \u0006 \u0005(כ\"כ בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006, \u0005 וְכֵן נוֹהֲגִין: \u0010c15\u0011 \u0010g47\u0011 \u0010r65\u0011 \u0006\nיִהְיוּ בּוֹ שְׁתֵּי רְצוּעוֹת \u0010t19\u0011 לְקָשְׁרוֹ בָּהֶם, אַחַת בְּצַד זֶה וְאַחַת בְּצַד זֶה. \u0010g48\u0011 \u0010r66\u0011 וְיֵשׁ אוֹמְרִים שֶׁרְצוּעוֹת אֵלּוּ יִהְיוּ לְבָנוֹת. \u0010r67\u0011 \u0005 וְגַם רְצוּעוֹת הַתְּפִירָה יִהְיוּ לְבָנִים. \u0010r68\u0011 אֲבָל הַשְׁאָר, הַכֹּל שָׁחוֹר מִבַּחוּץ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּיבָמוֹת)\u0006, \u0005 וְכֵן \u0010r69\u0011 נוֹהֲגִים. אֲבָל מִבִּפְנִים, אֵין לָחוּשׁ. וְאִם הֻשְׁחֲרוּ הָרְצוּעוֹת מֵחֲמַת זִקְנָה, אֵין לְהַקְפִּיד \u0006 \u0005(פִּסְקֵי מהרא\"י סִימָן ר\"ה)\u0006, \u0005 וְכֵן נוֹהֲגִין. \u0010r70\u0011 וְיִהְיוּ הָרְצוּעוֹת אֲרֻכּוֹת, שֶׁיּוּכַל לִכְפֹּל כָּל אַחַת שְׁתֵּי פְּעָמִים \u0006 \u0005(כָּל בּוֹ)\u0006: \u0010g49\u0011 \u0010r71\u0011\nיַעֲשׂוּ בּוֹ כְּמִין קֶשֶׁר, שֶׁקּוֹרִים חֻמַרְתָּא, בַּצַּד הָאֶחָד, שֶׁיִּכָּנֵס בַּנֶּקֶב שֶׁבַּצַּד הָאַחֵר כְּדֵי לְהַדְּקוֹ יָפֶה. \u0010g50\u0011 \u0010r72\u0011 וְיֵשׁ אוֹמְרִים שֶׁיַּעֲשׂוּ שְׁלשָׁה קְשָׁרִים בְּעִנְיָן זֶה, וּלְפָחוֹת שְׁתַּיִם. \u0005 הַגָּה: וְנוֹהֲגִים לַעֲשׂוֹת \u0010r73\u0011 שְׁלשָׁה. וְלֹא יִהְיוּ הַקְּשָׁרִים מִן הַמִּנְעָל עַצְמוֹ, אֶלָּא רְצוּעָה אַחֶרֶת מְחֻבֶּרֶת בְּרֹאשׁ הַמִּנְעָל. וְכֵן יַעֲשֶׂה הַקְּרָסִים שֶׁבַּצַּד הַשֵּׁנִי \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006 \u0005 וְכֵן נוֹהֲגִין. וְיִתְפֹּר אֵלּוּ הַלּוּלָאוֹת וְהַקְּרָסִים \u0010t20\u0011 \u0006 \u0005 מִבַּחוּץ, וְלֹא מִבִּפְנִים, וְכֵן נוֹהֲגִין: \u0010g51\u0011 \u0010r74\u0011 \u0006\nיֵשׁ אוֹמְרִים שֶׁלֹּא יִהְיֶה לוֹ לָשׁוֹן כְּמוֹ שֶׁרְגִילִים לַעֲשׂוֹת בְּמִנְעָלִים, \u0010c16\u0011 כְּדֵי שֶׁלֹּא יְהֵא מֵעַל \u0010t21\u0011 דְּמֵעַל. \u0005 הַגָּה: יֵשׁ אוֹמְרִים לִתְפֹּר שָׂפָה סְבִיב הַמִּנְעָל לְמַעְלָה \u0006 \u0005(ר\"י מִינְ\"ץ בְּשֵׁם ראבי\"ה)\u0006, \u0005 וְלֹא נָהֲגוּ כֵּן. \u0010r75\u0011 וְיִזָּהֵר לְתָפְרוֹ בִּתְפִירוֹת \u0010g52\u0011 תְּכוּפוֹת זוֹ לָזוֹ \u0006 \u0005(בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006. \u0010r76\u0011 \u0005 וְעוֹשִׂין אָזְנֵי הַמִּנְעָל קְצָרִים, שֶׁלֹּא יִהְיוּ הַלּוּלָאוֹת וְהַקְּרָסִים עַל הַמִּנְעָל, רַק עַל הָרֶגֶל, שֶׁלֹּא יִהְיֶה מֵעַל דְּמֵעַל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006: \u0010g53\u0011 \u0010r77\u0011\nיְהֵא עָשׂוּי לְצוּרַת רֶגֶל \u0010t22\u0011 יְמָנִית, \u0010g54\u0011 וְיִנְעֲלוֹ בְּרַגְלוֹ הַיְמָנִית; \u0010g55\u0011 וְיִהְיֶה לְמִדַּת \u0010t23\u0011 רַגְלוֹ, שֶׁלֹּא יְהֵא גָּדוֹל עַד שֶׁאֵין רָאוּי לֵילֵךְ בּוֹ, \u0010r78\u0011 וְלֹא יִהְיֶה קָטָן \u0010r79\u0011 עַד שֶׁאֵינוֹ מְכַסֶה רֹב הָרֶגֶל. וְלֹא יִהְיֶה קָרוּעַ עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ: \u0010g56\u0011 \u0010r80\u0011\nחָלְצָה בְּסַנְדָּל שֶׁל עֵץ \u0010r81\u0011 אוֹ שֶׁל שַׁעַם \u0010c17\u0011 שֶׁאֵינָם מְחֻפִּים עוֹר, \u0010r82\u0011 אוֹ בְּרֶגֶל שְׂמֹאל, \u0010r83\u0011 אוֹ שֶׁהָיָה מִנְעָל גָּדוֹל עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, אוֹ קָטָן שֶׁאֵינוֹ מְכַסֶה רֹב רַגְלוֹ, \u0010r84\u0011 אוֹ קָרוּעַ שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, \u0010r85\u0011 אוֹ בְּסַנְדָּל \u0010c18\u0011 שֶׁאֵין לוֹ \u0010t24\u0011 עָקֵב, \u0010r86\u0011 אוֹ \u0010c19\u0011 בְּאַנְפִּלְיָא שֶׁל בֶּגֶד, חֲלִיצָתוֹ \u0010g57\u0011 פְּסוּלָה. \u0010c20\u0011 \u0010r87\u0011 \u0005 הָיָה שֶׁל עֵץ וּמְחֻפֶּה עוֹר, \u0010r88\u0011 אוֹ שֶׁבֶּגֶד פִּשְׁתָּן תָּפוּר בִּפְנִים, \u0010r89\u0011 אוֹ \u0010g58\u0011 שֶׁחָלַץ בְּמִנְעָל שֶׁל שְׂמֹאל \u0010g59\u0011 בְּיָמִין, כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006: \u0010c21\u0011 \u0010g60\u0011\nמִנְעָל שֶׁל עוֹבְדֵי אֶלִילִים שֶׁמַּנִּיחִים אוֹתוֹ לְרַגְלֵי הַצּוּרָה וּמְהַלְּכִין אוֹתָהּ בּוֹ, \u0010g61\u0011 לֹא תַּחֲלֹץ בּוֹ; וְאִם חָלְצָה, חֲלִיצָתָהּ כְּשֵׁרָה. אֲבָל בְּשֶׁל \u0010c22\u0011 \u0010g62\u0011 תִּקְרֹבֶת עֲבוֹדָה זָרָה, אוֹ שֶׁל עִיר הַנִּדַּחַת, אוֹ \u0010g63\u0011 שֶׁנַּעֲשֵׂית לְתַכְרִיכֵי הַמֵּת, אִם חָלְצָה, חֲלִיצָתָהּ \u0010g64\u0011 \u0010r90\u0011 פְּסוּלָה:\nשׁוֹלֵט בִּשְׁתֵּי רַגְלָיו, וְכֵן הִיא בִּשְׁתֵּי יָדֶיהָ, יַעֲשׂוּ בְּשֶׁל יָמִין. \u0010r91\u0011 \u0005 וְאִם הִיא אִטֶּרֶת יָד, תַּעֲשֶׂה בְּיָמִין דִּידַהּ, שֶׁהוּא שְׂמֹאל כָּל אָדָם \u0006 \u0005(טוּר בְּשֵׁם י\"א)\u0006: \u0010r92\u0011\nאִטֵּר בְּרַגְלוֹ, \u0010c23\u0011 \u0010g65\u0011 \u0010r93\u0011 יֵשׁ אוֹמְרִים שֶׁחוֹלֵץ \u0010t25\u0011 בִּשְׁתֵּיהֶם, בְּמִנְעָל שֶׁל יָמִין בְּיָמִין, וּבְמִנְעָל שֶׁל שְׂמֹאל בִּשְׂמֹאל. \u0010g66\u0011 \u0010r94\u0011 וְיֵשׁ מִי שֶׁנִּסְתַּפֵּק לוֹמַר שֶׁאֵין לוֹ תַּקָּנָה. \u0005 וְנָהֲגוּ כַּסְּבָרָא הָרִאשׁוֹנָה, וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף מ': \u0010g67\u0011 \u0010r95\u0011 \u0006\nיִנְעַל הַמִּנְעָל עַל רַגְלוֹ כְּשֶׁהוּא יָחֵף, וְלֹא עַל בָּתֵּי \u0010c24\u0011 שׁוֹקַיִם, שֶׁלֹּא יְהֵא מֵעַל \u0010t26\u0011 דְּמֵעַל. \u0010r96\u0011 וּמִטַּעַם זֶה יֵשׁ מְדַקְדְּקִים שֶׁלֹּא יְהֵא טִיט דָּבוּק בַּמִּנְעָל מִבִּפְנִים, וְגַם מִטַּעַם זֶה \u0010g68\u0011 יֵשׁ מַצְרִיכִים \u0010t27\u0011 לִרְחֹץ רַגְלוֹ הַיְמָנִית יָפֶה יָפֶה: \u0010g69\u0011\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהַיָּבָם קוֹשֵׁר כְּנַף הַמִּכְנָסַיִם לְמַעְלָה מִשּׁוֹקוֹ, \u0005 כְּדֵי שֶׁיִּרְאוּ הַדַּיָּנִים הֵיטֵב שֶׁאֵין דָּבָר בֵּין רַגְלוֹ וּבֵין מִנְעָלוֹ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006: \u0010g70\u0011\nיִנְעַל הַמִּנְעָל \u0010r97\u0011 וְיִכְרֹךְ הָרְצוּעוֹת סָבִיב לַמִּנְעָל בְּרַגְלוֹ, \u0010r98\u0011 וְיִקְשֹׁר שְׁנֵיהֶם יַחַד \u0010r99\u0011 שְׁנֵי קְשָׁרִים זֶה עַל זֶה, \u0010r100\u0011 \u0005 וְאַל יְהַדֵּק קֶשֶׁר הַשֵּׁנִי בְּחֹזֶק, כְּדֵי שֶׁתּוּכַל לְהַתִּירוֹ בְּיָמִין \u0006 \u0005(כֵּן עָשָׂה מַהֲרִי\"ל וְכֵן מַשְׁמַע בַּסְמַ\"ג)\u0006, \u0010g71\u0011 וַעֲנִיבָה עֲלֵיהֶם. \u0010r101\u0011 וְצָרִיךְ שֶׁיִּהְיֶה הַקֶּשֶׁר עַל בְּשַׂר שׁוֹקוֹ, וְלֹא עַל אָזְנֵי הַמִּנְעָל, \u0010g72\u0011 לְכָךְ צָרִיךְ שֶׁיַּחְתֹּךְ בַּמִּנְעָל לְפָנָיו וּלְאַחֲרָיו כְּמוֹ פְּגִימָה, כְּדֵי שֶׁתְּהֵא הָרְצוּעָה הַחוֹזֶרֶת דְּבוּקָה מַמָּשׁ עַל רַגְלוֹ יָחֵף. \u0010g73\u0011 \u0010r102\u0011 וִיסַבֵּב הָרְצוּעוֹת פַּעֲמַיִם \u0010r103\u0011 סָבִיב לַשּׁוֹק, עַד שֶׁיָּשׁוּבוּ רָאשֵׁי הָרְצוּעוֹת \u0010g74\u0011 \u0005(עַל הַשּׁוֹק לְפָנִים)\u0006 \u0005 מִמַּעַל לְאָזְנֵי הַמִּנְעָל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006, \u0010c25\u0011 עַל הַשּׁוֹק \u0010t28\u0011 עָרֹם. וְיִהְיוּ הַקְּשָׁרִים \u0010g75\u0011 עַל פְּנֵי הַשּׁוֹק וְלֹא מֵאֲחוֹרָיו. \u0010g76\u0011 וְיַכְנִיס הַקְּשָׁרִים \u0010g77\u0011 \u0005(שֶׁבְּאָזְנוֹ)\u0006 בַּנְּקָבִים שֶׁבְּאָזְנוֹ \u0010c26\u0011 \u0010g78\u0011 הַשְּׁנִיָּה:\nמְלַמְּדִין אוֹתָהּ וְאֶת הַיָּבָם לִקְרוֹת, עַד שֶׁהוּא וְהִיא יִהְיוּ רְגִילִים, וְתִהְיֶה יְכוֹלָה לִקְרוֹת \"לֹא אָבָה\" \u0010c27\u0011 \u0010t29\u0011 \u0005(דְּבָרִים כה, ז)\u0006 בִּנְשִׁימָה אַחַת. \u0010g79\u0011 \u0010r104\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁצָּרִיךְ גַּם כֵּן שֶׁהוּא יִהְיֶה יָכוֹל לוֹמַר: \"לֹא חָפַצְתִּי\" \u0005(דברים כה, ח)\u0006 בִּנְשִׁימָה אַחַת. \u0010g80\u0011 \u0010r105\u0011 וְיִקְרְאוּ אוֹתָהּ, וְהִיא \u0010g81\u0011 מְעֻמָּד, בִּלְשׁוֹן \u0010c28\u0011 הַקֹּדֶשׁ: \"מֵאֵן יְבָמִי לְהָקִים לְאָחִיו שֵׁם בְּיִשְׂרָאֵל לֹא אָבָה יַבְּמִי\" \u0005(דְּבָרִים כה, ז)\u0006 וְיִקְרְאוּ אוֹתוֹ, וְהוּא מְעֻמָּד; לֹא חָפַצְתִּי לְקַחְתָּהּ \u0010r106\u0011 \u0005(דְּבָרִים כה, ח)\u0006 \u0005 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ שֶׁיְּדַקְדְּקוּ עִמָּהּ שֶׁהִיא תִּקְרָא: \u0010r107\u0011 \"לֹא אָבָה יַבְּמִי\", בִּנְשִׁימָה אַחַת \u0006 \u0005(טוּר)\u0006. \u0005 וְכֵן הוּא הַמִּנְהָג. \u0010r108\u0011 גַּם בְּ\"לֹא חָפַצְתִּי לְקַחְתָּהּ\". וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ס\"ו: \u0010g82\u0011 \u0010r109\u0011 \u0006\nיַעֲמֹד אֵצֶל כֹּתֶל אוֹ אֵצֶל עַמּוּד וְיִשָּׁעֵן \u0010t30\u0011 בּוֹ, \u0010g83\u0011 וְיִדְחֹק רַגְלוֹ בַּקַּרְקַע, \u0010r110\u0011 וְתַתִּיר קִשְׁרֵי הַמִּנְעָל, \u0010g84\u0011 וְאַחַר כָּךְ הַקְּרָסִים, \u0010r111\u0011 הַכֹּל בְּיָדָהּ הַיְמָנִית, וְתִתְפֹּס רַגְלוֹ בְּיָדָהּ הַשְּׂמָאלִית, וְתִהְיֶה שׁוֹמֶטֶת הַמִּנְעָל מִן הָעָקֵב בְּיָדָהּ הַיְמָנִית, וְתַחֲלֹץ כָּל הַמִּנְעָל גַּם בְּיָדָהּ הַיְמָנִית, \u0010g85\u0011 \u0010r112\u0011 וְכָל זֶה בְּלִי סִיּוּעַ יָד שְׂמָאלִית. \u0010g86\u0011 \u0010r113\u0011 וּבְכָל זֶה לֹא תִּהְיֶה יוֹשֶׁבֶת, וְלֹא עַל בִּרְכֶּיהָ, אֶלָּא תִּהְיֶה \u0010g87\u0011 מְעֻמָּד, וְתָכֹף עַצְמָהּ. \u0010r114\u0011 וּמַשְׁלֶכֶת הַמִּנְעָל \u0010t31\u0011 לָאָרֶץ. \u0010r115\u0011 \u0005 חָלְצָה בְּיָדָהּ הַשְּׂמָאלִית אוֹ בְּשִׁנֶּיהָ, כְּשֵׁרָה \u0010g88\u0011 \u0006 \u0005(טוּר)\u0006: \u0010g89\u0011\nגִּדֶּמֶת, חוֹלֶצֶת \u0010c29\u0011 \u0010g90\u0011 בְּשִׁנֶּיהָ:\nיֵשׁ אוֹמְרִים, שֶׁאִם לֹא דָּחַק רַגְלוֹ \u0010t32\u0011 בַּקַּרְקַע, חֲלִיצָתָהּ פְּסוּלָה: \u0010g91\u0011\nהִתִּיר הוּא הַקֶּשֶׁר, וְשָׁמְטָה הִיא הַמִּנְעָל מֵרַגְלוֹ; אוֹ שֶׁהִתִּירָה הִיא, וְשָׁמַט הוּא, חֲלִיצָתָהּ פְּסוּלָה. \u0005 הַגָּה: \u0010c30\u0011 \u0010r116\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁאֵינוֹ יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה; אֲבָל אִם יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה, וְחָלְצָה אוֹתוֹ, הַחֲלִיצָה כְּשֵׁרָה אַף עַל פִּי שֶׁהוּא הִתִּיר הַקֶּשֶׁר \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006: \u0010g92\u0011\nהָיְתָה רַגְלוֹ עֲקֻמָּה לְאָחוֹר, אוֹ הֲפוּכָה עַל צִדָּהּ, \u0010r117\u0011 אוֹ שֶׁמְּהַלֵּךְ עַל אֶצְבְּעוֹת רַגְלָיו, אֵינוֹ חוֹלֵץ: \u0010g93\u0011\nחָלְצָה \u0010g94\u0011 מִן הָאַרְכֻּבָּה וּלְמַטָּה, חֲלִיצָתָהּ כְּשֵׁרָה. \u0010c31\u0011 מִן \u0010t33\u0011 הָאַרְכֻּבָּה וּלְמַעְלָה, חֲלִיצָתָהּ פְּסוּלָה. \u0010g95\u0011 \u0010r118\u0011 וְיֵשׁ אוֹמְרִים דְּאַקְּשִׁירָה קָאֵי, שֶׁאִם הָיָה הַקֶּשֶׁר לְמַעְלָה מֵהָאַרְכֻּבָּה, פְּסוּלָה. אֲבָל אִם נִקְטְעָה רַגְלוֹ, אֲפִלּוּ מִן הָאַרְכֻּבָּה וּלְמַטָּה, \u0010c32\u0011 אֵינוֹ חוֹלֵץ. \u0005 וְעַל כֵּן לֹא יִהְיֶה הַמִּנְעָל אָרֹךְ עַד לְמַעְלָה מִן הָאַרְכֻּבָּה \u0006 \u0005(מָרְדְּכַי רֵישׁ מִצְוַת חֲלִיצָה)\u0006. \u0010c33\u0011 \u0010g96\u0011 \u0010r119\u0011 וְיֵשׁ אוֹמְרִים דִּבְנִקְטְעָה רַגְלוֹ \u0010t34\u0011 מַיְרֵי, שֶׁאִם נִקְטְעָה לְמַטָּה מֵהָאַרְכֻּבָּה וְנִשְׁאַר כָּל כָּךְ מִשּׁוֹקוֹ שֶׁיָּכוֹל לְהַכְנִיס בּוֹ הַמִּנְעָל \u0010c34\u0011 וּלְקָשְׁרוֹ לְמַטָּה מֵהָאַרְכֻּבָּה, חוֹלֵץ: \u0010c35\u0011 \u0010g97\u0011\nקָרְעָה הַמִּנְעָל מַעַל \u0010t35\u0011 רַגְלוֹ, אוֹ שֶׁשְּׂרַפְתּוֹ, \u0010t36\u0011 פְּסוּלָה: \u0010g98\u0011\nהָיָה לָבוּשׁ שְׁנֵי מִנְעָלִים, \u0010c36\u0011 וְחָלְצָה \u0010t37\u0011 הָעֶלְיוֹן, אַף עַל פִּי שֶׁקָּרְעָה הַתַּחְתּוֹן עַד שֶׁנִּתְגַּלֵּית רַגְלוֹ, חֲלִיצָתָהּ פְּסוּלָה. \u0010r120\u0011 \u0005 אֲבָל אִם חָלְצָה \u0010t38\u0011 \u0006 \u0005 שְׁנֵיהֶם, חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006: \u0010g99\u0011 \u0010r121\u0011\nתַּעֲמֹד נֶגֶד הַיָּבָם, וְתִירַק בָּאָרֶץ כְּנֶגֶד פְּנֵי הַיָּבָם, \u0010r122\u0011 רֹק הַנִּרְאֶה \u0010g100\u0011 לַדַּיָּנִים כְּשֶׁיֵּצֵא מִפִּיהָ \u0010c37\u0011 עַד שֶׁיַּגִּיעַ לִפְנֵי \u0010t39\u0011 הַיָּבָם. \u0010g101\u0011 וְאִם לֹא רָאוּ הַדַּיָּנִים כְּשֶׁיָּצָא הָרֹק מִפִּיהָ, \u0010c38\u0011 \u0010t40\u0011 כְּשֵׁרָה: \u0010g102\u0011\nרָקְקָה וּקְלַטְתּוֹ הָרוּחַ קֹדֶם שֶׁהִגִּיעַ נֶגֶד פָּנָיו, כְּגוֹן שֶׁהִיא אֲרֻכָּה מִמֶּנּוּ, \u0010c39\u0011 צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. אֲבָל לְאַחַר שֶׁהִגִּיעַ הָרֹק נֶגֶד פָּנָיו, אֲפִלּוּ לֹא הִגִּיעַ לָאָרֶץ, כְּשֵׁרָה. לְפִיכָךְ, אִם הוּא אָרֹךְ וְהִיא קְצָרָה, קָרֵינָן בֵּהּ שַׁפִּיר \"בְּפָנָיו\" \u0010g103\u0011 \u0010r123\u0011 \u0005(דְּבָרִים כה, ט)\u0006:\nיְבָמָה שֶׁרָקְקָה דָּם, \u0010c40\u0011 אֵינָהּ צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. \u0010g104\u0011 \u0010r124\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא \u0010t41\u0011 בְּמוֹצֶצֶת, מִשּׁוּם דְּאִי אֶפְשָׁר לָהּ בְּלֹא צִחְצוּחֵי \u0010g105\u0011 רֹק:\nאָכְלָה שׁוּם אוֹ גַּרְגֵּר וְכַיּוֹצֵא בּוֹ, מִדְּבָרִים הַמַּרְבִּים \u0010c41\u0011 רֹק, וְהָיָה \u0010t42\u0011 רֹק זָב מִפִּיהָ, אֵינוֹ כְּלוּם. \u0010g106\u0011 \u0010r125\u0011 וְנָהֲגוּ לְמָנְעָהּ \u0010t43\u0011 מִלֶּאֱכֹל כְּלוּם. \u0005 וְכֵן לִשְׁתּוֹת, וּתְמַעֵט בְּדִבּוּר, כְּדֵי שֶׁיָּבֹא הָרֹק מֵעַצְמוֹ. גַּם לֹא תְּנַקֵּר שִׁנֶּיהָ, כְּדֵי שֶׁלֹּא תִּרֹק דָּם \u0006 \u0005(כ\"ז בִּסְדָרִים)\u0006: \u0010g107\u0011\nאַחַר כָּךְ מַקְרִין אוֹתָהּ \u0010g108\u0011 מְעֻמָּד: \"כָּכָה יֵעָשֶׂה \u0010t44\u0011 לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו, וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל\" \u0005(דְּבָרִים כה, ט י)\u0006. וּמִצְוָה לְכָל \u0010g109\u0011 הָעוֹמְדִים לוֹמַר: \"חֲלוּץ הַנַּעַל\", \u0010c42\u0011 \u0010g110\u0011 \u0010g111\u0011 \u0010t45\u0011 שָׁלשׁ פְּעָמִים. וְיֵשׁ אוֹמְרִים שֶׁגַּם הַיְבָמָה תֹּאמַר כֵּן: \u0010g112\u0011\nנִמְצָא סֵדֶר הַחֲלִיצָה: קוֹרְאָה \"מֵאֵן יְבָמִי\" \u0005(דְּבָרִים כה, ז)\u0006, וְקוֹרֵא \"לֹא חָפַצְתִּי לְקַחְתָּהּ\" \u0005(דְּבָרִים כה, ח)\u0006, וְחוֹלֶצֶת, וְרוֹקֶקֶת, וְקוֹרְאָה \"כָּכָה יֵעָשֶׂה לָאִישׁ\" \u0005(דְּבָרִים כה, ט י)\u0006 וְאֵין הַסֵדֶר מְעַכֵּב. \u0010g113\u0011 וְלֹא עוֹד, אֶלָּא אֲפִלּוּ לֹא קָרְאָה וְלֹא רָקְקָה, אֶלָּא שֶׁחָלְצָה בִּלְבַד, הַחֲלִיצָה כְּשֵׁרָה. \u0010g114\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיוּ יְכוֹלִים לְדַבֵּר, שֶׁהֲרֵי הֵם רְאוּיִם לִקְרוֹת. אֲבָל אִלֵּם וְאִלֶּמֶת \u0010g115\u0011 \u0010r126\u0011 וּקְטַנָּה, אֵינָם חוֹלְצִין, וְאִם חָלְצוּ, חֲלִיצָתָן פְּסוּלָה; \u0010r127\u0011 וְאֵינָהּ \u0010g116\u0011 כְּשׁוֹטֶה וְקָטָן, שֶׁלֹּא עָשׂוּ כְּלוּם, שֶׁאֵינָהּ נִפְסֶלֶת לָאַחִים וִיכוֹלָה לְהִתְיַבֵּם לָהֶם אוֹ לוֹ. \u0010c43\u0011 וְיֵשׁ אוֹמְרִים \u0010g117\u0011 דְּהוּא הַדִּין לַחֲלִיצַת חֵרֵשׁ וְחֵרֶשֶׁת שֶׁאֵינָהּ כְּלוּם. \u0010g118\u0011 \u0010r128\u0011 וְיֵשׁ אוֹמְרִים שֶׁחֲלִיצָתָן פְּסוּלָה, כְּמוֹ שֶׁל אִלֵּם וְאִלֶּמֶת: \u0010g119\u0011\nצָרִיךְ שֶׁיְּכַוְּנוּ הַיָּבָם \u0010t46\u0011 וְהַיְבָמָה שֶׁתְּהֵא מֻתֶּרֶת לְזָר בַּחֲלִיצָה זוֹ. \u0010c44\u0011 נִתְכַּוֵּן הוּא וְלֹא הִיא, אוֹ הִיא וְלֹא הוּא, לֹא הֻתְּרָה; אֲבָל חֲלִיצָה פְּסוּלָה הִיא לְפָסְלָהּ עַל הָאַחִים. \u0010g120\u0011 לְפִיכָךְ, יְבָמָה שֶׁגָּדְלָה בֵּין הָאַחִים, וְרָאִינוּ שֶׁחָלְצָה נַעֲלוֹ שֶׁל אֶחָד מֵהֶם, אֲסוּרָה לְהִתְיַבֵּם, שֶׁמָּא כִּוְּנוּ לְשֵׁם חֲלִיצָה; וּצְרִיכָה חֲלִיצָה כְּשֵׁרָה, לְהַתִּירָהּ לְזָר; אֲבָל כָּל זְמַן שֶׁלֹּא רָאִינוּ שֶׁחָלְצָה לְאֶחָד מֵהֶם, מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵין חוֹשְׁשִׁין שֶׁמָּא חָלְצָה: \u0010g121\u0011\nוְכֵן אִם רָקְקָה לִפְנֵי הַיָּבָם \u0010c45\u0011 \u0010g122\u0011 \u0010r129\u0011 בִּפְנֵי \u0010t47\u0011 בֵּית דִּין, נִפְסְלָה \u0010c46\u0011 \u0010g123\u0011 \u0010r130\u0011 מִלְּהִתְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי כְּשֶׁרָקְקָה רֹק, אֲבָל אִם רָקְקָה דָּם, וְאֵין רֹק מְעֹרָב בּוֹ, אֵינָהּ נִפְסֶלֶת בְּכָךְ: \u0010g124\u0011\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁיֵּשׁ לִזָּהֵר שֶׁלֹּא תִּירֹק הַיְבָמָה לִפְנֵי הַיָּבָם קֹדֶם חֲלִיצָה, כְּדֵי שֶׁלֹּא תְּהֵא חֲלִיצָה פְּסוּלָה \u0010r131\u0011 וּתְהֵא צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים: \u0010g125\u0011\nאִם קָרְאָה לְבַד, לֹא נִפְסְלָה בְּכָךְ \u0010c47\u0011 \u0010g126\u0011 מִלְּהִתְיַבֵּם:\nהַסוּמָא, אֵינוֹ חוֹלֵץ \u0010t48\u0011 לְכַתְּחִלָּה. וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה. \u0010g127\u0011 \u0010r132\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵין אָח אֶלָּא הוּא, חוֹלֶצֶת לְכַתְּחִלָּה, \u0005 כְּדֵי שֶׁלֹּא תִּתְעַגֵּן \u0006 \u0005(ב\"י מ\"כ)\u0006. \u0010r133\u0011 \u0005 וְלֹא מִקְּרֵי סוּמָא, אֶלָּא בִּשְׁתֵּי עֵינָיו \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006: \u0010g128\u0011 \u0010r134\u0011\nקְטַנָּה שֶׁחָלְצָה לְגָדוֹל, \u0010c48\u0011 חֲלִיצָתָהּ פְּסוּלָה וְנִפְסְלָה עַל כָּל הָאַחִים. \u0010g129\u0011 \u0010r135\u0011 \u0005 וּכְשֶׁתַּגְדִּיל, תַּחֲלֹץ מֵאֶחָד מֵהֶם, \u0010c49\u0011 וְאֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים: \u0010g130\u0011 \u0006\nחֲלִיצָה מֻטְעֵת, שֶׁאוֹמְרִים לוֹ: חֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לְךָ מָאתַיִם זוּז, הַחֲלִיצָה כְּשֵׁרָה, אֲפִלּוּ אֵינָהּ נוֹתֶנֶת לוֹ כְּלוּם, \u0010g131\u0011 \u0010r136\u0011 וַאֲפִלּוּ כָּפַל הַתְּנַאי. \u0010r137\u0011 \u0005 וַאֲפִלּוּ אָמַר לָהּ בִּשְׁעַת הַחֲלִיצָה: \u0010c50\u0011 עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לְאִישׁ, וְכָפַל תְּנָאוֹ, אֵינוֹ כְּלוּם \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל נ\"ב)\u0006. \u0010r138\u0011 וְאַף עַל פִּי שֶׁהַחֲלִיצָה כְּשֵׁרָה אַף אִם לֹא תִּתֵּן לוֹ, \u0010g132\u0011 \u0010r139\u0011 מִכָּל מָקוֹם חַיֶּבֶת לִתֵּן לוֹ, \u0010r140\u0011 כִּשְׁאָר שְׂכַר שָׂכִיר לַעֲשׂוֹת מְלַאכְתָּן. \u0010c51\u0011 \u0010g133\u0011 אֲבָל אִם יֵשׁ טַעֲנָה שֶׁאֵינָהּ חֲפֵצָה בּוֹ מִפְּנֵי שֶׁאֵינוֹ הָגוּן לָהּ, וְהוּא חַיָּב לַחֲלֹץ אֶלָּא שֶׁאֵינוֹ רוֹצֶה, וְהִטְעוּהוּ שֶׁיַּחֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז, אֵינָהּ חַיֶּבֶת לִתֵּן לוֹ כְּלוּם. \u0010c52\u0011 \u0005 אֲבָל אִם נָתְנָה לוֹ הַמָּעוֹת אוֹ הִשְׁלִישָׁה לוֹ \u0010t49\u0011 \u0006 \u0005 הַמָּעוֹת, אֵינָהּ יְכוֹלָה לַחֲזֹר \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א אֶלֶף ר\"מ)\u0006. \u0005 וְעַיֵּן לְעֵיל רֵישׁ סִימָן קס\"ה: \u0010g134\u0011 \u0006\nאָמְרוּ לוֹ: חֲלֹץ לָהּ וּבְכָךְ אַתָּה כּוֹנְסָהּ, \u0010r141\u0011 אוֹ שֶׁאָמְרוּ לֵהּ: חֲלֹץ לָהּ \u0010g135\u0011 שֶׁזּוֹ מִצְוָה הִיא וְאֵינָהּ מַפְסֶדֶת עָלֶיךָ כְּלוּם, וְאִם תִּרְצֶה אַחַר כָּךְ לְיַבֵּם, תְּיַבֵּם, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, אֵינָהּ חֲלִיצָה לְהַתִּירָהּ, כֵּיוָן שֶׁלֹּא נִתְכַּוֵּן לְהַתִּירָהּ, \u0010r142\u0011 אֲבָל נִפְסְלָה בְּכָךְ \u0010r143\u0011 מִלְּהִתְיַבֵּם, וְכוֹפִין אֲפִלּוּ בְּשׁוֹטִים לַחֲלֹץ לָהּ חֲלִיצָה כְּשֵׁרָה: \u0010g136\u0011 \u0010r144\u0011\nאָמְרוּ לוֹ: הָאִשָּׁה הַזֹּאת אֵינָהּ רוֹצָה בְּךָ דֶּרֶךְ יִבּוּם, אֶלָּא חֲלֹץ לָהּ וַעֲקֹר זִקָּתָהּ הֵימֶנָּה וְהִיא נִשֵּׂאת לְךָ דֶּרֶךְ \u0010c53\u0011 נִשּׂוּאִין, יֵשׁ מִי שֶׁאוֹמֵר שֶׁחֲלִיצָתָהּ כְּשֵׁרָה: \u0010g137\u0011\nדִּין חֲלִיצָה מְעֻשֵּׂית עַל יְדֵי יִשְׂרָאֵל אוֹ עַל יְדֵי עכו\"ם, דִּינָהּ כְּדִין גֵּט מְעְשֶּׂה, שֶׁנִּתְבָּאֵר בְּסִימָן קל\"ד. \u0005 וְעַיֵּן לְעֵיל סִימָן זֶה סָעִיף י\"ג: \u0010g138\u0011 \u0010r145\u0011 \u0006\nֹ מָסַר מוֹדָעָא עַל הַחֲלִיצָה, אֵינָהּ חֲלִיצָה בְּטֵלָה, אֶלָּא \u0010c54\u0011 חֲלִיצָה פְּסוּלָה הִיא: \u0010g139\u0011\nחֲלִיצָה פְּסוּלָה פּוֹסֶלֶת עַל כֹּל הָאַחִים, וּפוֹסֶלֶת לִכְהֻנָּה, וְאוֹסֶרֶת עָלָיו כָּל קְרוֹבוֹתֶיהָ, וְאֵינָהּ נִשֵּׂאת לְזָר עַד שֶׁתַּחֲלֹץ חֲלִיצָה כְּשֵׁרָה. \u0010r146\u0011 עָבְרָה וְנִשֵּׂאת לְזָר \u0010g140\u0011 קֹדֶם שֶׁתַּחֲלֹץ, חוֹלֵץ לָהּ חֲלִיצָה כְּשֵׁרָה וְהִיא תַּחַת בַּעְלָהּ, וְאֵין מוֹצִיאִין אוֹתָהּ מִמֶּנּוּ, \u0010g141\u0011 מִכָּל מָקוֹם מַפְרִישִׁין אוֹתָהּ מִבַּעְלָהּ עַד שֶׁיַּחֲלֹץ לָהּ הַיָּבָם: \u0010g142\u0011\nלְאַחַר שֶׁחָלְצָה, \u0010c55\u0011 \u0010r147\u0011 כּוֹתְבִין לָהּ בֵּית דִּין שֶׁחָלְצָה \u0010t50\u0011 בִּפְנֵיהֶם, גֵּט חֲלִיצָה. \u0010r148\u0011 וְאִם לֹא כְּתָבוּהוּ לָהּ, כָּל שְׁנַיִם שֶׁרָאוּ הַחֲלִיצָה יְכוֹלִים לְכָתְבוֹ, אַף עַל פִּי שֶׁאֵינָם מַכִּירִים לֹא הַיָּבָם וְלֹא הַיְבָמָה; שֶׁבֵּית דִּין לֹא חָלְצוּ בִּפְנֵיהֶם אִם לֹא הָיוּ מַכִּירִים. \u0010g143\u0011 וּצְרִיכִין לְשַׂרְטְטוֹ, מִפְּנֵי מִקְרָאוֹת שֶׁבּוֹ. \u0005 וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ל\"ה: \u0006 \u0005(אָמַר הַמַּגִּיהַּ גַּם פֹּה בְּסֵדֶר חֲלִיצָה כָּל מָקוֹם שֶׁלֹּא נִזְכַּר בַּהַגָּהוֹת שֵׁם אוֹמְרָהּ, סְתָמָן כְּפֵרוּשָׁן שֶׁהֵם לְקוּחִים מֵהַסְדָרִים וּבִפְרָט מִסֵדֶר מהר\"י מַרְגָּלִיוֹת)\u0006:",{"g":["משנ' יבמות דק\"א ע\"א","פי' לאפוקי גרים כדבסמוך","טור והטעם משום דחליצ' דין הוא וכמו שיתבאר בסמוך","שם במשנ'","בריי' שם","רמב\"ם פ\"ד מה\"י וכמ\"ש הב\"י דהב\"ע כשהיבמה והיבם יודעים לקרות בעצמם מבלי שיקרא להם אחר א\"נ אפי' לא קראו כלל החליצ' כשירה בדיעבד וכמו שיתבאר לקמן ססמ\"ג","מימרא דרבא שם ריש דף קב","וכ\"כ התו' שם","במשנה וכת\"ק","טור מדין יבמה שגדלה בין האחים כמ\"ש בסעיף מ'","כמה עובדי שם בגמר' דף קא ע\"ב","טור וכ\"כ רמב\"ם שם בפ\"ד ופשוט הוא","מימר' דרבא שם ויליף לה מקרא ועלתה יבמתו השערה","טור בשם אבי עזרי בשם רבותיו","שם בשם אבי מורי","משנה שם דק\"ד ע\"א וכר\"א וכתירוצ' בתרא שם בגמר' דסתמ' דמתני' יחידאה היא וטעמ' מפ' שם בגמר' דחליצ' הוה כתחלת דין ואין דנין בלילה","משנ' ביצה דל\"ה ע\"ב","בריי' מ\"ק די\"ד ע\"ב דנין ד\"נ וד\"מ במועד","כ\"כ מהרא\"י סי' רכז","\u0003יבמות דל\"ה ע\"ב אתקין ר\"י בגיט' דחליצ' וכו'\u0004 וכרבא דידי' אמר וכו' שם דק\"ו ע\"א","מסקנת הגמרא שם דל\"ט ע\"ב דגילוי מילתא הוא","הרמב\"ם שם בפ\"ד","\u0003טור וכ\"כ סה\"ת והסמ\"ק ממשנ' היבמה לא תחלוץ וכו'\u0004 שם דמ\"א ע\"ב","לשון הב\"י","\u0003משנה וחולצת לקטן וכו'\u0004 שם דק\"ד ע\"ב","טור וכ\"כ הרא\"ש בסדר חליצה בס\"פ מצות חליצה וכ\"כ הרשב\"א בתשו' וסה\"ת וכדתנן א\"א לבא העליון עד שיבא התחתון נדה דמ\"ח ע\"א וכ\"כ התו' שם","שם וכ\"כ התו' יבמות דף פ' ע\"ב","שם בשם הרמב\"ם בפ\"ב מה\"א וכ' ה\"ה שהוא נלמד ממימרא דרב חסד' ותניא כוותי' קדושין סוף דס\"ג וכ\"כ המרדכי בפ' מצות חליצה בשם כמה גדולים","שם בשם סה\"ת בשם מורו ריב\"ש","שם וכ\"כ תו' שם בקדושין","עיין בפי' סד\"ח וסנ\"ז שיעור אורך שערות","שם בתו'","ממשנ' ריש יבמות וכדאמר ר\"ס שם סוף די\"ב ונתבאר לעיל סקנ\"ה סעי\"ב והביאו הב\"י בפי' סד\"ח סעיף ס\"ח","טור וכ\"כ הרא\"ש בסדר חליצ' וכ\"כ בס\"ה","רא\"ש שם משום דדמיא לג\"ד ובספרי מסמיך לה אקרא ועמד","מבריי' ריש דק\"ג","\u0003טור וסמ\"ג והרא\"ש וכ\"כ הרמב\"ם בפ\"ד וכתב ה\"ה שטעמיה מהא דאמרינן חליצה מעושת כו'\u0004 שם דק\"ו ע\"א ומדהשווי' החליצה לגט יש לחליצ' דין הגט במסירת המודע' כמש\"ל ריש סקל\"ד","\u0003מעובדא קמיה דר\"י כו'\u0004 שם דף קג ע\"ב","טור בשי\"א","משנה שם דף ק\"א ע\"א","\u0003מימר' דר\"י כו'\u0004 כפי' השני שברש\"י שם דף קב ע\"ב","\u0003טור בשם סמ\"ג מהא דאמרינן איכ' בינייהו מנעל לכתחלה כו'\u0004 שם כפירש\"י וכ\"כ הרי\"ף והרא\"ש כי לישנ' דלכתחלה סנדל בעינן ופרש\"י שם במשנה דסנדל הוא של עור קשה ומבושל","מפירש\"י שבת דף ס' ע\"ב","מדברי סמ\"ג וסמ\"ק","כפירש הראשון ברש\"י במימרא דר\"י הנז\"ל","נ\"י בשם הרבה מהמפרשים וכתב הריטב\"א שיש לחוש גם לזה","תו' בשם ר\"ת אמימרא דר\"י שם והביאו הטור וכ\"כ הסמ\"ג וסה\"ת וש\"פ","\u0003ממימר' דרב אי לאו דחמיתי כו'\u0004 שם דף ק\"ב ע\"א","סמ\"ק והכלבו בשם מהרי\"ף","שם במימרא דרב פי' הטור וכ\"כ ר' ירוחם וש\"פ","המר' בשם הגהות סמ\"ק והכל בו בשם מהרי\"ף","טור בשם סמ\"ג וכ\"כ הסמ\"ק","פי' סמיכות","שם וכפי הגי' שמצא הב\"י כתוב","משנה בשמאל חלוצה פסולה שם דף קד ע\"א","משנה שם דף קא ע\"א","בריית' שם ריש דף ק\"ג","בריית' וכאוקימת' דגמ' שם","עיין במ\"ש לעיל סעיף ט\"ו וצ\"ע שהשמיט הרמ\"א או שתפירותיו בפשתן שכתב הטור שכשר כמ\"ש הב\"י בשם הרא\"ש אמימרא דרב יהודה שציינתיו בסעיף הנ\"ל דלכתחלה קאמר וכן משמע ל' המחבר ב\"י בסעיף הנ\"ל","משנה שם דף קא ע\"א","מימרא דרב שם סוף דף קג","פי' ר\"ת דאחר ביטול איירי ולכתחלה לא תחלוץ דמאיס לענין מצות ורש\"י פי' בע\"א","הני לשריפ' קיימי דאין להם ביטול עולמות וכתותי מיכתת שיעורא","כיון דלאו להליכ' עביד לאו נעל הוא","טור בשם ס\"ג","שם ושם","הר\"ן בריש פ' גיד הנשה הרמב\"ן והנ\"י ביבמות שם בשם הרשב\"א מברייתא בכורות דף מה ע\"ב","טור וכ\"כ המרדכי בשם אבי\"ה שם ביבמות וסה\"ת","מרדכי בשם ראבי\"א","הגהת מרדכי","ל' הסמ\"ג וכ\"כ הטור וש\"פ","לקיים דברי הירושלמי","טור בשם סמ\"ג והב\"י כתב שלא מצאו אלא שם במרדכי בשם אבי\"ה","הגהות מרדכי","כן הוא שם","בקונדרסים","טור וכתב הב\"י פשוט הוא","כן הוא בטור ושקשרים האלו הם החומרת' הנז' לעיל סעיף יט","שם בשם הרמב\"ם בפ\"ד ממימרא דאביי שם דף קו ע\"ב ומסיק שם בגמ' דמודה רבא בהא דלא לשתמע לא כלומר לא מאן אלא אבה יבמי","\u0003ה\"ה בשם הרשב\"א כפי דבריהם וכו'\u0004 ","כתב ה\"ה שהוא בברייתא בספרי","משנה סוטה דף לב ע\"א ויבמות דף קו ע\"ב","טור וכ\"כ הרא\"ש בסדר החליצ'","מימרא דאמימר שם דף קג ע\"א","טור וכ\"כ התו' שם בדף ק\"ב ע\"א בשם הירושלמי","שם בשם סמ\"ג וכ\"כ סמ\"ק סי\"ח","טור","בסמ\"ג וסמ\"ק כתוב או תכוף","וכ\"כ התו' והרא\"ש שם","שם בגמ' דף קה ע\"א","\u0003טור בשם הרי\"ף שהוא מדמה אותו לאידך דאמימר מאן דמסגי וכו'\u0004 שם דף קג ע\"א","מימרא דר' ינאי שם דף קב ע\"א","\u0003טור בשם הרמב\"ם שם ממימרא דאמימר מאן דמסגי וכו'\u0004 שם דף קג ע\"א כיון שאינו יכול לנעץ עקיבו בקרקע","משנה שם דף קא ע\"א","פי' הכרעיי' דמיני' כפיף ומיניה זקוף","טור בשם הרי\"ף והרמב\"ם פ\"ד וסה\"ת וכן משמע בירושלמי וכן פי' ר' נסים גאון במגילת סתרים וכתב ה\"ה שכן דעת בעל העיטור","שם בשם ר\"ח ואביו הרא\"ש וה\"ה בשם בעל המאור והרשב\"א","בעיא דרב ינאי ולא אפשט' שם דף קב ע\"א ולחומרא","לשון הרמב\"ם שם בעיא דרבי נחמי' כפי גירסתו שם","משנה שם דף קי ע\"ב","מימר' דרבא שם","טור בשם הרמב\"ם בפ\"ד וכתב ה\"ה שלמד כן מדלא אמר רבא לאו חליצ' היא כדאמר באידך אכל' תומא וכו'","מימרא דאביי שם","שם דף קה ע\"א","טור בשם הרי\"ף וכ\"כ הרמב\"ם בפ\"ד","שם בשם הרמב\"ם שם ממימרא דרבא שם דף קז ע\"ב","שם בשם סה\"ת","ממשנה שם","מהספרי","שם וכר' יהודה","בריי' שם","הגהת מיי' בשם רבי יהודאי גאון וכ\"כ המרד'","ל' הטור ממשנה וממימרא דרב יהודה ובברייתא שם","ברייתא ריש דף קה ואוקימנא כר\"ע ידוע דהלכ' כמותו","ממימרא דרבא וכולי שם וכר' זירא שם דף ק\"ד ע\"ב","טור וכ\"כ הרמב\"ם ממסקנת הגמרא והלכה עד שתביא ב' שערות שם דף קה ע\"ב ומשמע שאפילו בדיעבד פסול' ה\"ה","תוספת' הביאה ה\"ה","רמב\"ם שם וכתב ה\"ה שסמך על התוספת'","טור וכ\"כ ה\"ה בשם הרמב\"ן והרשב\"א ממימרא דרבא דלעיל הסוגיא שם","ממימרא דר' יוחנן דף קז ע\"א וברייתא שם דף קב ע\"א","מימרא דרב וכלישנ' בתרא שם דידוע דהלכ' כלישנא בתרא","שלחו ליה לאבוה דשמואל וכולי שם דף ק\"ד ע\"ב ואוקימנא שם כר\"ע","טור וש\"פ וכמ\"ש הרא\"ש והנ\"י שם","שם וכ\"כ הרא\"ש שם בפסקיו בשם הראב\"ד","הגהת מיי' וכ\"כ במרדכי מקבלת אבי\"ה","בריית' שם ריש דק\"ה","טור וכ\"כ הרמב\"ם בפ\"ד דכתיב וירק' בפניו ואין זה רואה הרוק וכ' ה\"ה שלמד זה מהברייתא דתנא חליצתו כשיר' דמשמע דיעבד שם ריש דק\"ג","הראב\"ד שם בהשגות","ציינתיו לעיל בסעיף מ\"ג","משנה שם דק\"ד ע\"ב","בריית' שם דק\"ז ע\"א","כמו שפירש\"י דכל תנאי מבני גד ומבני ראובן גמרי' שאפשר להתנות ע\"י שליח דכל תנאי דלא אפשר לעשות ע\"י שליח נגון חליצה אין תנאי מועיל בה כמפור' בכתובות דמ\"ד ע\"א:","עובדא לקמיה דאביי וכפירש רש\"י והרא\"ש שם יבמות דק\"ו ע\"א","מעובדא לקמיה דרבי חייא שם בבריית'","ל' הרמב\"ם שם מעובד' דלעיל","כ' ה\"ה שנראה שלמד זה מהירוש'","עובדא בירושלמי הביאו ה\"ה וכ' בשם הרשב\"א שהמעשה הזה הלכה הוא ושאפשר שגם הרמב\"ם מודה בזה כיון שפירשו לו בכאן שהוא עוקר זיקתה הימנ'","ברייתא שם בבבלי וכדמפרש לה שם","\u0003תשובת הריב\"ש סימן תפ\"ב ושכ\"כ הרמב\"ם בפ\"ד וכ' הרמב\"ם ראוי לדיינין לומר לבטל המודעא וכו'\u0004 וכתבו המחבר לעיל","טור והרמב\"ם כמימרא דשמואל גיטין דף כ\"ד ע\"ב דמשמע שם דהלכת' כוותי' בחליצה","טור וכ' הב\"י שפשוט הוא ושגם דעת הרמב\"ם כן","ב\"י וכן משמעות לשון הטור","מימרא דרבא יבמות דק\"ו ע\"א וכמו שפירש רש\"י שם","שם ע\"ב משמיה דמר זוטרא"],"t":["\u0003חליצה. \u0004 היא אחת ממצות התורה ואין מברכין עליה. רשב\"א סי' י\"ח:","\u0003הדיוטות. \u0004 ואפילו שאין רב המומחה עומד עליהם. מהר\"ם מינץ:","\u0003פסול. \u0004 משום דחליצה נקרא דין. ואפילו אם קבלו עליהם לא מהני כאן. רב שפסול להיות דיין מחמת קורבא. לבי מגמגם אם יוכל לעמוד ע\"ג שלשה הדיינין לסדר החליצה. מהר\"ם מינץ סי' כ'. וכנה\"ג כתב ול\"נ שאין להקפיד בזה:","\u0003גר. \u0004 ולא מהני בחליצה הורתו ולידתו בקדושה ואפילו לחליצת גרים נמי פסול. רש\"ל סימן נ':","\u0003מישראל. \u0004 ובני אנוסים עיין כנה\"ג בהגהת הטור סעיף י\"א. שתוקי שאמרה אמו לכשר נבעלתי אי איכא רובא להתירה לכ\"ע מותר להיות דיין לחליצה אבל אם רוב פסולים אצלה דעת הרמ\"א בתשובה סימן כ\"ד דפסול להיות דיין לחליצה לכתחלה ע\"ש: \u0003הרב\u0004 והתלמיד נמנין שנים לחליצה אעפ\"י שהתלמיד אינו יודע דיני חליצה מהריב\"ל ח\"א כלל נ' משפטי שמואל סי' ק' והסכימו עמו ז' רבנים ע\"ש:","\u0003הג'. \u0004 לפרסומי מילתא. ובפרק ר\"א דמילה מפורש כל חליצה בעשרה. הר\"ם מינץ סימן ס\"א. וכתב הד\"מ באלו שנים אין קפידא אם נוטלין שכר הרבה:","\u0003ופסולים. \u0004 ויהיו רחוקים משאר דיינין קצת. ואף הבאים למיחזי יהיו רחוקים קצת מן הדיינים. הר\"מ מינץ סי' ס\"א וכ\"כ הכנה\"ג:","\u0003מקום. \u0004 עיין בפירוש סדר חליצה. בבוקר ביום חליצה יאמרו נלך לחלוץ במקום אשר קבענו אתמול בערב ס\"ח למהר\"י מינץ. אף במקום שיש ב\"ד קבוע בכל יום צריכים למקבע דוכתי' כנה\"ג. אין קובעין בשבת וקביעות מקום הוא משום פרסום לכן צריך להיות בגובה שבעיר. ואם יש פרסום בלא זה עיין בתשובת ר\"י לבית הלוי סי' יו\"ד:","\u0003שלפניו. \u0004 בין מנחה למעריב רש\"ל סימן נ'. בח\"ה סי' רכ\"א כתב שיכולין לקבוע מקום בערב שנים או שלשה ימים קודם החליצה. ומהר\"י מברונא כתב אם אירע עיכוב שלא יוכלו לחלוץ באותו יום בטל קביעות הלילה וצריך לקבוע פעם שנית וכן שלישית ורביעית לכאורה נראה דלא פליגי. די\"ל דלא הצריך מהר\"י מברונא קביעות מקום פעם אחרת אלא דוקא כשקבע מקום לחלוץ למחרתו ואירע עיכוב אבל אם מעיקרא לא קבעי מקום לחלוץ אלא לאחר כמה ימים יודה מהר\"י מברונא. אבל מסתימת אחרונים נראה דאין חילוק וצריך לקבוע דוקא ביום שלפניו וכן פסק בכה\"ג ב\"י סעיף י\"ג י\"ד ע\"ש. ועיין בפירוש ס\"ח וסעיף ט\"ו:","\u0003המת. \u0004 מאביו:","\u0003או אשה. \u0004 דוקא שלא בשעת מעשה אבל בשעת מעשה אין אשה וקרוב נאמן מהריב\"ל ח\"ב סי' מ\"ט. בתשובת מהרשד\"ם חא\"ה סי' רנ\"ט כתב דאפילו מפי כתב אפשר מהני להכיר אותה ע\"ש:","\u0003השערות. \u0004 אבל על השנים צריך לבדוק. ודוקא בדדין כגון בוחל וצמל שאינן גדולים ממש אבל אם הם גדולים כ\"כ כמו שדרך להיות באשה גדולה שבאת לכלל הקומה א\"צ לשאול על השנים אעפ\"י שעדיין לא גדלה בקומה מ\"ב סי' יו\"ד. ובדיקת דדין צריך להיות ע\"י אנשים אא\"כ הוחזקה גדולה בשנים אז בודקים ע\"י נשים עיין ב\"ש. וכנה\"ג:","\u0003קרובים. \u0004 אין עד מפי עד כשר לעדות השנים. רשד\"ם חא\"ה סי' פ\"ד מהרש\"ך ח\"א סי' צ\"ג וצ\"ד. עדות שבשטר לא מהני לעדות השנים מ\"ץ ח\"א סי' ס\"ה. עדים שהעידו שמצאו כתוב בספר שלהם שנולד בת א' מהם באיזה זמן ובזמן זה נולדה זאת הנערה או הנער ולפי זה הוא גדול. אינו עדות מהריב\"ל ח\"ד סימן ט' ועד המעיד שאמר לו אבי הנערה כמדבר איש אל רעהו שבתו נולדה בשבת פלוני. הוי עדות ולא הוי עד מפי עד מהרש\"ך ח\"א סי' כ\"ג וכ\"ד. הרשד\"ם חא\"ה סי' ט' ס\"ל דהוי עד מפי עד. עדים שהעידו שהיה נראה להם כשראה אותם שהיו מוטלים בעריסה שהיו כבן שנה וחצי לאו עדות גמור הוא ועבידי אינשי דטעו בחצי שנה. מהרש\"ל ועיין כנה\"ג:","\u0003הדיינים. \u0004 אופן ישיבתם נתבאר בס\"ח בקצרה:","\u0003מעומד. \u0004 משום דדמי לדין. ואם יבם חלש או זקן נותנים לו מקל בידו לסמוך עליו. ולהרמב\"ם ונ\"י אפי' לכתחלה חליצת המנעל מותר בישיבה עיין ב\"ש:","\u0003במתנה. \u0004 ואם המנעל הוא של אדם אחר מקנהו לראש בית דין וראש ב\"ד מקנהו ליבם רש\"ל סי' צ'. אבל בס\"ח בקצרה סעי' ל\"ט כתב יתן בעל המנעל ליבם וכו'. משמע דלא צריך להקנות לראש ב\"ד:","\u0003מעור. \u0004 אלא של שער שבא מעור אבל של שאר מינים פסול. ב\"ח ב\"ש:","\u0003נוהגין. \u0004 ואם המנעל הוא שיוכל להלוך בו בלא קשירה אז נראה לכ\"ע כשר אפי' אם הרצועות הם של שאר מינין. ב\"ש:","\u0003לרככו. \u0004 ומהרש\"ל סי' ו' כתב אם נתייבש קצת יכולין לעשות אותו כדי שיהא רך ויהא ראוי להלוך ע\"ש ועיין כנה\"ג בהגהת הטור סעיף ס\"א:","\u0003לקשרו. \u0004 ואם המנעל היא שיוכל להלוך בלא קשירה אז כשר החליצה אפי' שאין בו רצועות וקשרים הרא\"ש ב\"ש:","\u0003מבחוץ. \u0004 דהיינו הקרסים לצד שמאל והלולאות לצד ימין במנעל של ימין ואם הדרך באותו מקום שהרצענים משנים יעשה כמנהגם רש\"ל שם. וכנה\"ג סעי' ס\"ו:","\u0003דמעל. \u0004 וזהו חומרא בעלמא. ובדיעבד אין חשש. פוסקים:","\u0003ימנית. \u0004 דהיינו שהרגל של ימין אצבע גדול עד הקטן הוא באלכסון לצד ימין. ובצד שמאל הוא באלכסון מאצבע גדול עד הקטן לצד שמאל וזהו מ\"ש הפוסקים כצורת רגל הימנית ובצורת רגל השמאלית לחתוך אותם כן. אע\"ג שבמנעלים שאנו לובשין בכל יום אין עושין כן לפי שדרכן להפכן לפעמים מרגל ימין לשמאל משא\"כ בחליצה שבות יעקב ח\"ב שאלה קכ\"ט ע\"ש. וכ\"כ בנחלת שבעה מהדורא בתרא דף כ\"ה:","\u0003רגלו. \u0004 מנעל גדול שמרוב גדלו וכפל ע\"ג הרגל אין חולצין בו לכתחלה אפי' יוכל להלוך בו ובדיעבד שפיר דמי. ואם אינו יוכל להלך בו אפילו בדיעבד פסול מהר\"י ווייל סי' פ\"ו:","\u0003עקב. \u0004 שצריך שלא יוציא הרגל חוץ למנעל:","\u0003בשתיהן. \u0004 ותחלוץ בשני רגליו בפעם אחת. תחלוץ ביד א' מרגל א' ובידה שניה מרגל שני דאם תחלוץ זה אחר זה הוי חליצה פסולה. כ\"כ בפירוש ס\"ח סעיף מ' ע\"ש. וב\"ח כתב דמנהג הוא לחלוץ זה אחר זה ויכוונו היבם והיבמה לחלוץ בזה שע\"פ הדין הוא לחלוץ. ואם הוא שולט בב' רגליו חולץ בימין כל אדם עיין בס\"ח בקצרה ס\"ק כ\"ז מש\"ש. וסעי' מ' בפי' ס\"ח. וכנה\"ג סעיף מ\"ה. ובתשובת שבות יעקב ח\"ב שאלה קכ\"ט:","\u0003דמעל.\u0004 ובדיעבד הוי חליצה פסולה. ב\"ש:","\u0003רגלו.\u0004 זהו חומרא בעלמא לכתחלה. ב\"ש:","\u0003ערום. \u0004 וז\"ל הלבוש ויכרוך הרצועות סביב הרגל ג\"כ מן הארכובה ולמטה היינו במקום שמנעל פתוח מאחורי הרגל שתי חורים ובין החורים הוא שלם יכרוך הארוכות בין הלולאות עד שיגיע באחורי הרגל בחור העליון ויניחם ג\"כ שם מכוונות זה אצל זה ואח\"כ יכרוך הרצועות פעם ג' סביב הרגל ועד שיגיע למעלה מן הלולאות על גב הרגל שקורין בל\"א שינביי\"ן דעל שינביי\"ן נמי מעל רגלו נקרא. ועיין פרישה הטעם משום דבמקום שפוגעים בו שני הרצועות הארוכות מלפניו ולאחריו כופלין אותו זה על זה מחשב כקשר מש\"ה צריך שיהיה אותו הכפילה במקום בשר שוקו אבל מה שמשם והלאה מונח הרצועה על עור המנעל אין קפידא דאין דומה לקשר כלל. ב\"ש:","\u0003בנשימה א'. \u0004 וא\"צ ליתן ריוח בין האלפי\"ן שבלא אבא ב\"ח. אם היבם נלעג לשון וערל שפתים ולא יוכל לדבר מבטא האותיות כתקנם וכחתוכם אין בכך כלום מאחר שכך מנהגו לבטא אותם אותיות בשבוש זו היא אמירתו מהרי\"ט. ח\"ב חא\"ה סימן י\"ו:","\u0003בו. \u0004 ומ\"מ אומרים לו שלא ישען כ\"כ שאם יוטל משענתו יפול דא\"כ לא הוי מעומד ס\"ח למהר\"י מינץ וכ\"כ לקמן בס\"ח בקצרה סעיף מ\"ה:","\u0003לארץ. \u0004 בכח. רש\"ל בס\"ח:","\u0003בקרקע. \u0004 מי שמתחייב לחלץ וטוען שרגליו נפוחות אם יוכל לעמוד על כפות רגליו חייב לחלוץ דשפיר מצי דחיק ואף אם לא יוכל להלך עם המנעל אין חשש הר\"ם פדוואה סימן כ\"ג. יבם שרגלו עקום ומהלך בצד רגלו ולפעמים דוחק קצת עקבו בארץ חליצתו כשרה רשד\"ם חא\"ה סימן צ\"ו והר\"א ששון סי' קמ\"ג. יבמה זקוקה ליבם מומר פסח בשתי רגליו עקומות והפוכות לפנים עיין מהר\"ם לובלין סימן ל\"ו וע\"ל סי' קנ\"ו ס\"ק ג' מש\"ש:","\u0003ולמעלה. \u0004 היינו מה שבין השוק לקוליות ולא מה שבין הארכובה הנמכר עם הראש והשוק וכל השוק נקרא מעל רגלו:","\u0003מיירי. \u0004 עיין ב\"ש. וכתב הרשב\"א כשנקטעה ליבם רגלו צריך לדחוק בשוקו בקרקע:","\u0003רגלו. \u0004 וכ\"ש היכא שנקרע המנעל שלא בכונת היבמה. רש\"ך ח\"ב סימן \u0005(כ\"א)\u0006 [נ\"ב]:","\u0003פסולה. \u0004 דכתיב וחלצה. ואם קרעה מצד העקב שיעור שלשה או ד' אצבעות אעפ\"י שיוכל להלך בו וחלצה אח\"כ המנעל לא מהני. הרש\"ך שם:","\u0003העליון. \u0004 ואם קרעה העליון ומ\"מ קם. ומחמת הקריעה יכולה לשלוף התחתון הוי נמי חליצה פסולה אפילו קרעה לעליון רוב עקב או רוב המנעל שא\"י להלך בו מ\"מ כיון דקם הוי חליצה פסולה. מיהו אם קרעה לעליון לגמרי וחלצה התחתון הוי חליצה מעליותא עיין ב\"ש והרש\"ך ח\"ב סימן נ\"ב:","\u0003שניהם. \u0004 דוקא בפעם א'. ב\"ש:","\u0003יבם. \u0004 ובתוס' אין מצוה מן המובחר עד שיגיע לארץ. וכן הוא לקמן בס\"ח בקצרה. יזהירוה הדיינים שלא תרוק עד שיאמרו לה שתרוק ואם צריכה לרוק תרוק באפרקסותה שלא כנגד היבם ס\"ח למהר\"י מינץ. ונהגו לכסות פיה בצעיף כדי שלא תרוק. רש\"ל בס\"ח:","\u0003כשרה. \u0004 כ\"כ הרמב\"ם בפ\"ו מהלכות יבום וחליצה. וכתב המגיד הטעם הואיל ולא אמר רבא אם לא חזו דייני דוקא לאו כלום הוא ע\"ש. אע\"ג דאמר אמימר האי מאן דחליץ צריך למדחסי' לכרעי' ביבמות דף ק\"ג ע\"א. ואפ\"ה פסק המחבר בסעי' ל\"ב אם לא דחק רגלו חליצתו פסולה אע\"ג דאמר נמי צריך עיין ב\"י וב\"ש ס\"ק למ\"ד ויונעם לך. וב\"ח מדייק מתו' ד\"ה והחולצת מן הסומא וכו' יבמות דף ק\"ג ע\"א אם הדיינים לא ראו הרוק פסול ע\"ש והב\"ח חולק עליו ע\"ש. ועיין עוד בב\"ח במ\"ש דבריש מצות חליצה כתבו התוס' בד\"ה זקני שנים וכו'. דב\"ד אם לא ראו הרוק אפילו בדיעבד החליצה פסולה ע\"ש ודוק היטב לכאורה דברי תוס' בכאן בריש מצות חליצה ד\"ה זקני שנים וכו'. סותרים למ\"ש בדף ק\"ג ע\"א בד\"ה והחולצת מן הסומא וכו'. וצ\"ע:","\u0003במוצצת. \u0004 ואם רקקה בלא מוצצת. ולא שותת לא מהני. הרשב\"א ב\"ש:","\u0003זב. \u0004 ל\"ד אלא כיון שהרוק בא מחמת דבר אחר לא הוי רקיקה אפילו לא זב. מיהו במוצצת י\"ל דמהני לכ\"ע. וכתב בש\"ג אם רקקה מחמת דבר אחר לא הוי רקיקה כלל ולא נפסלה על האחין. ב\"ש:","\u0003כלום. \u0004 טוב שיזהירו היבמה בבוקר וכן בערב שלא תאכל ולא תשתה למחרתו קודם החליצה. ואם למחרתו הוא תענית ציבור א\"צ להזהירה מבערב:","\u0003לאיש. \u0004 כ\"ף ראשונה דגושה שניה רפויה. ס\"ח להר\"י אדרבי:","\u0003ג\"פ. \u0004 חלוץ הנעל כאבל. חלוץ הנעל כמנודה. חלוץ הנעל כמורד במצות סיני:","\u0003והיבמה. \u0004 הראנ\"ח לא רצה שתחלוץ אשה אוננת אפילו במקום עיגון וה\"ה אם האיש אונן וטעמו כי בהיותם אוננין אינם יכולין לכווין ומהרי\"ט ח\"ב חא\"ה סימן י\"ו כתב הטעם משום דהחליצה מצוה מן התורה ואונן פטור מכל המצות בתורה ואם רצה להחמיר על עצמו אינו רשאי וכתב הכנה\"ג בי\"ד סימן שמ\"א ונ\"מ בין הטעמים אם יוכל לחלוץ לאבל תוך שבעה או מיד לאחר הקבורה ע\"ש. ובתשובת חכם צבי סימן א' הקשה ע\"ז אם כדבריו אין לך אשה שכשירה ליבום שהרי הוא והיא נעשים אוננים וקי\"ל כל יבמה שאין אני קורא בה בשעת נפילה יבמה יבא עליה וכו'. ע\"ש לכאורה אישתמיטתי' לי' תוס' זה ואחות אשת וכו'. יבמות דף ב' ע\"א אין להקשות דנדה וכו' ע\"ש ודו\"ק:","\u0003ב\"ד. \u0004 דוקא בפני ב\"ד המזומנין לכך הרב בצלאל סימן כ\"ח. יבם שרוצה ליבם ליבמתו ורקקה בפניו בפני ב\"ד כדי שתאסור עליו עיין כנה\"ג בהגהת הטור סעיף ק\"ח. וב\"ש ס\"ק מ\"ה:","\u0003לכתחלה. \u0004 כ\"כ הרמב\"ם וצריך ישוב למה פסוק דחליצת מנעל הוא מיושב לכתחלה כדאי' שם בפ\"ד ובחליצת סומא דווקא דיעבד הא תרווייהו קא חשוב בחד בריית' ביבמות דף ק\"ג ע\"א בין יושב בין מוטה והחולצת מן הסומא חליצתו כשרה. ומ\"ש הא מהא. ואפשר לומר מדמקש' על אמימר שם והתניא בין עומד בין יושב וכו' ואי אמרינן דיושב דוקא דיעבד הוא א\"כ מה מקשה הא בדיעבד כשר נמי אי לא דחק רגלו בארץ להרמב\"ם כדאי' במגי\"ד שם. ודו\"ק:","\u0003המעות. \u0004 ואם מסרה מודעה אינה מחויבת ליתן לו כלום. רש\"ל סי' כ\"ד ועיין ב\"ש:","\u0003בפניהם. \u0004 ואנו אין נוהגין לכתוב גט חליצה מאחר שחולצת ברבים אינה צריכה לשטר ראייה מהר\"י מרגלית. ורש\"ל בס\"ח כתב שמנהג יפה הוא לכותבו:"],"r":["\u0003ישראלים כו'. \u0004 ק\"א ב' בישראלים בב\"ד של ישראל כו':","\u0003ושלא כולי \u0004 ולא כולי מתני' ק\"ד ב' וקי\"ל כת\"ק וה\"ה זה לזה כמ\"ש בתוספת' וירושלמי פ\"ג דסנהדרין והוב' ברי\"ף ורא\"ש שם:","\u0003ואפילו כולי. \u0004 כמ\"ש בח\"מ סימן ל\"ג ס\"ד בהג\"ה ומיהו כולי וכתב במרדכי משום ב\"ד טועין כיון שאינו מפורש בגמ' בהדי' להיתר ובחד בעל הן פסולין:","\u0003אבל שני כולי. \u0004 גמר' שם ובב\"ב קכ\"ח א':","\u0003ואם חלצה בפני כולי. \u0004 ממ\"שש במתני' וברייתא מצות חליצה כו' מ' דוקא למצוה וכמש\"ש ק\"ו ב' אר\"י מצות חליצה כו' הקמ\"ל מצוה הכי כו':","\u0003נמצ' כו'. \u0004 מתני' הנ\"ל:","\u0003או גר. \u0004 ק\"א ב' ואנא גר אנא אלמ' אפי' א' מהן","\u0003וי\"א כו'. \u0004 דאפי' לענין יוחסין לר\"י דפוסל באמו מישר' מכשיר באביו ע\"א וכ' שם וצ\"ע מאי ראיה מיוחסין שאני כאן שהתורה מיעטתו בישר' שיה' כולו מישר' והא לראב\"י ביוחסין אפילו אמו מישר' כשר ולר' יוסי א\"צ כלל אפי' אמו וקי\"ל כוותיה בקידושין שם וכ\"כ נ\"י וכ\"כ בשם שאילתות ע\"ש:","\u0003ומיהו כו' \u0004 מתני' שם חליצתה פסול' ואמרינן ברפ\"ג דגיטין כ\"ד ב' כ\"מ כו' ואף ר\"א ל\"פ אלא בקטן ואנפילי' כמ\"ש הריב\"ש סימן תפ\"ב וכמ\"ש הרמב\"ם וש\"ע סנ\"ה:","\u0003אפילו כו'. \u0004 עבה\"ג וכמ\"ש ק\"ב ב':","\u0003י\"א כו' \u0004 דהנוטל כו'. מתניתין בבכורות פ\"ט:","\u0003דהרי בעינן כו'. \u0004 מתני' ק\"א א' וגמ' שם מ\"ט דת\"ק כו' ושם ב' בכ\"ד ישראל כו' וק\"ב צ' וק\"ד א':","\u0003ועיין כו'. \u0004 כתובות ק\"ה א':","\u0003ואפי' הב' הן ע\"ה. \u0004 שהן א\"צ להקרות:","\u0003חלצו כו'. \u0004 פי' לכתב אין עיכוב כמש\"ש ק\"ה ב' ועתו\"ס שם. ד\"ה לכתחלה:","\u0003ואלו השנים כו'. \u0004 דהא אפילו גרים דכשרים בד\"מ פסולים בהן כמ\"ש ק\"א ב' וכ\"ש קרובים או פסולים:","\u0003ודוק' כו'. \u0004 דהא אין מעכבין כנ\"ל וכמו בשלש' לר\"ש ור\"י הסנדלר שם ק\"ד ב' כ\"כ ב\"י ונ\"ל כו' והוא דוקא שהקצו השלש' לבד אבל בלא\"ה קי\"ל בספ\"א דמכות דאפי' מאה ונמצ' א' קרוב או פסול דבטלה כל העדות וה\"ה לדיינים דהא דיינים מעדות גמרינן וכ\"כ נ\"י בשם הריטב' אלא שכ' דכה\"ג אפי' לכתב כשר אלא שלא היה כבודו של רב שמואל להקצותו מן הב\"ד ונראה מה שסתם הרב משום דנוהגין להקצותו לבד כמ\"ש בסד\"ח סי\"ב וס\"ל דלא כנ\"י שמכשיר כה\"ג לכת' ועבפס\"ח סה\"א וכן נראה עיקר:","\u0003מיהו אם כו'. \u0004 דקאמר (שם לא עשתה ולא כלום ובזה) צריכה כו' מ' לכתב:","\u0003וי\"א וכו' \u0004 עפס\"ח ס\"ט ומש\"ש:","\u0003ומיהו בח\"ה כו'. \u0004 דהא הטעם שמא יכתוב כמש\"ש וכותבין שט\"ח בח\"ה כמ\"ש בפ\"ג דמ\"ק ועיין בה\"ג:","\u0003וי\"א דאין כו' \u0004 דהא דין הוא כנ\"ל ואין דנין בהן כמ\"ש בירושלמי הוב' ברא\"ש פ\"ד דסנהדרין ועח\"מ סימן ב' בהג\"ה ודוקא כו':","\u0003ושהיה בעולמו רפ\"ב:\u0004 ","\u0003וזאת כו'. \u0004 קי\"א:","\u0003או אפי' שם:\u0004 ","\u0003או עבד כו'.\u0004 רמב\"ם וכמ\"ש הרי\"ף שם דאין זה עדות כלל ע\"ש:","\u0003צריך שידעו כו'. \u0004 כמ\"ש לעיל סי' קס\"ד ס\"א:","\u0003צריך כו'. \u0004 כמ\"ש חזקה אין העדים חותמין כו' וכ\"ש ב\"ד וכן הכלל לכל מ\"ש כאן:","\u0003בן י\"ג כו'. \u0004 מתני' בנדה מ\"ה ב' ועתוס' שם ד\"ה אלו כו':","\u0003והיבמה בת כו'. \u0004 ק\"ו ב' והלכת' כו':","\u0003ושהביאו כו'. \u0004 כמש\"ש ה\"ד אי דלא אייתי כו':","\u0003אחר כו'. \u0004 שם מ\"ו א' מ\"ח ב':","\u0003ואם יש כו' \u0004 תוספת מ\"ט א' סד\"ה ואב\"א כרבנן דר\"פ בא סי' דא\"א לעליון בלא תחתון ובדדים א\"א לומר שומא דאין באין בלא זמנם:","\u0003וכן כו'. \u0004 פח\"מ סימן ל\"ה ס\"א:","\u0003אלא ע\"פ כו' \u0004 יבמות ל\"ט ב' פליגי בה כולי וכאן כ\"ע מודים:","\u0003וי\"א כו'. \u0004 ממ\"ש בקידושין פ' א' מלקין כו' סוקלין כו' אע\"ג שאין האב נאמן למכות ולעונשין כמש\"ש אלמ' הוי כעדות:","\u0003או שיצא כו' \u0004 כמש\"ש מלקין כו' הוחזקה נדה כו' ומפרש היאך הוחזקה נדה שיצא עליה קול נדה בין השכנים וזה כולו מדברי ר\"ת אבל רש\"י פי' בכתובות ע\"ב שראוה לובשת וכו' וכ\"כ לעיל סימן קט\"ו ס\"ב ובי\"ד סימן קפ\"ה ס\"ב וכבר הקשה עליו הר\"ר יואל הלוי כמ\"ש במרדכי פמ\"ח:","\u0003או בדקוה צ\"ל אם בדקו' ובדיקה מהני בכל אדם כמש\"ל סימן קנ\"ה:\u0004 ","\u0003אבל לא כו'. \u0004 דשמ' עשו ע\"פ האב כי האב נאמן להקדשות כו' כמש\"ש מרדכי ובלא\"ה אמרי' קטן עולה למנין שבעה אלא משום ש\"ץ כמ\"ש בפ\"ג דמגילה המפטיר בנבי' כו' ואף למ\"ש בא\"ח סימן נ\"ה ס\"ה בהג\"ה וכמ\"ש בירושלמי אין מדקדקין בקטן מ\"מ שנים בעינן כמ\"ש שם:","\u0003או שהם אריכות כו' \u0004 וע\"ז סומכים כו'. סה\"ת ומרדכי שם:","\u0003ואם יש כולי. \u0004 כפירש הרי\"ף ורש\"י וש\"פ שם דאפילו קודם י\"ב שנה דלא כהרמב\"ם וכרב ספרא אבל רב זביד מספקא ליה וכמ\"ש תוס' שם ד\"ה רב וביד כו' ומשני חוששין כו' וכ\"כ הרא\"ש שם אבל הרמב\"ן ורשב\"א כ' שיש לפרש גם לרב זביד ודאי סימני' לה ומה שפריך ונבדוק ה\"ק ל\"ל לסמוכי על החזקה במקום שאפשר לבדוק ע\"ש:","\u0003ישבו כו'. \u0004 עתוס' ק\"ג א' ד\"ה בין כו' ואמרינן כו' ואע\"ג דקי\"ל דחליצה כתחלת הדין כמש\"ש ק\"ד א' היינו להחמיר:","\u0003ויעמדו כו'. \u0004 שם ק\"ו א' בתי כו' לחד פי' שברש\"י ובספרי ועמד כו' וכמ\"ש בתוס' הנ\"ל:","\u0003אבל בדיעבד כו'. \u0004 גמ' שם בין עומד כו' ובע\"ג דמ\"ק כ\"א ועח\"מ סימן י\"ז אבל הרשב\"א ס\"ל אף לכתחל' מיושב והוכיח ממש\"ש א\"ל ר\"א והתניא בין כו' והוא לשיטת הראב\"ד והרא\"ש דס\"ל דאמימר לכתחלה קאמר אבל לפי' הרי\"ף דפוסל אפילו בדיעבד ופי' דשייך באידך דאמימר וכמ\"ש תוס' שם ד\"ה מאן בשם ר\"ח וכמש\"ל סל\"ב אין ראיה משם וכ\"פ ס\"ח סל\"א. דעת הרמב\"ם דקריא' בעמידה מהא דספרי וכן רקיק' אבל חליצה מיושב מברייתא הנ\"ל אבל מסוגיא דמ\"ק א\"א לומר כן וע' רשב\"א שדחק עצמו לתרץ דבריו וכ' שעיקר ראייתו מהא דפריך ר\"א לאמימר ע\"ש וא\"א לומר כן דהא הרמב\"ם ס\"ל כר\"ח ורי\"ף שהרי כ' או שהיה מהלך על אצבעות רגליו כו' שהחולץ כו' וכמ\"ש בפס\"ח סל\"א ע\"ש:","\u0003וכן חולה כו'. \u0004 ק\"ו א' לפרש\"י הנ\"ל:","\u0003דכ\"ד כו'. \u0004 כמ\"ש בכתובות י\"ד א' וע' תוס' דפסחים ל' א' בד\"ה לישהינ'. ור\"י מפרש כו':","\u0003שאם כו'. \u0004 כמ\"ש בגט ספ\"ה דערכין כ\"א ב' ועתו' שם ד\"ה האי כו' וביבמות שם חליצה כו' זימנין כו' דתניא וקרוב כו' ובערכין שם מאי עד שיאמר כו':","\u0003וכן אם כו'. \u0004 הגמ' דיבמות הני שהשוו לגט ובתוספתא פי\"ב חליצה מעושית בב\"ד של ישראל כשירה בב\"ד של גוים פסולה ובגוים חובטין אותו וא\"ל עשה מה שרב פלוני אומר לך כו' אמרינן בגיטין פ\"א לענין גט:","\u0003ואע\"ג כו'. \u0004 ר\"ל דהא בב\"ד שם ישראל כשר כנ\"ל כמש\"ש גט המעושה כו':","\u0003וא\"כ כל כו'. \u0004 ר\"ל דכפיה בישראל דוקא בדין כשר כמש\"ש בסוף","\u0003מ\"מ אין כו' \u0004 ר\"ל כיון דרוב הפוסקים מסכימים דאין לכוף מפני זזה כמ\"ש ל\"ט ב' אין כופין דקי\"ל כדעת תוס' ד\"ה אימר דאין כופין דלא כרש\"י כמו שהוכיח שם בתוס' ומש\"ש בדברי ר\"ת אלא אדרבא כופין כו' היינו במילי כמ\"ש בכתובות ס\"ד א' סד\"ה ודיני כו' וכמ\"ש בסימן קס\"ה ס\"א ע\"ש מרדכי:","\u0003ר\"א כו' \u0004 ובמרדכי כ' עוד ט\"א שיראו אם מכוון לרגלו כמ\"ש במתני' בגדול שהוא יכול להלך כו' וכמ\"ש בפס\"ח סס\"ב:","\u0003לפיכך כו'. \u0004 כפי' ב' שברש\"י דפי' ראשון כבר דחו אותה וכמש\"ל סכ\"ב בהג\"ה:","\u0003לכתחלה. \u0004 כ\"כ הרא\"ש דדרשא דחשש אסמכתא בעלמא היא דאל\"כ לא הוי פליג ר\"מ ובפ' בתרא דיומא אמרי' דכ\"ע הוא כו':\nנג) \u0003ויש פוסלין כו'. \u0004 ערש\"י ק\"ג א' ד\"ה אנפליא וד\"ה מדסיפא כו':","\u0003אבל רצועותיו כו'. \u0004 טור ומ' בכ\"ד כשר ב\"י. וצ\"ל לפ\"ז שלמד ממש\"ש ק\"ב א' קטרינן ביה מיתנא והוא חבל כמ\"ש בכמה מקומות:","\u0003וי\"א כו'. \u0004 וה\"ה של שער אבל שאר דבר לא ממש\"ש א\"ל מי לא קרינן כו' א\"ה כו' וההוא מיתנא הנ\"ל פי' הרשב\"א של עור או של שער:","\u0003צריך לכתחלה כו'. \u0004 דלכתחלה צריך לחלוץ בסנדל דרבה ורב יוסף הלכה כרבה כמ\"ש בב\"ב קי\"ד קמ\"ג ובגיטין ע\"ד ב' ועוד דהלכה כר' יוסי אפילו מחבריו וגם פשטא דמתני' מ' דיעבד כמש\"ש אלא שאין סנדל מצוי בינינו וסומכין על הירושלמי ר\"פ מ\"ח חלצה במנעל חליצתה כשרה למי נצרכה לר\"מ דרמ\"א אין חולצין במנעל תנא א\"ר יוסי מעשה שהלכתי לנציבין וראיתי שם זקן אחד ונומתי לו בקי לך ריב\"ב מימיך ונימא לי ר' שולחני הייתי בעירי ועל שולחני היה תדיר ונמתי לו ראית חולץ מימיך במה היה חולץ בסדל או במנעל אמר לי רבי וכי יש סנדל במקומינו ואמרתי מה ראה ר\"מ לומר אין חולצין במנעל וכמ\"ש הרא\"ש וש\"פ אלא שהרמב\"ן הקשה עליה אדרבא משם מוכח להיפך דאף במקום שאין מצוי מדאמר מה ראה ר\"מ כו' אלא לפי שאין תקנה בדבר חשוב דיעבד וגם סומכין על פוסקים הנ\"ל מ\"מ לכתחלה עושין צורתו דומה לסנדל בכל מה דאפשר:","\u0003שיהא העור כו'. \u0004 רש\"י ק\"א ק\"ב:","\u0003וי\"א שתהא כו' \u0004 מהא דשבת ס' ב' וכפי' הסמ\"ג וסמ\"ק:","\u0003וי\"א מבפנים. \u0004 ט\"ס וצ\"ל ולא מבפנים כו':","\u0003וי\"א כו' \u0004 כפרש\"י שם ומ\"ש בגד הוא עפ\"י פי' ראשון של רש\"י ליבמות. ק\"ב ב' ד\"ה התפור:","\u0003וי\"א שעושין כו' \u0004 שכן פי' החילוק בין מנעל לסנדל ואמרו שזהו מסאנא שאמר הרי\"ף שם ונראה שמפ' מ\"ש גזירה משום מנעל מרופט היינו קרוע התפר אבל בשבת מ' שהיה מב' חתיכות וערש\"י שם ב' ד\"ה אלא לחזק כו':","\u0003אבל כו' \u0004 וגם כו'. ממ\"ש סנדל התפור בפשתן כו':","\u0003וגם הרצועות כו'. \u0004 ממ\"ש הוא של עור ותרסיותיו כו':","\u0003י\"א כו'. \u0004 כמ\"ש בפ\"ב דשבת חשש כו' ואף שהרא\"ש וש\"פ דחו דבריו מ\"מ הרבה פוסקים כתבו כדבריו ועב\"י:","\u0003וגם כו' \u0004 דהכל למידין מתחש כמ\"ש בגמרא שם הוא של עור כו':","\u0003יהיו בו כו'. \u0004 ק\"ב א' קטרינן בה מיתנא כו' ושם ב' תרסיותיו מ' שנים וכמ\"ש בהדיא בשבת קי\"ב א' אלא שרש\"י פי' שם פי' אחר על תרסיותיו שפירש מקום קביעות הרצועות מכל מקום מ' שהן שנים:","\u0003וי\"א כו'. \u0004 מהא דב\"ק נ\"ט ב' וסנהדרין ע\"ד ב' ותענית כ\"ב א' ומכמו שכתבו תוס' שם ושם עיין מש\"ש: אבל הרי\"ף והרא\"ש פ' בסנהדרין שם ערקתא דמסאנא שאומות העולם עושין אדומות וישראל שחורות ואף לפירוש תוס' חומרא זו אין לה פנים דבשלמא החילוק שבין מנעל לסנדל ניחא דמנעל לכתחלה גזירה משום כו' אבל במנעל עצמו כיון דהאידנא הכל הולכין ברצועות שחורות מאי קפידא איכא ואף שכאן בסימן זה כתב כמה חומרות וחומרות דחומרות חומרא זו א\"ל פנים וקולא היא:","\u0003וגם כו'. \u0004 סדרים:","\u0003אבל השאר כו'. \u0004 כמ\"ש ספ\"ק די\"ט תוס' הנ\"ל:","\u0003אבל מבפנים כו'. \u0004 כי לא אמרו שם אלא מבחוץ וכמש\"ש רי\"א אף לא מנעל שחור כו' באתרא כו':","\u0003ויהיו הרצועות כו'. \u0004 וכמש\"ש דמיהדק טפי כו' ובכך הוא מהודק היטיב:","\u0003יעשו בו כו'. \u0004 כפי' הטור ורי\"ו מש\"ש חומרתא וכדעת רוב הפוסקים דשניהם בעינן חומרתא ומיתנא אף שהרמב\"ם ורשב\"א סבירא ליה דרצועות לבד סגי אלא דחומרתא לבד לא ורי\"ף וראבי\"ה סוברים דשנצי לבד סגי ומה שכתב האי דידן ר\"ל דלית ביה שנצי והרא\"ש כ' דבדידן א\"צ לכלום שדידן מהודק בלא\"ה כמ\"ש בסנ\"ג בהג\"ה ע\"ש מ\"מ יש לעשות כהני רבוותא הנ\"ל:","\u0003וי\"א כו'. \u0004 כגי' חומרתי לשון רבים ורבים הם שלשה כמ\"ש בספ\"ד דגיטין ולפחות שנים:","\u0003ולא יהיו הקשרים כו'. \u0004 כמ\"ש בשבת קי\"ב א' בדחומרתא דקטרי כו':","\u0003י\"א שלא כו'. \u0004 כמש\"ש ק\"ב א' אבל משמע משם להיפך כמ\"ש מ\"ט אילימא כו' וערש\"י ד\"ה א\"ה אפילו כו' אלא לחומרא בעלמא לכתחלה:","\u0003ויזהר לתפרו כו'. \u0004 ממ\"ש בספ\"ק די\"ט דנקט בסיכי וערש\"י שם:","\u0003ועושין כו'. \u0004 כצ\"ל ואפשר שהן מפ' א\"ם אפילו ר\"ל אם עשו בצורה זו אפי' דיעבד פסול אלא בשאינו עשוי כך וכן לא איבעיא להו כה\"ג דודאי פסול שחולץ שניהם כאחד ולא איבעיא להו רק בשחולץ אחד וגם הא דמחופ' עור ל\"ק דשם תפור ונראה כ\"א משא\"כ כאן וכ\"ז דוחק גדול דאין נראה כלל:","\u0003יהא עשוי כו'. \u0004 מתני' ק\"א א' ובשבת קי\"ב א':","\u0003ולא יהיה כו'. \u0004 ק\"ב א':","\u0003עד כו'. \u0004 מהא דשבת קמ\"א ב' תוס' שם ושם:","\u0003חלצה כו'. \u0004 כרבנן דר\"מ וכמ\"ש ק\"ג א\"ב ועא\"ח סימן ש\"א סט\"ז:","\u0003או של שעם. \u0004 ק\"א ב':","\u0003או ברגל שמאל ק\"ד א' כת\"ק:\u0004 ","\u0003או שהיה כו' \u0004 או כו'. ק\"ג ב'):","\u0003או קרוע כו'. \u0004 ק\"ב א' כנ\"ל:","\u0003או בסנדל כו'. \u0004 מתני' ק\"א א':","\u0003מי כו'. \u0004 ק\"ב ב'):","\u0003היה כו' \u0004 כנ\"ל:","\u0003או שבגד כו'. \u0004 דלא כלשון ראשון שברש\"י ק\"ב ב' ד\"ה התפור וראיה ממחופה עור הנ\"ל כ\"כ כל הפוסקים:","\u0003או שחלץ כו'. \u0004 מתני' וגמרא ק\"א א' ק\"ב א':","\u0003שולט כו'. \u0004 כמ\"ש בתפילין בס\"ב דמנחות:","\u0003ואם היא כו'. \u0004 כמש\"ש בתפילין:","\u0003אטר כו'. \u0004 סמ\"ג וסמ\"ק כתב לחלוץ בשל ימין דל\"ד לתפילין דשם משום כהה וראיה מאזן דודאי לא שייך שם משום כח בימין יותר משמאל אלא גזירת הכתוב הוא במצות חליצה:","\u0003י\"א כו'. \u0004 ממ\"ש בחולין צ\"ב ב' בעי ר' ירמיה כו' והקשו מאי איבעיא ליה והא אמרינן בספ\"ג דמנחות דבתר דידיה אזלינן ותי' דתפילין שאני דלא כתיב ימין או שמאל אלא יד כהה אותו שהוא כהה אבל במה שהקפיד תורה ימין או שמאל או שאר דבר מספקא לן אי בתר דידיה אזלינן או דשלמא:","\u0003ויש כו'. \u0004 מברייתא דבכורות מ\"ה ב' דאטר פסול ופי' לפי שאין לו ימין כלל אבל ס' הראשונה פי' שם משום כחישותא והוי מום ודוקא שולט בשתי ידיו כו' דברייתא אתחילה בשמאל כמ\"ש שם:","\u0003יבטל כו'. \u0004 ק\"ב א' ה\"ד אילימא כו'):","\u0003ומטעם זה כו'. \u0004 וגם כולי כ\"ז אינו אלא חומרא בעלמא","\u0003ויכרוך כו' \u0004 דלכך עביד מיתנ' אע\"ג דאית חומרת':","\u0003ויקשור כו'. \u0004 עמש\"כ אבל לדינא עיקר כדברי ירוש' בקשר א' ועניב' ע\"ג דאף דבשבת לא הוי קשירה מ\"מ לחליצה לא בעינן רק שיהא מהודק וכמ\"ש הרא\"ש וכמש\"ל בסל\"ג בהג\"ה ועניב' מהודק וכמ\"ש בשבת קי\"א ב' בעי רב אחדבוי כו' והוא יותר טוב מב' קשרים שאינן מהודקין כמ\"ש בשבת שם א\"ד טעמיה כו' וז\"ש בירוש' הנ\"ל עונבו כדי כו' ול\"ק בקשר שאינו מהודק ואף ר\"ז דאמר קושרו ל\"פ על ר\"ח אלא קושרו בעניב' קאמר וכ\"ה הגירס' בירושלמי ר\"ז מחוי לר' בא ב\"י כיצד הוא עושה כדי שיכול להלך בו מאיליו כיצד הוא עושה א\"ר חנינא עונבו כדי כו' ור\"ל היאך עושה שיהא מהודק שיכול להלך בו מאיליו וגם להתירו בא' מידיו וזה א\"א ע\"י קשרים ואף לגי' שכ' תוס' י\"ל ג\"כ שמפרש דברי ר\"ז ואף את\"ל דפליג מ\"מ בירושלמי מסיק כדברי ר' חנינא וכ\"כ המרדכי שפ' ר\"ח עיקר:","\u0003שני כו'. \u0004 שאין קשר גמור פחות מהן מהא דפ\"ד דשבת בשקשרן:","\u0003ואל יהדק כו'. \u0004 ועניב' כו'. עתוס' שס ד\"ה אע\"ג בשם הירושל' וכ' ומיהו כו' וכ\"כ הרא\"ש דהא קי\"ל דעניב' לאו קשר הוא אבל מרדכי כתב נראה דר' חנינא עיקר ע\"כ לא יהדק הקשר השני וסה\"ת כ' לצאת י\"ש ת\"ק ור\"ח וז\"ש ועניב' כו' וכבר הקשה ב\"י הא העניב' הוא כדי שתוכל להתירו כו' ועכצ\"ל ס\"ל ג\"כ שאין מהדק הקשר השני אלא שאין יוכל להתקיים וע\"י עניבא מתקיים ועפס\"ח סימן ס\"א:","\u0003וצריך כו' \u0004 כנ\"ל משום מעל דמעל:","\u0003ויסבב כו'. \u0004 כנ\"ל שיהא מיהודה:","\u0003סביב לשוק. \u0004 ששם היא על השוק ערום וז\"ש בירושלמי ביני מתני' שקושר מן הארכובה למטה:","\u0003ויש מי כו'. \u0004 כגי' הרי\"ף מודה רבא בלא אבה יבמי ואסוקי מילתא היא כר\"ז דאמר כל הראוי כו' וכ' הנ\"י ואם ראויה למקרי' בבת אחת לא מיעכב' ואי לא מיעכב' ולדבריו ה\"ה בלא חפצתי והא דנקט לא אבה דסתמן של אנשים ראוין לכרת ועפס\"ח סס\"ו:","\u0003ויקראו כו'. \u0004 כנ\"ל סי\"ב:","\u0003וי\"א כו'. \u0004 ממ\"ש אלא לא אבה יבמי כו' וכן בלא חפצתי לקחתה אבל כל הפוסקים כ' רק לא אבה לא חפצתי וכמ\"ש לא לחודיה:","\u0003לא אבה יבמי. \u0004 ל\"ד אלא ב' תיבות לבד כמ\"ש בפס\"ח ס\"ט צ\"ו וכן בלא חפצתי:","\u0003גם בלא חפצתי. \u0004 כדעת הסמ\"ק דלכתחלה מודה רבא וע' בפס\"ח שם ומש\"ש:","\u0003יעמוד כו'. \u0004 כדי שיוכל לדחוק יפה:","\u0003ותתיר כו'. \u0004 שם ק\"ב א' בין שהתיר כו':","\u0003הכל כו' \u0004 ותתפוס ותחלוץ ירושלמי הנ\"ל וכגי' כל הפוסקים וגוררתו בימין:","\u0003וכ\"ז בלי סיוע כו'. \u0004 ממ\"ש בירושלמי שם והביאו תוס' שם עונבו כדי שתוכל להתירו בא' מידיו דלא כר\"ת שכתב שמסייע בשמאל והוא כגי' תוס' וגוררתו בשמאל ופי' שמסייעתא ועספ\"ז דברכות:","\u0003ובכ\"ז כו') . \u0004 מברייתא הנ\"ל בין עומד כו' דיעבד דלא כהרמב\"ם:","\u0003ומשלכ' כו'. \u0004 עמ\"ש בפס' סע\"ד:","\u0003חלצ' כו'. \u0004 מהא דסל\"א וכמ\"ש בגמ' מי כתיב וחלצ' כו':","\u0003וי\"א כו'. \u0004 כמ\"ש בירוש' ר\"ז מחוי לר' בא ב\"ר יצחק כיצד הוא עושה קושרו כדי שהוא יכיל להלך בו מאיליו אלמא דוקא בסנדלים שלהן שלא היו יכולים להלך בו בלא קשיר' וע\"ז אמרו שם כיצד הוא עושה כו' ואמרו שם עיקר חליצה התרת הרצועה לפי שניתר ונופל מאיליו אבל בשלנו א\"צ דהא קשירה לא נזכר בתורה:","\u0003או שמהלך כו'. \u0004 כשטתו שמפרש כפיר\"ת והרי\"ף כנ\"ל ועבה\"ג:","\u0003וי\"א כו' \u0004 ירושלמי כינוי מתני' בקושר מן הארכוב' ולמטן כשירה מ' הארכוב' ולמעלה פסולה:","\u0003וי\"א דבנקטע' כו' \u0004 ממ\"ש ק\"ג א' ורמינהו רגלים כו' הרז\"ה וכפ' רא\"ש שם:","\u0003אבל אם כו'. \u0004 רש\"י שם א\"ה אפילו כו' כנ\"ל:","\u0003תעמוד כו'. \u0004 כמ\"ש וירקה בפניו:","\u0003רוק הנראה לדיינים מתני' ק\"ו ב':\u0004 ","\u0003יבמה כו'. \u0004 כמש\"ש מי כתיב וירקה כו' ודלא בהא דאבוה דשמואל שם והראב\"ד כ' דהא דאבוה דשמואל מיירי שלא בפני ב\"ד לפסול מן האחין וכמש\"ל סמ\"ה:","\u0003וי\"א כו' \u0004 כההי' דאבוה דשמואל ס\"ל דבני מדרשא ל\"פ אזה וכפירש\"י שם ד\"ה מי כולי ואף את\"ל דפליגי בדאורי' אזלי' לחומרא אלא דלפרש\"י דל\"פ אפי' חליצה פסולה לא הוי וע\"ל סמ\"ח וכ\"ה בירושלמי הלכה ו' בעובדא הנ\"ל דלוי הנ\"ל אמר שם ירקא דם אם יש בו לחלוחית של רוק כשר וכן אמרו שם בשם הרבה מאמוראים דדוקא אם יש לחלוחית של רוק ואין חילוק בדבר ואף שהעובדא דלוי שם בע\"א דלא שאול בי מדרשא ע\"ש מ\"מ לדינא ל\"פ:","\u0003ונהגו כו'. \u0004 משום דמצינו בכתובות מ\"א ב' ד\"א מרבי' רוק וא\"א בקיאין בכולן סה\"ת:","\u0003וקטנה כי' כגי' שלנו קטנה כו' \u0004 פסולה:","\u0003ואינה כשוטה וקטן כו' \u0004 וי\"א דה\"ה כו'. הכל מדברי רמב\"ם וקטן מפורש שם ק\"ה ב' וברפ\"ג דגיטין ובתוספתא פ\"א דיבמות חרש שנחלץ וחרשת שחלצת והחולצת מן השוטה וכן שוטה שחלצה וחולצות מן הקטן תצא ושלשה עשר דבר בה דר\"מ שאמר משום ר\"ע וחכ\"א אין ממזר מיבמה וכמ\"ש בגמ' ל\"ב א' ומדס\"ל לר\"ע דהוי ממזר אלמא אין חליצתה כלום ועוד דבחליצה פסולה לא תצא כמ\"ש בסנ\"ה ולכך נקט הנך:","\u0003וי\"א שחליצתן כו'. \u0004 מדאמר במתני' פסולה ובגמרא אמרינן הטעם לפי שאינו באמר ואמרו כמו באלם וכן אמרינן שם ק\"י א' ועמ\"מ שם. ומש\"ש ק\"ה ב' חרש שנחלץ כו' אר\"ל א\"ר זו דברי ר\"מ אבל חכ\"א אין כו' אלמא דפסולה דמתני' דוקא הוא ודברי רמב\"ם תמוהים מאד:","\u0003בפני ב\"ד. \u0004 ממ\"ש ק\"ב ב' ואין חוששין שמא חלצה כו' ולא חששו לרקיקה:","\u0003ויש כו'. \u0004 כנ\"ל ס\"מ:","\u0003ותהא כו' \u0004 כמ\"ש ברפ\"ג:","\u0003ויש מי כו'. \u0004 כנ\"ל סי\"ב דכ\"ד שאין לו תקנה הוי דיעבד:","\u0003ולא מיקרי כו'. \u0004 שהרמב\"ם כתב הטעם משום שנאמר וירקה בפניו ואין זה רואה הרוק ועיין תוס' ק\"א ב' ד\"ה ש\"מ כו':","\u0003קטנה כו'. \u0004 כנ\"ל כגי' פסולה וכמ\"ש ברפ\"ג דגיטין:","\u0003וכשתגדיל כו' \u0004 משום דגי' הירושלמי ואם לא חלצה חליצתה כשירה ובתוספות קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה דר\"א וחכמים אמרו אם לא חלצה חליצתה כשירה ולפי זה מה שכתב בגמ' והלכתא כו' היינו לכתחלה הרשב\"א ואף לפי גי' שלנו כתב תוס' ק\"ה ב' ד\"ה קטנה כו' דלהכי לא ערב לה ותני יתור לשון החלוץ ומשתגדיל להורות דאינו כלום כמו בקטן וא\"צ לכל הנ\"ל א\"צ לחזור רק הרמב\"ם כתב דחליצה פסולה ויחידאה הוא. תה\"ד ע\"ש:","ואפי' כפל התנאי ממש\"ש גט המוטעת פסולה וע\"כ בשכפל דקי\"ל כר\"מ ובכתובות ע\"ד א' מכדי כל תנאי כו'. ר\"ל ואע\"ג דרבינא ור\"א אמרו ביבמות נ\"ז א' דבתנאי בחליצה פליגי ורבינא אמר תנאי כפול כבר פי' תוס' ד\"ה רבינא דלענין קדושין שאמרו:","\u0003ואפי' כו'. \u0004 כנ\"ל דאין תנאי בחליצה ואפילו חלוץ לה ובכך אתה כונסה היה כשר אי לאו משום דאין מתכוין משא\"כ כה\"ג:","\u0003ואע\"פ שחליצה כו'. \u0004 כנ\"ל דמוטעת כשירה:","\u0003מ\"מ כו'. \u0004 כמש\"ש זיל הב לה ואף רב פפא ל\"ק משום שאינו הגון לה ומצוה רמי עליה לחלוץ והוי כעין אנוסה וכמ\"ש הירושלמי שם א\"ר מנא אם אמר ע\"מ ניתנית:","\u0003כשאר כו'. \u0004 רש\"י שם וכתב הרמב\"ן ורשב\"א ורא\"ש בע\"כ מדין תנאי אין מצריכין ליתן דכל האומר ע\"מ אין מחייבין אותו לקיים אלא אם יקיים תנאו יתקיים המעשה כו' וראיה ממ\"ש בגיטין ע\"ד ע\"ה מתקנתו של הלל כו' ואם איתא כיון דנתחייב המעות פשיטא דבע\"כ הוי פרעון כמ\"ש בב\"מ ע\"ג ב' פרעיה זוזא כו' ועתוס' בגיטין שם ד\"ה מכלל כו' אלא דכאן כיון שא\"א לחליצה ליבטל חייב מדין שכירות:","\u0003או שא\"ל חולץ שזו כו' \u0004 ירושלמי שם איזה חליצה מוטעת שרשב\"ל כל שא\"ל חלוץ והיא ניתרת לך לאחר זמן אר\"י אמש הייתי שונ' הוא מתכוין כו':","\u0003אבל נפסלה כו'. \u0004 גמרא שם:","\u0003וכופין \u0004 כו' כמ\"ש בנודרת הנאה כו' עד שכופין כו'. בשגיטה יוצאה כו'. אלמא כיון דאסורה לו כופין וכמ\"ש לעיל סימן קס\"ה ס\"ב ובירושלמי אתא עובדא קומי רב הונא ועבד כרשב\"ל כד שמע רבי יוחנן פלג וכתב וחלץ לה זימנא תנינית:","\u0003א\"ל כו'. \u0004 ירושלמי שם אתא עובדא קומי ר\"ח בר אבא וא\"ל בני האשה הזאת אינה רוצה להנשא לך דרך ייבום אלא חלוץ לה עקור זיקתך ממנה והיא נישאת לך דרך נישואין מן החלץ לה א\"ל אין אתא משה ושמואל לא שריא לה:","\u0003מסר כו'. \u0004 ממ\"ש פסולה וכמש\"ל סנ\"ה:","\u0003עברה ונשאת כו'. \u0004 אע\"ג דבלא חליצה אסרינן אבעלה משום קנסא הואיל ואסרה עצמה איבם כמ\"ש איתגורי איתגור וכן באשת איש אמרו בהאשה רבה משום קנסא וכמו שכתבו בירושלמי שם קנס קנסו בה שתהא בודקת יפה מה שאין כן כאן דבלא\"ה אסורה לו ריב\"ש:","\u0003כותבין \u0004 כו'. ספ\"ק דב\"מ שטרי חליצה כו' וכל כו' אלמא מעשה ב\"ד הוא:","\u0003ואם כו'. \u0004 יבמות ק\"ו א':"]}],["הַיְבָמָה שֶׁנָּתַן לָהּ הַיָּבָם גֵּט כְּרִיתֻת, פְּסָלָהּ וּפָסַל צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִים, \u0010c0\u0011 מִדִּבְרֵיהֶם. וְכָל גֵּט שֶׁפּוֹסֵל אִשְׁתּוֹ מְהַכְּהֻנָּה, פּוֹסֵל יְבִמְתּוֹ מֵהַיִּבּוּם; וְאֵינָהּ מֻתֶּרֶת לְזָר, עַד שֶׁיַּחֲלֹץ לָהּ:\nוְכֵן הַמַּאֲמָר \u0005(פי', יְבָמָה נִקְנֵית מִדְּאוֹרָיְתָא בְּבִיאָה, לֹא זוּלַת, וַחֲכָמִים תִּקְנוּ שֶׁיְּקַדְּשֶׁנָּהּ תְּחִלָּה, וְזֶהוּ הַנִּקְרָא מַאֲמָר, פֵּרוּשׁ מַאֲמַר חֲכָמִים)\u0006, אֵינוֹ קוֹנֶה בָּהּ קִנְיָן גָּמוּר; שֶׁאִם בָּא לְהוֹצִיאָהּ אַחַר הַמַּאֲמָר, צְרִיכָה גֵּט לַמַּאֲמָר, וַחֲלִיצָה לְהַפְקִיעַ הַזִּקָּה:\nמֵאַחַר שֶׁאֵין מַאֲמָר קוֹנֶה קִנְיָן גָּמוּר, וְלֹא גֵּט דּוֹחֶה דְּחִיָּה גְּמוּרָה, לְפִיכָךְ, מוֹעִיל הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחַר כָּךְ, הֵן גֵּט אַחַר גֵּט, הֵן מַאֲמָר אַחַר מַאֲמָר, אוֹ גֵּט וַחֲלִיצָה וּבִיאָה אַחַר הַמַּאֲמָר, אוֹ מַאֲמָר וּבִיאָה וַחֲלִיצָה אַחַר גֵּט, בֵּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, בֵּין בִּיבָמָה אַחַת וּשְׁנֵי יְבָמִים, בֵּין בִּשְׁתֵּי יְבָמוֹת וּשְׁנֵי יְבָמִים:\nכֵּיצַד, יָבָם שֶׁנָּתַן גֵּט לִיבִמְתּוֹ, וְחָזַר וְנָתַן גֵּט לְצָרָתָהּ, \u0010c1\u0011 נֶאֱסַר בִּקְרוֹבוֹת שְׁתֵּיהֶן. אוֹ שְׁנֵי יְבָמִין שֶׁנָּתְנוּ שְׁנֵיהֶם גֵּט לִיבָמָה אַחַת, זֶה אַחַר זֶה, שְׁנֵיהֶם נֶאֶסְרוּ בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים וּשְׁתֵּי יְבָמוֹת, כָּל אֶחָד נָתַן גֵּט לְאַחַת, כָּל אֶחָד נֶאֱסַר בַּקְּרוֹבוֹת שֶׁל אוֹתָהּ שֶׁנָּתַן לָהּ גֵּט:\nכְּשֶׁבָּאִים לְהוֹצִיאָהּ, לְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת צְרִיכָה חֲלִיצָה מִכָּל אֶחָד וְאֶחָד. \u0010c2\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהוּא הַדִּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, וְנָתַן גֵּט לִשְׁתֵּיהֶן, שֶׁצָּרִיךְ לַחֲלֹץ לִשְׁתֵּיהֶן. וּלְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה אֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, אֲפִלּוּ בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת, דַּי בַּחֲלִיצָה אַחַת. \u0005 הַגָּה: וְלָזֶה הִסְכִּים הָרֹא\"שׁ זַ\"ל. \u0010c3\u0011 וְהָא דַּחֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר, הַיְנוּ שֶׁהָיְתָה זְקוּקָה לְגַמְרֵי, וְנִפְסְלָה, שֶׁנִּקְלְשָׁה הַזִּיקָה. אֲבָל חֲלִיצָה פְּסוּלָה מֵעִקָּרָא, אֵינָהּ צְרִיכָה לַחֲזֹר: \u0006\nוְכֵן יֵשׁ מַאֲמָר אַחַר מַאֲמָר, שֶׁאִם עָשָׂה מַאֲמָר בְּזוֹ וְאַחַר כָּךְ בְּזוֹ, אוֹ אַחִים עָשׂוּ מַאֲמָר בָּהּ אוֹ בַּחֲבֶרְתָּהּ, כָּל אַחַת צְרִיכָה גֵּט לַמַּאֲמָר, \u0010c4\u0011 וַחֲלִיצָה לְאַחַת מֵהֶם לִפְטֹר אֶת שְׁתֵּיהֶן. וְכֵן אִם עָשָׂה מַאֲמָר בְּזוֹ, וְאַחַר כָּךְ נָתַן גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עַל צָרָתָהּ, אוֹ שֶׁאַחַר הַמַּאֲמָר שֶׁלּוֹ נָתַן לָהּ אָחִיו גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר מַאֲמָר לֶאֱסֹר בַּעֲלַת הַמַּאֲמָר, וְלֵאָסֵר \u0005(בִּקְרוֹבוֹתֶיהָ)\u0006 [בַּקְּרוֹבוֹת] בַּמַּעֲשֶׂה שֶּׁנַּעֲשָׂה אַחַר הַמַּאֲמָר, וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר וּבִיאָה שֶּׁנַּעֲשָׂה אַחֲרָיו:\nוְזֶה תַּקָּנָתָם: עָשָׂה בָּהּ מַאֲמָר \u0010c5\u0011 וְנָתַן לָהּ גֵּט, צְרִיכָה חֲלִיצָה. עָשָׂה מַאֲמָר וְחָלַץ, צְרִיכָה גֵּט. עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט לָזוֹ, נוֹתֵן גֵּט לְבַעֲלַת הַמַּאֲמָר, וְהוּא אוֹ אָחִיו חוֹלְצִים לְאַחַת מֵהֶן, וְתִפָּטֵר הָאַחֶרֶת. \u0010c6\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁשְּׁתֵּיהֶן צְרִיכוֹת חֲלִיצָה:\nעָשָׂה מַאֲמָר בָּזוֹ, וּבָעַל הוּא אוֹ אָחִיו לָזוֹ, בַּעֲלַת הַמַּאֲמָר צְרִיכָה גֵּט, וְכֵן הַשְּׁנִיָּה צְרִיכָה גֵּט, וְצָרִיךְ לַחֲלֹץ לְאַחַת מֵהֶן:\nוְכֵן אִם נָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר אוֹ בַּחֲבֶרְתָּהּ, אוֹ שֶׁחָלַץ לַחֲבֶרְתָּהּ, אוֹ שֶׁאַחַר הַגֵּט שֶׁלּוֹ עָשָׂה בָּהּ אָחִיו מַאֲמָר אוֹ בָּא עָלֶיהָ, אוֹ חָלַץ לָהּ אוֹ לַחֲבֶרְתָּהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר הַגֵּט לֵאָסֵר בִּקְרוֹבוֹתֶיהָ וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר שֶּׁנַּעֲשָׂה אַחֲרָיו:\nוְזֶה תַּקָּנָתָם: נָתַן לָהּ גֵּט וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט וַחֲלִיצָה:\nנָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ שֶׁעָשׂוּ בָּהּ מַאֲמָר, זוֹ שֶׁבָּא עָלֶיהָ אוֹ שֶׁעָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט, וְצָרִיךְ חֲלִיצָה לְאַחַת מֵהֶן לִפְטֹר שְׁתֵּיהֶן:\nהַבְּעִילָה קוֹנָה קִנְיָן גָּמוּר, וְכֵן הַחֲלִיצָה דּוֹחָה דְּחִיָּה גְּמוּרָה. \u0010c7\u0011 לְפִיכָךְ, אֵין הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחֲרֵיהֶם, מוֹעִיל, לֹא לִפְסֹל אֶת זוֹ וְלֹא לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. כֵּיצַד, בָּא עַל יְבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם. וְכֵן אִם אָחִיו חָזַר וְנָתַן גֵּט לָהּ אוֹ לְצָרָתָהּ, אֵינוֹ כְּלוּם. וְכֵן אִם חָזַר וְעָשָׂה בָּהּ מַאֲמָר אוֹ בָּעַל, אֵינוֹ כְּלוּם. אֲבָל אִם בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט:\nוְכֵן אִם חָלַץ לִיבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלְצוּ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים שֶׁחָלְצוּ לִיבָמָה אַחַת, זֶה אַחַר זֶה, אֵין חֲלִיצָה אַחֲרוֹנָה כְּלוּם, וּמֻתָּר בִּקְרוֹבוֹתֶיהָ. אֲבָל אִם אַחַר שֶׁחָלַץ לִיבִמְתּוֹ, בָּעַל, אוֹ קִדֵּשׁ הוּא אוֹ אָחִיו אוֹתָהּ אוֹ צָרָתָהּ, תָּפְסֵי לְהוּ קִדּוּשִׁין בָּהֶם וּצְרִיכָה גֵּט, בֵּין קִדְּשָׁהּ לְשֵׁם אִשּׁוּת כְּגוֹן שֶׁקִּדְּשָׁהּ סְתָם, \u0010c8\u0011 בֵּין לְשֵׁם יַבְמוּת כְּגוֹן שֶׁאָמַר לָהּ: הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי לְזִקַּת יְבָמִים:\nהָא דְּאֵין מַעֲשֶׂה מוֹעִיל אַחַר בִּיאָה, דַוְקָא בְּבִיאָה כְּשֵׁרָה שֶׁלֹּא קָדַם לָהּ מַעֲשֶׂה אַחֵר. \u0010c9\u0011 אֲבָל בִּיאָה פְּסוּלָה, כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ וּבָעַל אֶת זוֹ, אוֹ עָשָׂה מַאֲמָר בָּזוֹ וּבָעַל אֶת זוֹ, מוֹעִיל מַעֲשֶׂה שֶׁיַּעֲשׂוּ אַחֲרֶיהָ, שֶׁאִם יַחֲלֹץ הוּא אוֹ אָחִיו לַשְּׁלִישִׁית, יֵאָסְרוּ בִּקְרוֹבוֹתֶיהָ, וְגַם הִיא לֹא סָגֵי לָהּ בְּגֵט, דְּאַכַּתִּי נִשְׁאָר בָּהּ זִקָּה. אֲבָל חֲלִיצָה, אֲפִלּוּ הִיא פְּסוּלָה, שֶׁקָּדַם לָהּ מַעֲשֶׂה אַחֵר, כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ אוֹ מַאֲמָר בָּזוֹ, וְאַחַר כָּךְ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אֲפִלּוּ הָכִי אֵין מוֹעִיל אַחֲרֶיהָ, אִם חָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ; אֲבָל אִם בָּעַל אוֹ קִדֵּשׁ, תָּפְסוּ בָּהּ:\nעָשָׂה מַאֲמָר בִּיבִמְתּוֹ וְאַחַר כָּךְ נָתַן לָהּ גֵּט לְזִקָּתָהּ, פָּסְלָה עָלָיו וְעַל כָּל הָאַחִין, וּצְרִיכָה גֵּט לְמַאֲמָרָהּ וַחֲלִיצָה לְזִקָּתָהּ. \u0005 וְאִם נָתַן לָהּ גֵּט סְתָם, הָוֵי כְּאִלּוּ פֵּרַשׁ לְזִקָּתָהּ. \u0006 נָתַן לָהּ גֵּט לְמַאֲמָרָהּ וְלֹא לְזִקָּתָהּ, נִשְׁאֲרָה זְקוּקָה כְּמוֹ שֶׁהָיְתָה, וְאֵינָהּ מֻתֶּרֶת אֶלָּא לִשְׁאָר אַחִים, אֲבָל הַמְגָרֵשׁ אָסוּר בָּהּ. \u0010c10\u0011 וְיֵשׁ אוֹמְרִים שֶׁמֻּתֶּרֶת אַף לַמְגָרֵשׁ:\nבִּיאַת בֶּן תִּשְׁעָה כְּמַאֲמָר בְּגָדוֹל. לְפִיכָךְ, בָּא עַל הַיְבָמָה, פְּסָלָהּ עַל כָּל הָאַחִים. וְאִם אַחַר שֶׁבָּא עָלֶיהָ חָזַר אָחִיו הַגָּדוֹל וּבָא עָלֶיהָ אוֹ עַל צָרָתָהּ, אוֹ עָשָׂה מַאֲמָר אוֹ נָתַן גֵּט אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, פְּסָלָהּ עַל הַקָּטָן. וְכֵן אִם חָזַר הַקָּטָן וּבָא עַל צָרָתָהּ, אוֹ שֶׁאָחִיו בֶּן ט' בָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ עָלָיו כְּדִין מַאֲמָר אַחַר מַאֲמָר. וְכֵן אִם עָשָׂה הַגָּדוֹל מַאֲמָר בִּיבָמָה, וְחָזַר אָחִיו בֶּן ט' וּבָא עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ כְּדִין מַאֲמָר אַחַר מַאֲמָר. \u0010c11\u0011 וּמַאֲמָר שֶׁל בֶּן ט' אֵינוֹ חָשׁוּב כְּמַאֲמַר הַגָּדוֹל, וְאֵינוֹ מוֹעִיל אֶלָּא בִּתְחִלָּה, אֲבָל לֹא בַּסוֹף. כֵּיצַד, עָשָׂה קָטָן מַאֲמָר, מוֹעִיל לְפָסְלָהּ עַל הָאַחִים. אֲבָל אִם עָשָׂה הַגָּדוֹל מַאֲמָר, וְחָזַר בֶּן ט' וְעָשָׂה מַאֲמָר בָּהּ אוֹ בְּצָרָתָהּ, אֵינוֹ מוֹעִיל לְפָסְלָהּ עַל הָאָח הַגָּדוֹל. אֲבָל מַאֲמָרוֹ שֶׁל בֶּן ט', אַחַר מַאֲמָר בֶּן ט', אִכָּא לִמֵימַר שֶׁמּוֹעִיל, כֵּיוָן שֶׁמַּאֲמַר הָרִאשׁוֹן מִבֶּן ט'. וְגֵט וַחֲלִיצָה, אֵין לַקָּטָן כְּלָל, לֹא בִּתְחִלָּה וְלֹא בַּסוֹף:\nגָּדוֹל שֶׁעָשָׂה מַאֲמָר בִּיבָמָה אוֹ נָתַן לָהּ גֵּט וְלָהּ צָרָה, כְּשֶׁבָּא לַחֲלֹץ לְאַחַת מֵהֶן וּלְהַתִּירָן, אֵין חֲלִיצַת בַּעֲלַת הַגֵּט אוֹ בַּעֲלַת הַמַּאֲמָר פּוֹטֶרֶת הַצָּרָה. אֲבָל חֲלִיצַת הַצָּרָה פּוֹטֶרֶת לְבַעֲלַת הַגֵּט לְגַמְרֵי, וּלְבַעֲלַת הַמַּאֲמָר מֵחֲלִיצָה, וּצְרִיכָה עוֹד גֵּט לְמַאֲמָרָהּ. וְאִם עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט לָזוֹ, חוֹלֵץ לְאֵיזוֹ שֶׁיִּרְצֶה וּפוֹטֵר הַשְּׁנִיָּה, כְּמוֹ שֶׁנִּתְבָּאֵר:\nמִי שֶׁנָּפְלוּ לְפָנָיו שְׁתֵּי יְבָמוֹת מִבַּיִת אֶחָד, הָאַחַת שְׁנִיָּה לְיָבָם וְאַחֶרֶת \u0005 מֻתֶּרֶת, \u0006 כְּשֶׁהוּא מְיַבֵּם מְיַבֵּם לָאַחֶרֶת, כְּשֶׁהוּא חוֹלֵץ \u0010c12\u0011 חוֹלֵץ לַשְּׁנִיָּה. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם חָלַץ לַאֲסוּרָה, לֹא הֻתְּרָה צָרָתָהּ; חָלַץ לַצָּרָה, הֻתְּרָה הָאֲסוּרָה:\nיְבָמוֹת רַבּוֹת הַבָּאוֹת מִבַּיִת אֶחָד, כֵּיוָן שֶׁנִּבְעֲלָה אַחַת מֵהֶן בְּעִילָה כְּשֵׁרָה, אוֹ נֶחְלְצָה חֲלִיצָה מְעֻלָּה, הֻתְּרוּ הַכֹּל וְנִסְתַּלְּקָה זִקַּת הַיָּבָּם מֵעֲלֵיהֶן. וְאִם נִבְעֲלָה אַחַת מֵהֶן בְּעִילָה פְּסוּלָה, אוֹ נָתַן לָהּ מַאֲמָר פָּסוּל, נֶאֶסְרוּ כֻּלָּם לְיִבּוּם, וּצְרִיכָה גֵּט זוֹ שֶׁנִּבְעֲלָה אוֹ שֶׁנָּתַן לָהּ מַאֲמָר, \u0010c13\u0011 וּצְרִיכָה כָּל אַחַת מֵהֶן חֲלִיצָה לְהַתִּירָהּ לְזָר, שֶׁאֵין זִקַּת הַיִּבּוּם מִסְתַּלֶּקֶת בִּבְעִילָה פְּחוּתָה. נֶחְלְצָה אַחַת מֵהֶן חֲלִיצָה פְּחוּתָה, הֻתְּרָה לְהִנָּשֵׂא לְזָר אוֹתָהּ שֶׁנֶּחְלְצָה, אֲבָל צָרָתָהּ אֲסוּרָה עַד שֶׁתַּחֲלֹץ גַּם הִיא, אוֹ עַד שֶׁיַּחְלְצוּ כָּל הָאַחִים לָרִאשׁוֹנָה שֶׁנֶּחְלְצָה הַחֲלִיצָה הַפְּחוּתָה, שֶׁאֵין חֲלִיצָה פְּחוּתָה מְסַלֶּקֶת זִקַּת יִבּוּם מִבַּיִת זֶה, עַד שֶׁתַּחֲזֹר עַל כָּל הָאַחִים, אוֹ עַד שֶׁתַּחֲלֹץ כָּל אַחַת מֵהֶן. זֶהוּ דַּעַת הָרַמְבַּ\"ם \u0005(ח\"ב קי\"ח ב')\u0006, וְנֶחְלְקוּ עָלָיו \u0005 כְּמוֹ שֶׁהוּא מְפֹרָשׁ בְּדִבְרֵי הַטּוּר: \u0006\nשְׁנֵי יְבָמִים שֶׁיִּבְּמוּ שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד, וְלֹא נוֹדַע מִי יִבֵּם תְּחִלָּה, שְׁנֵיהֶם יוֹצִיאוּ בְּגֵט, וְיֻתְּרוּ לְזָרִים, וַאֲסוּרוֹת לִיְבָמִים. לְפִיכָךְ, רְאוּבֵן שֶׁהָיוּ לוֹ שְׁתֵּי נָשִׁים, אַחַת בְּעַכּוֹ וְאַחַת בְּצוֹר, וְשִׁמְעוֹן וְלֵוִי אֶחָיו, הָאֶחָד בְּעַכּוֹ וְהָאֶחָד בְּצוֹר, וְשָׁמְעוּ שֶׁמֵּת רְאוּבֵן לֹא יְיַבֵּם אֶחָד מֵהֶם עַד שֶׁיֵּדַע מֶה עָשָׂה אָחִיו. \u0010c14\u0011 קָדַם אֶחָד מֵהֶם וְיִבֵּם, אֵין מוֹצִיאִין מִיָּדוֹ עַד שֶׁיִּוָּדַע שֶׁאָחִיו יִבֵּם תְּחִלָּה:",[],["\u0003מדבריהם\u0004. הטעם מבואר בש\"ס מדהגט וקידושין מהני בעלמא חיישינן דיאמרו הואיל הגט לא מהני ומותרת ליבם ה\"ה אחר החליצ' מותרת ליבם אף על גב דהגט לא מהני אלא מדרבנן מ\"מ עשאו בכל הגט אפי' גט דלא מהני באשה בעלמא רק פוסל לכהונה מ\"מ מהני ביבמה דאסורה ליבם וכן מאמר דמהני בעלמא יאמרו מדמאמר לא מהני ומותר לישא השניה כן מותרת השניה אחר הביאה ואתי למבעל אחר הביאה והוה ליה בונה שני בתים ועיין לקמן:","\u0003נאסר בקרובות שתיהן\u0004. הנה ליש מי שאומר שהביא בסעיף ה' בשתי יבמות לא נפטרה הצרה בחליצה פסולה כזו שנתן גט לראשונה וצריך לחלוץ אף לשניה אם כן ממילא אסור בקרובות שתיהן אפילו לא תפס הגט בשניה אלא נ\"מ אף אם לא חלץ לשניה:","\u0003ויש מי שאומר\u0004. מקור דין זה נובע מסוגיא ר\"פ ד' אחים דאיתא שם בעלת מאמר ובעלת גט כי הדדי נינהו ופרש\"י שחליצת א' מהן פוטרת חברתה כיון שהן שוין דבעלת מאמר צריכה נמי גט וכתבו תוספות והרא\"ש דאתי' סוגי' זו כשמואל ואליבי' תירוץ הראשון בסוגי' הקודמות לזו ובג' אחיות הנופלות לפני ב' האחים זו אחר זו דס\"ל לשמואל א' חולץ לאחת והשני לשניה ולשלישית חולץ א' מהם אף על פי שהיא חליצה פסולה א\"צ לחזור על כל האחים ולפי תירוץ זה אין חילוק בין היבמה ובין צרתה א\"כ נשמע נמי בצרתה אם שניהם שוין פוטרת א' לחברתה כשם שיבמה שלישית נפטרה בחליצה א' אעפ\"י שאסורה עליו משום אחות חלוצתו מ\"מ פוטר כיון שאחיו ג\"כ שוה לו באיסור ש\"מ כל ששוים פוטר זא\"ז ולרב כשם דס\"ל דשלישית צריכה חליצה מכל א' כן ה\"נ אם נתן גט לשתי יבמות צריכה כל אחת חליצה ורש\"י לא פירש בסוגי' זו תלי' בפלוגתת רב ושמואל הנ\"ל מזה דייק הטור דס\"ל לרש\"י בשתי יבמות עדיף אף לרב א\"צ חליצה כל אחת וכן משמע מדבריו ר\"פ ר\"ג מאמר בזו ומאמר בזו ע\"ש ולזה נתכוון הטור מ\"ש בדין זה בשם רש\"י דחולק על יש מי שאומר שהבי' כאן וא\"צ דחיק' הב\"ח ע\"ש, והנה בסמוך סעיף ז' הבי' ג\"כ דיעה זו בשם יש מי שאומר ותימ' עליו אף דיש לדייק מרש\"י כהנ\"ל מ\"מ מדברי תו' והרא\"ש משמע דאתי' כשמואל אבל לרב לא עדיף חליצה פסולה זו בשתי יבמות מחליצה פסולה שני יבמים וצריכים כולם חליצה וכן הוא לדעת רש\"י שהבי' הרא\"ש וגם למ\"ש בסעיף י\"ט מבואר אף להרמב\"ם ס\"ל כן ושם נתבאר בס\"ד:","\u0003והא דחליצה פסולה\u0004. כ\"כ בד\"מ בשם א\"ז, וכבר כתבתי כן בשם תוס' ועיין בת\"ה סימן רכ\"ה קטנה שחלצה בטעות אחר שהגדילה א\"צ לחזור על כל האחים דחליצת קטנה אינה חליצה כלל וכו' ש\"מ כל מה דאינה חליצה מדאורייתא לא קלשה הזיקה וא\"צ לחזור ע\"כ האחים:","\u0003וחליצה לאחת מהן\u0004. גם כאן לטעמיה אזיל כמ\"ש בסעיף הקודם דס\"ל יבם א' וב' יבמות ונתן גט לכ\"א די בחליצה לאחת מהן כן ה\"נ אם עשה מאמר בזו ובזו צריכה כ\"א גט מ\"מ די בחליצה א' וכן אם עשה הוא מאמר בא' ואחיו בשניה צריכה כ\"א גט ודי בחליצה אחת לא' משתיהן, היינו אם הוא נותן חליצה חולץ לשניה מה שאחיו גירש אז זו נפטרה בחליצה זו מאחר שזה לא גירש אותה ועדיף חליצתו בה מחליצת אחיו ושני' גם כן פטורה מחמת חליצה זו, ואם הוא עשה מאמר בזו ואחיו עשה ג\"כ בזו באמת צריכה חליצה מכל א' כמ\"ש בסעיף הקודם ולא כתב כאן אלא חליצה לאחת מהן מאלו יבמות שנתנו לה הגט:","\u0003ונתן לה הגט\u0004. אפילו נתן לה גט סתם א\"צ גט אחר והוי גט למאמר ולזיקה ומ\"ש בהגהות סעיף ט\"ו לא כתב אלא לענין אם נאסרת לשאר אחים ועיין תוס' ריש פר\"ג:","\u0003ויש מי שאומר\u0004. כאן הביא דיעה זו ובכמה סעיפים סותם ופסק דחליצת א' מהן פוטרת את חברתה:","\u0003לפיכך אין המעשה וכו' מועיל\u0004. בביאה שפיר לא מהני בה שום מעשה אף על גב דמהני בצרתה, אבל בחליצה מהני אף בה דאם קידש או בעיל וע\"כ צ\"ל מ\"ש אין המעשה מועיל סמך אמ\"ש כיצד כלומר המעשה המבואר אין מועיל אבל ביאה וקידושין מועיל ואסור בקרוביה של צרתה אם בא עליה דהא צריכה גט ממנו, וכ\"כ בפרישה סעיף כ\"ב ולא כמ\"ש בדרישה וקידושין בצרתה אחר שבעיל את זו אם אמר בזיקת יבמים דינו כמו קידושין אחר שחלץ והכל דין א' כמ\"ש בסעיף י\"ג ואם קידש סתם קידושין דאורייתא כי אז פרח הזיקה ועיין בסמוך:","\u0003בין לשם יבמות\u0004. עיין בהרא\"ש והנה לדעת הרי\"ף ורמב\"ם והרא\"ש וכן דעת הרמב\"ן במלחמות ה' אפילו חלץ חליצה כשירה ואמר מקודשת לי בזיק' יבמה תפסו בה קידושין כי היכי דתקנו חז\"ל דקדושין ביבמה תופסים כך קדושין אלו אחר החליצה תופסים בה אף שהוא סבר שהיא יבמתו ובאמת היא אחר החליצה לאו יבמתו מ\"מ קידושין תופסין בה מדרבנן אלא החילוק הוא אם קדשה בסתם או לשם אישות אז הוי קידושין דאורייתא אף על פי שהיא אסור' עליו בלאו כמ\"ש בסי' קס\"ב מ\"מ מדאורייתא הוי קידושין גמורים אבל אם קידש בזיקת יבמי' אפי' אם חלץ חליצה פסולה לפי מה דקי\"ל חליצה פסולה פוטרת תו ליכא קידושין דאוריית' ועיין בש\"ג שם ס\"פ ר\"ג ונראה אף למ\"ד חליצה פסולה צריכה לחזור ע\"כ האחים אם חלץ לה ח\"פ ויש כאן שאר אחים וקידש אותה בזיקת יבמים החולץ אף שעדיין יש עליה זיקה וצריכה חליצ' משאר אחים מ\"מ קדושין אינן תופסים מדאורייתא:","\u0003אבל ביאה פסולה וכו'\u0004. היינו חז\"ל עשאו זאת דמהני אחר ביאה פסולה דאי ביאה אחר הגט גזירה משום ביאה אחר חליצה כלומר אם יקנה הביאה אחר הגט קניה גמורה אתי למבעל לכתחלה אחר החליצ' ואם ביאה אחר המאמר גזרי' אטו ביאה אחר ביאה כלומר אתי למבעל צרה זו אחר שייבם אחת מהן אבל החליצה אף שהוא ח\"פ ליכא למגזר כלום ועיין בש\"ס:","\u0003וי\"א שמותרת אף למגרש\u0004. וא\"ל לפ\"ז למה תני מאמר בזו ומאמר בזו צריכה גט כ\"א וחליצה ואסור לייבם, למה לא יתן גט למאמר בפירוש ואז מותרת לו וגם לדיעה קמייתא קשה יתן גט למאמר לאחת ולייבם השני תירצו תוס' פד\"א דף ל\"ב לכתחלה אין לעשות כן דגזרנן גט למאמרו אטו גט לזיקתו ודוקא בדיעבד קאמר הכי דאם גירש למאמרו הותרה:","\u0003ומאמר של בן ט' וכו'\u0004. באמת לא מצינו שום טעם למה מאמר של קטן מהני לפי הטעם ר\"פ ר\"ג שהבאתי רס\"ז דמאמר מהני בגדול הטעם דגזרינן הואיל ומאמר היינו קידושין מהני בעלמא וביבמה לא מהני יאמר אף הביאה לא מהני א\"כ בקטן דאינו קונה לא שייך גזירה זו והנה פ\"ק דקדושין דף י\"ט איתא שם דרש\"י ותוס' מחולקים בקטן הבא על יבמתו לרש\"י קונה אותה מדאורייתא לכל מילי רק הבא עליה אין חייב משום א\"א לפ\"ז י\"ל דאיכ' נמי צד איסור דאוריית' אם בא עליה אחיו אחר שבא עליה הקטן משום איסור אשת אחיו והוי כמו החולץ בא עליה בזה שפיר הגזירה מדקדושין וביאה של קטן בעלמא אינו כלום יאמרו ביבמה ג\"כ אינו כלום ויבא עליה אחיו אבל לשיטת התוס' דס\"ל דביאה של קטן ביבמה מדרבנן כמו מאמר דגדול א\"כ מנ\"ל לגזור אטו ביאה כיון אחר הביאה ג\"כ אין איסור, ועיין במגיד פ\"ה הביא ג\"כ פלוגתא זו וצ\"ע, וליורשה ולטמא לה תלי' נמי בפלוגת' זו כמ\"ש שם לפ\"ז אפשר מ\"ש רש\"י בנדה דזוכה בנכסי אחיו והבאתי ר\"ס קס\"ז י\"ל רש\"י לטעמיה דס\"ל דהוי קנין גמור אבל לשיטת שאר פוסקים אינו זוכה בשום דבר מדין עד שיגדיל:","\u0003חולץ לשניה\u0004. כ\"כ המגיד פ\"ז בשם ה\"ג אף על גב דקי\"ל חליצה פסולה אינה פוטרת צרתה היינו דוקא שנאסרה עליו בזיקה כגון שעשה בה מאמר או נתן לה גט אבל כשאסורה עליו מתחלתן חליצה כשרה היא וכ\"כ תוספ' ר\"פ ד\"א והיינו כמ\"ש בהגהות רס\"ז וכ\"פ הש\"ג ויש מי שאומר הוא דעת הרמב\"ם והטור וכן משמע מרש\"י ר\"פ ד\"א דס\"ל דשוה לדין בעלת גט ובעלת מאמר, אלא דקשה לפ\"ז מבריית' פ\"ב דף כ' דתני איסור מצוה ואיסור קדושה חלץ לה נפטר צרתה, וב\"ח כתב דבריית' זו איירי מדאוריית' פוטרת אלא מדרבנן תקנו דח\"פ אין פוטרת ול\"ד דהא איסור מצוה ואיסור קדושה תנא וא' מהם היינו שניות א\"כ אף מדרבנן פוטר ואפשר ליישב למ\"ש שם לצדדים אתמר בא עליה קאי על איסור מצוה שהוא מדרבנן וחלץ לה קאי על איסור קדושה וי\"ל דאיירי דצרתה גם כן אסורה כמותה מ\"ה באיסור מצוה שהיא מדרבנן מ\"מ פוטר בביאה כשהיא וצרתה שוין כמ\"ש ר\"ס קע\"א ובאיסור קדושה פוטרת מדאוריית' בחליצה והנה לפוסקים דס\"ל בצרות כשהם שוים באיסור פוטרת זא\"ז כמ\"ש רס\"ז י\"ל הברייתא איירי כשהצרה ג\"כ איסור מצוה וכ\"כ המגיד אלא לפי פירושו לדעת הרמב\"ם דס\"ל אף כשצרות שוים מ\"מ אין פוטרת זא\"ז קשה לו ליישב וע\"ש ובסמוך יתבאר זאת ועל המחבר תימא שהביא דעת הרמב\"ם בשם יש מי שאומר ש\"מ עיקר כדיעה קמייתא ובסימן קע\"ד סותם ופוסק כרמב\"ם גם על רמ\"א קשה שכתב בסימן קס\"ז בענין חליצה פסולה דוקא שהיתה זקוקה ונפסלה והיינו כדיעה קמייתא ושם בר\"ס קע\"ד לא הגיה כלום:","\u0003וצריכה כ\"א מהן חליצה\u0004. כ\"כ המגיד עיקר הגירס' ברמב\"ם כך היא ובטור הביא דברי הרמב\"ם ושם כתב וצריכה אחת מהן חליצה גם לא כתב בסוף דבריו עד שתחלוץ כל א' ודוחק לומר שדולג מדברי הרמב\"ם מה שחולק על הטור בענין אם הצרות שוים פוטרת זא\"ז בחליצה של אחת מהן, ולפי הגירסא בטור ס\"ל לרמב\"ם נמי כשהן שוים פוטרת זא\"ז ומ\"ש וצריכה אחת מהן חליצה היינו א' מצרות ולא זו שנבעלה ביאה פסולה או נתן לה מאמר פסול, ואם נחלצה א' משאר צרות אז כולם פטורות כי זו שנבעלה פשיטא פטורה דהא חליצתה גרוע מחליצה זו ושאר צרות שוים לזו ופטורה כמו בעלת מאמר ובעלת גט לפ\"ז ל\"ק נמי הברייתא איסור מצוה ואיסור קדושה נפטרה צרתה כמ\"ש בסעיף הקודם לפ\"ז אם נפלו לפניו ב' אחיות מב' בתים ולכ\"א צרה א' אם חלץ לאחיות לא נפטרו הצרות שום אחת מצרות לא נפטרה כגון אם חלץ לאה בראשון והוי ח\"פ משום דהיא אחות זקוקה מ\"ה לא נפטרה הצרה, ואם אח\"כ חלץ לרחל שהיא אחות חליצתו לא נפטרה הצרה דלא שוה רחל עם הצרה אף על גב דהצרה ג\"כ אסורה משום צרות קרובת חליצתו מ\"מ קרובת חליצתו גרע, כן הוא לפי תירוץ רב אשי דקי\"ל כוותיה אף על גב לפי תירוץ התחיל ולא התחיל מוכח דשוים נינהו מ\"מ לתירוץ רב אשי חליצת רחל גרועה טפי ועיין בהרא\"ש שם אבל לפי הגירסא שכתב כאן והיינו גירסת המגיד ס\"ל לרמב\"ם ח\"פ אינה פוטרת צרתה אפי' כשהן שוין בפסול מ\"ה צריכה כ\"א חליצה והיינו שאר צרות ועליהן כתב כ\"א ולא דיבר כאן מזו שנפסלה בגט או במאמר שזו בוודאי נפטרה בחליצת אחרת ולא כהבנת המגיד מ\"ש צריכה כ\"א והיינו זו שנפסלה וכ\"א משאר צרות ותמה על הרמב\"ם למה לא נפטרה זו בחליצת שאר צרות כמו חלץ לצרה נפטרה בעלת הגט דאמר שמואל, וא\"ל לפ\"ז על המחבר שסתם ופסק כמה פעמים בסימן זה דח\"פ פוטרת צרתה כשהן שוין וכאן הביא דעת הרמב\"ם דצריכה כ\"א חליצה, וי\"ל דסמך את עצמו על מה שמסיים ונחלקו עליו וס\"ל עיקר כדעת החולקי' אלא הביא דברי הרמב\"ם דנשמע מדבריו כמה דינים דח\"פ פוטרת לזו וגם אם חלצו כל האחים לזו פוטרת את אחרת ועיין במגיד שכתב בשם הרמב\"ן והרשב\"א דחולקים עליו בזה ואף לפי גירסא זו י\"ל הברייתא איסור מצוה ואיסור קדושה דס\"ל לרמב\"ם אף על גב ח\"פ אין פוטרת את צרתה אפילו בשוין מ\"מ באיסור שבכה\"ג איסור מצוה ואיסור קדושה שאסור מתחלתה ולא נפקעה הזיקה פוטרת את צרתה כשהן שוין, וכשהיא פטורה בח\"פ איתא בסוגיא שני תירוצים לתירוץ א' אפילו לכתחלה לא מהדרין אחר חליצה כשרה כגון אם כבר חלץ ראובן לאחת וזו אחות חליצתו ויש כאן אחר מ\"מ חולץ ראובן לזו וכ\"פ הרי\"ף אבל לדעת הראב\"ד והרא\"ש דכל מה שאפשר לחלוץ חליצה כשרה מהדרין אחר חליצה כשירה אפילו למפטר נפשיה לפ\"ז אם א' מאחין נתן גט מהדרין שיחלוץ אחר ולא הוא אף על פי שהוא שליח דכולם לענין איסור דכולם אסורין לייבם מחמת גיטו, ולכאורה נראה לדעת הרא\"ש אפילו בדיעבד לא נפטרה היא מאחר דאפשר לחלוץ מאח השני דהא הוא תופס עיקר התירוץ הראשון חולץ לכולם היינו אמצעית ולההיא שינויא לא מפליגין בין מפטר נפשה למפטר צרה אם כן כשם אם חלץ לבעלת גט לא נפטרה הצרה אף בדיעבד כן הוא אם חלץ אח אחד שחליצתו פסולה טפי משני לא נפטרה זו כמ\"ש שם מפורש בתוס' ובהרא\"ש מ\"ה כתבו לפי תירוץ זה כל ששווים פטורה זו בחליצת זו וכן באחים אם הם שווים ש\"מ אם אין שוין אפילו בדיעבד לא נפטרה ולכאורה קשה על הטור שכתב בשם הראב\"ד לכתחלה מהדרין אחר חליצה כשרה לפטור את עצמה ובדיעבד מה דעבד עבד וכתב ולזה הסכים הרא\"ש ולכאורה לא משמע כן אף שהביא הרא\"ש דברי הראב\"ד מ\"מ לפסק הלכה לפי מה שפסק הרא\"ש בתירוץ קמא לפי דאתי אליביה דרב אשי כמ\"ש בתוספות משמע דס\"ל אף בדיעבד לא נפטרה, ואפשר דס\"ל כמ\"ש ברי\"ו דקי\"ל כתרי תירוצים בש\"ס לכתחילה מהדרין אחר חליצת כשירה כתירוץ הראשון ובדיעבד מהני ח\"פ כתירוץ שני דמחלק בין למפטר נפשיה ובין למפטר צרה ועיין ב\"ח שהביא דברי רי\"ו ג\"כ מיהו לישנא דהרא\"ש מ\"ש הלכך האי שינויא עיקר לא נתיישב לפ\"ז, עיין בהרא\"ש שכתב שתים הראשונים אי נפלו בבת אחת זה חולץ לאחת וזה חולץ לאחת, וטעמו משום ח\"פ א\"צ חזר' ע\"כ אחין מ\"ה הראשונה אף על גב דאסורה משום אחות זקוקתו מ\"מ א\"צ חזרה ע\"כ אחים והשניה אסורה לראשון משום אחות חלוצתו ולשני אסורה משום אחות זקוקתו יותר טוב שיחלוץ השני אף שאסורה עליו משום אחות זקוקתו, ומ\"ש אי נפלו בבת אחת לרבותא כ\"כ ומכ\"ש אי נפלו זא\"ז ואפשר צריך להיות הגירסא אפי' נפלו בבת אחת, וראיתי בב\"ח מגי' אי לא נפלו בבת א' ולכאורה נראה כמ\"ש דיותר עדיף שיחלוץ זה שאסורה עליו משום זיקא דהא לזה שחלץ אסורה משום אחות חלוצה ובאמת עדיין הן זקוקים לו ואסורה משום אחות זקוקה:","\u0003קדם א' מהם\u0004. עיין ברמב\"ם פ\"ה מסיים וכתב רצה א' לחלוץ קודם שידע מה עשה אחיו אין מונעים אותו והמחבר דילג משום דהקשה עליו בכ\"מ ובבדק הבית דיש לחוש שמא כבר ייבם אחיו ואם כן החליצה אינו ואתה מצריכה כרוז לכהונה כמ\"ש באשה שהלך בעלה וצרתה למ\"י וכמ\"ש בס\"ס ק\"מ ובאמת על קושיא זו י\"ל דאין חשש שייב' אחיו דהא אסור לייבם עד שנדע מיבמה שניה אלא זאת קשה שמא חלץ אחיו ולמ\"ש שם לק\"מ ועיין ב\"ח ודרישה, והב\"י כתב בשם תשובת הגאונים בשני יבמים שייבמו שתי יבמות דצריכין לגרש וצריך לחלוץ אחת דיש לחוש שמא א' עשה בה מאמר ואח\"כ בא אחיו על השניה והוי ביאה אחר מאמר, ואף שבעל המאמר בא אח\"כ על הראשונה מכל מקום ביאתו פסולה:"],"\u0010g0\u0011 \u0010r0\u0011 הַיְבָמָה שֶׁנָּתַן לָהּ הַיָּבָם גֵּט כְּרִיתֻת, פְּסָלָהּ \u0010r1\u0011 וּפָסַל צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִים, \u0010c0\u0011 \u0010r2\u0011 מִדִּבְרֵיהֶם. \u0010g1\u0011 וְכָל גֵּט שֶׁפּוֹסֵל אִשְׁתּוֹ מְהַכְּהֻנָּה, פּוֹסֵל יְבִמְתּוֹ מֵהַיִּבּוּם; \u0010g2\u0011 \u0010r3\u0011 וְאֵינָהּ מֻתֶּרֶת לְזָר, עַד שֶׁיַּחֲלֹץ לָהּ: \u0010g3\u0011 \u0010r4\u0011\nוְכֵן הַמַּאֲמָר \u0005(פי', יְבָמָה נִקְנֵית מִדְּאוֹרָיְתָא בְּבִיאָה, לֹא זוּלַת, וַחֲכָמִים תִּקְנוּ שֶׁיְּקַדְּשֶׁנָּהּ תְּחִלָּה, וְזֶהוּ הַנִּקְרָא מַאֲמָר, פֵּרוּשׁ מַאֲמַר חֲכָמִים)\u0006, אֵינוֹ קוֹנֶה בָּהּ קִנְיָן גָּמוּר; \u0010r5\u0011 שֶׁאִם בָּא לְהוֹצִיאָהּ אַחַר הַמַּאֲמָר, צְרִיכָה גֵּט לַמַּאֲמָר, וַחֲלִיצָה לְהַפְקִיעַ \u0010g4\u0011 \u0010r6\u0011 הַזִּקָּה:\nמֵאַחַר שֶׁאֵין מַאֲמָר קוֹנֶה קִנְיָן גָּמוּר, וְלֹא גֵּט דּוֹחֶה דְּחִיָּה גְּמוּרָה, לְפִיכָךְ, מוֹעִיל הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחַר כָּךְ, הֵן גֵּט אַחַר גֵּט, הֵן מַאֲמָר אַחַר מַאֲמָר, \u0010r7\u0011 אוֹ גֵּט וַחֲלִיצָה וּבִיאָה אַחַר הַמַּאֲמָר, אוֹ מַאֲמָר וּבִיאָה וַחֲלִיצָה אַחַר גֵּט, \u0010r8\u0011 בֵּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, בֵּין בִּיבָמָה אַחַת וּשְׁנֵי יְבָמִים, בֵּין בִּשְׁתֵּי יְבָמוֹת וּשְׁנֵי יְבָמִים: \u0010g5\u0011 \u0010r9\u0011\nכֵּיצַד, יָבָם שֶׁנָּתַן גֵּט לִיבִמְתּוֹ, וְחָזַר וְנָתַן גֵּט לְצָרָתָהּ, \u0010c1\u0011 נֶאֱסַר בִּקְרוֹבוֹת שְׁתֵּיהֶן. \u0010r10\u0011 אוֹ שְׁנֵי יְבָמִין שֶׁנָּתְנוּ שְׁנֵיהֶם גֵּט לִיבָמָה אַחַת, זֶה אַחַר זֶה, שְׁנֵיהֶם נֶאֶסְרוּ בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים וּשְׁתֵּי יְבָמוֹת, כָּל אֶחָד נָתַן גֵּט לְאַחַת, כָּל אֶחָד נֶאֱסַר בַּקְּרוֹבוֹת שֶׁל אוֹתָהּ שֶׁנָּתַן לָהּ גֵּט: \u0010g6\u0011 \u0010r11\u0011\nכְּשֶׁבָּאִים לְהוֹצִיאָהּ, לְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת צְרִיכָה חֲלִיצָה מִכָּל אֶחָד וְאֶחָד. \u0010c2\u0011 \u0010g7\u0011 \u0010r12\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהוּא הַדִּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, וְנָתַן גֵּט לִשְׁתֵּיהֶן, שֶׁצָּרִיךְ לַחֲלֹץ לִשְׁתֵּיהֶן. \u0010g8\u0011 \u0010r13\u0011 וּלְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה אֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, אֲפִלּוּ בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת, דַּי בַּחֲלִיצָה אַחַת. \u0005 הַגָּה: וְלָזֶה הִסְכִּים הָרֹא\"שׁ זַ\"ל. \u0010c3\u0011 \u0010r14\u0011 וְהָא דַּחֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר, הַיְנוּ שֶׁהָיְתָה זְקוּקָה לְגַמְרֵי, וְנִפְסְלָה, שֶׁנִּקְלְשָׁה הַזִּיקָה. אֲבָל חֲלִיצָה פְּסוּלָה מֵעִקָּרָא, אֵינָהּ צְרִיכָה \u0010g9\u0011 \u0010r15\u0011 לַחֲזֹר: \u0006\nוְכֵן יֵשׁ מַאֲמָר אַחַר מַאֲמָר, \u0010r16\u0011 שֶׁאִם עָשָׂה מַאֲמָר בְּזוֹ וְאַחַר כָּךְ בְּזוֹ, אוֹ אַחִים עָשׂוּ מַאֲמָר בָּהּ אוֹ בַּחֲבֶרְתָּהּ, כָּל אַחַת צְרִיכָה גֵּט לַמַּאֲמָר, \u0010c4\u0011 \u0010r17\u0011 וַחֲלִיצָה לְאַחַת מֵהֶם לִפְטֹר אֶת שְׁתֵּיהֶן. \u0010r18\u0011 וְכֵן אִם עָשָׂה מַאֲמָר בְּזוֹ, וְאַחַר כָּךְ נָתַן גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עַל צָרָתָהּ, אוֹ שֶׁאַחַר הַמַּאֲמָר שֶׁלּוֹ נָתַן לָהּ אָחִיו גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר מַאֲמָר \u0010r19\u0011 לֶאֱסֹר בַּעֲלַת הַמַּאֲמָר, \u0010r20\u0011 וְלֵאָסֵר \u0005(בִּקְרוֹבוֹתֶיהָ)\u0006 [בַּקְּרוֹבוֹת] בַּמַּעֲשֶׂה שֶּׁנַּעֲשָׂה אַחַר הַמַּאֲמָר, \u0010r21\u0011 וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר וּבִיאָה שֶּׁנַּעֲשָׂה אַחֲרָיו: \u0010g10\u0011\nוְזֶה תַּקָּנָתָם: עָשָׂה בָּהּ מַאֲמָר \u0010c5\u0011 וְנָתַן לָהּ גֵּט, צְרִיכָה חֲלִיצָה. עָשָׂה מַאֲמָר וְחָלַץ, צְרִיכָה גֵּט. עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט \u0010g11\u0011 לָזוֹ, נוֹתֵן גֵּט לְבַעֲלַת הַמַּאֲמָר, \u0010g12\u0011 \u0010r22\u0011 וְהוּא אוֹ אָחִיו חוֹלְצִים לְאַחַת מֵהֶן, וְתִפָּטֵר הָאַחֶרֶת. \u0010c6\u0011 \u0010g13\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁשְּׁתֵּיהֶן צְרִיכוֹת חֲלִיצָה: \u0010g14\u0011\nעָשָׂה מַאֲמָר בָּזוֹ, \u0010g15\u0011 וּבָעַל הוּא אוֹ אָחִיו לָזוֹ, בַּעֲלַת הַמַּאֲמָר צְרִיכָה גֵּט, וְכֵן הַשְּׁנִיָּה צְרִיכָה גֵּט, וְצָרִיךְ לַחֲלֹץ לְאַחַת מֵהֶן: \u0010g16\u0011 \u0010r23\u0011\nוְכֵן אִם נָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר אוֹ בַּחֲבֶרְתָּהּ, אוֹ שֶׁחָלַץ לַחֲבֶרְתָּהּ, אוֹ שֶׁאַחַר הַגֵּט שֶׁלּוֹ עָשָׂה בָּהּ אָחִיו מַאֲמָר אוֹ בָּא עָלֶיהָ, אוֹ חָלַץ לָהּ אוֹ לַחֲבֶרְתָּהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר הַגֵּט \u0010r24\u0011 לֵאָסֵר בִּקְרוֹבוֹתֶיהָ \u0010r25\u0011 וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר שֶּׁנַּעֲשָׂה אַחֲרָיו: \u0010g17\u0011\nוְזֶה תַּקָּנָתָם: נָתַן לָהּ גֵּט וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט וַחֲלִיצָה: \u0010g18\u0011\nנָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ שֶׁעָשׂוּ בָּהּ מַאֲמָר, זוֹ שֶׁבָּא עָלֶיהָ אוֹ שֶׁעָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט, וְצָרִיךְ חֲלִיצָה לְאַחַת מֵהֶן לִפְטֹר שְׁתֵּיהֶן: \u0010g19\u0011 \u0010r26\u0011\nהַבְּעִילָה קוֹנָה קִנְיָן גָּמוּר, וְכֵן הַחֲלִיצָה דּוֹחָה דְּחִיָּה גְּמוּרָה. \u0010c7\u0011 \u0010r27\u0011 לְפִיכָךְ, אֵין הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחֲרֵיהֶם, מוֹעִיל, לֹא לִפְסֹל אֶת זוֹ וְלֹא לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. \u0010r28\u0011 כֵּיצַד, בָּא עַל יְבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם. וְכֵן אִם אָחִיו חָזַר וְנָתַן גֵּט לָהּ אוֹ לְצָרָתָהּ, אֵינוֹ כְּלוּם. וְכֵן אִם חָזַר וְעָשָׂה בָּהּ מַאֲמָר אוֹ בָּעַל, אֵינוֹ כְּלוּם. \u0010g20\u0011 אֲבָל אִם בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט: \u0010g21\u0011\nוְכֵן אִם חָלַץ לִיבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלְצוּ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים שֶׁחָלְצוּ לִיבָמָה אַחַת, זֶה אַחַר זֶה, אֵין חֲלִיצָה אַחֲרוֹנָה כְּלוּם, וּמֻתָּר בִּקְרוֹבוֹתֶיהָ. \u0010g22\u0011 אֲבָל אִם אַחַר שֶׁחָלַץ לִיבִמְתּוֹ, בָּעַל, אוֹ קִדֵּשׁ הוּא אוֹ אָחִיו אוֹתָהּ אוֹ צָרָתָהּ, תָּפְסֵי לְהוּ קִדּוּשִׁין בָּהֶם וּצְרִיכָה גֵּט, בֵּין קִדְּשָׁהּ לְשֵׁם אִשּׁוּת כְּגוֹן שֶׁקִּדְּשָׁהּ סְתָם, \u0010c8\u0011 \u0010r29\u0011 בֵּין לְשֵׁם יַבְמוּת כְּגוֹן שֶׁאָמַר לָהּ: הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי לְזִקַּת יְבָמִים: \u0010g23\u0011 \u0010r30\u0011\nהָא דְּאֵין מַעֲשֶׂה מוֹעִיל אַחַר בִּיאָה, דַוְקָא בְּבִיאָה כְּשֵׁרָה שֶׁלֹּא קָדַם לָהּ מַעֲשֶׂה אַחֵר. \u0010c9\u0011 אֲבָל בִּיאָה פְּסוּלָה, \u0010r31\u0011 כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ וּבָעַל אֶת זוֹ, אוֹ עָשָׂה מַאֲמָר בָּזוֹ וּבָעַל אֶת זוֹ, מוֹעִיל מַעֲשֶׂה שֶׁיַּעֲשׂוּ אַחֲרֶיהָ, שֶׁאִם יַחֲלֹץ הוּא אוֹ אָחִיו לַשְּׁלִישִׁית, יֵאָסְרוּ בִּקְרוֹבוֹתֶיהָ, \u0010r32\u0011 וְגַם הִיא לֹא סָגֵי לָהּ בְּגֵט, דְּאַכַּתִּי נִשְׁאָר בָּהּ \u0010r33\u0011 זִקָּה. אֲבָל חֲלִיצָה, אֲפִלּוּ הִיא פְּסוּלָה, שֶׁקָּדַם לָהּ מַעֲשֶׂה אַחֵר, כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ אוֹ מַאֲמָר בָּזוֹ, וְאַחַר כָּךְ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אֲפִלּוּ הָכִי אֵין מוֹעִיל אַחֲרֶיהָ, אִם חָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ; \u0010g24\u0011 \u0010r34\u0011 אֲבָל אִם בָּעַל אוֹ קִדֵּשׁ, תָּפְסוּ בָּהּ: \u0010g25\u0011 \u0010r35\u0011\nעָשָׂה מַאֲמָר בִּיבִמְתּוֹ וְאַחַר כָּךְ נָתַן לָהּ גֵּט לְזִקָּתָהּ, פָּסְלָה עָלָיו וְעַל כָּל הָאַחִין, וּצְרִיכָה גֵּט לְמַאֲמָרָהּ וַחֲלִיצָה לְזִקָּתָהּ. \u0005 וְאִם נָתַן לָהּ גֵּט סְתָם, הָוֵי כְּאִלּוּ \u0010g26\u0011 \u0010g27\u0011 פֵּרַשׁ לְזִקָּתָהּ. \u0006 נָתַן לָהּ גֵּט לְמַאֲמָרָהּ וְלֹא לְזִקָּתָהּ, נִשְׁאֲרָה זְקוּקָה כְּמוֹ שֶׁהָיְתָה, \u0010g28\u0011 \u0010r36\u0011 וְאֵינָהּ מֻתֶּרֶת אֶלָּא לִשְׁאָר אַחִים, אֲבָל הַמְגָרֵשׁ אָסוּר בָּהּ. \u0010c10\u0011 \u0010g29\u0011 \u0010r37\u0011 וְיֵשׁ אוֹמְרִים שֶׁמֻּתֶּרֶת אַף לַמְגָרֵשׁ: \u0010g30\u0011\nבִּיאַת בֶּן תִּשְׁעָה כְּמַאֲמָר בְּגָדוֹל. \u0010g31\u0011 לְפִיכָךְ, בָּא עַל הַיְבָמָה, פְּסָלָהּ עַל כָּל הָאַחִים. וְאִם אַחַר שֶׁבָּא עָלֶיהָ חָזַר אָחִיו הַגָּדוֹל וּבָא עָלֶיהָ \u0010r38\u0011 אוֹ עַל צָרָתָהּ, אוֹ עָשָׂה מַאֲמָר אוֹ נָתַן גֵּט אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, פְּסָלָהּ עַל הַקָּטָן. \u0010g32\u0011 וְכֵן אִם חָזַר הַקָּטָן וּבָא עַל צָרָתָהּ, אוֹ שֶׁאָחִיו בֶּן ט' בָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ עָלָיו כְּדִין מַאֲמָר אַחַר מַאֲמָר. \u0010g33\u0011 וְכֵן אִם עָשָׂה הַגָּדוֹל מַאֲמָר בִּיבָמָה, וְחָזַר אָחִיו בֶּן ט' וּבָא \u0010r39\u0011 עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ כְּדִין מַאֲמָר אַחַר מַאֲמָר. \u0010c11\u0011 \u0010g34\u0011 וּמַאֲמָר שֶׁל בֶּן ט' אֵינוֹ חָשׁוּב כְּמַאֲמַר הַגָּדוֹל, וְאֵינוֹ מוֹעִיל אֶלָּא בִּתְחִלָּה, אֲבָל לֹא בַּסוֹף. כֵּיצַד, עָשָׂה קָטָן מַאֲמָר, מוֹעִיל לְפָסְלָהּ עַל הָאַחִים. \u0010g35\u0011 אֲבָל אִם עָשָׂה הַגָּדוֹל מַאֲמָר, וְחָזַר בֶּן ט' וְעָשָׂה מַאֲמָר בָּהּ אוֹ בְּצָרָתָהּ, אֵינוֹ מוֹעִיל לְפָסְלָהּ עַל הָאָח הַגָּדוֹל. אֲבָל מַאֲמָרוֹ שֶׁל בֶּן ט', אַחַר מַאֲמָר בֶּן ט', \u0010g36\u0011 \u0010r40\u0011 אִכָּא לִמֵימַר שֶׁמּוֹעִיל, כֵּיוָן שֶׁמַּאֲמַר הָרִאשׁוֹן מִבֶּן ט'. \u0010g37\u0011 \u0010r41\u0011 וְגֵט וַחֲלִיצָה, אֵין לַקָּטָן כְּלָל, לֹא בִּתְחִלָּה וְלֹא בַּסוֹף: \u0010g38\u0011\nגָּדוֹל שֶׁעָשָׂה מַאֲמָר בִּיבָמָה אוֹ נָתַן לָהּ גֵּט וְלָהּ צָרָה, כְּשֶׁבָּא לַחֲלֹץ לְאַחַת מֵהֶן וּלְהַתִּירָן, \u0010g39\u0011 אֵין חֲלִיצַת בַּעֲלַת הַגֵּט אוֹ \u0010g40\u0011 בַּעֲלַת הַמַּאֲמָר פּוֹטֶרֶת הַצָּרָה. אֲבָל חֲלִיצַת הַצָּרָה פּוֹטֶרֶת לְבַעֲלַת הַגֵּט לְגַמְרֵי, וּלְבַעֲלַת הַמַּאֲמָר מֵחֲלִיצָה, וּצְרִיכָה עוֹד גֵּט לְמַאֲמָרָהּ. \u0010g41\u0011 וְאִם עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט לָזוֹ, חוֹלֵץ לְאֵיזוֹ שֶׁיִּרְצֶה וּפוֹטֵר הַשְּׁנִיָּה, כְּמוֹ שֶׁנִּתְבָּאֵר: \u0010g42\u0011\nמִי שֶׁנָּפְלוּ לְפָנָיו שְׁתֵּי יְבָמוֹת מִבַּיִת אֶחָד, הָאַחַת שְׁנִיָּה לְיָבָם וְאַחֶרֶת \u0010r42\u0011 \u0005 מֻתֶּרֶת, \u0006 כְּשֶׁהוּא מְיַבֵּם מְיַבֵּם לָאַחֶרֶת, כְּשֶׁהוּא חוֹלֵץ \u0010c12\u0011 \u0010r43\u0011 חוֹלֵץ לַשְּׁנִיָּה. \u0010g43\u0011 \u0010r44\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם חָלַץ לַאֲסוּרָה, לֹא הֻתְּרָה צָרָתָהּ; חָלַץ לַצָּרָה, הֻתְּרָה הָאֲסוּרָה: \u0010g44\u0011\nיְבָמוֹת רַבּוֹת הַבָּאוֹת מִבַּיִת אֶחָד, כֵּיוָן שֶׁנִּבְעֲלָה אַחַת מֵהֶן בְּעִילָה כְּשֵׁרָה, אוֹ נֶחְלְצָה חֲלִיצָה מְעֻלָּה, הֻתְּרוּ הַכֹּל וְנִסְתַּלְּקָה זִקַּת הַיָּבָּם מֵעֲלֵיהֶן. \u0010r45\u0011 וְאִם נִבְעֲלָה אַחַת מֵהֶן בְּעִילָה פְּסוּלָה, אוֹ נָתַן לָהּ מַאֲמָר פָּסוּל, נֶאֶסְרוּ כֻּלָּם לְיִבּוּם, וּצְרִיכָה גֵּט זוֹ שֶׁנִּבְעֲלָה אוֹ שֶׁנָּתַן לָהּ מַאֲמָר, \u0010c13\u0011 \u0010g45\u0011 \u0010r46\u0011 וּצְרִיכָה כָּל אַחַת מֵהֶן חֲלִיצָה לְהַתִּירָהּ לְזָר, שֶׁאֵין זִקַּת הַיִּבּוּם מִסְתַּלֶּקֶת בִּבְעִילָה פְּחוּתָה. \u0010r47\u0011 נֶחְלְצָה אַחַת מֵהֶן חֲלִיצָה פְּחוּתָה, הֻתְּרָה לְהִנָּשֵׂא לְזָר אוֹתָהּ שֶׁנֶּחְלְצָה, אֲבָל צָרָתָהּ אֲסוּרָה עַד שֶׁתַּחֲלֹץ גַּם הִיא, \u0010g46\u0011 אוֹ עַד שֶׁיַּחְלְצוּ כָּל הָאַחִים לָרִאשׁוֹנָה שֶׁנֶּחְלְצָה הַחֲלִיצָה הַפְּחוּתָה, שֶׁאֵין חֲלִיצָה פְּחוּתָה מְסַלֶּקֶת זִקַּת יִבּוּם מִבַּיִת זֶה, עַד שֶׁתַּחֲזֹר עַל כָּל הָאַחִים, אוֹ עַד שֶׁתַּחֲלֹץ כָּל אַחַת מֵהֶן. זֶהוּ דַּעַת הָרַמְבַּ\"ם \u0005(ח\"ב קי\"ח ב')\u0006, \u0010r48\u0011 וְנֶחְלְקוּ עָלָיו \u0005 כְּמוֹ שֶׁהוּא מְפֹרָשׁ בְּדִבְרֵי הַטּוּר: \u0010g47\u0011 \u0010r49\u0011 \u0006\nשְׁנֵי יְבָמִים שֶׁיִּבְּמוּ שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד, וְלֹא נוֹדַע מִי יִבֵּם תְּחִלָּה, שְׁנֵיהֶם יוֹצִיאוּ \u0010g48\u0011 \u0010r50\u0011 בְּגֵט, וְיֻתְּרוּ לְזָרִים, וַאֲסוּרוֹת לִיְבָמִים. לְפִיכָךְ, רְאוּבֵן שֶׁהָיוּ לוֹ שְׁתֵּי נָשִׁים, אַחַת בְּעַכּוֹ וְאַחַת בְּצוֹר, וְשִׁמְעוֹן וְלֵוִי אֶחָיו, הָאֶחָד בְּעַכּוֹ וְהָאֶחָד בְּצוֹר, וְשָׁמְעוּ שֶׁמֵּת רְאוּבֵן לֹא יְיַבֵּם אֶחָד מֵהֶם עַד שֶׁיֵּדַע מֶה עָשָׂה אָחִיו. \u0010c14\u0011 קָדַם אֶחָד מֵהֶם וְיִבֵּם, אֵין מוֹצִיאִין מִיָּדוֹ \u0010r51\u0011 עַד שֶׁיִּוָּדַע שֶׁאָחִיו יִבֵּם תְּחִלָּה:",{"g":["ל' הרמב\"ם ריש פ\"ה מה' יבום וחליצה ומפורש בהרבה מקומות ומהם במשנה יבמות ד\"נ ע\"א וכחכמים וכדמפרש טעמא בגמ' שם ע\"ב משום דמהני גט בעלמא דאי אמרת לא ליהני אמרי גט להוציא וחליצה להוציא ומדגט לא מהני חליצה נמי לא מהני ואתי למבעל אחר חליצה","\u0003בעיא דאביי מרבה וכו'\u0004 שם דכ\"ב ע\"א ומשמע דלמפשט הבעיא אמר רבה הכי דכל דפסול בכהונה פסול ביבמה וכמ\"ש הרא\"ש שם","מבואר שם ובמקומות הרבה","מבואר שם במשנה וכחכמים וכדמפרש טעמא בגמ' שם ע\"ב","ל' הטור ומבוארים במשנה וגמרא שם ובדף נא ע\"א ואליבא דחכמים","מבואר שם","\u0003מימרא דרבה בר רב הונא אמר רב וכו'\u0004 שם דף כו ע\"ב כ\"כ הטור בשם הרמ\"ה והרמב\"ן","שם בשם הרמב\"ן","שם בגמרא משמיה דשמואל וכתב הרי\"ף שם ופסקו רבוותא הלכה כשמואל","ל' הטור ומבואר שם במשנה","שם ושם מבואר שם במשנה","בטור איתא הוא או אחיו","בעיא שם ונפשטה לפרש\"י שם דף כז ריש ע\"ב וכ\"כ הטור בשמו ושלזה הסכים אביו הרא\"ש","שם בשם הר\"י וכ\"כ התו' שם","שם ושם במשנה ד\"נ ע\"ב","ואסור לקיימ' הואיל וקמיית' אגידה ביה ה\"ל ב' בתים וצריכות ב' גיטין זו גט למאמרו וזו גט לביאתו וחליצה לאחת מהן ופוטרת צרתה אבל בגט לחודיה לא נפקא בעלת ביאה דביאה פסולה היא רש\"י","שם ושם במשנה","שם ושם במשנה","שם","שם במשנה","ממימרא דרב יהודא אמר רב זו דברי ר\"ע דאמר אין קידושין תופסין בחייבי לאוין אבל חכמים אומרים וכו' שם דנ\"ב ע\"ב וכתבו הרי\"ף והרא\"ש דה\"ה הא דתנן אין אחר הבעילה כלום אליבא דר\"ע הוא אבל אליבא דחכמים יש אחריה כלום דקי\"ל כמ\"ד דהבא על יבמתו ואח\"כ בא הוא או אחיו על צרתה הוא בעשה וכמ\"ש לעיל סימן קכב סעיף ח' וכ\"כ הרמב\"ם בפ\"ה","שם במשנה","\u0003מימרא דרב יהודה וכו'\u0004 הנזכר לעיל וברייתות שם וכחכמים וכמו שכתב הרי\"ף דאע\"ג דשקלו וטרו אמוראי טובא לפרש מלתייהו הא קי\"ל הלכה כרבי מחבירו ולא מחביריו ולזה הסכים הרא\"ש וכמ\"ש הטור בשמם","מבואר שם במשנ' וכת\"ק דרבי נחמיה","מבואר במ\"ש בסעי' יג","ממימרא דרבה שם דף לב ע\"א וכפירש\"י שם","כפירש רש\"י שם וכ\"כ כרא\"ש וה\"ה בפ\"ה וכ\"כ המחבר ב\"י לקמן בסימן קעד סעיף ה' כלישנא בתרא דרבא שם כמ\"ש הרא\"ש דאזלי' לקולא בשל סופרים וכדפשיט לי' לרבא","שם דף נב ע\"ב","כפירש רש\"י וכ\"כ הרמב\"ם שם בפ\"ה","מתו' שם וכ\"כ הראב\"ד שם בהשגות ולזה הסכים הרא\"ש והביאם הטור","ברייתא שם דף צו ע\"א","משנה שם וכת\"ק","משנה שם ע\"ב","\u0003אוקימתא דמתני' שם וחסורי מחסרה וה\"ק וכו'\u0004 ","שם ע\"א","שם","ל' טור מסוגיא דגמ' שם סוף ע\"א נ\"ל","\u0003כסתם מתני' וברייתא הוא פוסל בדבר א' וכו'\u0004 וכת\"ק דברייתא דפליג על ר\"מ שם וכדאמר רב יהודה אמר רב שם דף קה ריש ע\"ב כמ\"ש התו' והרא\"ש שם וכ\"כ הרמב\"ם בפ\"ה","מימרא דשמואל דף כז ע\"א וכ\"פ הרי\"ף והרא\"ש והרמב\"ן והרשב\"א וש\"פ","כיון דקליש' זיקא אין חליצתה הוגנת","כיון שחליצה זו אינה פוטרה לגמרי שעדיין צריכה גט למאמרו רש\"י","בעיא שם וכפשטא וכפירש\"י שם ולזה הסכים הרא\"ש והטור","ה\"ה בפ\"ז בשם בה\"ג ויש מן המפרשים סוברים כן ואומר שלא אמרו חליצה פסולה אינה פוטרת אלא כגון שנאסרה עליו בזיקה וכו'","הרמב\"ם שם וכ\"כ הטור בשמו וכמ\"ש ה\"ה שם","ל' הרמב\"ם בפ\"ה ממשנה שם סוף דף מג","ה\"ה תמה עליו בזה דלא פסק כשמואל דחליצת הצרה פוטרת לבעלת הגט כנז' לעיל סעיף י\"ז וכמ\"ש שם והטור כתב טעמו בע\"א וב\"י בשם הרד\"ך האריך בזה","גם בזה כתב שאינו יודע מהיכן יצא לו דין זה ושדעת הרמב\"ן והרשב\"א בזה שחליצתה של זו ואפילו חלצו לה כל האחין אינה פוטרת האחרת","ג\"ז שם","\u0003וכ' הב\"י בשם תשובת הגאונים שצריך לחלוץ לאחת מהן וכו'\u0004 דאפשר דתרווייהו ביאות פסולות חדא ביאה אחר מאמר וחדא ביאה אחר ביאה וכי הא יש אחרי' כלום"],"r":["\u0003היבמה כו'. \u0004 נ\"ב ב' מנין כו'. נ' ב' אבל גט אחד כו' קי\"ב א' וש\"מ:","\u0003ופסל כו' \u0004 ועל כו' מתני' רפ\"ה רג\"א אין גט כו' בין ביבם זו כו' ובגמ' נ\"א א' ת\"ר כיצד אר\"ג אין גט כו' ומותר כו' וכן אתה כו' ושם מ\"ט דר\"ג דמספק' גט אי כו' אי קמא כו' ובירושלמי שם ותני חזקיה מנין לנותן גט ליבמתו שהי' אסורה עליו ועל אחיו אצלו קור' אני אשר שלח אצל האחין אני קור' אשר שלחה:","\u0003מדבריהם נ' ב' גט יבמין כו' \u0004 נ' ב' מ\"ט אמרו רבנן גט כו' נ' א' או רבנן כו':","\u0003ואינה מותר כו'. \u0004 נ\"א א' איתביה אביי ומודה כו' אלא כו' מיהו אמור רבנן כו' ורבנן כו' חד כו' ושם ת\"ר כיצד כו' ובמתני' גט לזו וגט כו' ושם קי\"ב א' וש\"מ ובירושלמי שם כמה דרבנן אמרין המאמר קונה ומשייר כן אמרינן הגט פוטר ומשייר ויפטור הגט פטור גמור מק\"ו כו' ת\"ל וחלצה בחליצה היא ניתרת ואינה ניתרת בגט וכן הוא בגמרא דקידושין י\"ד א' ובירושלמי שם כתיב ולא תהי' לאיש זר מה אנן קיימין כשבא עליה אשתו היא אם בשחלץ לה תלך ותנשא לשוק אלא כן אנן קיימין בשנתן לה גט כו' ותתיר חליצה באשה מק\"ו ומה אם היבמה שאין הגט כו' וכ\"ה בגמ' דקדושין:","\u0003וכן המאמר כו'. \u0004 נ\"ד א' ביאה כו' כ\"א איפשט' ליה לר\"ג כו' ורבנן כו' כ\"ט א' ל\"ת מאמר כו' ובקדושין י\"ד א' ואימ' לכול' כו':","\u0003שאם בא כו'. \u0004 שם ושם ובמתני' רפ\"ה כיצד עשה מאמר ביבמתו כו' וכול' מתני' שם וגמ' נ\"א א' וש\"מ:","\u0003מאחר כו' \u0004 הן כו'. כחכמים במתני' וגמ':","\u0003או גט כו'. \u0004 או כו'. בין כו'. בין כו' במתני' כיצד עשה מאמר בזו כו' עד חלץ וחלץ ושם ושם בין יבם א' כו' ובזה אף ר\"ג מודה. כמ\"ש שם נ\"א א' ומודה ר\"ג כו':","\u0003בין כו'. \u0004 נלמד מהקודם וכן בכל הסי':","\u0003כיצד כו' \u0004 נ\"א א' ת\"ר כיצד כו' וחכ\"א כו' וכן כו':","\u0003או שני כו'. \u0004 כנ\"ל:","\u0003כשבאים להוציאם למ\"ד כו'. \u0004 נ\"א ב' קתני סיפא וכן כו' ואנן קיי\"ל יש זיקה כמש\"ל סי' קנ\"ט ס\"ה:","\u0003ויש מי כו'. \u0004 הוא דעת הרמב\"ם וש\"פ וכ\"ד תוס' וכמ\"ש למטה וס' ח' הוא דעת רש\"י כמ\"ש בטור וכמ\"ש רש\"י שם ד\"ה צריכות כו' וקתני סיפא כו' ויתר למטה מקור מחלוקתם. ולכאורה אין חילוק בדבר דהא שני יבמות גריעא מב' יבמין כמש\"ש ואב\"א כי כו' אלא שהטור כתב ומדברי רש\"י יראה דאפילו למ\"ד חליצה פסולה צריכה כו' בב' יבמות ואח אחד נפטרה צרתה בחליצתה והנה רש\"י כתב שם אלא ש\"מ כי הדדי נינהו ומפטרא צרתה ודלא כריב\"ן בתוס' ורא\"ש שם ובזה נכונים דברי רש\"י מאד דודאי לשמואל בשוין פוטרת צרתה ודלא כההיא לישנא דהתחיל ולא התחיל וכמ\"ש רש\"י בפר\"ג נ\"א א' בד\"ה נימא כו' ומדרבנן כו' וזו ראיה גדולה ועוד ראיה ממש\"ש נ\"ב א' כיצד לימא כו' בכולהו מסייע לשמואל ובמציעתא לימא מסייע לרבב\"ה ול\"ק גם כן לשמואל ולשמואל הוא יותר פשוט מרישא וכ\"ד כל הפוסקים לבד מריב\"ן אלא מ\"ש הטור דאף לרבב\"ה מודה בזה סוגיא דגמרא משמע כן דקאמר שם נ\"א ב' קתני סיפא כו' ולא פריך מרישא ושם נ\"ג א' לימא מסייע לרבב\"ה ל\"ק קתני סיפא אלא כדברי הטור הנ\"ל לסייע הוא כ\"ש מרישא משא\"כ אותביה וכ\"מ מרש\"י במתני' דפר\"ג דמפרש כולה מתני' חליצה לאחת מהן ולא הזכיר שום חולק ע\"ח ב' בד\"ה וחליצה כו' וד\"ה מאמר לזו ובעל כו' וד\"ה צריכות כו' ומזה דייק הטור וכ' ומדברי רש\"י כו' וכ\"מ מלישנא דמתני' דקא' בכולה מתני' גט וחליצה אבל תוס' שם ד\"ה צריכות כו' כתב כדברי הרמב\"ם דלרבב\"ה ד\"ה בשני יבמות וקאמר חליצה אגב גט ומ\"ש נ\"ב ב' קתני סיפא ניחא לגמרא ליפרוך בדדמי כמ\"ש הרמב\"ן והרשב\"א והא דקאמר שם נ\"ג א' לימא מסייע לרבב\"ה כ' תוס' נ\"א ב' בד\"ה בן עזאי דר\"ל מסיפא וכן כו' וכן פרש\"י שם נ\"ג א' ד\"ה צריכות כו' ואף שלדברי רש\"י גם מתירץ ראשון מוכח מ\"מ לא רצה רש\"י לומר מכח כ\"ש מה שמפורש בהדיא במתני' וכן כו'. ועוד שלדעת המקשה ג\"כ אינה מודה רבב\"ה בב' יבמות דהא קתני ברישא צריכות אבל למסקנא אף לרב\"ה צ\"ל צריכות דעלמא ברישא לדעת רש\"י ופשטא דסוגיא משמע כדברי רש\"י כנ\"ל אלא שדוחק לומר דשמואל ורב יהיו הפכין לכן נראין דברי הרא\"ש שפסק כשמואל דאז אין חילוק כלל בין יבמין ליבמות דשוין בשני כו' פוטרין ובגרועין בשניהם אינן פוטרין וכת\"ק כנ\"ל ונמצא ג' שיטות לפסוק כרב או כשמואל כלישנא קמא או כליו בתרא. ובשיטות לפטור צרה ג\"כ שיטות שלשה. ריב\"ן ורמב\"ן ורש\"י ועוד ב' שיטות הרמב\"ם והראב\"ד כמש\"ש:","\u0003ולמ\"ד כו'. \u0004 כמ\"ש שם ושם וכשמואל שם נ\"ו כ\"ז וכתב הרי\"ף שם ופ' רבוותא הלכה כשמואל ופירש הראב\"ד כשמואל קמייתא דבתרייתא ליכא מאן דפליג וכ\"כ הרשב\"א דלרב צריך לאוקמי דפר\"ג הנ\"ל כמ\"ד אין זיקה דלא כהלכתא וכ\"מ מרי\"ף שהביא ברייתא דשם ופ' כרבנן ואלו לרב ליתא לא דר\"ג ולא דרבנן ופ' כתירוץ בתרא שם ואב\"א כי קאמר כו' ואע\"ג דאיכא מעולה מיניה וכ\"ד הרי\"ף שלא הביא אלא האי תירוצא וכ\"ד הרמב\"ם כמ\"ש בסי\"ט אלא שפירש בדרך אחר ע\"ש כ\"כ הראב\"ד אבל הרא\"ש פסק כשנויא קמא מאי אחד כו' וכ\"כ הראב\"ד לעשות כן לכתחלה אבל בדיעבד שנויא בתרא עיקר. אבל הרמב\"ן ורמ\"ה פ' כרב וכתב הרמב\"ן אף ע\"ג דקי\"ל כשמואל בברייתא ע\"ז כתב הרי\"ף פ' רבוותא כשמואל פירוש הראשונים דתרווייהו הילכתא נינהו אף דקי\"ל כתירוץ דרב אשי לעולא כדאמרת כו' וכ\"כ דרב אשי הני מילי בחליצה מעולה לפטור הגרושה אבל בשוין קי\"ל כרב דאמר באמצעית אחד חולץ לשתיהם וכן בנפלו בבת אחת לכל השלשה כמש\"ש וכ\"ש בצרות דבשתיהן שוות דחולץ לשתיהן וכמ\"ש התחיל ולא התחיל קאמר כו' ואף רב אשי לא פליג אלא משום דלא אלימי כו' וכמ\"ש שם ואב\"א כי קאמר שמואל כו' אלמא חמירא למיפטר צרה וכיון דקי\"ל כרב כ\"ש למיפטר צרה והא דאמר שם איבעיא להו בעלת הגט כו' אלא לאו כו' פירש הרמב\"ן כפירש הרא\"ש בשם ריב\"ם דשתיהן צריכות חליצה וכ\"כ הרא\"ש בשמו והרמב\"ן ז\"ל כתב דלדברי ר\"א ז\"ל כו' קמ\"ל דכי אמרינן כו' וכ\"ש ע\"כ הצרות כו' אבל רש\"י פירש שם ד\"ה כי הדדי כו' דבשתיהן שוות חליצה אחת פוטרת דדוקא הגרועה אינה פוטרת וכמ\"ש בתירוץ קמא מכדי שמעינן לשמואל כו' מאי אחד כו' אלמא פוטר בשוות ואף לתירוץ בתרא ואב\"א כו' קיימא הך סברא לענין מפטר צרה והא דקאמר התחיל ולא התחיל כו' קס\"ד הכי ונדחית למסקנא ואף לרב דקאמר חליצה פסולה צריכה כו' אף בשווין מ\"מ למיפטר צרה פוטר בשוות היפך מס' דשמואל לתירוץ בתרא דחמירא ליה צרה וכ\"כ הרמב\"ן שיטה זו אבל חלק עליה וראיה לדעת רש\"י ממש\"ש נ\"א לימא תהוי תיובתא דשמואל כו' קתני סיפא כו' ולא פריך מרישא דרבנן לשמואל ולרב אלא ש\"מ דבשוות למיפטר צרה כ\"ע מודי דמיפטר בין רב בין שמואל וכ\"כ רש\"י שם ד\"ה לימא כו' ומדרבנן ליכא לאותובי כו' וז\"ש רש\"י נ\"ב א' דמסיפא פריך לרב וכמ\"ש כאן וקתני סיפא כו' וערמב\"ן שדמק עצמו בזה וכ' כיון דלא איתמר בהדיא בדבריהם לכך לא פריך מזה ודעת ר\"ח ורשב\"א כדעת רש\"י וכן שיטת הרא\"ש שכ' וכן עיקר כפירש\"י וכ' דתרוצא קמא אליבא דשמואל עיקר וכמ\"ש התחיל ולא התחיל ע\"כ כתי' בתרא ולכך פ' כתי' קמא כיון דלא קי\"ל כתי' דהתחיל כו' אלא כרב אשי ועיין תוספות שם ד\"ה מאי אחד כו' וד\"ה אלא כי כו' אלא שדבריו צ\"ע דלא מוכח דרב אשי סובר דוקא כתי' קמא וכן תמה עליו לח\"מ ולכך פיר' הרא\"ש כשמואל כיון דקיימא לן כתירוץ קמא ע\"כ ליתא לדרב אלא דס\"ל דוקא בשוין אבל הרשב\"א פי' כתי' בתרא דאף בגרועה פוטר כתי' בתרא כנ\"ל ועתוס' שם ד\"ה איתיביה כו' אבל ריב\"ן פיר' כו' וכ' הרא\"ש ומכאן ראיה דהל' כשמואל דר\"י ס\"ל כוותיה וכ\"כ הרמב\"ן והרשב\"א דלא כרש\"י שכת' דה\"ה דפריך נמי לרב דא\"א לומר כן ומש\"ש תנן היתה כו' ואע\"ג דאר\"י אחיות איני יודע כו' מ\"מ כל הני לישתביש וליזיל ומשני אר\"פ כגון כו' אבל לרב קושיא אלא שכ' כתי' השני שבתו' שם ומיהו נראה לר\"י כדפרישית כו' דע\"כ רב חייש לביטול דהא אין זיקה ס\"ל וכמ\"ש בריש פרקין ש\"מ יש זיקה כו' ושם והאמר רב כו' ומ\"מ צריך גם לתי' קמא של תוס' דס\"ל לר\"י כשמואל דאל\"כ מאי פריך אלא דלא סגי כתי' קמא דאכתי תקשי לרב מסיפא תנן כו' וערמב\"ן שדחק עצמו בזה וכ' כיון דלא איתמר בהדיא דפליג ר\"י ארב לא דחינן לדרב ועוד תי' אחר ע\"ש ויש להרמב\"ם שיטה אחרת ויתר בסי\"ט. כללא דמילתא דהא דשמואל בתרייתא הלכתא הוא לכ\"ע אלא שהרמב\"ן בקמייתא כרב ובאב\"א כי קאמר כו' אבל רב ל\"פ ואף בשוות אבל רש\"י סובר בשוות א\"צ אף לרב בצרות והרא\"ש פ' כשמואל כתי' קמא והרשב\"א פ' כתי' בתרא ושניהם ס\"ל לדינא כרש\"י דבשוות פוטרת צרה כנ\"ל ושיטה ה' להרמב\"ם כמש\"ל:","\u0003והא דחליצה כו'. \u0004 ר\"ל דוקא אחות זקוקתו ואחות חליצתו ובעלת הגט ובעלת מאמר דקלשא זיקא דאחות זקוקא דמיא לאחות אשתו דאין בה זיק' וכן אחות חליצה דמי לאחות גרושתו וכן בעלת הגט לחלוצה וכן מאמר לכניס' דאין בהו זיקה וכן סוטה דרבנן דאמרי' רפ\"ו רש\"א ביאתה או חלוצתה כו' ואמרינן עלה בירושל' הדא אמר' קסבר ר\"ש חליצה פסולה פוטרת צרתה משום דדמיא לסוטה דאורייתא דאין בה זיקה כמ\"ש י\"א א' טומאה כתיב כו' אבל בלא\"ה לא וראי' ממש\"ש א\"ל תניתוה היתה כולי אלא לאו כשירה כו' וקא' דחולץ לפסולה ושם או היא או צרתה כו' ושם כ' ב' מתיב רבא איסור מצוה ואיסור כו' ועתוס' כ\"ו ב' ד\"ה וחליצה כו' אבל דעת הרמב\"ם דרש\"י דכל שא\"י לייבם הוי חליצה פסולה כמ\"ש בט\"ז הלכה ט' חליצת האחיות אינן פוטרות הצרות מפני שחליצת האחיות חליצה שאינה מעולה כולי יראה לי שכך הדין בחלץ לשניה או לח\"ל שאינה פוטרת צרתה וכמש\"ל בסי\"ח מההיא דלעיל י\"א קס\"ד הכי ולא קיימא במסקנא וההיא דאיסור מצוה כו' מפ' לה בששתיהן אסורות דשוות פוטרת כנ\"ל אלא דבתוספתא פ\"י תניא מי שהיה נשוי שתי נשים ביאתה או חליצתה של אחת מהן פוטרת צרתה היתה א' מהן אסורה לא' מן האחים איסור ערוה וחלץ לה לא עשה כלום ולא פטר את צרתה אלא או היא או צרתה מתייבמת לשאר אחים היתה איסור מצוה ואיסור קדושה חלץ לה או בא עליה נפטרה צרתה. רשב\"א ועמ\"מ שם וע\"ל סי\"ט וסתם כאן כדעת בה\"ג שם","\u0003וכן יש כו' \u0004 כחכמים:","\u0003שאם כו'. \u0004 מתני' שם כיצד עשה כו' וגמ' שם נ\"א א':","\u0003וחליצה כו' \u0004 דלא כהרמב\"ן בס\"ח:","\u0003וכן אם עשה כו'. \u0004 במתני' שם כיצד עשה מאמר ביבמתו כו' כיצד עשה מאמר בי' כו' בין יבם כו':","לאסור בעלת מאמר בתוספתא פ\"ז העושה מאמר ביבמתי קנאה לעצמו ופסל' ע\"י אחים באו עליה ועשו בה מאמר ונתנו גט וחלצו פסלו על ידו כמש\"ל במתני' צ\"ו א' כיצד בן תשע כו' וכמש\"ל וסט\"ז:","\u0003לאסור כו'. \u0004 דבהא פליג ר\"ג וחכמים וקי\"ל כחכמים ושם ומודה ר\"ג שיש כו' וכ\"ש בביאה וחלצה אחריהם","\u0003ולהאריך כו' \u0004 מפו' במתני' כנ\"ל וכמש\"ו:","\u0003והוא או כו' \u0004 ויש כו' הוא פלוגתת רש\"י ורמב\"ן בבעיא דשם וכנ\"ל בס\"ה וכבר סתם כרש\"י בס\"ו וס\"ח וסי\"א וסט\"ז:","\u0003וכן אם כו' \u0004 ולהצריך כו'. מתני' נתן גט ועשה כו' גט לזו וגט כו':","\u0003ליאסר בקרובותיה. \u0004 הוא פלוגתא דר\"ג ורבנן ומודה ר\"ג כו' כנ\"ל:","\u0003ולהצריך כו'. \u0004 כנ\"ל וכמש\"ו בס\"י וסי\"א:","\u0003הבעילה כו' \u0004 וכן כו' מתני' דריש קידושין וש\"מ כנ\"ל ובפ' הבע\"י ובירושלמי רפ\"ה יכול כשם שהביאה גומרת כו' ויפטור בגט פטור גמור ביבמה מק\"ו מחליצה כו':","\u0003לפיכך כו'. \u0004 מתני' אבל לא אמר כו':","\u0003כיצד כו' \u0004 וכן אם חלץ כו'. מתני' חלץ ועשה כו' חלץ וחלץ כו' וז\"ש לא לפסול את זו ואמר ולא לאסור בקרובותיה דבהא פליגי ר\"ג וחכמים ומודים חכמים לר\"ג כמ\"ש אבל לא אחר כו':","\u0003בין לשם יבמות כו'. \u0004 ע' בה\"ג ומש\"ש דרבנן ס\"ל אין זיקה וחליצה פסולה אינה פוטרת ויש תנאי בחליצה אע\"ג דלא קי\"ל כן לא דרבנן ס\"ל כן בכ\"מ אלא ס\"ל דכאן מהני כיון דיש קידושין ביבמה ולענין זה פליגי ר' וחכמים וקי\"ל כחכמים וע' ברא\"ש שם:","\u0003הא דאין כו'. \u0004 מתני' והבעילה בזמן כו' וגמ' שם ביאה פסולי יש אחרי' כו':","\u0003כגון כו' \u0004 שאם יחלוץ כו'. נ\"א א' ומודה ר\"ג וערש\"י שם וכ\"ה בירושלמי שם ומודה ר\"ג כו' היאך עבידא היה שלש יבמות עשה מאמר בזו ובעל לזו ונתן גט לשלישית כו' נתן גט לזו ובעל לזו ועשה מאמר בשלישית כו' ושם סוף פרקין דתניא שלש יבמות ליבם א' עשה מאמר בזו ובעל לזו ונתן גט לשלישית רנ\"א כולי ורבנן אמרי אסור בקרובות שלשתן וצריכות ג' גיטין וחליצה לאחת מהן וט\"ס וצ\"ל מאמר בשלישית וכ\"ה בתוספתא ספ\"ז:","\u0003וגם היא כו'. \u0004 במתני' נתן גט ובעל כו' גט לזו ובעל לזו כו':","\u0003אבל חליצה כו'. \u0004 במתני' ודלא כתנא דברייתא נ\"ד ב':","\u0003אבל אם כו'. \u0004 נ\"ג א' והכא בחליצה פסולה כו' וכ\"ש לפי מ\"ש בסי' י\"ג:","\u0003עשה מאמר כו'. \u0004 נ\"ב ב' בעי רב חנניא כו' תפשוט כו' ועבדינן כפשיטותיה דרבה וערש\"י שם ד\"ה או דלמא כו':","\u0003ואינה מותרת כו'. \u0004 רש\"י הנ\"ל:","\u0003וי\"א כו' \u0004 תוספת שם ד\"ה או דלמא כו' ופליגי במ\"ש אפילו היא אי אמתני' דוקא קאי ולאחין או אעלמא קאי ומדקבעוה שם משמע כרש\"י ועמ\"מ:","\u0003או על צרתה. \u0004 כמו בצרה אחר מאמר כנ\"ל:","\u0003או על כו'. \u0004 נלמד מהקודם וכמש\"ו כדין כו':","\u0003איכא למימר כו'. \u0004 גמ' ערוכה שם או שקטן אחר קטן וכ\"ש במאמר דעדיפא כמ\"ש תוס' שם ד\"ה וכן כו' וז\"ש וגט כו' וערא\"ש שם שכתב והא דאמרינן עשו ביאת כו' ולא אמרו כמאמרו ג\"כ כתירץ הגמ' ה\"מ בגדול אחר כו':","\u0003וגט כו'. \u0004 דלא כשמואל דדוקא לר\"מ דגט במקום חליצה הוא כמ\"ש תוספת הנ\"ל וכמ\"ש בגמרא שם ושם ג' ב' וכיון דלא קי\"ל כר\"מ בחליצה כמ\"ש ק\"ה ב' ה\"ה בגט ועתוס' שם ד\"ה רמ\"א כו' ורא\"ש שם:","\u0003כשהוא מייבם כו'. \u0004 כמ\"ש בתוספתא וירושלמי צרה שניה חולצת או מתייבמת והביאו הרא\"ש ברפ\"ג וכן בתוספתא כל האסורות כו' וכ' למעלה ס\"ה:","\u0003חולץ לשניה ר\"ל אף לשניה ועבה\"ג ועמ\"ל מ\"ה:\u0004 ","\u0003ויש כו' \u0004 צ\"ע דאם קורא לזו חליצה פסולה א\"כ ה\"ה דביאתה ביאה פסולה ואמרינן בפר\"ג דחליצה פסולה אין אחריה כלום וביאה פסולה כו' והוא פסק דביאתה פוטרת צרתה כמ\"ש ר\"ס קע\"ד ועוד דכ\"ש הוא ביאה מחליצה וע\"ל ר\"ס קע\"ד אבל מ\"ש המ' ממ\"ש ך' ב' בא עלי' או כולי י\"ל דההיא ברייתא אתי' כמ\"ד אין זיקה וכ\"מ ברשב\"א ע' תוס' ך\"ו ב' ד\"ה מדקאמרת כו' ולר\"י נראה כו':","\u0003ואם נבעלה כו'. \u0004 כמש\"ל סימן ד':","\u0003וצריכה כל אחת. \u0004 נ\"ה גי' המ\"מ וליתא אלא וצריכ' אחת כו' וכ\"ה גי' הטור וכמש\"ל ס\"ה דרמב\"ם מוקי לההיא ברייתא כ' ב' איסור מצוה כו' בשתיהן אסורות ובזה נסתלקה תמיהת המ\"מ עליו שם פ\"ז הלכה י' ומה שמדייק המ\"מ שם פ\"ה הלכה י\"א דהרמב\"ם סובר אפילו בשוות אינה פוטרת מהא דלמטה ליתא דהוא מפ' שפ' כרב אבל ליתא כמ\"ש למטה:","\u0003נחלצה אחת כו'. \u0004 פ' כשמואל וכמ\"ש הרי\"ף וכתי' בתרא ומפרש מ\"ש כי קאמר שמואל כו' קאי אצריך לחזור ע\"כ האחין היכא דוקא לפטור צרתה אז צריכה לחזור אבל אם חולץ לכל אחת בפ\"ע א\"צ לחזור ונ\"ה בפי' בסיפ\"ה ע\"ש וכ\"כ הרמב\"ן ורשב\"א דשיטה כשמואל ומיירי בשוות כמ\"ש למטה אז עד שתחלוץ כ\"א כו' ואם איתא בחליצתן לבד סגי וס\"ל דבשוות שנפלו לפני אח אחד פוטרת צרתה כנ\"ל וכן לפני אחין הרבה ונחלצה אחת מכולן אבל גרושה אפילו נחלצה מכל האחין לא מהני דלא עדיף מנפלו לפני אח אחד וכמש\"ש בפ\"ז הלכה ט' וכנ\"ל סי\"ח אלא שדבריו סתומים כדרכו ואפשר לקיים ג\"כ כגי' של המ\"מ הנ\"ל כ\"א ונפלו לפני כמה אחין כמש\"ו ושיטתו כשיטת הרשב\"א שפ' כשמואל וכתי' בתרא וכתב דקיי\"ל כסתם מתניתין דפ\"ה ודלא כמו שדחקו בגמרא לפרושי למ\"ד אין זיקא וכן הברייתא דשם וכן המתני' דקאמר עשה מאמר בזו ומאמר כולי וחליצה וכ\"ה לשיטת הרמב\"ם ול\"פ על הרשב\"א אלא בשני יבמין ושתי יבמות וזה לא נזכר במתני' שם ולא בברייתא שם וכלל שדעתו כדעת הרי\"ף ורשב\"א וכתי' בתרא דשמואל אלא בב' יבמות ובב' יבמין:","\u0003ונחלקו עליו כו'. \u0004 עמש\"ש בס\"ה. וכללא דמילתא דחליצה מעולה פוטרת לד\"ה ואף לתי' קמא התחיל ולא התחיל כ' הרא\"ש בשם הריב\"ש דדוק' שם משום דשם פסולייהו שוין דהוא בכרת כמו אחות אשה עצמה ואף שתוספת לא סבירא ליה כן מ\"מ לדינא ודאי לכל הדיעות פוטרת מדאיבעי' להו לגמ' בעלת הגט כו' ובשו\"ת להרמב\"ן דפ' כרב אינה פוטרת ולש\"פ שפ' כשמואל פוטרת ובגרועה ללישנא קמא דשמואל אינה פוטרת וכ\"פ הרא\"ש ולרי\"ף וראב\"ד פוטרת שפ' כלישנא בתרא וזהו באחין באשה אחת וביבם א' ושתי נשים הגרוע ודאי אינה פוטרת ומעולם פוטרת ובשווין פליגי רש\"י וסיעתו עם הריב\"ם ורמב\"ן וכמ\"ש ברא\"ש וכמ\"ש שם:","\u0003שני יבמין כולי \u0004 מ\"ש כ\"ד א' תני שילא כו' מ\"ט כו' משא\"כ בדאורייתא:","\u0003בגט. \u0004 כגון שבא אחר קידושיה מיד אז בלא קידושין דממ\"נ סגי בגט:","\u0003עד שידע כו' \u0004 ל\"ד אלא ה\"ה אם יסתפק לו כנ\"ל אלא לאפוקי דאם נידע שמייבם אחיו לבסוף או שלא נודע כלל שייבם אחיו דס\"ס הוא שמא לא ייבם ואת\"ל ייבם את\"ל ייבם שמא לבסוף וז\"ש עד שידע כו' תחלה וכמ\"ש קי\"ט א' היה לה כו' וערש\"י ד\"ה אינה כו' אבל לכתחל' ודאי אסור דאין כאן אלא ספק א' שמא לא ייבם:"]}],["מִי שֶׁהָיָה נָשׂוּי יְתוֹמָה קְטַנָּה \u0005 שֶׁהִשִּׂיאוּהָ אָחִיהָ וְאִמָּהּ, שֶׁאֵין קִדּוּשֶׁיהָ רַק מִדְּרַבָּנָן, \u0006 וְחֵרֶשֶׁת, וּמֵת, וְנָפְלוּ לִפְנֵי אָחִיו \u0010c0\u0011 לְיִבּוּם, אֵין בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ. וְכֵיצַד תַּקָּנָתָם, מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וְכוֹנֵס אֶת הַחֵרֶשֶׁת. וְאִם רָצָה לְגָרְשָׁהּ, כּוֹתֵב לָהּ גֵּט אַחַר שֶׁיָּבֹא עָלֶיהָ, וּמֻתֶּרֶת לְזָר:\nהָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת אוֹ קְטַנּוֹת, \u0010c1\u0011 בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ:\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בִּיאַת גְּדוֹלָה אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת הַקְּטַנָּה, וְאֵין בִּיאַת הַקְּטַנָּה פּוֹטֶרֶת אֶת הַגְּדוֹלָה:\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בִּיאַת הַפִּקַּחַת אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת אֶת הַחֵרֶשֶׁת, וְאֵין בִּיאַת הַחֵרֶשֶׁת פּוֹטֶרֶת אֶת הַפִּקַּחַת:\nהָיוּ שְׁתֵּיהֶן קְטַנּוֹת, וּבָא הַיָּבָם עַל אַחַת מֵהֶן, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַשְּׁנִיָּה, \u0010c2\u0011 לֹא פָּסַל הָרִאשׁוֹנָה עָלָיו, אֲבָל אָסוּר לוֹ לְקַיֵּם הַשְּׁנִיָּה, אֶלָּא מְלַמְּדִין אוֹתָהּ שֶׁתְּמָאֵן, וִיקַיֵּם הָרִאשׁוֹנָה:\nוְכֵן אִם הָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת, אֵין בִּיאַת הַשְּׁנִיָּה פּוֹסֶלֶת הָרִאשׁוֹנָה, וְהַשְּׁנִיָּה אֲסוּרָה לוֹ וְיוֹצִיאֶנָּה בְּגֵט:\nקְטַנָּה וְחֵרֶשֶׁת, שֶׁבָּא הַיָּבָם תְּחִלָּה עַל הַקְּטַנָּה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, \u0010c3\u0011 לֹא פָּסַל אֶת הַקְּטַנָּה, וְהַחֵרֶשֶׁת צְרִיכָה גֵּט, שֶׁבִּיאַת הַקְּטַנָּה מְעֻלָּה מִבִּיאַת הַחֵרֶשֶׁת, שֶׁהַקְּטַנָּה רְאוּיָה לְאַחַר זְמַן. לְפִיכָךְ, יְקַיֵּם הַקְּטַנָּה שֶׁנִּבְעֲלָה תְּחִלָּה:\nבָּא עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, פָּסַל אֶת הַחֵרֶשֶׁת. וּמְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וְיוֹצִיא הַחֵרֶשֶׁת בְּגֵט. \u0005 זֶהוּ דַּעַת הָרַמְבַּ\"ם, אֲבָל אֲחֵרִים חוֹלְקִים עָלָיו כַּמְפֹרָשׁ בַּטּוּר וּבְנִמּוּקֵי יוֹסֵף פֶּרֶק בֵּית שַׁמַּאי: \u0006\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בָּא הַיָּבָם עַל הַפִּקַּחַת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, לֹא פָּסַל הַפִּקַּחַת, וְהַחֵרֶשֶׁת צְרִיכָה גֵּט. בָּא הַיָּבָם עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַפִּקַּחַת, פָּסַל אֶת הַחֵרֶשֶׁת; הַחֵרֶשֶׁת יוֹצְאָה בְּגֵט, וְהַפִּקַּחַת בְּגֵט וַחֲלִיצָה:\nאַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בָּא עַל הַגְּדוֹלָה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, לֹא פָּסַל הַגְּדוֹלָה, וּמְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ. בָּא עַל הַקְּטַנָּה, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַגְּדוֹלָה, מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וִיקַיֵּם הַגְּדוֹלָה:",[],["\u0003אין ביאת אחת מהן פוטרת\u0004. מפורש בש\"ס קטנה ספק קנויה וחרשת קנויה ומשויירת לכן אין חליצה אחת פוטרת את חברתה בין אם נפלו מפקח ובין אם נפלו מחרש והסכימו רוב הפוסקים מלמדין הקטנה שתמאן בו ואם לא תרצה למאן אז לכ\"ע מייבם את החרשת ויוציא אותה בגט ותמתין לקטנה עד שתגדיל וחולצת ואם ייבם את הקטנה אז אין תקנה לחרש כי א\"י לייבם אותה מאחר שכבר ייבם א' מבית זה והיא אין בת חליצה ועיין בש\"ג פ' ב\"ש:","\u0003ביאת א'\u0004. כלומר בקטנות וחרשות אין פוטרת צרות בחליצה אפי' הצרה שוה לה אבל בביאה פוטרת כששוה לה:","\u0003לא פסל הראשונה\u0004. ממ\"נ אם קנויה היא אם כן קנה הראשונה תו לא פסלה השניה את הראשונה כמו בגדולה אם בא על אחת תו ביאת השניה לא פסלת, ואם אינה קנויה א\"כ הוי כאלו שתיהם נכריות ומקיים הראשונה ולא את השניה שמא הראשונה קנויה היא והשניה צריכה מיאון דהא הביאה מהני בה וכן בשתיהן חרשת נמי אין השניה פוסלת את הראשונה אלא הביאה מהני בה וצריכה גט:","\u0003לא פסל את הקטנה\u0004. כן הוא הגירסא במתני' לשיטת הרי\"ף והרמב\"ם והטעם משום ממ\"נ הנ\"ל, אבל בא על החרשת ואח\"כ על הקטנה פוסלת את החרשת כי החרשת קנוי' ואינה קנויה והקטנה שמא קנויה הוא ואז קנויה היא לגמרי ופוסלת את החרשת וסבירא לי' לרמב\"ם דאז אסור בשתיהן מאחר בעת הביאה של הקטנה היתה החרשת פסולה עליו תו לא מהני מיאון דקטנה לקיים את החרשת כיון דבחרשת ליכא מצות יבום גמור משא\"כ כשבא על הגדולה אחר שבא על הקטנה מלמדין לקטנה שתמאן ומותר בגדול' כיון שמקיים בגדולה מצות יבום:"],"\u0010g0\u0011 מִי שֶׁהָיָה נָשׂוּי יְתוֹמָה קְטַנָּה \u0010r0\u0011 \u0005 שֶׁהִשִּׂיאוּהָ אָחִיהָ וְאִמָּהּ, שֶׁאֵין קִדּוּשֶׁיהָ רַק \u0010g1\u0011 מִדְּרַבָּנָן, \u0006 וְחֵרֶשֶׁת, וּמֵת, וְנָפְלוּ לִפְנֵי אָחִיו \u0010c0\u0011 לְיִבּוּם, אֵין בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ. \u0010r1\u0011 וְכֵיצַד תַּקָּנָתָם, \u0010g2\u0011 \u0010r2\u0011 מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וְכוֹנֵס אֶת הַחֵרֶשֶׁת. \u0010r3\u0011 וְאִם רָצָה לְגָרְשָׁהּ, כּוֹתֵב לָהּ גֵּט אַחַר שֶׁיָּבֹא עָלֶיהָ, וּמֻתֶּרֶת לְזָר: \u0010g3\u0011 \u0010r4\u0011\nהָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת אוֹ קְטַנּוֹת, \u0010c1\u0011 בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ: \u0010g4\u0011 \u0010r5\u0011\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בִּיאַת גְּדוֹלָה אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת הַקְּטַנָּה, וְאֵין בִּיאַת הַקְּטַנָּה פּוֹטֶרֶת אֶת הַגְּדוֹלָה: \u0010g5\u0011\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בִּיאַת הַפִּקַּחַת אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת אֶת הַחֵרֶשֶׁת, וְאֵין בִּיאַת הַחֵרֶשֶׁת פּוֹטֶרֶת אֶת הַפִּקַּחַת: \u0010g6\u0011\nהָיוּ שְׁתֵּיהֶן קְטַנּוֹת, וּבָא הַיָּבָם עַל אַחַת מֵהֶן, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַשְּׁנִיָּה, \u0010c2\u0011 \u0010g7\u0011 לֹא פָּסַל הָרִאשׁוֹנָה עָלָיו, \u0010g8\u0011 \u0010r6\u0011 אֲבָל אָסוּר לוֹ \u0010g9\u0011 לְקַיֵּם הַשְּׁנִיָּה, \u0010r7\u0011 אֶלָּא מְלַמְּדִין אוֹתָהּ שֶׁתְּמָאֵן, וִיקַיֵּם הָרִאשׁוֹנָה: \u0010g10\u0011\nוְכֵן אִם הָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת, אֵין בִּיאַת הַשְּׁנִיָּה פּוֹסֶלֶת הָרִאשׁוֹנָה, \u0010r8\u0011 וְהַשְּׁנִיָּה אֲסוּרָה לוֹ \u0010g11\u0011 \u0010r9\u0011 וְיוֹצִיאֶנָּה בְּגֵט: \u0010g12\u0011\nקְטַנָּה וְחֵרֶשֶׁת, שֶׁבָּא הַיָּבָם תְּחִלָּה עַל הַקְּטַנָּה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, \u0010c3\u0011 \u0010g13\u0011 \u0010r10\u0011 לֹא פָּסַל אֶת הַקְּטַנָּה, וְהַחֵרֶשֶׁת צְרִיכָה גֵּט, \u0010r11\u0011 שֶׁבִּיאַת הַקְּטַנָּה מְעֻלָּה מִבִּיאַת הַחֵרֶשֶׁת, שֶׁהַקְּטַנָּה רְאוּיָה לְאַחַר זְמַן. לְפִיכָךְ, יְקַיֵּם הַקְּטַנָּה שֶׁנִּבְעֲלָה תְּחִלָּה: \u0010g14\u0011\nבָּא עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, פָּסַל אֶת הַחֵרֶשֶׁת. וּמְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, \u0010g15\u0011 וְיוֹצִיא הַחֵרֶשֶׁת בְּגֵט. \u0005 זֶהוּ דַּעַת הָרַמְבַּ\"ם, \u0010r12\u0011 אֲבָל אֲחֵרִים חוֹלְקִים \u0010g16\u0011 עָלָיו כַּמְפֹרָשׁ בַּטּוּר וּבְנִמּוּקֵי יוֹסֵף פֶּרֶק בֵּית שַׁמַּאי: \u0010g17\u0011 \u0006\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בָּא הַיָּבָם עַל הַפִּקַּחַת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, לֹא פָּסַל הַפִּקַּחַת, \u0010g18\u0011 וְהַחֵרֶשֶׁת צְרִיכָה גֵּט. בָּא הַיָּבָם עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַפִּקַּחַת, \u0010g19\u0011 פָּסַל אֶת הַחֵרֶשֶׁת; \u0010g20\u0011 \u0010r13\u0011 הַחֵרֶשֶׁת יוֹצְאָה בְּגֵט, וְהַפִּקַּחַת בְּגֵט וַחֲלִיצָה: \u0010g21\u0011\nאַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בָּא עַל הַגְּדוֹלָה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, לֹא פָּסַל הַגְּדוֹלָה, וּמְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ. בָּא עַל הַקְּטַנָּה, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַגְּדוֹלָה, מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וִיקַיֵּם הַגְּדוֹלָה:",{"g":["משנה יבמות דק\"י ע\"א","שלא ינהג בה מנהג הפקר וקידושי' תלוין עד שתגדיל וחרשת תקנו לה נישואין כדי שלא תשאר פנויה לעולם רמב\"ם בפ' ה' מהלכות ייבום וכתב ה\"ה שהטעם שכ' רבינו וכולי נתבאר בפ' חרש (דקי\"ב ע\"ב) וזהו מ\"ש שם בגמרא דק\"י ע\"ב אליבא דרב והביאו הטור שקידושי הקטנה הם בספק וקידושי החרשת קונין מקצתה ומשייכי' מקצתה וכולי לפיכך אין ביאת אחת מהן פוטרת צרתה","כרבי אליעזר שם במשנה דף קי\"א ע\"ב וכ\"כ הרי\"ף והרמב\"ם שם וכמ\"ש ה\"ה שסובר רבינו דרב דאמר כונס את החרשת וכולי שם דק\"י ע\"ב לא אמרה אליבא דר\"א ולזה הסכים הרא\"ש כמ\"ש הטור","שם במשנה דק\"ו ע\"א","שם במשנה","שם במשנ'","משנ' שם דקי\"ד ע\"א","שהרי ביאתה שוה ואי ראשונה קנויה הוא הרי היא אשתו ואחרונה ביאת זנות ואי לא קנוי' היא הרי שתיהן נכריות אצלו","דלמא קנויות הוו ומשבא על הראשונה קיימ' הך עליה באיסור ב' בתים","כר\"א שם במשנה","שם במשנה ומטעם דלעיל","טור כיון שאין ביאת החרשת הראשונה ביאה גמורה להפקיע כל הזיק'","להרמב\"ם שם פ\"ה","כתב ה\"ה שכך היא הגירס' במשנה בספרי הגאונים ובהלכות והן הן דברי רבינו כולי ואפשר שרבינו וההלכות סוברין דהך ברייתא (שם ע\"ב) פליגא אמתני' והוי הלכה כסתם משנה וכ\"כ הטור שהיא גירס' אביו הרא\"ש","גם שם ממשנה שם ופי' הטור ותשאר החרשת אצלו","אם היא רוצה להוציאה אח\"כ וכמו שהוכיח הרשב\"א שהדין כן והביאו הב\"י שם","רש\"י שם וכגרסת הש\"ס שלפנינו וכהשגת הראב\"ד שם וכ' ה\"ה שהרשב\"א הכריע כדבריהם","גם זה ממשנה שם","\u0003כ' ה\"ה שכבר נתבאר שיש ביאה אחר ביאה וכו'\u0004 והוא שבא עליה לשם אישות או לשם יבמות","ג\"ז שם ממשנה שם","כ' ה\"ה שפשוט היא שהחרש' שביאת' ביאה כשירה היתה ומספיק לה בגט משא\"כ הפקחת שביאתה היתה ביאה פסול'","ג\"ז שם ממשנה שם וכר\"א דאיפסק' שם הלכה כותיה"],"r":["\u0003שהשיאוה כולי. \u0004 כמש\"ל סי' קנ\"ה:","\u0003וכיצד תקנתם כו'. \u0004 שם ב' כיצד תקנתם אר\"ח א\"ר כונס כו'. וכ' הרי\"ף עלה ולד\"א מצמדין את הקטנה שתמאן בו ומייבם את החרש' וכן הל' ור\"ל דשם קי\"א ב' במתני' רא\"א מלמדין כו' וגירסת הרי\"ף בכולן מלמדין כו' וכ\"ה בתוספ' פי\"ג ור\"ל בכל הנך דמתני' ורב לא אמר תקנתא אלא לת\"ק ואנן קיי\"ל כר\"א כמש\"ש בגמרא וכ\"ה דברי הרמב\"ם וש\"ע כאן ואף שהקשה הראב\"ד בהשגות דלא אמרו אלא בגדולה וקטנה כמו בהנך תרי בבי כגי' ספרים שלנו דל\"ג בכולן דמלמדין כדי שתתקיים בגדולה מצות ייבום דאורייתא אבל יבום חרשת דרבנן והא קיים לה בביאה ראשונה דחרשת בתקנתא דרב ולעולם יתרחק מן המיאונין ור\"ל כמש\"ש ק\"ט א' ומי שרי והתני ב\"ק כו' ומשני מיאון דמצוה שאני משא\"כ כה\"ג כנ\"ל אבל הרמב\"ן יישבה דטעמיה דבר קפרא כמ\"ש ק\"ט ב' דלמא גדלה ומתחרט' משא\"כ כה\"ג למה תתעגן עד שתגדיל ותחלוץ ותפסל מכהונה שופך מי בורו כו' ותיאסר חרשת עליו שכנסה בהיתר והא דפריך ק\"ט א' ומי שרי כולי למ\"ד אין זיקא כר\"ג דלא נאסרה עליו וכ\"מ שם קי\"א ב' דכר\"ג ס\"ל דקאמר ואי אשמעינן בהא כולי ואם איתא הרי רמיא קמי' לחלוץ ואי משום דאסורה לייבם הרי גם כאן משבא על הקטנה אסורה הגדולה ואף שאמרו שם כ\"ט ב' אלא לר\"א נהי כו' לרווחא דמילתא אמר כן ונסתלק' תלונות הלח\"מ עוד הקשה לח\"מ דלדבריו ל\"ל בגמ' שם ואי אשמועינן בהא כו' הל\"ל טעמו של הרמב\"ן משום דע\"כ יוצאת כו' כנ\"ל ולא עי' בדברי הרמב\"ן דהא י\"ל היאך אמר ואי אשמעינן כו' לגי' בכולן מלמדין כולי וכן הקשה הרא\"ש בשם הראב\"ד אבל הרמב\"ן יישבו שם דהצריכותא א\"צ אלא בהנך תרתי בבי כנ\"ל דבכל הנ\"ל סגי טעמו של הרמב\"ן למ\"ד מרישא דאין זיקה כנ\"ל ובסיפא שמ\"ש הרמב\"ן משום דאיקיים מצות ייבום והוא פסל על עצמה בפשיעה אלא שקשה לו להלח\"מ בהנך בבות דמתני' קי\"א בשתי יתומו' קטנות ובבא על החרשת ואח\"כ על הקטנה דלגי' בכולן מלמדין כו' וכמ\"ש הרמב\"ם וש\"ע בס\"ה וס\"ח דשם ג\"כ פסל בפשיעה ואקיים ייבום וליכא גדולה אבל ל\"ק כלל דשם א\"צ לכ\"ז דע\"כ ל\"ק בר קפרא אלא בכנס את הקטנה בהיתר אבל באיסור ודאי מצוה למאן ובזה צדקה גי' הרמב\"ם בבא על הקטנה ואח\"כ על החרשת דלא פסל כו' כמ\"ש בס\"ז ולא קאי בכולן עלה:","\u0003מלמדין כולי. \u0004 עמש\"ש שהראב\"ד חולק ע\"ז והקשה ממ\"ש וצריכ' כו' הא בבבא אמצעית בא יבם על החרשת וחזר ובא על הקטנה ליכא הנך ב' טעמי דהא איקיים מצות ייבום ולא רמיא גדולה קמיה וכן הקשה לח\"מ ומה שתי' הרמב\"ן דהצריכה לא קאי אלא ארישא ואסיפא משום דרישא אין זיקה כו' כמש\"ש וליתא דהא הצריכה הוא אליבא דשמואל ושמואל סבר יש זיקה וגם שם כ\"ט ב' אמרינן דר\"א ס\"ל יש זיקה ועמש\"ש ועי\"ל דא\"כ מאי משני בנד' ח' א' מאי קטנות כו' הא בדר' אליעזר איכא טובא לגי' רש\"י וש\"פ דגרסי קטנה וחרשת בא כו' פסל את הקטנה וגי' עיקר כמו שהוכיח הרשב\"א בראיות ברורות ועמש\"ש וא\"כ קאי ר\"א מלמדין נמי אהא ושם בא עליה בהיתר וליכא הנך טעמי וכמש\"ש ואף לגי' דל\"ג בכולן מ\"מ קאי גם כן אמתני' דשם ק\"י א' אין ביאת קטנה פוטרת את הגדולה אלא פוסלת את הגדולה ועל מתניתין דכאן בא יבם על הקטנה וחזר ובא כו' פריך אפילו לא בא על הגדולה פסל את הקטנה ומשני דנ\"מ שאילו לא בא על הגדולה ומתה היה מותר בקטנה ועכשיו אפילו מתה פסל את הקטנה אבל בחייה שזה בא אח\"כ על הגדולה או לא וכן לר\"א דמלמדין וכ\"ש לגי' בכולן מלמדין כולי דקאי אשם והן ד' בבי שם קטנה וחרשת וקטנה וגדולה וכאן קטנה וחרשת וקטנה וגדולה כמש\"ש:","\u0003ואם רצה כולי \u0004 שם ק\"י ב' כונס כולי ומוציא' כולי אבל לר\"א אם רצה כולי וכמ\"ש במתני' קי\"ב ב' כונס ואם רצה להוציא כולי לאפוקי בחליצה דלאו בת חליצה כמ\"ש בגמ' שם:","\u0003היו כולי \u0004 ביאת כולי ול\"ק חליצת כמ\"ש בגמ' שם וחרשת כולי ועתוס' שם ד\"ה וחרשת כולי ומיהו כולי ואשמעינן דאף ע\"ג דאכתי הוא מדרבנן אבל הרמב\"ם מפרש כמ\"ש תוס' שם ועוד כולי ואנן קי\"ל כר\"מ כמ\"ש ק\"ה ב' וכמש\"ש ק\"י ב' וקטנה תמתין כולי:","\u0003היתה כולי \u0004 מתני' שם וה\"ה לחליצה ולא תני במתני' חליצה אגב רישא קטנה וחרשת ופקחת וחרשת:","\u0003אבל אסור כו'. \u0004 רש\"י שם:","\u0003אלא כולי \u0004 רמב\"ם וכנ\"ל ס\"א. דבריו תמוהין ל\"ל וכי א\"י להוציא בגט ומשום שלא תפסל לכהונה אין אנו אחראין לזה אין מלמדין אלא להתיר השניה וכ\"כ בס\"י ג\"כ בא על הגדול' כולי מלמדין כו' וגם מ\"ש בסיפא בא על הקטנה וחזר כולי ג\"כ ק' ל\"ל וחזר כולי אפי' לא חזר הא ע\"כ גדולה צריכה חליצה וא\"כ ג\"כ תפסול הקטנה וכ\"ד אין נראין בזה והכלל דלגי' בכולן כולי וקאי אקטנה וחרשת ואקטנה וגדולה והן ד' בבי בבא ראשונה קטנה וחרשת ק\"י א' ושם קטנה וגדולה אין ביאת הקטנה פוטרת כולי ושני בבי כאן קטנה וחרשת לגי' הגאונים דלא פסל קאי אסיפא לבד ולגי' רש\"י גם ארישא על הקטנה ואח\"כ על החרשת ובבא קטנה וגדולה על הקטנה ואח\"כ על הגדולה אבל לפירוש הרמב\"ם במתני' הנ\"ל חדא קטנה וחרשת וכאן ד' בבות ברישא ב' קטנות ומציעת' חרשת וקטנה וסיפ' גדולה וקטנה וקטנה וגדולה אבל ליתא כנ\"ל:","\u0003והשני' אסור'. \u0004 דקנינן שוה ונפטרה:","\u0003ויוציאנ' בגט עבה\"ג ס\"ק ק' וכמש\"ל סימן ק\"ע סי\"ב:\u0004 ","\u0003לא פסל כו'. \u0004 עבה\"ג ור\"ל ברייתא שם א' מי שהי' נשוי כו' דדילמא כולי:","\u0003שביאת כולי \u0004 כבר הקשו עליו הרשב\"א והמפ' דהא בגמ' אמרי' משום דקטנה קנויה כולי ועוד דא\"כ תפטור לכתחלה אבל כוונתו בזה לסתור טעמא דגמר' הנ\"ל דדלמא קדים כולי ואמר שביאת כולי ולא אתי לאחלופי כמו בגדולה וקטנה ופקחת וחרשת:","\u0003אבל אחרים כולי \u0004 ר\"ל על ב' סעי' אלו מ\"ש בס\"ז דלא פסל גי' רש\"י וראב\"ד וש\"פ דפסל וכמ\"ש בגמ' שם א' ועוד הקשה הרשב\"א על גי' הגאונים מאי קמ\"ל רב חסדא חרשת קנויה כו' הא מתני' היא ועוד אדדייק שם מברייתא לידוק ממתני' וע\"ל מ\"ש בס\"ח ויוציא הקשו הרמב\"ן ורשב\"א הא קי\"ל כמ\"ד ממאנת אף לזיקתו ולמה תאסר עליו כמ\"ש הרמב\"ם בעצמו לקמן ס\"י מלמדין כולי ויקיים הגדולה אבל הרמב\"ם נזהר מזה שכ' שם שבעילתה קונה קנין גמור ר\"ל מדאורייתא ואף שביאה פסולה מותרת במיאון הקטנה משא\"כ בחרשת שביאתה בפסול היה וע\"ל סימן י' ס\"ב:","\u0003החרשת יוצאת כו'. \u0004 תוספתא והיא כתובה אצלנו בשבוש דתניא פי\"ג קטנה וחרשת בא יבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת נאסרו שתיהן עליו חרשת יוצא' בגט קטנה יוצאת בגט וחליצה פקחת וחרשת בא יבם על הפקח' וחזר ובא על החרשת או שבא אחיו על החרש' חרשת יוצאה בגט וחליצה גדולה וקטנה בא יבם על הגדולה וחזר כולי קטנה יוצא' בגט וגדולה יוצאה בגט וחליצה רא\"א בכולן מלמדין כולי וט\"ס הוא וצ\"ל בהיפוך בכולם בא יבם על החרשת וחזר ובא על הקטנה כולי בא יבם על החרשת וחזר ובא על הגדולה כו':"]}],["\u0010c0\u0011 סְרִיס חַמָּה \u0005(פֵּרוּשׁ, שֶׁנִּסְתָּרֵס עַל יְדֵי קַדַּחַת, עָרוּךְ)\u0006, וְאַיְלוֹנִית \u0005(פֵּרוּשׁ אַיְלוֹנִית, שֶׁיֵּשׁ לָהּ טֶבַע זָכָר, כְּלוֹמַר שֶׁאֵינָהּ יוֹלֶדֶת, וְאַיְלוֹנִית נִגְזַר מֵאַיִל שֶׁהוּא זְכַר הַצֹאן)\u0006, אֵינָם בְּנֵי חֲלִיצָה וְיִבּוּם. לְפִיכָךְ, אַיְלוֹנִית וַדָּאִית שֶׁחָלְצָה, לֹא נִפְסְלָה לִכְהֻנָּה. וְכֵן סְרִיס חַמָּה שֶׁחָלַץ, אוֹ שֶׁחָלְצוּ לְאִשְׁתּוֹ, אֵינוֹ כְּלוּם. \u0005 הַגָּה: הָיָה סְפֵק סָרִיס, חוֹלֵץ. וְלֹא מַחְזְקִינָן לֵהּ בְּוַדַּאי סָרִיס, אֶלָּא אִם רָאוּ בּוֹ, שֶׁנּוֹלַד, \u0010c1\u0011 אֶחָד מִסִּימָנֵי סָרִיס, כְּגוֹן שֶׁהֵטִיל מַיִם וְלֹא עָשָׂה כִּפָּה; אֲבָל בְּלָאו הָכִי יֵשׁ לָחוּשׁ שֶׁנִּתְקַלְקֵל אַחַר לֵדָתוֹ, וְצָרִיךְ לַחֲלֹץ \u0006 \u0005(רִיבָ\"שׁ סִימָן תע\"ד)\u0006. הָיָה לְאַיְלוֹנִית וַדָּאִית, צָרָה, \u0010c2\u0011 מֻתֶּרֶת לְהִתְיַבֵּם:\nסְפֵק אַיְלוֹנִית, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת.\nסְרִיס אָדָם \u0005 פֵּרוּשׁ, שֶׁנִּסְתָּרֵס וְנֶחְתַּךְ בִּידֵי אָדָם)\u0006, שֶׁהָיָה לוֹ שְׁעַת הַכּשֶׁר, חוֹלְצִין לְאִשְׁתּוֹ אוֹ מְיַבְּמִין, וְהוּא חוֹלֵץ וְאֵינוֹ מְיַבֵּם, מִפְּנֵי שֶׁפָּסוּל לָבֹא בַּקָּהָל. וְאִם עָבַר וּבָא עָלֶיהָ, קָנָה, וּמוֹצִיא בְּגֵט. \u0005 וְאִם הָיָה יְבִמְתּוֹ גִּיֹּרֶת אוֹ שְׁאָר אִשָּׁה הַמֻּתֶּרֶת לִפְצוּעַ דַּכָּא, מֻתָּר לְיַבְּמָהּ \u0006 \u0005(נ\"י פ' הֶעָרֵל)\u0006:\nאֵלּוּ הֵם סִימָנֵי אַיְלוֹנִית: כָּל שֶׁאֵין לָהּ דַּדִּים, וּמִתְקַשָּׁה בִּשְׁעַת תַּשְׁמִישׁ, וְאֵין לָהּ שִׁפּוּלֵי מֵעַיִם כַּנָּשִׁים, וְקוֹלָהּ עָבֶה, וְאֵינָהּ נִכֶּרֶת בֵּין אִישׁ לְאִשָּׁה. \u0005 וְיֵשׁ אוֹמְרִים דִּבְאֶחָד מֵאֵלֶּה נִקְרֵאת אַיְלוֹנִית \u0006 \u0005(טוּר)\u0006:\nאֵלּוּ הֵם \u0010c3\u0011 סִימָנֵי סְרִיס חַמָּה: כָּל שֶׁאֵין לוֹ זָקָן, וּשְׂעָרוֹ לָקוּי, וּבְשָׂרוֹ מַחֲלִיק, וּכְשֶׁמֵּטִיל מַיִם אֵינוֹ עוֹשֶׂה כִּפָּה, וְשִׁכְבַת זַרְעוֹ דֵּיהָא, וְאֵין מֵימֵי רַגְלָיו מַחֲמִיצִין, וְרוֹחֵץ בִּימוֹת הַגְּשָׁמִים וְאֵין בְּשָׂרוֹ מַעֲלֶה הֶבֶל, וְקוֹלוֹ לָקוּי, וְאֵינוֹ נִכָּר בֵּין אִישׁ לְאִשָּׁה. \u0005 הַגָּה: הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֵינוֹ סָרִיס אֶלָּא \u0010c4\u0011 עַד שֶׁיִּהְיוּ לוֹ כָּל הַסִּימָנִים הַלָּלוּ \u0006 \u0005(טוּר)\u0006. \u0005 אֲבָל אִם לֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֲפִלּוּ אֵין בּוֹ \u0010c5\u0011 רַק אֶחָד מֵהַסִּימָנִים הַלָּלוּ, הָוֵי סָרִיס \u0006 \u0005(הַמ\"מ פ\"ה דְּאִשּׁוּת וְכֵן מַשְׁמַע בְּטוּר)\u0006. \u0005 הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּשְׁאָר הַגּוּף, אֵינוֹ סָרִיס, אַף עַל פִּי שֶׁיֵּשׁ לוֹ כָּל הַסִּימָנִין הַלָּלוּ \u0006 \u0005(טוּר)\u0006: \u0010c6\u0011\nבְּנֵי כַּמָּה שָׁנִים יִהְיוּ לְשֶׁיִּהְיוּ נִדּוֹנִים כְּאַיְלוֹנִית וְסָרִיס עַל פִּי סִימָנִים הַלָּלוּ, נִתְבָּאֲרוּ בְּהָרַמְבַּ\"ם פֶּרֶק שֵׁנִי מֵהִלְכוֹת אִשּׁוּת, וּבְסִימָן קנ\"ה. \u0005 הַגָּה: סָעִיף י\"ג לְעִנְיַן אַיְלוֹנִית, וְהוּא הַדִּין לְסָרִיס. וְיֵשׁ אוֹמְרִים דְּאֵין לָדוּן עַכְשָׁו דִּין סְרִיס וַדַּאי, דְּחַיְשִׁינָן שֶׁמָּא הָיָה לוֹ שְׂעָרוֹת וְנָשְׁרוּ, אוֹ שֶׁהָיוּ לוֹ גֻּמּוֹת, וְאֵין אָנוּ בְּקִיאִין \u0006 \u0005(עַיֵּן בָּרִיבָ\"שׁ סִימָן תע\"ד)\u0006, \u0005 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ה לְעִנְיַן מֵאוּן. לָכֵן דַּיְנִינָן לֵהּ בִּסְפֵק סָרִיס, וְחוֹלֵץ, \u0010c7\u0011 וְכֵן רָאוּי לְהוֹרוֹת: \u0010c8\u0011 \u0006\nמִי שֶׁחָתְכוּ אוֹ נִתְּקוּ אוֹ מֵעֲכוּ גִּידָיו אוֹ בֵּיצָיו, בִּידֵי אָדָם, נִקְרָא סְרִיס אָדָם; וּכְשֶׁיִּהְיֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, נִקְרָא גָּדוֹל, שֶׁאֵין זֶה מֵבִיא סִימָנִים לָעוֹלָם:\nאַנְדְּרוֹגֵינוֹס, אֵינוֹ בַּר חֲלִיצָה וְיִבּוּם. \u0010c9\u0011 וְיֵשׁ אוֹמְרִים שֶׁדִּינוֹ כְּזָכָר לְכָל דָּבָר:\nטֻמְטוּם, חוֹלֵץ וְלֹא מְיַבֵּם, מִפְּנֵי שֶׁהוּא סָפֵק. וְאִם נִקְרַע, וְנִמְצָא זָכָר, רָצָה חוֹלֵץ, רָצָה \u0010c10\u0011 מְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא סָפֵק, \u0010c11\u0011 וּלְחֻמְרָא:\nהַזָּקֵן בְּיוֹתֵר, שֶׁתָּשׁ כֹּחוֹ וְכָשַׁל, דִּינוֹ כִּסְרִיס אָדָם לְעִנְיַן חֲלִיצָה וְיִבּוּם, אֶלָּא שֶׁאִם בָּא עַל יְבִמְתּוֹ מֻתָּר לְקַיְּמָהּ:\nהַחֵרֶשֶׁת וְהַשּׁוֹטָה וְהַקְּטַנָּה, מִתְיַבְּמוֹת וְלֹא חוֹלְצוֹת. וְאִם רָצָה הַיָּבָם \u0010c12\u0011 לְגָרֵשׁ הַחֵרֶשֶׁת בְּגֵט אַחַר שֶׁיִּבְעֹל אוֹתָהּ, הֲרֵי זֶה מְגָרֵשׁ:\nחֵרֵשׁ שׁוֹטֶה וְקָטָן, אֵינָם בְּנֵי חֲלִיצָה, אֲבָל \u0010c13\u0011 מְיַבְּמִין. וְהַחֵרֵשׁ, אִם נָפְלָה לוֹ מֵאָחִיו פִּקֵּחַ, אֵינוֹ יָכוֹל לְהוֹצִיא לְעוֹלָם. אֲבָל אִם נָפְלָה לוֹ מֵאָחִיו חֵרֵשׁ, יָכוֹל לְהוֹצִיא בְּגֵט אַחַר שֶׁיִּבְעֹל. וְהַקָּטָן, יוֹצִיא בְּגֵט, אִם בָּא עָלֶיהָ לְאַחַר שֶׁהִגְדִּיל; וְאִם לָאו, צְרִיכָה גֵּט לְמַאֲמָרוֹ וַחֲלִיצָה לְזִיקָתוֹ:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים פִּקְחוֹת, מֵת חֵרֵשׁ בַּעַל הַפִּקַּחַת, אָחִיו הַפִּקֵּחַ רָצָה חוֹלֵץ רָצָה מְיַבֵּם. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ אֵינוֹ יָכוֹל לַחֲלֹץ, וְכוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם:\nשְׁתֵּי אַחִים פִּקְחִים נְשׂוּאִים שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, מֵת פִּקֵּחַ בַּעַל הַחֵרֶשֶׁת, אֵין הַחֵרֶשֶׁת בַּת חֲלִיצָה, אֶלָּא כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ לְהוֹצִיא בְּגֵט, יוֹצִיא. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו, רָצָה חוֹלֵץ, רָצָה מְיַבֵּם:\nשְׁנֵי אַחִים, אֶחָד חֵרֵשׁ וְאֶחָד פִּקֵּחַ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים, אַחַת חֵרֶשֶׁת וְאַחַת פִּקַּחַת, פִּקֵּחַ לְפִקַּחַת, וְחֵרֵשׁ לְחֵרֶשֶׁת, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אָחִיו הַפִּקֵּחַ כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ, יוֹצִיא בְּגֵט. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ כּוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם. הַסוּמָא, מְיַבֵּם, \u0005 הַגָּה: וְאֵינוֹ חוֹלֵץ; וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0005 וְנִרְאֶה לִי, שֶׁאִם אֵין כָּאן אָח, אֶלָּא הוּא, חוֹלֵץ לְכַתְּחִלָּה, מֵאַחַר שֶׁאִי אֶפְשָׁר בְּעִנְיָן אַחֵר. וְע\"ל סִימָן קמ\"ט בְּפֵרוּשׁ הַחֲלִיצָה סָעִיף ס\"ד: \u0006\nאֵשֶׁת קָטָן וְאֵשֶׁת הַשּׁוֹטֶה, פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֲבָל אֵשֶׁת הַחֵרֵשׁ, וְהַזְּקֵנָה, וְהָעֲקָרָה, הֲרֵי הֵם כִּשְׁאָר כָּל הַנָּשִׁים, וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:",[],["\u0003סריס חמה ואיילונית\u0004. התורה מיעטו מחליצה ויבום ה\"ה אף אם בא על יבמתו אינו פוטר משאר אחים דאינו עולה ליבום אצלו גם א\"צ גט ממנו דאסורה עליו בכרת אשת אח שלא במקום מצוה משא\"כ סריס אדם שהיה לו שעת הכושר וראוי ליבום וחליצה אלא הוא מחייבי לאוין שהוא פצוע דכא מ\"ה אם בא עליה קנאה כמ\"ש בסוגיא דף כ':","\u0003א' מסימני סריס\u0004. משמע אפילו שאר סימן הניכר בקטנותו כגון שאין מימי רגליו מחמיצין סמכינן נמי שהוא סריס ממעי אמו, ומה שאמר אביי שאין עושה כיפה לאו דוקא ויתבאר בסמוך:","\u0003ספק איילונית\u0004. היינו הסימן איילוני' שיש בה אין היכר יפה כמ\"ש בב\"י סי' מ\"ד וכתב ב\"ח ספק איילונית אפילו לא הכיר בה בעלה שהיא ספק איילונית מ\"מ צריכ' חליצה:","\u0003סימני סריס\u0004. בזה לכ\"ע באחד מסימנים נקרא סריס אלא אם יש לו שתי שערות בזקנו כמו שכתוב בהג\"ה:","\u0003עד שיהיו לו כל הסימנים\u0004. וא\"ל איך אפש' שיהא לו סימנים דהא יש לו זקן תרצו התוס' דלא נקרא זקן אא\"כ נתמלא זקנו וכן הסכימו כל הפוסקים לא כראב\"ד דס\"ל כשיש לו ב' שערות בזקן תו לא נקרא סריס והנה כוונת תוספות מ\"ש יש לו זקן היינו נתמלא זקנו כלומר אם נתמלא זקנו תו א\"א לומר שיהא לו כל הסימני סריס אם כן לאו סריס הוא, אבל י\"ל מ\"מ אין לו דין גדול אלא קטן הוא עד רוב שנותיו לכן אין מובן לי מ\"ש הב\"י ר\"ס קס\"ט במה שכתב הטור שם אם נתמלא זקנו א\"צ לבדוק יותר כתב שלמד מתוס' הנ\"ל ובאמת מתוס' הנ\"ל לא משמע כלום אלא כוונתם ב' שערות בזקן לא נקרא יש לו זקן ושייך לומר שיהא לו כל סימני סריס:","\u0003רק א' מסימנים הללו\u0004. כלומר אם אין ב' שערות בכל הגוף ובזקן ויש לו עוד סימן א' מהני סימנים מחזיקין אותו לסריס כן הוא דעת הרמב\"ם וכן הוא בטור מיהו תוס' וראב\"ד ס\"ל בזה סימן לבד שאין לו ב' שערות כלל מחזיקין לסריס וא\"צ שום סימן אחר, ומה שכתב הריב\"ש בתשו' סי' תע\"ד דהרא\"ש מפרש גם כן כהראב\"ד א\"י מנ\"ל ואפשר ט\"ס שם, ולכאורה קשה איך אפשר בסי' זה לבד מחזיקין לסריס איך קאמר ר' יוחנן אפ' באחד מהם היינו שאין ב' שערות דהא ע\"כ צריך להיות שאין עושה כיפה כי בזה ניכר שלא נתרפא בינו לבינו וכה\"ג הקשה שם אליבא דמ\"ד עד שיהיו כולם ותירצו כיון שניכר מיד שאינו עושה כיפה ושאר סימנים ניכרים כ\"א בזמנו הוכיח הראשון על האחרים שממעי אמו הוא לקוי א\"כ אליבא דר' יוחנן קשה קושיא זו ואם תאמר דאיירי בילדותו לא היה עושה כיפה ואחר כן עושה כיפה משנתגדל אלא שאין לו ב' שערות א\"כ נעשה שינוי אצלו ואכתי יש לחוש שמא הבריא בנתיים כקושיית הש\"ס וצ\"ל דס\"ל אף בכה\"ג לא חיישינן שמא הבריא מאחר דנולד בו סי' אחר והוי לקוי בתחלה וסוף, שוב מצאתי קושיא זו בחדושי הלכות ע\"ש ותירץ דר\"י לא איירי לענין סריס חמה אלא הסימן מהני שהוא סריס:","\u0003בני כמה שנים\u0004. עיין תשובת ריב\"ש סימן שפ\"ד והובא בב\"י ומדבריו נלמד הכלל אף על פי שיש לו סימני סריס קודם עשרים שנה אמרינן עדיין קטן הוא עד שהוא בן עשרים ואז הוא סריס, ואם הוא בן כ' ולא הביא סימני סריס ויש לו ב' שערות לא דיינינן ליה כסריס אף על פי שנולדו בו סימני סריס אחר כך כיון שהביא שתי שערות קודם סימני סריס כן הוא הגירסא בריב\"ש ובב\"י איתא טעות, וכן הביא בב\"ח הגירסא, ואם קדמו סימני סריס אפילו אח\"כ הביא ב' שערות מחזיקין לסריס ואם אין לו ס\"ס ולא שתי שערות הרי הוא קטן עד רוב שנותיו ואז הרי הוא סריס אפילו אין לו ס\"ס, ואם קודם רוב שנותיו הביא ב' שערות ואחר כך ס\"ס הרי הוא גדול מיום הבאת ב' שערות, ואם הביא ס\"ס ואחר כך ב' שערות הרי הוא סריס ועיין ב\"ח:","\u0003וכן ראוי להורות\u0004. וצ\"ל אפילו הטיל מים ואינו עושה כיפה מיום שנולד מ\"מ חיישינן שמא נשרו אף על גב שנולד בו ס\"ס קודם מ\"מ אם הביא ב' שערות קודם עשרים הוא גדול, ומ\"ש בסעיף א' דצריך לחלוץ היכא דלא בדקו אם עושה כיפה היינו אפילו לבקיאין מיהו משמע ב' שערות בזקן דוקא שערות ולא גומות:","\u0003מי שחתכו וכו'\u0004. היינו שחתכו קודם שנבדקו אם עושה כיפה אבל בוודאי אם לא עשה כיפה לא יצא מידי ספיקא:","\u0003וי\"א שדינו כזכר\u0004. כ\"כ הטור בשם התוס' והרא\"ש ובספרו ב\"י השיג ע\"ז דלא כתבו לענין חליצה ויבום מאחר שאין מוליד אם כן דינו כסריס חמה דהא לא היה לו מעולם שעת הכושר וכן השיג מהרש\"ל ועיין דרישה וב\"ח, ורי\"ו כתב בשם הרמ\"ה אנדרוגינוס חולץ וחולצין לאשתו ואם כנס כהן אין מוציאין דספק חליצה לא גזרו רבנן גם עליו קשה מברייתא שהביאו הרי\"ף והרא\"ש אשת אנדרוגינוס פטורה מחליצה, מיהו גם הנ\"י פירש במשניות דתני אנדרוגינוס נושא היינו שאשתו צריכה חליצה, לפ\"ז לפסק תוס' דקי\"ל כמתניתין דזכר הוא א\"כ צריכה חליצה ולא כברייתא הנ\"ל, ולדינא נראה דחולץ וחולצין כמ\"ש הרמ\"ה:","\u0003ויש מי שאומר\u0004. היינו הרא\"ש פוסק כר' יוסי דאמר שמא נקרע וימצא סריס חמה היינו אף אם יהיה זכר ספק לנו שמא סריס הוא אפי' בלא סימני סריס ועיין בכורות דף מ\"ב:","\u0003הזקן ביותר וכולי\u0004. מדאוריית' ראוי לייבם שהרי כמה זקינים מולידי' אלא מדרבנן אסור לכתחלה לייבם אף על גב זקנה מותרת לייבם לכתחלה כמ\"ש בס\"ס משום זקנה יותר ראוי לביאה מזקן ועיין בד\"מ:","\u0003לגרש החרשת\u0004. בטור כתב סתם לגרש והיינו קטנה ואביה חי אז יצאת בגט כשאביה מקבל הגט כמו שכתב בסי' קמ\"א, ושוטה היינו דיכולה לשמור את גיטה אז מגורשת מדאורייתא גם אם יכולה לשמור את עצמה ומ\"מ היא שוטה אז מגורשת אבל מעשי' שהוא חלצה לאו מעשה הוא:","\u0003והחרש אם נפלה לו וכו'\u0004. הנה ברמב\"ם פ\"ו לא חילק בזה אלא סתם דבריו שבעילתו עושה אותה א\"א גמורה וב\"י וכ\"מ כתבו דע\"כ הרמב\"ם איירי כשנפלה מאחיו פקח כמה שמחלק בפ\"ב מה\"ג, והנה לירושלמי שכתב דחרש א\"י להוציא בגט אלא בקידשה ולא בעיל כמ\"ש בב\"י סימן קכ\"א, לפ\"ז מיושב שפיר דברי הרמב\"ם ומיהו הנ\"י כתב דלא מצינו שום פוסק שס\"ל חילוק של הירושלמי גם לשון הרמב\"ם היה דחוק אם ס\"ל כירושלמי:"],"\u0010c0\u0011 \u0010g0\u0011 \u0010r0\u0011 סְרִיס חַמָּה \u0005(פֵּרוּשׁ, שֶׁנִּסְתָּרֵס \u0010g1\u0011 עַל יְדֵי קַדַּחַת, עָרוּךְ)\u0006, וְאַיְלוֹנִית \u0005(פֵּרוּשׁ אַיְלוֹנִית, שֶׁיֵּשׁ לָהּ טֶבַע זָכָר, כְּלוֹמַר שֶׁאֵינָהּ יוֹלֶדֶת, וְאַיְלוֹנִית נִגְזַר מֵאַיִל שֶׁהוּא זְכַר הַצֹאן)\u0006, \u0010g2\u0011 אֵינָם בְּנֵי חֲלִיצָה וְיִבּוּם. \u0010r1\u0011 לְפִיכָךְ, אַיְלוֹנִית וַדָּאִית שֶׁחָלְצָה, לֹא נִפְסְלָה לִכְהֻנָּה. וְכֵן סְרִיס חַמָּה שֶׁחָלַץ, \u0010r2\u0011 אוֹ שֶׁחָלְצוּ לְאִשְׁתּוֹ, אֵינוֹ כְּלוּם. \u0005 הַגָּה: \u0010r3\u0011 הָיָה סְפֵק סָרִיס, חוֹלֵץ. \u0010r4\u0011 וְלֹא מַחְזְקִינָן לֵהּ בְּוַדַּאי סָרִיס, אֶלָּא אִם רָאוּ בּוֹ, שֶׁנּוֹלַד, \u0010c1\u0011 אֶחָד מִסִּימָנֵי סָרִיס, כְּגוֹן שֶׁהֵטִיל מַיִם וְלֹא עָשָׂה \u0010r5\u0011 כִּפָּה; אֲבָל בְּלָאו הָכִי יֵשׁ לָחוּשׁ שֶׁנִּתְקַלְקֵל אַחַר לֵדָתוֹ, וְצָרִיךְ לַחֲלֹץ \u0006 \u0005(רִיבָ\"שׁ סִימָן תע\"ד)\u0006. \u0010g3\u0011 הָיָה לְאַיְלוֹנִית וַדָּאִית, צָרָה, \u0010c2\u0011 \u0010g4\u0011 \u0010r6\u0011 מֻתֶּרֶת לְהִתְיַבֵּם:\nסְפֵק אַיְלוֹנִית, חוֹלֶצֶת וְלֹא \u0010g5\u0011 מִתְיַבֶּמֶת.\nסְרִיס אָדָם \u0005 פֵּרוּשׁ, שֶׁנִּסְתָּרֵס וְנֶחְתַּךְ בִּידֵי \u0010t0\u0011 אָדָם)\u0006, שֶׁהָיָה לוֹ שְׁעַת הַכּשֶׁר, חוֹלְצִין לְאִשְׁתּוֹ \u0010r7\u0011 אוֹ \u0010r8\u0011 מְיַבְּמִין, וְהוּא חוֹלֵץ וְאֵינוֹ מְיַבֵּם, מִפְּנֵי שֶׁפָּסוּל לָבֹא בַּקָּהָל. \u0010g6\u0011 וְאִם עָבַר וּבָא עָלֶיהָ, קָנָה, וּמוֹצִיא בְּגֵט. \u0005 וְאִם הָיָה יְבִמְתּוֹ גִּיֹּרֶת אוֹ שְׁאָר אִשָּׁה הַמֻּתֶּרֶת לִפְצוּעַ דַּכָּא, מֻתָּר לְיַבְּמָהּ \u0006 \u0005(נ\"י פ' הֶעָרֵל)\u0006: \u0010g7\u0011\nאֵלּוּ הֵם סִימָנֵי אַיְלוֹנִית: כָּל שֶׁאֵין לָהּ דַּדִּים, וּמִתְקַשָּׁה בִּשְׁעַת תַּשְׁמִישׁ, \u0010g8\u0011 וְאֵין לָהּ שִׁפּוּלֵי מֵעַיִם כַּנָּשִׁים, \u0010g9\u0011 וְקוֹלָהּ עָבֶה, וְאֵינָהּ נִכֶּרֶת בֵּין אִישׁ לְאִשָּׁה. \u0010r9\u0011 \u0005 וְיֵשׁ אוֹמְרִים דִּבְאֶחָד מֵאֵלֶּה נִקְרֵאת אַיְלוֹנִית \u0006 \u0005(טוּר)\u0006: \u0010r10\u0011\nאֵלּוּ הֵם \u0010c3\u0011 סִימָנֵי סְרִיס חַמָּה: \u0010g10\u0011 כָּל שֶׁאֵין לוֹ זָקָן, וּשְׂעָרוֹ לָקוּי, וּבְשָׂרוֹ מַחֲלִיק, \u0010g11\u0011 וּכְשֶׁמֵּטִיל מַיִם אֵינוֹ עוֹשֶׂה \u0010g12\u0011 כִּפָּה, וְשִׁכְבַת זַרְעוֹ דֵּיהָא, \u0010g13\u0011 וְאֵין מֵימֵי רַגְלָיו מַחֲמִיצִין, \u0010g14\u0011 וְרוֹחֵץ בִּימוֹת הַגְּשָׁמִים וְאֵין בְּשָׂרוֹ מַעֲלֶה הֶבֶל, \u0010g15\u0011 וְקוֹלוֹ לָקוּי, וְאֵינוֹ נִכָּר בֵּין אִישׁ לְאִשָּׁה. \u0005 הַגָּה: \u0010r11\u0011 הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֵינוֹ סָרִיס אֶלָּא \u0010c4\u0011 עַד שֶׁיִּהְיוּ לוֹ כָּל הַסִּימָנִים הַלָּלוּ \u0006 \u0005(טוּר)\u0006. \u0005 אֲבָל אִם לֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֲפִלּוּ אֵין בּוֹ \u0010c5\u0011 רַק אֶחָד מֵהַסִּימָנִים הַלָּלוּ, הָוֵי סָרִיס \u0006 \u0005(הַמ\"מ פ\"ה דְּאִשּׁוּת וְכֵן מַשְׁמַע בְּטוּר)\u0006. \u0005 הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּשְׁאָר הַגּוּף, אֵינוֹ סָרִיס, אַף עַל פִּי שֶׁיֵּשׁ לוֹ כָּל הַסִּימָנִין הַלָּלוּ \u0006 \u0005(טוּר)\u0006: \u0010c6\u0011 \u0010r12\u0011\nבְּנֵי כַּמָּה שָׁנִים יִהְיוּ לְשֶׁיִּהְיוּ נִדּוֹנִים כְּאַיְלוֹנִית וְסָרִיס עַל פִּי סִימָנִים הַלָּלוּ, נִתְבָּאֲרוּ בְּהָרַמְבַּ\"ם פֶּרֶק שֵׁנִי מֵהִלְכוֹת אִשּׁוּת, וּבְסִימָן קנ\"ה. \u0005 הַגָּה: סָעִיף י\"ג לְעִנְיַן אַיְלוֹנִית, וְהוּא הַדִּין לְסָרִיס. \u0010r13\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין לָדוּן עַכְשָׁו דִּין סְרִיס וַדַּאי, דְּחַיְשִׁינָן שֶׁמָּא הָיָה לוֹ שְׂעָרוֹת וְנָשְׁרוּ, אוֹ שֶׁהָיוּ לוֹ גֻּמּוֹת, וְאֵין אָנוּ בְּקִיאִין \u0006 \u0005(עַיֵּן בָּרִיבָ\"שׁ סִימָן תע\"ד)\u0006, \u0005 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ה לְעִנְיַן מֵאוּן. לָכֵן דַּיְנִינָן לֵהּ בִּסְפֵק סָרִיס, וְחוֹלֵץ, \u0010c7\u0011 וְכֵן רָאוּי לְהוֹרוֹת: \u0010c8\u0011 \u0010g16\u0011 \u0010r14\u0011 \u0006\nמִי שֶׁחָתְכוּ אוֹ נִתְּקוּ אוֹ מֵעֲכוּ גִּידָיו אוֹ בֵּיצָיו, בִּידֵי אָדָם, נִקְרָא סְרִיס אָדָם; וּכְשֶׁיִּהְיֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, נִקְרָא גָּדוֹל, \u0010r15\u0011 שֶׁאֵין זֶה מֵבִיא סִימָנִים לָעוֹלָם: \u0010g17\u0011 \u0010r16\u0011\nאַנְדְּרוֹגֵינוֹס, אֵינוֹ בַּר חֲלִיצָה וְיִבּוּם. \u0010c9\u0011 \u0010g18\u0011 \u0010r17\u0011 וְיֵשׁ אוֹמְרִים שֶׁדִּינוֹ כְּזָכָר לְכָל דָּבָר: \u0010r18\u0011\nטֻמְטוּם, חוֹלֵץ וְלֹא מְיַבֵּם, מִפְּנֵי שֶׁהוּא סָפֵק. וְאִם נִקְרַע, וְנִמְצָא זָכָר, \u0010g19\u0011 רָצָה חוֹלֵץ, רָצָה \u0010c10\u0011 \u0010g20\u0011 \u0010r19\u0011 מְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא סָפֵק, \u0010c11\u0011 \u0010g21\u0011 \u0010r20\u0011 וּלְחֻמְרָא:\nהַזָּקֵן בְּיוֹתֵר, שֶׁתָּשׁ כֹּחוֹ וְכָשַׁל, דִּינוֹ כִּסְרִיס אָדָם לְעִנְיַן חֲלִיצָה וְיִבּוּם, \u0010r21\u0011 אֶלָּא שֶׁאִם בָּא עַל יְבִמְתּוֹ \u0010g22\u0011 מֻתָּר לְקַיְּמָהּ:\nהַחֵרֶשֶׁת וְהַשּׁוֹטָה \u0010g23\u0011 \u0010r22\u0011 וְהַקְּטַנָּה, מִתְיַבְּמוֹת וְלֹא חוֹלְצוֹת. \u0010g24\u0011 וְאִם רָצָה הַיָּבָם \u0010c12\u0011 לְגָרֵשׁ הַחֵרֶשֶׁת בְּגֵט אַחַר שֶׁיִּבְעֹל אוֹתָהּ, הֲרֵי זֶה מְגָרֵשׁ: \u0010g25\u0011 \u0010r23\u0011\nחֵרֵשׁ שׁוֹטֶה \u0010g26\u0011 \u0010r24\u0011 וְקָטָן, אֵינָם בְּנֵי חֲלִיצָה, \u0010g27\u0011 אֲבָל \u0010c13\u0011 \u0010r25\u0011 מְיַבְּמִין. וְהַחֵרֵשׁ, אִם נָפְלָה לוֹ מֵאָחִיו פִּקֵּחַ, אֵינוֹ יָכוֹל לְהוֹצִיא לְעוֹלָם. \u0010g28\u0011 אֲבָל אִם נָפְלָה לוֹ מֵאָחִיו חֵרֵשׁ, יָכוֹל לְהוֹצִיא בְּגֵט אַחַר \u0010g29\u0011 \u0010r26\u0011 שֶׁיִּבְעֹל. וְהַקָּטָן, יוֹצִיא בְּגֵט, אִם בָּא עָלֶיהָ לְאַחַר שֶׁהִגְדִּיל; \u0010g30\u0011 וְאִם לָאו, צְרִיכָה גֵּט לְמַאֲמָרוֹ וַחֲלִיצָה לְזִיקָתוֹ: \u0010g31\u0011\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים פִּקְחוֹת, מֵת חֵרֵשׁ בַּעַל הַפִּקַּחַת, אָחִיו הַפִּקֵּחַ רָצָה חוֹלֵץ רָצָה מְיַבֵּם. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ אֵינוֹ יָכוֹל לַחֲלֹץ, וְכוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם: \u0010g32\u0011\nשְׁתֵּי אַחִים פִּקְחִים נְשׂוּאִים שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, מֵת פִּקֵּחַ בַּעַל הַחֵרֶשֶׁת, אֵין הַחֵרֶשֶׁת בַּת חֲלִיצָה, אֶלָּא כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ לְהוֹצִיא בְּגֵט, יוֹצִיא. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו, רָצָה חוֹלֵץ, רָצָה \u0010g33\u0011 מְיַבֵּם:\nשְׁנֵי אַחִים, אֶחָד חֵרֵשׁ וְאֶחָד פִּקֵּחַ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים, אַחַת חֵרֶשֶׁת וְאַחַת פִּקַּחַת, פִּקֵּחַ לְפִקַּחַת, וְחֵרֵשׁ לְחֵרֶשֶׁת, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אָחִיו הַפִּקֵּחַ כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ, יוֹצִיא בְּגֵט. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ כּוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם. \u0010g34\u0011 \u0010r27\u0011 הַסוּמָא, מְיַבֵּם, \u0005 הַגָּה: וְאֵינוֹ חוֹלֵץ; וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0010r28\u0011 \u0005 וְנִרְאֶה לִי, שֶׁאִם אֵין כָּאן אָח, אֶלָּא הוּא, חוֹלֵץ לְכַתְּחִלָּה, מֵאַחַר שֶׁאִי אֶפְשָׁר בְּעִנְיָן אַחֵר. וְע\"ל סִימָן קמ\"ט בְּפֵרוּשׁ הַחֲלִיצָה סָעִיף ס\"ד: \u0010g35\u0011 \u0006\nאֵשֶׁת קָטָן וְאֵשֶׁת הַשּׁוֹטֶה, פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. \u0010g36\u0011 אֲבָל אֵשֶׁת הַחֵרֵשׁ, \u0010g37\u0011 וְהַזְּקֵנָה, וְהָעֲקָרָה, הֲרֵי הֵם כִּשְׁאָר כָּל הַנָּשִׁים, וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:",{"g":["ל' הטור ממשנה יבמות דע\"ט וכר\"ע","פי' במעי אמו וכדמפרש שם בגמ' ריש דף פ' דהיא ע\"י שנתחממ' אמו בחו' התנור וחום הצהרים ושתתה משקה חזק","דכתיב לא ימחה שמו מישראל פרט לסריס ששמו מחוי והאיילונית דכתיב והיה הבכור אשר תלד פרט לאיילונית","מסקנת הגמרא שם די\"ב ע\"ב","טור ופשוט הוא","שם במשנה דע\"ט ע\"ב וכר\"ע","ברייתא שם","בריית' שם ד\"פ ע\"ב וכת\"ק","כרשב\"ג שם","כרשב\"א שם","ברייתא שם וכת\"ק ופי' לקוי רך","שם וכיש אומרים ופי' כיפ' קילוח שאינו הולך למרחוק","שם וכרשב\"ג וכולי ופי' דיהא שאינו קשו' אלא צלול כמים","שם וכי\"א ופי' מחמיצין מסריחים","שם וכאחרים","שם וכרשב\"א","רמב\"ם בפ' ב' מהלכות אישות והביאו הטור וכתב ופשוט הוא","רמב\"ם בריש פ\"ו מה' ייבום וחליצה וכ' ה\"ה מפורש בתוספת' הובאה בהל' ספ\"ק","\u0003טור לדעת ר\"י ולדעת אביו הרא\"ש שפירש והא דאמרי בי רב הלכה כר' יוסי וכו'\u0004 שם דפ\"ג ע\"א אר' יוסי דמתני' קאי וכפירש\"י שם והב\"י כ' ואפשר דלא אמרו הלכה כר' יוסי אלא להאכילו בתרומ' לחייב עליו סקילה מ\"מ לענין יבום וחליצה דינו כסריס חמה כדקתני בברייתא משום דאינו ראוי להוליד","\u0003הרמב\"ם שם ודלא כרב יהודה במשנה שם דפ\"א ע\"א מהא דא\"ר אמי עביד וכו'\u0004 שם דפ\"ג ע\"א דמשמע דפליגי רבנן וסברי חולץ ומיבם","טור בשם אביו הרא\"ש וכרב יוסי בר יהודה שם בברייתא וכדמפרש בגמ' שם ולחומרא כיון דלא מפורש דרבנן פליגי בזה","רמב\"ם בפרק ו' מבריי' הביאה הרי\"ף בספ\"ק","תוספת' והביא הר\"ף והרא\"ש ספ\"ק","ציינתי לעיל סימן קס\"ז","משנה שם דקי\"ב ע\"ב","שם במשנה וברייתא דלעיל","ציינתיו לעיל","שם במשנה","\u0003טור ממשנה שם כשם שכונס ברמיזה וכו'\u0004 וה\"ה ליבמה ואין דעת הרמב\"ם כן וכמ\"ש הב\"י טעמו","משנה נדה דמ\"ה ע\"א","שם ביבמות במשנה דף צ\"ו ע\"ב","שם במשנה דף קיב ע\"א","שם במשנה","שם במשנה","טור דהא לא אימיע' אלא מחליצ' לכתחלה משום דבעינן וירקה בפניו ואין זה רואה הרוק כמ\"ש בסי' קס\"ט סעיף מח","משנה וברייתא שם דף צ\"ו ע\"ב","ציינתיו בסעיפים דלעיל","ברייתא הביאו הרי\"ף והרא\"ש ספ\"ק דיבמות ופי' בנ\"י דטעמא משום דכמ' עקרות וזקנות נפקדו וראויות להקים מה שא\"כ באילונית והרמב\"ם בפ\"ו כתב משום דזקינה ועקרה היתה להם שעת הכושר"],"t":["\u0003אדם וכו'. \u0004 או מייבמין והוא חולץ ואינו מייבם. עיין תוס' י\"ט פרק ח' דיבמות משנה ד' מ\"ש על הרמב\"ם וכנה\"ג מיישבו:"],"r":["\u0003סריס חמה כו'. \u0004 כר\"ע דאין הלכה כר\"א דשמותי היא ועוד מעדותו של ר' יהושע ב\"ב ועוד דמחלוקת ואח\"כ סתם כמ\"ש ס' ב':","\u0003לפיכך כו' \u0004 וכן כולי. מתני' שם:","\u0003או שחלצו כולי. \u0004 תוספתא פי\"א סריס חמה ואנדרוגינוס ואח מאם וגר ועבד משוחרר לא חולצין ולא מיבמין כיצד מתו והניחו נשים ולהם אחים באו אחים ועשו מאמר נתנו גט וחלצו לא עשו כלום בעלו פסלו מן הכהונה וחייבין בקרבן מתו אחים כולי:","\u0003היה ספק כו'. \u0004 פ\"ג ב' מאי בינייהו כולי:","\u0003ולא מחזקי' כו'. \u0004 ע\"ט פ' ה\"ד סריס חמה כו' מנא ידעינן כי' וע\"תוס פ' ב' ד\"ה עד כולי מ\"מ כיון שניכר כולי וז\"ש אחד מסימני סריס כו':","\u0003אבל בלא\"ה כו'. \u0004 שם בתוס' וא\"ת כולי ואור\"י כולי:","\u0003ספק איילוני' כולי \u0004 כנ\"ל בסריס וע\"תוס שם ב' ב' ד\"ה או כולי:","\u0003או מייבמין. \u0004 במתני' שם וייבמו את אשתו:","\u0003והוא כולי \u0004 ואם היה. גמ' שם ועתוס' שם ד\"ה אי הכי כולי:","\u0003וי\"א דבאחד כולי. \u0004 כמו באיש בלא הביא ב' שערות בזקן כיון דל\"ל סימן כלל בזקן על הולדה די באחד. ובזה מתי' קושית תוספת ד' א' ד\"ה דלא כו' דאליבא דר' יוחנן אמר דקיי\"ל כוותיה ולר\"ה ל\"ק כמש\"ש ולמר בר\"א כולי הא אמרינן כולי:","\u0003אלו הם כולי \u0004 דכל אחד מוסיף על חבירו ממש\"ש רה\"א עד כולי רי\"א אפי' כולי וכן אביי דאמר שם כל המטיל כולי וכן רבה בר אבוה דאמר לרבנן עיינו כולי וחסר כאן אין מימיו מעלין רתיחות וט\"ס הוא וברמב\"ם וטור איתא:","\u0003היו לו כולי \u0004 אבל כולי. גמרא שם וכרבי יוחנן ועתו\"ס דברכות מ\"ם ב' ד\"ה ור\"י כולי היו לו כולי. עתו\"ס דיבמו' שם ד\"ה דהביא וא\"ת והא כו' ואר\"י שערות כולי:","\u0003בני כולי. \u0004 גמ' שם:","\u0003וי\"א כולי \u0004 דחיישינן כו' כמ\"ש בנדה מ\"ו א' דבספיקא דאורייתא חיישינן שמא נשרו ואף בלא בעל עתוס' שם נ\"ב ב' ד\"ה הלכה ור\"ת כולי וז\"ש דחיישינן כולי או כולי:","\u0003מי שחתכו כו'. \u0004 כמ\"ש בברייתא שם פצוע דכא כו' וערש\"י כ' ב' ד\"ה סריס כו' וד\"ה או כולי וכ\"ה בתוספת ספ\"ב והוב' ברי\"ף ספ\"ק וברא\"ש שם:","\u0003שאין זה כו'. \u0004 שלכן אמרו שם א' ורמינהו בן כולי דא\"א לומר בסריס אדם שא\"צ עד כולי:","\u0003אנדרוגינוס כולי \u0004 תוספתא ספ\"ב והובא ברי\"ף ספ\"ק ופי\"א וכ' בס\"א:","\u0003וי\"א כולי \u0004 טור וכפירש\"י ותוספת פ\"ג א' ד\"ה הלכה כולי וכמש\"ל סימן מ\"ד ס\"ה בהג\"ה ומ\"מ תמוה דאינו ענין לכאן דהא מידי ספק לכ\"ע לא נפק וחליצה עכ\"פ צריך ממנו ואפ\"ה קתני בתוספתא הנ\"ל לא חולץ ואם חלץ לא פסלה ואם בעלה פסלה ודאי וחייבין בקרבן וכן בנשותיהם כמו שכתב בתוספתא שם וכבר השיגו ב\"י ורש\"ל וש\"פ ודברי ב\"ש דחויין והנה גם לעיקר דינא פליגי הרי\"ף ורמב\"ם וש\"פ על רש\"י ומפ' דאר\"י דברייתא קאי וכמ\"ש רב שם ליתא למתני' מקמי ברייתא ואע\"ג דשמואל פליג הלכה כרב והא דר\"י א\"ר שם ב' אמוראי נינהו וכמה משניות וברייתות בש\"ס ותוספתא וירושלמי דספיקא הוא וכן סתם בש\"ע בא\"ח סימן י\"ז וסימן של\"ה וסימן תקפ\"ט וסימן תר\"מ וסימן תרפ\"ט ובי\"ד סימן קפ\"א וסימן קצ\"ד רס\"ה רס\"ו ובא\"ה סימן כ\"ב ובח\"מ סימן ל\"ה וסימן רנ\"ג וסימן ר\"פ וברמב\"ם עוד בהרבה מקומות:","\u0003טומטום כולי \u0004 תוספתא רפי\"א טומטום שקידש כולי חולץ וחולצין לאשתו אם יש שם אחים אין חולץ ואין מייבם אבל מייבמין את אשתו ר\"י בר' יהודה אומא לא חולץ ולא חולצין לאשתו לא מייבם ולא מייבמין את אשתו שמא יקרע וימצא סריס חמה ופ' כת\"ק וז\"ש ואם נקרע כולי דע\"כ ת\"ק ל\"ל דריב\"י וכ\"ש דר' יהודה:","\u0003ויש כולי. \u0004 עבה\"ג אבל בתוספתא פליגי רבנן בהדיא כנ\"ל:","\u0003הזקן כולי. \u0004 עבה\"ג ודלא כרש\"י כ' ב' ד\"ה והזקן כולי:","\u0003אלא כולי. \u0004 שם ד\"ה יאסור כולי וכן ע\"ט ב' ד\"ה ואסור כולי וכמ\"ש בגמרא בהדיא משום שנאסר כולי:","\u0003והקטנה כולי. \u0004 ס\"א ב' ותניא קטנה כולי ודלא כר\"מ וכסתם מתני' שם קי\"א ב' וכמ\"ש בגמ' שם:","\u0003חרש ושוטה. \u0004 תוספתא הנ\"ל:","\u0003וקטן. \u0004 כמ\"ש במתני' הנ\"ל דלא כר\"מ כמ\"ש בסי\"א ולא חולץ כמ\"ש בפס\"ח:","\u0003והחרש כולי \u0004 אבל כולי. במתני קי\"ב ב' ואם היו נכריות כולי ועסי\"ג וסט\"ו ובתוספתא ספי\"ג פקחת לפקח ולו אח חרש כונס ואינו מוציא לעולם פקחת לחרש ולו אח חרש כונס ואם רצה להוציא יוציא:","\u0003והקטן כולי \u0004 ואם לאו כולי. מתני' וגמ' ונדה מ\"ה א' בן ט' כולי ולכשיגדיל כולי:","\u0003הסומא מייבם ואינו כולי. \u0004 מ\"ג א':","\u0003ונ\"ל כולי \u0004 כ\"כ הראב\"ד וכמש\"ל סימן קס\"ט סמ\"ח:"]}],["הַיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם בְּאִסוּר כָּרֵת, \u0010c0\u0011 חוּץ מִן הַנִּדָּה, אֵינָהּ זְקוּקָה לַיָּבָם, וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, וְכֵן צָרוֹתֶיהָ פְּטוּרוֹת מִן הַחֲלִיצָה וּמֵהַיִּבּוּם. וְאִם הָיָה לוֹ אָח אַחֵר, וְאַחַת מִצָּרוֹתֶיהָ נִתְיַבְּמָה לְאוֹתוֹ אָח, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵחֲלִיצָה וּמִן הַיִּבּוּם. וְאִם הָיָה לוֹ עוֹד אָח אַחֵר, וְאַחַת מֵהַנָּשִׁים אֵלּוּ נִתְיַבְּמָה לוֹ, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִבּוּם. וְכֵן עַד עוֹלָם:\nאֲבָל אִם אַחַת מִכָּל הָעֲרָיוֹת נְשׂוּאָה לְזָר שֶׁאֵינוֹ אָחִיו, וּמֵת, מֻתָּר לִשָּׂא צָרָתָהּ: \u0010c1\u0011\nיְבָמָה שֶׁהִיא סְפֵק עֶרְוָה עַל בַּעְלָהּ, אוֹ סְפֵק עֶרְוָה עַל הַיָּבָם, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. לְפִיכָךְ, מִי שֶׁקִּדֵּשׁ אִשָּׁה בִּסְפֵק קִדּוּשִׁין, וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיָה נוֹשֵׂא אֲחוֹתָהּ, וְנָפְלָה לוֹ לְיִבּוּם, שֶׁהִיא סְפֵק אֲחוֹת אִשְׁתּוֹ, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וּמוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט מִסָפֵק, וּשְׁתֵּיהֶן אֲסוּרוֹת עָלָיו; יְבִמְתּוֹ, מִפְּנֵי שֶׁהִיא סְפֵק עֶרְוָה; וַאֲרוּסָתוֹ, מִפְּנֵי \u0010c2\u0011 שֶׁהִיא סְפֵק קְרוֹבַת חֲלוּצָתוֹ:\nהָיְתָה הַיְבָמָה בְּאִסוּר עֶרְוָה עַל הַבַּעַל, אֵינָהּ אִשְׁתּוֹ. וְאִם הָיָה לָהּ צָרָה, חוֹלֶצֶת \u0010c3\u0011 אוֹ מִתְיַבֶּמֶת. וְזוֹ שֶׁהָיְתָה לַבַּעַל בְּאִסוּר עֶרְוָה, הִיא לַיָּבָם כְּמוֹ אִשָּׁה דְּעָלְמָא, וּמֻתָּר בָּהּ:\nהָיְתָה הַיְבָמָה סְפֵק עֶרְוָה עַל הַבַּעַל, אוֹ חוֹלֶצֶת אוֹ \u0010c4\u0011 מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא סְפֵק עֶרְוָה לַיָּבָם, וְהָיָה לְאָחִיו בָּהּ סְפֵק קִדּוּשִׁין אוֹ סְפֵק גֵּרוּשִׁין, וְלוֹ אִשָּׁה אַחֶרֶת, אוֹתָהּ הַצָּרָה חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nהָיָה אָחִיו נָשׂוּי אִשָּׁה שֶׁהִיא עֶרְוָה לַיָּבָם, וְלוֹ עוֹד אִשָּׁה אַחֶרֶת, וְאַחַר כָּךְ מֵתָה הָעֶרְוָה בְּחַיֵּי בַּעְלָהּ, אוֹ \u0010c5\u0011 גֵּרְשָׁהּ, אוֹ שֶׁהָיְתָה קְטַנָּה \u0010c6\u0011 וּמֵאֲנָה בּוֹ, וְאַחַר כָּךְ מֵת, מֻתֶּרֶת צָרָתָהּ לְהִתְיַבֵּם. אֲבָל אִם לֹא מֵאֲנָה בּוֹ בְּחַיָּיו, וּמֵאֲנָה בּוֹ אַחַר מוֹתוֹ, צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nסָפֵק אִם אוֹתָהּ שֶׁהִיא עֶרְוָה לַיָּבָם מֵתָה בְּחַיֵּי הַבַּעַל אוֹ אַחַר מוֹתוֹ, צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם וְהִיא \u0010c7\u0011 אַיְלוֹנִית, אֲפִלּוּ הִכִּיר בָּהּ בַּעְלָהּ, הֲרֵי הִיא כְּמִי שֶׁאֵינָהּ, וְצָרָתָהּ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. וְאִם יִבֵּם הַצָּרָה מִפְּנֵי שֶׁהָיָה סָבוּר שֶׁהָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת שֶׁאֵינָהּ אַיְלוֹנִית, תֵּצֵא מִיבָמָהּ \u0010c8\u0011 בְּלֹא גֵּט, וְהַוָּלָד מַמְזֵר:\nנִשֵּׂאת הַצָּרָה לְזָר, מִפְּנֵי שֶׁהָיְתָה סְבוּרָה שֶׁאֵין הָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת אַיְלוֹנִית, תֵּצֵא מֵהַבַּעַל בְּגֵט, וּבַחֲלִיצָה מֵהַיָּבָם לְהַתִּירָהּ. וְאִם מִתְּחִלָּה לֹא נִשֵּׂאת לְזָר, אֶלָּא נִתְקַדְּשָׁה לוֹ בִּלְבַד, מֻתֶּרֶת לַיָּבָם:\nמִי שֶׁזִּנְּתָה אִשְׁתּוֹ תַּחְתָּיו בְּעֵדִים וּבְרָצוֹן, וּמֵת בְּלֹא זֶרַע, וְנָפְלָה לִפְנֵי אָחִיו, \u0010c9\u0011 דִּינָהּ כְּדִין עֶרְוָה, וְהִיא וְצָרָתָהּ פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִּבּוּם, אֲבָל אִם \u0010c10\u0011 סָפֵק זִנְּתָה אִם לָאו, הִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ, אוֹ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דַּאֲפִלּו זִנְּתָה וַדַּאי, צְרִיכָה חֲלִיצָה \u0006 \u0005(הַשָּׂגוֹת הָרַאֲבַ\"ד)\u0006, \u0005 וְהוּא הַדִּין לְצָרָתָהּ, \u0010c11\u0011 \u0006 \u0005 וְיֵשׁ לְהַחֲמִיר. וְלָכֵן, מִי שֶׁיֵּשׁ לוֹ אִשָּׁה שֶׁהֵמִירָה, אַף עַל גַּב דְּוַדַּאי זִנְּתָה, צָרָתָהּ צְרִיכָה חֲלִיצָה \u0006 \u0005(מָרְדְּכַי רֵישׁ יְבָמוֹת וְכ\"כ מהרא\"י סִימָן רי\"ט)\u0006. \u0010c12\u0011 \u0005 אִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא הַבַּעַל וּמֵת, צָרָתָהּ מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵינָהּ כְּצָרַת סוֹטָה \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פֶּרֶק הָאִשָּׁה)\u0006: \u0010c13\u0011\nאֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ, הֲרֵי הִיא אֵשֶׁת אָח שֶׁלֹּא בִּמְקוֹם מִצְוָה, וּפוֹטֶרֶת צָרָתָהּ. כֵּיצַד, רְאוּבֵן שֶׁמֵּת, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי שִׁמְעוֹן אָחִיו, וְאַחַר כָּךְ נוֹלַד לֵוִי אָחִיו, בֵּין שֶׁנּוֹלַד קֹדֶם שֶׁיִּבֵּם שִׁמְעוֹן אֵשֶׁת רְאוּבֵן, בֵּין שֶׁנּוֹלַד אַחַר שֶׁיִּבְּמָה, וּמֵת שִׁמְעוֹן, אֲסוּרָה עַל לֵוִי לְעוֹלָם. וְאִם הָיָה לְשִׁמְעוֹן אִשָּׁה אַחֶרֶת, גַּם הִיא פְּטוּרָה מֵחֲלִיצָה וּמֵהַיִּבּוּם, וּפוֹטֶרֶת צָרָתָהּ וְצָרַת צָרָתָהּ עַד סוֹף הָעוֹלָם, כְּדִין צָרַת עֶרְוָה. וְאִם מֵת שִׁמְעוֹן, אֲפִלּוּ קֹדֶם שֶׁעָשָׂה בָּהּ מַאֲמָר, אֵשֶׁת שִׁמְעוֹן חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, מִשּׁוּם דְּכֵיוָן דְּקַיְמָא לָן יֵשׁ זִקָּה, אֲפִלּוּ לֹא עָשָׂה מַאֲמָר \u0010c14\u0011 הֲוָה לֵהּ כְּצָרַת אֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ:\nקְטַנָּה \u0010c15\u0011 שֶׁהָיְתָה נְשׂוּאָה לְאָחִיו מֵאִמּוֹ [לַאֲחִי אִמּוֹ] שֶׁהִיא שְׁנִיָּה לוֹ, וּמֵת, וְנִשְׁאַר וּנְשָׂאָה אָחִיו מֵאָבִיו, וּמֵת, וְנָפְלָה לְפָנָיו לְיִבּוּם וְעוֹדֶנָּה קְטַנָּה, אֵין אוֹמְרִים תְּמָאֵן, לַעֲקֹר נִשּׂוּאִין הָרִאשׁוֹנִים, כְּדֵי שֶׁתִּתְיַבֵּם, אֶלָּא צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, שֶׁאַף הִיא חוֹלֶצֶת אִם תְּמָאֵן:\nקְטַנָּה שֶׁאֵינָהּ עֶרְוָה עָלָיו, וּמֵת, וּמֵאֲנָה הַקְּטַנָּה בַּיָּבָם, \u0010c16\u0011 אֲסוּרָה לוֹ וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, \u0010c17\u0011 אִם אֵין שָׁם אַחִים אֲחֵרִים. וְדַוְקָא הִיא, \u0010c18\u0011 אֲבָל צָרָתָהּ מֻתֶּרֶת לוֹ, וַאֲפִלּוּ הִיא מֻתֶּרֶת לִשְׁאָר אַחִים שֶׁלֹּא מֵאֲנָה בָּהֶם:\nהָיוּ לְאָחִיו בְּאִשְׁתּוֹ סְפֵק גֵּרוּשִׁין, וְנָפְלָה לְפָנָיו \u0010c19\u0011 לְיִבּוּם, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. אֲבָל אִם הָיָה לְאָחִיו סְפֵק קִדּוּשִׁין, הֲרֵי זוֹ יְכוֹלָה \u0010c20\u0011 לְהִתְיַבֵּם:\nהַמְגָרֵשׁ אִשְׁתּוֹ גְּדוֹלָה, אוֹ קְטַנָּה שֶׁהִשִּׂיאוּהָ אָחֶיהָ, וְהֶחֱזִירָהּ, וּמֵת, וְנָפְלָה לִפְנֵי יָבָם, מֻתֶּרֶת לוֹ. אֲבָל קְטַנָּה שֶׁהִשִּׂיאָה אָבִיהָ, וְנִתְגָּרְשָׁה בְּקַטְנוּתָהּ עַל יְדֵי אָבִיהָ, וְהֶחֱזִירָהּ וָמֵת בְּעוֹדָהּ קְטַנָּה, \u0010c21\u0011 אֲסוּרָה לְיָבָם. וְכֵן הַדִּין בִּמְגָרֵשׁ הַפִּקַּחַת, וְנִתְחָרְשָׁה, וְהֶחֱזִירָהּ, וּמֵת, וְהִיא חֵרֶשֶׁת; וּבֵין בָּזוֹ וּבֵין בָּזוֹ, \u0010c22\u0011 צָרָתָהּ מֻתֶּרֶת לְהִתְיַבֵּם:\nהֶחֱזִירָהּ כְּשֶׁהִיא קְטַנָּה אוֹ חֵרֶשֶׁת, וְגָדְלָה וְנִתְפַּקְּחָה אֶצְלוֹ, וּמֵת, מֻתֶּרֶת לְהִתְיַבֵּם. וְאֵין צָרִיךְ לוֹמַר אִם הֶחֱזִירָהּ אַחַר שֶׁגָּדְלָה אוֹ נִתְפַּקְּחָה:",[],["\u0003חוץ מן הנדה\u0004. הטעם מבואר בתוס' והרא\"ש ריש יבמות דלא דמי לעריות שאסורה ליבם מחמת קורבה ומותרת לאחר משא\"כ נדה שאסורה לכל גם עומדת לטבילה:","\u0003יבמה שהיא ספק ערוה על בעלה או ספק ערוה וכו'\u0004. כצ\"ל וכן הוא ברמב\"ם והטור תמה ע\"ז למה היא אסורה לייבם דהא ממ\"נ מותרת דאם היא ערוה לבעל הוי כאלו אינה אשתו ומותרת ליבם ואם היא אינה ערוה לבעל א\"כ היא זקוק' ליבם ובכ\"מ כתב דיש למחוק האלף של או וצ\"ל וספק ערוה על היבם היינו שהיה ספק ערוה על היבם ועל הבעל לכן אסורה ליבם ומ\"מ אין מיושב שפיר דאכתי קשה ל\"ל דהיא לשניהם ספק ערוה ת\"ל דאם היא ליבם לבד ספק ערו' נמי אסורה לייבם ובמ' כתב ומפרש דברי הרמב\"ם דקאי על הצרה, ואנ\"ל דהא לא אדכר כלום צרה, ולכאורה נ\"ל דאיירי ג\"כ דאסורה לבעלה מספק כמו הספק דאסורה ליבם ובשני בבות אסורה ליבם מספק או מחמת קידושין שלו או מחמת קידושי אחיו היינו שבעלה קידש אחת מספק קדושין ואח\"כ נשא אחותה א\"כ היא ספק ערוה לבעלה ואסורה ליבם דשמא קידושין של אחותה קידושין מעלייתא הם א\"כ אחותה זקוקה לו והיא אחות זקוקתו:","\u0003שהיא ספק קרובת חלוצתו\u0004. אף על גב אחות חליצתו מדברי סופרים א\"כ הוי ספק דרבנן אפ\"ה קנסו רבנן וגזרו באחות חליצה אטו אחות גרושה דאורייתא לפיכך אלמוה לגזרותם להוציא אפי' על הספק אפילו בדיעבד כ\"כ הנ\"י פ\"ב במתני' מי שקידש ולא כב\"ח שכתב לכתחילה אסור מיהו אם קדם וכנס אין מוצאין אלא אף בדיעבד אם כנס מוציאין ממנו ותימא על הב\"ח שהביא בסי' קט\"ו דברי הנ\"י וכאן אשתמט' מיניה:","\u0003או מתייבמת\u0004. מאחר שהיא ערוה לבעל ואין קידושין תופסין בה א\"כ לא הוי צרה שלה צרתה ואין חילוק בין עריות אפילו נשא אחיו את אחותו שהיא ג\"כ אחות היבם מ\"מ הצרה מותרת ליבם והגירסא במיימ' ישנים באחותו שחולץ לצרה ואסורה ליבם ט\"ס הוא כאשר הגיה הכ\"מ ובחנם טרח ב\"ח וכתב מה שכתב ואישתמטא מיניה דברי הכ\"מ:","\u0003יבמה שהיא ספק ערוה ליבם וכו'\u0004. כצ\"ל היינו שקידש אחיו ספק קידושין לבת אחיו אף על גב שצרתה עומדת בחזקת היתר ליבם מ\"מ מחמת קידושי ספק של זו אסורה ליבם וצריכה חליצה וכן אם כבר היה נשואה לו בת אחיו וצרה א\"כ הצרה בחזקת היתר לשוק עומדת מ\"מ מחמת גירושי ספק של בת אחיו אסורה זו לשוק בלא חליצה, וספק קידושין או גירושין היינו בזרק לה קידושין או גירושין וספק קרוב לו או לה הוי ספק דאורייתא ואם ב' עדים אומרים קרוב לה וב' עדים אומרים קרוב לו אז הוי ספיקא דרבנן כי מדאורייתא אוקמא תרי בהדי תרי ואוקמה אחזק' א\"כ בקידושין מותרת ליבם מדאורייתא, וכן בגירושין מותרת לשוק מדאורייתא ועיין בתוספות פד\"א, וכן אם ע\"א אמר קרוב לה וע\"א אמר קרוב לו הוי ספיקא דרבנן ועיין סימן קל\"ט שם מבואר דקי\"ל אפי' קרוב לה הוי ספיקא דדינא אם מגורשת מחמת קרוב לה וכן גט שאין בו זמן או כתב הבעל בכת\"י ואין עליו עדים וכן בכת' בכת\"י וחתום ע\"א הוי נמי בכלל ספק גירושין והיינו מדאורייתא מגורשת אלא מדרבנן פסול הגט, ובקידושין אין פסול כלל כשאין בו זמן וכן בכת\"י ואין עליו עדים כתב הרא\"ש דפסול הוא משום זמן שמא יקדים הזמן ובקדושין כשר:","\u0003או שהיתה קטנה\u0004. אף שאביה חי אשכחן מיאון כגון שאביה השיא אותה ונתגרשה כשהיתה קטנה שוב אין לאביה רשות בה והלכה ונשאת ש\"ס:","\u0003ומיאנה בו\u0004. וכן אם לא מיאנה הואיל והיא קטנה וקידושי' מדרבנן לכן צרתה חולצת ואסורה ליבם, מתני' ריש יבמות אלא קמ\"ל אפי' מיאנה מ\"מ צרתה אסור' ליבם הואיל ונראה בשעת נפילה כצרת בתו:","\u0003אפי' הכיר בה\u0004. דכי אסר רחמנא צרת ערוה במקום מצוה הוא דאסרה וכיון דאיילונית היא דבלאו ערוה נמי לא חזי ליבום הוי צרתה צרת ערוה שלא במקום מצוה רש\"י פ\"ק דיבמות ולענין אשת אחיו שהיא איילונית ולא הכיר בה ואין ערוה על היבם אם היא מותרת ליבם נראה דתליא בפלוגתא המבואר בסימן מ\"ד להני פוסקים דס\"ל כשלא הכיר בה א\"צ גט אז מותרת לו דהוי כאלו אינה אשת אחיו, אבל להפוסקים דס\"ל דצריכה גט מדרבנן א\"כ אסורה לו דהוי כאשת אח שלא במקום מצוה:","\u0003בלא גט\u0004. מאחר דהיא אשת אח שלא במקום מצוה והיא מחייבי כריתות אין קידושין תופסין בה אף על גב בחלץ לאחת תופסין קדושין בשניה ולא אמרינן דהיא מחייבי כריתות דשם כתיב אשר לא יבנה ניתק מכרת ללאו תוס' פ\"ק דיבמות והגירסא ברמב\"ם תצא בגט ט\"ס ועיין בהגהו' דריש' שדחק את עצמו ליישב קושיא זאת למה בחלץ לאחת מהן קידושין תופסין בשניה:","\u0003דינה כדין ערוה\u0004. מ\"ט טומאה כתיב בה ונסתרה והיא נטמאה ובעריות כתיב אל תטמאו בכל אלה מ\"ה דינה כערוה וצרתה היא צרת ערוה ופטורה מן החליצה ויבום ובנ\"י הניח בצ\"ע אשת כהן שנאנסה אם צריכה חליצה, ולכאורה תמוה הא איתא בש\"ס להדיא פ' הע\"י דף נ\"ה אשת כהן שנאנסה בעלה לוקה עליה משום טומאה דכתיב אחרי אשר הוטמא' היינו שנבעלה ובאשת כהן הוי אונס כרצון נשמע אף באונס טומאה כתיב בה א\"כ היא וצרתה פטורים מן החליצה כמו זנות ברצון וצל\"ע, שוב ראיתי גם ב\"ח הרגיש בזה, ואפשר דס\"ל דוקא לחומרא הוי אונס בכהן כרצון בישראל ולא לקולא כמ\"ש בתוס' ולענין ספק זינתה עיין ר\"ס י\"א מבואר אפי' אם נאסרה בקינוי וסתיר' מ\"מ קידושין של הנחשד תופסין בה וכן אפי' אם זינתה ברצון בעדים תופסין קידושי הבועל:","\u0003ספק זינתה\u0004. עיין בתו' סוטה דף ה' כתבו ספק סוטה לא אימעיט אלא גבי איסורא דבעל וקמ\"ל קרא כיון דבא מכח נשואי אחיו הרי הוא במקום בעל דאסורה לו ליבם אבל חליצה בעי ש\"מ דאינה אסורה ליבם אלא היכא דאסורה לבעלה:","\u0003ויש להחמיר\u0004. עיין ב\"ח שכתב או היא או צרת' צריכ' חליצה ולא שייך למימר חליצה פסולה כאן כמ\"ש בתוס' דף י\"א בד\"ה או היא ע\"כ, ודבריו תמוהים ע\"כ לא כתבו תוס' שם אלא באיסור דלא קלשה הזיקה אבל בסוטה קלשה הזיקה פשיטא שייך לומר חליצ' פסולה וכ\"כ תוס' להדיא ר\"פ ד\"א ע\"ש לכן נראה בחליצת הסוטה לא נפטר' הצרה:","\u0003אשה שהלך בעלה וכו'\u0004. בד\"מ כ\"כ בשם ש\"ג וא\"י מה חידש בזה הא ש\"ס ערוכה היא פ\"ק דף י\"א אמינא אנא סוטה דאורייתא ואת אמרת לי סוטה דרבנן ע\"ש בפרש\"י ואפש' דקמ\"ל שמותרת לכתחלה ליבם ובש\"ס ה\"א בדיעבד קאמר וע\"ש בתוס' ד\"ה ר\"ש אומר:","\u0003אשת אחיו שלא היה בעולמו\u0004. דכתיב כי ישבו אחים יחדיו שהית' להם ישיבה אחת בעולם א\"כ אם לא היה להם ישיבה אחת בעולם לא שריא רחמנא והיא מחייבי' כריתות עליו לכן אפי' צרתה אסורה ופטורה מחליצ' ויבום אף על גב דנפלה השתא מאח שהי' לו ישיבה אחת בעולם עמו מ\"מ אסור' לו מחמת אחיו הראשון:","\u0003הוה לי' כצרת א\"א שלא היה בעולמו\u0004. וכן הוא במתני' רפ\"ב וא\"ל למה לא תני טעם משום דהיא צרת בעלת זיקת שני יבמין משום כיון מצד ראובן בעלה הראשון אין לה זיקה עליו שהיא א\"א שלא היה בעולמו, א\"כ משום זיקת שני יבמין אינה אסורה אלא מדרבנן ומשום צרת א\"א שלא הי' בעולמו אסור מדאורייתא ועיין בש\"ג רפ\"ב כתב הא דקי\"ל יש זיקה היינו מדברי סופרים יש זיקה, ועיין בש\"ס דף כ\"ז ע\"ב ובתוס' שם מ\"ש בשם ר\"ת ועיין ס\"ס קע\"ד כתבתי אי לא עביד מאמר אינה אסורה משום צרת שני זיקות:","\u0003שהית' נשואה לאחיו מאמו\u0004. כן הוא בטור וקמ\"ל אף על גב דהיא אינה אסורה עליו מדאורייתא אלא שני' היא מחמת בעלה הראשון מ\"מ א\"י למאן השתא ולעקור נישואין קמאי כיון בעת הנפילה היתה נראית כאשת אחי אמו שהיא שני' לו ומכ\"ש כשהית' אשת אחיו מאמו דאז אסורה לו מדאורייתא וצרת' לעולם צריכה חליצה ואין נפטרת מחמת קטנה שהיא ערוה עליו דהא נישואי קטנה רק מדרבנן וקטנה זו אם ממאנת בנשואין הראשונים אז מדאורייתא עוקרת נישואין הראשונים וכאלו היא לבד אשת אחיו מאביו אלא מדרבנן היא אסורה מחמת נישואין הראשונים וצריכ' חליצה ואם אינה ממאנת אפי' בנשואין הראשונים אז אם התה אשת אחי אמו שהיא שניה לו צריכה חליצה ואם יש לה צרה היא נפטרת בחליצת הצרה ואם היא אשת אחיו מאמו א\"צ חליצה:","\u0003אסורה לו\u0004. ולא אמרי' דעקר' נישואין הראשוני' והרי היא נכרית משום דנראה כאשת אחיו כיון דלא מיאנה בבעל':","\u0003אם אין שם אחים אחרים\u0004. כ\"כ הרי\"ף והרא\"ש דאם יש אחים אחרים חולצין או מייבמין אף על גב דקי\"ל ממאנ' לזיקה ועוקרת נישואין הראשונים מ\"מ כה\"ג לא עקרה אלא מזה אבל משאר אחים נשאר הזיק' ועי' בהמאור ובמלחמות ה', מיהו נראה לשיטת הרמב\"ם מותרת לאחיו לאו מתורת הזיק' אלא עוקרת הזיקה והוי כאלו לא הית' אשת אחיהם ומותרת להם דהא הוא פוסק פי\"א מה\"ג מיאנ' ביבם מותרת לקרובי המת אלא לאביו אסורה ולמד זאת מדמותרת לאחים כמ\"ש בהמגיד שם וכך משמע שם מלשון הרמב\"ם ואי מותרת לאחים היינו זיקה אצלם אין ראי' מהיתר אחים להיתר שאר קרוביו כדמדחה הרמב\"ן באמת סברת הרמב\"ם וכתב לאחים מותרת מחמת הזיקה אבל לקרובי המת אסורה א\"ו צ\"ל הרמב\"ם ס\"ל דמותרת לאחים לאו משום זיקה אלא כשעוקרת הזיקה תו לא הוי אשת אחיהם ומותרת להם אף על גב דאסורה ליבם א\"כ נשמע נמי דמותרת לשאר קרובים לפ\"ז תימא על המחבר בסי' קנ\"ה סי\"א הביא פלוגתתם אם מותרת לשאר קרובים ומשמע שם דס\"ל עיקר כרמב\"ם דמותרת לשאר קרוביו א\"כ מוכח דליתא הזיק' וא\"צ חליצה וכאן סתם ופסק כשיטת הפוסקים דצריכה חליצ' משאר אחים:","\u0003אבל צרת' מותרת\u0004. כשם שהיא מותרת לשאר אחים משום דלא עבידא בה מעשה והיא אמר' לא ריענא בזה אבל לשאר אחים ריענא, כך צרתה מותרת, אלא לכאורה קשה מאחר דהיא אסור' א\"כ הממאנת כערוה עליו מחמת אשת אח שלא במקום מצוה, אם כן למה לא אסורה הצרה כמו בצרת איילונית וסוטה, וכעין זה הקשה תוספ' דף י\"ב, וצריך לומר דממאנת בעצמה על פי הדין מותרת מאחר דעקרה נישואין הראשונים ולא הוי כאשת אחיו א\"כ צרתה לא גרע מצרת חייבי לאוין או שניות דמותרת ליבם כמ\"ש בסי' א\"ז:","\u0003חולצת ולא מתייבמת\u0004. שהיא ספק גרושת אחיו שהיא בכרת משא\"כ בספק קידושין מותרת ממ\"נ:","\u0003המגרש וכו'\u0004. אף על גב בעת שגירש אחיו היתה אסורה לו משום גרושת אחיו מ\"מ כיון דלא היתה אסורה עליו בעת הזיקה לא אמרינן כיון דאסורה שעה א' אסורה לעולם וכן הדין בקטנה שהשיאוה אמה ואחיה, מיהו כשהשיאה אביה עדיין שם גרושה עליה כיון דחזרתה לאו חזרה גמורה דהא הגט הי' ע\"י אביה וחזרתה ע\"י עצמה כי אביה אין רשות עליה כיון דנתגרש' אחר הנשואין ועיין סי' קנ\"ה שהביא בהגהות וי\"א אם נשאת קטנה שלא לדעת אמה ואחיה א\"צ מיאון ש\"מ דלאו נשואין כלל הם נראה לכאורה שהשיאוה אמה ואחיה ונתגרשה תו א\"י אמה ואחיה להנשא לה דלא עדיפים מאביה א\"כ חזרת' לאו כלום הוא ושם גירושין עליה מיהו י\"ל בכה\"ג לכ\"ע נישואין שלה מהני מאחר דאין לאמה ואחיה שום רשות עליה מהני מעשיה גם י\"ל אמה ואחיה יכולים להנשא אותה אף שכבר השיאו אותה ונתגרשה דהא בהשיאוה אביה ונתגרשה יכולים אמה ואחיה להנשא ואביה א\"י להנשא אותה כמ\"ש בטור סימן מ\"ג:","\u0003אסורה ליבם\u0004. וכתב הרמב\"ם דא\"צ חליצה ולא יבום מיהו הרא\"ש והטור כתבו דצריכ' חליצה וכן הוא לשיטת הראב\"ד ובעל המאור והיא פטורה בחליצת הצרה והצרה אינה נפטרת בחליצת היתומה:","\u0003צרתה מותרת להתייבם\u0004. כ\"כ רוב הפוסקים אף על גב דהיא צרת ערוה דהא היתומה היא כגרושת אחיו ולרמב\"ם דינה ממש כגרושת אחיו מ\"ה א\"צ חליצה מ\"מ צרתה מותרת להתייב' ובעלמא קי\"ל צרת ערוה של קטנה חולצת ולא מתייבמת עיין בהרא\"ש שתירץ שאני ערוה זו שיש לה היתר לעצמה אם גדלה אצלו ועיין במלחמות ה':"],"\u0010g0\u0011 הַיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם בְּאִסוּר כָּרֵת, \u0010c0\u0011 \u0010g1\u0011 חוּץ מִן הַנִּדָּה, אֵינָהּ זְקוּקָה לַיָּבָם, וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, וְכֵן צָרוֹתֶיהָ פְּטוּרוֹת מִן הַחֲלִיצָה וּמֵהַיִּבּוּם. וְאִם הָיָה לוֹ אָח אַחֵר, וְאַחַת מִצָּרוֹתֶיהָ נִתְיַבְּמָה לְאוֹתוֹ אָח, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵחֲלִיצָה וּמִן הַיִּבּוּם. וְאִם הָיָה לוֹ עוֹד אָח אַחֵר, וְאַחַת מֵהַנָּשִׁים אֵלּוּ נִתְיַבְּמָה לוֹ, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִבּוּם. וְכֵן עַד עוֹלָם: \u0010g2\u0011 \u0010r0\u0011\nאֲבָל אִם אַחַת מִכָּל הָעֲרָיוֹת נְשׂוּאָה לְזָר שֶׁאֵינוֹ אָחִיו, וּמֵת, מֻתָּר לִשָּׂא צָרָתָהּ: \u0010c1\u0011 \u0010r1\u0011\nיְבָמָה שֶׁהִיא \u0010g3\u0011 סְפֵק עֶרְוָה עַל בַּעְלָהּ, אוֹ סְפֵק עֶרְוָה עַל הַיָּבָם, \u0010g4\u0011 \u0010r2\u0011 הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. לְפִיכָךְ, מִי שֶׁקִּדֵּשׁ אִשָּׁה בִּסְפֵק קִדּוּשִׁין, וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיָה נוֹשֵׂא אֲחוֹתָהּ, וְנָפְלָה לוֹ לְיִבּוּם, שֶׁהִיא סְפֵק אֲחוֹת אִשְׁתּוֹ, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא \u0010g5\u0011 \u0010r3\u0011 מִתְיַבֶּמֶת, וּמוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט מִסָפֵק, וּשְׁתֵּיהֶן אֲסוּרוֹת עָלָיו; יְבִמְתּוֹ, מִפְּנֵי שֶׁהִיא סְפֵק עֶרְוָה; וַאֲרוּסָתוֹ, מִפְּנֵי \u0010c2\u0011 שֶׁהִיא סְפֵק קְרוֹבַת \u0010t0\u0011 חֲלוּצָתוֹ: \u0010g6\u0011 \u0010r4\u0011\nהָיְתָה הַיְבָמָה בְּאִסוּר עֶרְוָה עַל הַבַּעַל, אֵינָהּ אִשְׁתּוֹ. וְאִם הָיָה לָהּ צָרָה, חוֹלֶצֶת \u0010c3\u0011 אוֹ \u0010r5\u0011 מִתְיַבֶּמֶת. וְזוֹ שֶׁהָיְתָה לַבַּעַל בְּאִסוּר עֶרְוָה, הִיא לַיָּבָם כְּמוֹ אִשָּׁה דְּעָלְמָא, וּמֻתָּר בָּהּ: \u0010g7\u0011 \u0010r6\u0011\nהָיְתָה הַיְבָמָה סְפֵק עֶרְוָה עַל הַבַּעַל, אוֹ חוֹלֶצֶת אוֹ \u0010c4\u0011 \u0010g8\u0011 מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא \u0010g9\u0011 סְפֵק עֶרְוָה לַיָּבָם, וְהָיָה לְאָחִיו בָּהּ סְפֵק קִדּוּשִׁין אוֹ סְפֵק גֵּרוּשִׁין, וְלוֹ אִשָּׁה אַחֶרֶת, אוֹתָהּ הַצָּרָה חוֹלֶצֶת וְלֹא \u0010g10\u0011 מִתְיַבֶּמֶת:\nהָיָה אָחִיו נָשׂוּי אִשָּׁה שֶׁהִיא עֶרְוָה לַיָּבָם, וְלוֹ עוֹד אִשָּׁה אַחֶרֶת, וְאַחַר כָּךְ מֵתָה הָעֶרְוָה בְּחַיֵּי בַּעְלָהּ, אוֹ \u0010c5\u0011 גֵּרְשָׁהּ, אוֹ שֶׁהָיְתָה קְטַנָּה \u0010c6\u0011 \u0010r7\u0011 וּמֵאֲנָה בּוֹ, וְאַחַר כָּךְ מֵת, מֻתֶּרֶת צָרָתָהּ \u0010g11\u0011 לְהִתְיַבֵּם. אֲבָל אִם לֹא מֵאֲנָה בּוֹ בְּחַיָּיו, וּמֵאֲנָה בּוֹ אַחַר מוֹתוֹ, \u0010g12\u0011 צָרָתָהּ חוֹלֶצֶת \u0010g13\u0011 וְלֹא \u0010g14\u0011 מִתְיַבֶּמֶת:\nסָפֵק אִם אוֹתָהּ שֶׁהִיא עֶרְוָה לַיָּבָם מֵתָה בְּחַיֵּי הַבַּעַל אוֹ אַחַר מוֹתוֹ, צָרָתָהּ חוֹלֶצֶת וְלֹא \u0010g15\u0011 מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם וְהִיא \u0010c7\u0011 \u0010g16\u0011 אַיְלוֹנִית, אֲפִלּוּ הִכִּיר בָּהּ בַּעְלָהּ, הֲרֵי הִיא כְּמִי שֶׁאֵינָהּ, וְצָרָתָהּ חוֹלֶצֶת אוֹ \u0010g17\u0011 \u0010r8\u0011 מִתְיַבֶּמֶת. וְאִם יִבֵּם הַצָּרָה מִפְּנֵי שֶׁהָיָה סָבוּר שֶׁהָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת שֶׁאֵינָהּ אַיְלוֹנִית, תֵּצֵא מִיבָמָהּ \u0010c8\u0011 בְּלֹא גֵּט, וְהַוָּלָד מַמְזֵר: \u0010g18\u0011 \u0010r9\u0011\nנִשֵּׂאת הַצָּרָה לְזָר, מִפְּנֵי שֶׁהָיְתָה סְבוּרָה שֶׁאֵין הָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת אַיְלוֹנִית, תֵּצֵא מֵהַבַּעַל בְּגֵט, וּבַחֲלִיצָה מֵהַיָּבָם לְהַתִּירָהּ. \u0010g19\u0011 \u0010r10\u0011 וְאִם מִתְּחִלָּה לֹא נִשֵּׂאת לְזָר, אֶלָּא נִתְקַדְּשָׁה לוֹ בִּלְבַד, מֻתֶּרֶת לַיָּבָם: \u0010g20\u0011 \u0010r11\u0011\nמִי שֶׁזִּנְּתָה אִשְׁתּוֹ תַּחְתָּיו בְּעֵדִים וּבְרָצוֹן, וּמֵת בְּלֹא זֶרַע, וְנָפְלָה לִפְנֵי אָחִיו, \u0010c9\u0011 דִּינָהּ כְּדִין \u0010t1\u0011 עֶרְוָה, וְהִיא וְצָרָתָהּ פְּטוּרוֹת מֵהַחֲלִיצָה \u0010g21\u0011 וּמֵהַיִּבּוּם, אֲבָל אִם \u0010c10\u0011 סָפֵק זִנְּתָה אִם לָאו, הִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ, אוֹ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. \u0005 הַגָּה: \u0010r12\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּו זִנְּתָה וַדַּאי, צְרִיכָה חֲלִיצָה \u0006 \u0005(הַשָּׂגוֹת \u0010g22\u0011 הָרַאֲבַ\"ד)\u0006, \u0010r13\u0011 \u0005 וְהוּא הַדִּין לְצָרָתָהּ, \u0010c11\u0011 \u0010t2\u0011 \u0006 \u0005 וְיֵשׁ לְהַחֲמִיר. וְלָכֵן, מִי שֶׁיֵּשׁ לוֹ אִשָּׁה שֶׁהֵמִירָה, \u0010r14\u0011 אַף עַל גַּב דְּוַדַּאי זִנְּתָה, צָרָתָהּ צְרִיכָה חֲלִיצָה \u0006 \u0005(מָרְדְּכַי רֵישׁ יְבָמוֹת וְכ\"כ מהרא\"י סִימָן רי\"ט)\u0006. \u0010c12\u0011 \u0010r15\u0011 \u0005 אִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא הַבַּעַל וּמֵת, צָרָתָהּ מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵינָהּ כְּצָרַת סוֹטָה \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פֶּרֶק הָאִשָּׁה)\u0006: \u0010c13\u0011 \u0010g23\u0011\nאֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ, הֲרֵי הִיא אֵשֶׁת אָח שֶׁלֹּא בִּמְקוֹם מִצְוָה, וּפוֹטֶרֶת צָרָתָהּ. \u0010g24\u0011 כֵּיצַד, רְאוּבֵן שֶׁמֵּת, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי שִׁמְעוֹן אָחִיו, וְאַחַר כָּךְ נוֹלַד לֵוִי אָחִיו, \u0010g25\u0011 בֵּין שֶׁנּוֹלַד קֹדֶם שֶׁיִּבֵּם שִׁמְעוֹן אֵשֶׁת רְאוּבֵן, בֵּין שֶׁנּוֹלַד אַחַר שֶׁיִּבְּמָה, וּמֵת שִׁמְעוֹן, אֲסוּרָה עַל לֵוִי לְעוֹלָם. וְאִם הָיָה לְשִׁמְעוֹן אִשָּׁה אַחֶרֶת, גַּם הִיא פְּטוּרָה מֵחֲלִיצָה וּמֵהַיִּבּוּם, וּפוֹטֶרֶת צָרָתָהּ וְצָרַת צָרָתָהּ עַד סוֹף הָעוֹלָם, כְּדִין צָרַת עֶרְוָה. וְאִם מֵת שִׁמְעוֹן, \u0010g26\u0011 \u0010r16\u0011 אֲפִלּוּ קֹדֶם שֶׁעָשָׂה בָּהּ מַאֲמָר, אֵשֶׁת שִׁמְעוֹן חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, מִשּׁוּם דְּכֵיוָן \u0010r17\u0011 דְּקַיְמָא לָן יֵשׁ זִקָּה, אֲפִלּוּ לֹא עָשָׂה מַאֲמָר \u0010c14\u0011 הֲוָה לֵהּ כְּצָרַת אֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ: \u0010g27\u0011 \u0010r18\u0011\nקְטַנָּה \u0010c15\u0011 שֶׁהָיְתָה נְשׂוּאָה לְאָחִיו מֵאִמּוֹ \u0010g28\u0011 [לַאֲחִי אִמּוֹ] שֶׁהִיא שְׁנִיָּה לוֹ, וּמֵת, וְנִשְׁאַר וּנְשָׂאָה אָחִיו מֵאָבִיו, וּמֵת, וְנָפְלָה לְפָנָיו לְיִבּוּם וְעוֹדֶנָּה קְטַנָּה, \u0010g29\u0011 אֵין אוֹמְרִים תְּמָאֵן, לַעֲקֹר נִשּׂוּאִין הָרִאשׁוֹנִים, כְּדֵי שֶׁתִּתְיַבֵּם, אֶלָּא צָרָתָהּ חוֹלֶצֶת וְלֹא \u0010r19\u0011 מִתְיַבֶּמֶת, שֶׁאַף הִיא חוֹלֶצֶת \u0010g30\u0011 אִם תְּמָאֵן: \u0010g31\u0011\nקְטַנָּה שֶׁאֵינָהּ עֶרְוָה עָלָיו, וּמֵת, וּמֵאֲנָה הַקְּטַנָּה בַּיָּבָם, \u0010c16\u0011 \u0010g32\u0011 אֲסוּרָה לוֹ \u0010r20\u0011 וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, \u0010c17\u0011 אִם אֵין שָׁם אַחִים אֲחֵרִים. וְדַוְקָא הִיא, \u0010c18\u0011 \u0010g33\u0011 \u0010r21\u0011 אֲבָל צָרָתָהּ \u0010r22\u0011 מֻתֶּרֶת לוֹ, \u0010g34\u0011 \u0010r23\u0011 וַאֲפִלּוּ הִיא מֻתֶּרֶת לִשְׁאָר אַחִים שֶׁלֹּא מֵאֲנָה בָּהֶם: \u0010g35\u0011\nהָיוּ לְאָחִיו בְּאִשְׁתּוֹ \u0010r24\u0011 סְפֵק גֵּרוּשִׁין, וְנָפְלָה לְפָנָיו \u0010c19\u0011 לְיִבּוּם, חוֹלֶצֶת וְלֹא \u0010g36\u0011 מִתְיַבֶּמֶת. אֲבָל אִם הָיָה לְאָחִיו סְפֵק \u0010g37\u0011 קִדּוּשִׁין, הֲרֵי זוֹ יְכוֹלָה \u0010c20\u0011 \u0010g38\u0011 לְהִתְיַבֵּם:\nהַמְגָרֵשׁ אִשְׁתּוֹ גְּדוֹלָה, אוֹ קְטַנָּה שֶׁהִשִּׂיאוּהָ אָחֶיהָ, וְהֶחֱזִירָהּ, וּמֵת, וְנָפְלָה לִפְנֵי יָבָם, מֻתֶּרֶת לוֹ. \u0010g39\u0011 אֲבָל קְטַנָּה שֶׁהִשִּׂיאָה אָבִיהָ, וְנִתְגָּרְשָׁה בְּקַטְנוּתָהּ עַל יְדֵי אָבִיהָ, וְהֶחֱזִירָהּ וָמֵת בְּעוֹדָהּ קְטַנָּה, \u0010c21\u0011 אֲסוּרָה לְיָבָם. \u0010r25\u0011 וְכֵן הַדִּין \u0010g40\u0011 בִּמְגָרֵשׁ הַפִּקַּחַת, וְנִתְחָרְשָׁה, וְהֶחֱזִירָהּ, וּמֵת, וְהִיא חֵרֶשֶׁת; וּבֵין בָּזוֹ וּבֵין בָּזוֹ, \u0010c22\u0011 \u0010g41\u0011 צָרָתָהּ \u0010g42\u0011 מֻתֶּרֶת לְהִתְיַבֵּם:\nהֶחֱזִירָהּ כְּשֶׁהִיא קְטַנָּה אוֹ \u0010g43\u0011 חֵרֶשֶׁת, וְגָדְלָה וְנִתְפַּקְּחָה אֶצְלוֹ, וּמֵת, מֻתֶּרֶת לְהִתְיַבֵּם. וְאֵין צָרִיךְ לוֹמַר אִם הֶחֱזִירָהּ אַחַר שֶׁגָּדְלָה אוֹ נִתְפַּקְּחָה: \u0010g44\u0011",{"g":["משנה ריש יבמות","כ\"כ התוספות ריש יבמות סוף ע\"א מהא דיבמתו נדה בעל פטור פסחים דע\"ב דמשמע דקנה","משנה שם די\"ג ע\"א","כן הוא ברמב\"ם בפ\"ו וכן העתיקו הטור והקש' על זה דספק ערוה על בעלה חולצת או מתייבמת כמבואר לקמן בסעיף ה ובכ\"מ שם כ' שלפי נוסח זה צריך לדחות ולומר דהאי או ט\"ס הוא וצריך למחוק האלף ולכתוב וספק ערוה שהיא ספק ערוה על שניהם וכולי ובית חדש כ' שקאי אצרתה שחולצת ולא מתייבמת אם כבר נשא היבם הספק ערוה וכולי ולפע\"ד הוא ג\"כ דוחק שהרי לא נזכר שם צרתה והנכון לענ\"ד למחוק בבא זו דספק ערוה וכצ\"ל יבמה שהיא ספק ערוה על היבם וכן העתיק ה\"ה וכ\"כ הכ\"מ בפשיטות ט\"ס הוא וכמ\"ש הטור","כ' ה\"ה זה פשוט שספק ערוה ליבם חולצת ולא מתייבמת","ג\"כ פשוט והכל מתבאר בפ\"ד אחין (דכ\"ט ע\"א) ונלמד כיוצא בזה ממשנה שומרת יבם שקדש אחיו את אחותה וכו' שבפרק החולץ (דמ\"א ע\"א) ה\"ה","ג\"ז שם שאין אישות וקדושין בעריות כמ\"ש במשנ' אמרו לו מתה אשתך כולי שם (דנ\"ד ע\"ב) ה\"ה","כמ\"ש הטור ממ\"נ תתיבם שאם לא היתה עליו ערוה הרי היה זקוק' ליבום ואם הית' עליו ערו' לא תפסי לו בה קידושין והרי היא ליבם כאש' נכרית","טור ממשנה שם דף ל' ע\"ב","כצ\"ל וכן הוא ברמב\"ם ובטור","משנה שם ריש יבמות ע\"ב וכדמתרץ רבא שם דף י\"ג ע\"א דהך ממשנ' ג' אחים ב' מהם נשואים ב' אחיות וכו' שם דף ל' ע\"א זו ואצ\"ל זו קתני הסכמת הפוסקים","משנה שם בריש יבמות ע\"ב","משום דקידושי הקטנה אינה אלא מדרבנן וזיק' נפילת' מדרבנן אינה פוטרת צרתה","כדמפרש שם בגמ' דף י\"ג ע\"א משום דמשעת נפיל' נראי' כצרת בתו","משנה שם דף סז ע\"ב","משנ' ריש יבמות","כדאמר רבא הלכתא וכולי שם דף יב ע\"ב","רמב\"ם בפרק ז' וכ' ה\"ה שזה פשוט דכיון שהי' צרת ערוה הוי' לה אשת אח שלא במקום מצוה","משנה גיטין דף פ' ע\"א ומה ששנינו שם וכל הדרכי' האלו בה אוקימנ' כר\"ע דס\"ל דיש ממזר מחייבי לאוין ואנן קי\"ל כחכמים","ציינתיו לעיל","כמימרא דרב יהודא אמר רב וכולי יבמות דף יא ע\"א כ\"פ הרמב\"ם וכ\"נ מהא דרי\"ף וכ\"פ הרא\"ש","שם בגמרא ובמשנה ריש סוטה","\u0003בפרושיו מהא דא\"ר יוסף אלו אית' לבעל מי לא בעי' גיט' וכו'\u0004 שם דף ה' ע\"ב","משנה ריש יבמות","משנה שם דף יז ע\"א","כת\"ק דר\"ש שם דף יח ע\"ב","טור בשם אביו הרא\"ש שם בפסקיו וכרב יהודה אמר שמואל שם דף יח ע\"א אע\"ג דקיימא לן הלכת' כרב באיסורי בהא קי\"ל כשמואל דשקלי וטרי אמוראי בתראי אליבי' וכ\"כ ה\"ה ושכן קיימא לן ובשם הרשב\"א והב\"י בשם הרי\"ף בפ\"ד אחין דיש זיקה אף בלא מאמר ושכ\"נ מהרמב\"ם","כרבי ישמעאל בר\"י שכן היתה השאלה כשנתנו ת' זהובים לב' בני אדם ושלחו לר\"ע לבית האסורים וכו'","כצ\"ל ודין אחיו מאמו שהיא ערוה לו כבר נתבאר לעיל סעיף ז'","כמ\"ש הרא\"ש שם מטעם שכתבתי לעיל סעיף ז' בדין איסור דערוה כגון אשת אחיו מאמו או בתו וכו'","פי' נשואים הראשונים והיינו באין לה צרה דאם יש לה צרה חליצת הצרה שזיקה מן התור' פוטרת הקטנה מהחליצה שזיקתה מדרבנן ולא איפכא","משנה שם דף ק\"ז ע\"א וכב\"ה","כשמואל שם ע\"ב דמדמי לה לבעלת הגט לגבי ההוא דמיאנ' בי'","זה פשוט דאפילו נתן לזו לא נאסר' צרתה","שם וכשמואל וכ\"פ הרי\"ף והרא\"ש משום דקאי ר' יוחנן כוותי'","בריית' שם דף מא ע\"ב","דשמא הוי גירושין והרי היא גרושת אחיו שהוא בכרת","ממה נפשך וכולי ומתבאר בסוגיא שם","משנה שם דף קח ע\"ב וכת\"ק","שם במשנה וכמו שפירש\"י שם ריש דף קט","רמב\"ם בפ\"ז וכתב ה\"ה שזה פשוט לפי מ\"ש שנישואי החרשת שוין לנשואי הקטנה וכולן מדבריהם ויש סמך לזה מהירושלמי","בעיא שם בגדולה אליב' דר\"א ונפשט' והביאה הרי\"ף לומר דה\"ה בקטנה אליב' דרבנן ושכן הכריע הרמב\"ן וזה דעת הרשב\"א וה\"ה וכ\"כ הטור בשם אביו הרא\"ש","ברייתא שם","מדין הקטנה וכמו שכ' בסעיף דלעיל","דין אחות גרושתו שפוטרת היא וצרותיה מן החליצ' ומן הייבום בטור ס\"ס זה ממשנ' שם דף מא ע\"א"],"t":["\u0003חלוצתו. \u0004 צ\"ע כיון דאחות חלוצה מדרבנן למה אסר בס\"ס דרבנן ובפרק כיצד אמרו דספק חלוצה לא גזרו רבנן כנה\"ג וכ\"כ הב\"ח ופסק דלכתחלה אסור מיהו אם קדם וכנס אין מוציאין ע\"ש. והב\"ש חולק עליו ופסק דאפי' בדיעבד אם כנס מוציאין מידו ע\"ש:","\u0003ערוה. \u0004 בנ\"י הניח בצ\"ע אשת כהן שנאנסה אם צריכה חליצה וב\"ח תמה עליו הא אי' ביבמות דף נ\"ו ע\"ב אשת כהן שנאנסה בעלה לוקה עליה משום טומאה ע\"כ נשמע אף באונס טומאה כתיב בי' א\"כ פטורה מן החליצה כמו זנות ברצון עיי\"ש ועיין ביבמות דף י\"א ובסוטה ד' ה':","\u0003ויש להחמיר. \u0004 ובחליצת הסוטה לא נפטרה הצרה ב\"ש דלא כב\"ח ע\"ש:"],"r":["\u0003אבל אם כו'. \u0004 ג' א\"ב ח' א\"ג וש\"מ:","\u0003יבמה כו' \u0004 עבה\"ג וכ\"ה לקמן בס\"ה ותוספתא הובא ברי\"ף ורא\"ש פ' קמא:","\u0003ה\"ז חולצת כו' \u0004 לפיכך כו' צ\"ט א' ת\"ר יש כו':","\u0003ומוציא כו'. \u0004 כמ\"ש במתני' ק\"ט א' רי\"א אילו כו' ואמרינן שם ק\"י א\"ב קטנה קנויה כולי וקי\"ל כר' יהושע אם לא מיאנה הקטנה דלא כר\"ג:","\u0003היתה כו'. \u0004 יו\"ד א' ומתני' צ\"ו א' ופוטרת כו':","\u0003וזו כו'. \u0004 מתני' צ\"ד ב' ושניה מותרת בקרוביו:","\u0003היתה כו' \u0004 דהוי ספק קידושין וכמ\"ש מ\"א ב' הרמב\"ם בפ\"ו הלכה י\"ג שחולצת ולא מתייבמת ותמה הטור עליו וכ' בכ\"מ שהוא ט\"ס ועוד נדחק שם בכ\"מ וב\"י וב\"ח אבל הנכון כמ\"ש מש\"ל דמיירי שקידש אחת משתי אחיות וכמ\"ש ברי\"ף ורא\"ש ספ\"ק הספיקות כגון שקידש כו' וכ\"ה ברמב\"ם שם הלכה ד' ואלו חולצין ולא מייבמין הספיקות כגון שהיתה ספק ערוה על אחין והן דברי גמרא מ\"א ב':","\u0003ומיאנה בו כו'. \u0004 תוספתא פ\"א והביאם הרי\"ף ורא\"ש בפ\"ק מיאנו בחיי הבעל כו' ובגמ' י\"ב י\"ג א' ק\"ז ב' ושם בתוספתא אימתי אמרו שאם מתו והובא ברי\"ף ורא\"ש שם וז\"ש לעיל בחיי בעלה וכ\"ה במתני' מתה כו' ואח\"כ מת אחיו כו' ועס\"ח:","\u0003ואם ייבם כו'. \u0004 מתני' צ\"ב א':","\u0003נשאת כו'. \u0004 מתני' דגיטין וכמ\"ש בירושלמי שם ופ\"י דיבמות זו דברי ר\"מ משום ר\"ע וחכ\"א אין ממזר מיבמה הא לצאת תצא:","\u0003ואם מתחלה כו'. \u0004 יבמות צ\"ב ב' וכמש\"ל ר\"ס קנ\"ט:","\u0003מי שזינתה כו' \u0004 כפירש\"י שם וש\"פ וכמ\"ש שם מתיב ר\"א כו' ושם נ' ב' לרב ולר\"א ליתנינהו וכו' והקשה הראב\"ד מסוגיא דסוטה ה' ב' דאמרי' שם אילו איתיה כו' ועוד דאמר שם לאחר כו' והאי בסוטה ודאי כתיב וע\"תוס שם ד\"ה לאחר וד\"ה אילו שנדחקו בזה וכן הרא\"ש ביבמות אבל העיקר דסוגיא דיבמות פליגא על ההיא סוגיא כמ\"ש המ\"מ וס\"ל לרב ג\"כ הלימוד לאחר ולא ליבם ועל סוטה ודאי ואף מהחליצה פטורה כקושית אביי אלא דצרתה כמוה יליף מטומאה כתיב בעריות וזה שנא אמר סוטה פטורה ופוטרת וכמ\"ש הרמב\"ן ובהכי ניחא דלר\"י בן כופר דטומאה כתיב במחזיר גרושתו ואעפ\"כ אינה פטורה מהחליצה וקושית רב אשי מסוטה נמי על צרתה דל\"ק אלא היא עצמה אבל צרתה אף ביבום מותרת וז\"ש ומ\"ש סוטה ודאי כו' ולא פריך שתהא פטורה מחליצה כיון דלא כ' לאחר עלה וכמ\"ש רש\"י שם בד\"ה ביארה כו' ואפילו רבנן ל\"פ כו' דהקושיא לא קאי אלא על שצרתה מותרת להתייבם וז\"ש הרמב\"ם וש\"ע וצרתה או כו':","\u0003וי\"א כו'. \u0004 כמ\"ש בריש סוטה לאחר ולא ליבם והאי בסוטה ודאי כתיבה ושם אלו איתא לבעל כו' אלמא דכל שצריכה גט צריכה חליצה וה\"ה לסוטה ודאי ופליגא על סוגיא דיבמות ואזלינן לחומרא רמב\"ן ורשב\"א וע\"ש ושם וברא\"ש שנדחקו בזה ודברי רא\"ש קשין להולמם ודברי הראב\"ד נבונים ומוכרחים וי\"א כו' מסוגיא דסוטה הנ\"ל וסוגיא דיבמות ג' ב' למעוטי דר' ודר\"א לר' ולר\"א כו' מ' דאין הל' כוותייהו:","\u0003וה\"ה לצרתה וכן בסוטה ספק כמ\"ש הרא\"ש דלהראב\"ד אין חילוק בין סוטה ודאי לסוטה ספק:\u0004 ","\u0003אע\"ג דודאי כו'. \u0004 כמש\"ל סימן ס\"א בהג\"ה ואע\"ג דברמב\"ם וש\"ע כ' בעדים ל\"ד ה\"ה כל דבר ברור כמ\"ש בכתובות ט' א' ופתח פתוח כו':","\u0003אשה שהלך כו'. \u0004 רש\"י הנ\"ל וכ\"ש לדברי הרמב\"ם הנ\"ל דאף בספק סוטה דאורייתא מתיבמת צרתה אע\"ג דאסורה מדאורייתא:","\u0003אפילו קודם כו'. \u0004 י\"ח ח' מתיב כו' טעמא כו' ה\"ה כו':","\u0003דקי\"ל כו'. \u0004 עבה\"ג ועוד דר' יוחנן ס\"ל כוותיה ופליג ארב כ\"ז ב' וע\"תוס שם ד\"ה אבל ב' וד\"ה איתיביה כו' אבל ר\"י סבר דע\"כ כו' וכן רב אשי דבתראה הוא ס\"ל כוותיה שם למ\"ד א' וכן רבא שם ב' ואמר ג\"כ ה\"ה אע\"ג כו':","\u0003קטנה כו' \u0004 עבה\"ג וכ\"ש לרב שם והרמב\"ם השמיטו לפי דקי\"ל כרב:","\u0003שאף היא חולצת כו'. \u0004 אין לו שחר שאף בלא מיאון חולצת ולכאורה י\"ל שבא להשמיענו שפוטרת צרתה בחליצתה וכשיטת הטור דשניה פוטר' צרה אבל מאי קאמר אם תמאן שהוא שוה בין במיאון בין בלא מיאון וז\"ל הטור קטנה שהיתה נשואה לאחיו מאמו או לאחי אמו ומת ונשאה כו' שתתייבם אלא צרתה חולצת ולא מתייבמת ונראה שאף היא חולצת אם תמאן ואאחיו מאמו קאי דבלא מיאון פטורה שאף שמ\"מ אינה ערוה רק מדרבנן מ\"מ לא עדיף נישואי אחיו מאמו ועתו\"ס שם ד\"ה יש כו' אבל באיסור ערוה כו' ודלא כב\"ח שכ' דגי' תוספ' הנ\"ל היתה ותתייבם צרתה דלא כגי' רש\"י ורי\"ף ורא\"ש ושגה בזה גם רש\"ל מחק תיבת צרתה מגמ' אבל הרשב\"א השיג עליו וקיים הגי' וכ' שהפירש הוא שתמאן בנשואין של אחיו מאביו ודחק עצמו מ\"ש ותעקרינהו לנשואי קמאי היינו נשואי אחיו מאביו כ' ושכ\"ה דברי הטור שכ' וצרתה כו' ושגה בזה הרבה דא\"כ ל\"ל כל האריכות הרי שהיתה כו' הל\"ל שניה סתם את אמו וכיוצא הרבה ועוד דאינו ענין לדברי ר\"י א\"ר דכל הסוגיא קאי על נשואין הראשונים וגם מ\"ש שהטור ס\"ל כן שגה דהא הטור כ' ונראה שאף היא חולצת אם תמאן וכ' בהדיא כדי שתתייבם ועוד שכ' בערוה ג\"כ וזה מותר שכבר כ' דין הערוה בריש הסימן אבל אם לא מיאנה בחייו כו' וז\"ש וצרת חולצת שהיא פטורה כמ\"ש למעלה ומלבד זה שגה הרבה דהא קי\"ל דצרה שני' מתייבמת כמ\"ש בירוש' וכמש\"ל סי' קע\"ד ס\"א בטוש\"ע ומזה מוכח שצריך להגיה בש\"ע נשואה לאחיו מאמו כדברי הטור וע\"ז קא' ג\"כ שאף הי' חולצת אם תמאן כדברי הטור וע\"ז אמר ג\"כ וצרתה חולצת דהלא פטורה לשיטתו כנ\"ל וה\"פ א\"י למאן לעקור כו' דאינה מועלת כלום והדין הוא בלא מיאון שצרתה חולצת כו' שאף היא חולצת אם תמאן:","\u0003ומותרת לזר כו'. \u0004 דלא כר' אושעיא שם אלא כעולא שם דרמי בר יחזקאל ס\"ל כוותיה וכן רב ושמואל ור\"י דפליגי מיאנה בזה כו'. הרא\"ש שם:","\u0003אבל צרתה כולי. \u0004 כר' יוחנן שם י\"ב ב':","\u0003מותרת לו וכו' \u0004 ואסור לזר:","\u0003ואפילו היא כו' \u0004 כשמואל דר' יוחנן שם ס\"ל כוותיה:","\u0003ספק כו' \u0004 תוספת שם ד\"ה אלימא בספק כו' וכמ\"ש בתוספתא י\"ב זה הכלל כל הספיקות ביבמה חולצין ולא מייבמין:","\u0003וכן הדין כו' \u0004 ובין כו' ירושלמי שם מודים חכמים לר\"א בקטנה שהשיאה אביה כו' והביאה הרא\"ש שם וסיים בירושלמי א\"ר אבא בר ממל מסתברא כמ\"ד צרתה מותרת ברם כמ\"ד צרתה אסורה אסורה ממה נפשך צד שקנה בה כנגדו מותר בצרה צד שלא קנה בה כנגדו התיר בצרה א\"ר שמאי וכי יש ממ\"נ בעריות מאי כדין כל יבמה שאינה כולה לחוץ צד הקנוי שבה ידין משום ערוה וערוה פוטרת צרתה וכ' הרמב\"ן במלחמות והרשב\"א הנה רבו המתירין ועוד שאף האוסרין לא אסרו וכו' אלא וכו' משום וכולי דהיא כקנויה ומשוירת אבל לדידן דקיי\"ל שהיא קנוייה ואינה קנויה אף ר' שמאי מודה דיש מ\"נ בעריות וכו' ומותרת. והנה משם למד הרמב\"ם לחרשת כי היכי דס\"ל להירו' בקטנה דקנויה ומשויירת כן קיי\"ל בחרשת אלא דלהאוסר ה\"ל לאסור בצרת חרשת אלא שפ' כהמתירין וכסברת הראשונה שכתב וזה שדייק ובין בזו כולי וכ\"ה ברמב\"ם:"]}],["יְבָמָה שֶׁהִיא אֲסוּרָה לַיָּבָם, בְּלָאו אוֹ בַּעֲשֵׂה אוֹ בְּאִסוּר שְׁנִיּוֹת דְּרַבָּנָן, הִיא \u0010c0\u0011 חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת \u0010c1\u0011 אוֹ מִתְיַבֶּמֶת; וְאֵין חֲלִיצָתָהּ פּוֹטֶרֶת צָרָתָהּ, אֲבָל חֲלִיצַת צָרָתָהּ פּוֹטֶרֶת אוֹתָהּ. וְאִם עָבַר וּבָא עָלֶיהָ, \u0010c2\u0011 קְנָאָהּ, וְנִפְטֶרֶת צָרָתָהּ. וְאִם רָצָה לְהוֹצִיאָהּ, מוֹצִיאָהּ בְּגֵט:\nהָיְתָה אֲסוּרָה לְבַעְלָהּ בְּאִסוּר לָאו אוֹ עֲשֵׂה אוֹ אִסוּר דְּרַבָּנָן, וּמֻתֶּרֶת לְיָבָם, יְכוֹלָה לְהִתְיַבֵּם; חוּץ מִמַּחֲזִיר גְּרוּשָׁתוֹ מִשֶּׁנִּשֵּׂאת, וּמֵת, \u0010c3\u0011 שֶׁהִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:\nאֲחוֹת חֲלוּצָה, אֲסוּרָה מִדְּרַבָּנָן. לְפִיכָךְ, נָפְלָה לִפְנֵי יָבָם, חוֹלֶצֶת \u0010c4\u0011 וְלֹא מִתְיַבֶּמֶת. וְכֵן צָרָתָהּ אֲסוּרָה מִדְּרַבָּנָן, וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nמִי שֶׁיֵּשׁ עָלֶיהָ \u0010c5\u0011 זִקַּת שְׁנֵי יְבָמִים, \u0010c6\u0011 הִיא אוֹ צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. כֵּיצַד, שְׁלשָׁה אַחִים נְשׂוּאִים שְׁלשָׁה נָכְרִיּוֹת, וּמֵת אֶחָד מֵהֶם וְעָשָׂה בָּהּ אֶחָד מֵהַנִּשְׁאָרִים מַאֲמָר בִּיבִמְתּוֹ, וּמֵת קֹדֶם שֶׁכָּנְסָהּ, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nנָתַן לָהּ גֵּט, וּפֵרַשׁ שֶׁהוּא לְמַאֲמָרוֹ, הֲרֵי בָּטֵל הַמַּאֲמָר שֶׁעָשָׂה, וְאֵין עָלֶיהָ אֶלָּא זִקַּת יָבָם אֶחָד, וּמִתְיַבֶּמֶת. אֲבָל אִם נָתַן לָהּ הַגֵּט סְתָם, אֲסוּרָה לְהִתְיַבֵּם:\nקָטָן שֶׁבָּא עַל יְבִמְתּוֹ, וּמֵת, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת; שֶׁאֵין בִּיאָתוֹ קוֹנָה קִנְיָן גָּמוּר, וְיֵשׁ עָלֶיהָ זִקַּת שְׁנֵי יְבָמִים:\nמִי שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין שֶׁנִּתְקַדְּשָׁה לִרְאוּבֵן, וְנִשְׁתַּחְרְרָה, וְקִדְּשָׁהּ שִׁמְעוֹן אָחִיו, וּמֵתוּ שְׁנֵיהֶם, וְנָפְלָה לִפְנֵי לֵוִי אֲחִיהֶם, מִתְיַבֶּמֶת לוֹ, שֶׁאֵינָהּ אֵשֶׁת שְׁנֵי מֵתִים; שֶׁאִם קִדּוּשֵׁי רְאוּבֵן קִדּוּשִׁין אֵין קִדּוּשֵׁי שִׁמְעוֹן כְּלוּם; וְאִם קִדּוּשֵׁי שִׁמְעוֹן קִדּוּשִׁין, אֵין קִדּוּשֵׁי רְאוּבֵן כְּלוּם:",[],["\u0003חולצת ולא מתייבמ'\u0004. עיין בסוגיא דף ך' מדאוריית' חזיא ליבום דקי\"ל עשה דיבום דוחה ל\"ת של הלאו לכן אם בא עליה פוטרת את צרתה אלא חז\"ל גזרו ביאה הראשונ' אטו ביאה שניה שאין מצות יבום אלא בביאה הראשונ' וכתבו תוס' ל\"ד אלא אפילו גמר הביאה נמי אסור כי היבמה נקנית בתחלת הביא' וכתבו תוס' שם מדביאה הראשונ' מותרת ביבם אפילו מן הארוסין אף על גב דקי\"ל אין אשה מתעבר' מביאה ראשונ' ש\"מ דלא בעינן שתהי' ראוי' להקמת שם אלא כשהם ראוים להקמת שם לאפוקי איילונית וסריס, מכאן נראה ה\"ה אם רוצה רק לבעול פ\"א ולגרש אותה מיד ג\"כ מותר, ומה קשה מכאן למ\"ש בסי' ק\"ע כתבתי שם וע\"ש ואם היא אלמנה מן הנשואין ובא עלי' כ\"ג לא נפטרה צרתה דאין עשה דוחה את ל\"ת ועשה של אלמנה לכ\"ג שם ורמב\"ם שם:","\u0003או מתייבמו'\u0004. כ\"כ הטור והנ\"י והש\"ג שאין צרתה פטורה אלא מערוה שהיא חייבי כריתות או ח\"מ כדנפקא לן מאחות אשה דכתב בה לצרור וכן הוא בירושלמי:","\u0003קנאה ונפטרת צרתה\u0004. כמ\"ש בס\"ק א' הטעם, ולכאור' תימא ע\"פ סוגיא שם משום דעשה דוחה ל\"ת מ\"ה חזי' לביאה וקונה אותה בביאה ונפטרה צרתה ונדחה שם תירוץ של רבא דאמר דלא דחי' עשה את ל\"ת מאחר דיכול לקיים שניהם העשה ואת ל\"ת וליתן חליצה ונדחה שם מטעם דקיי\"ל חליצה במקום יבום לאו מצוה היא, א\"כ להני פוסקים דפסקו מצות חליצה קודם כמ\"ש בסימן קס\"ה א\"כ אין העשה דוחה את הל\"ת כמימרא דרבא דהא מצות חליצה יותר מצוה א\"כ תירוץ של רבא עיקר לפ\"ז לא דחי' את הל\"ת ולא נפטרה הצרה דלא קיימא לביאה כקושי' הש\"ס שם, וצ\"ל מצות חליצה קודם דרבנן אבל מדאורייתא מצות יבום לכ\"ע קודם ודחי' את הל\"ת וכן הוא בנ\"י כמה שהבאתי לעיל, אלא צריך ישוב הש\"ס דף ל\"ט דמשמע דפליגי אם איכא א\"ד דהא חכמים דפליגי על אבא שאול למדו מקרא יבמה יבא עליה ואם א\"ש מדרבנן קאמר איך מייתו רבנן קרא מדאורייתא, וי\"ל רבנן ס\"ל אפי' אם נושא לשם דבר אחר ליכא איסור דאורייתא מ\"ה אם נושא סתם וא\"י אם נושא לשם ד\"א לא גזרי' דרבנן לכן הביאו קרא יבמה יבא עליה כלו' כיון דאורייתא ליכא איסור לא גזרי חז\"ל בנושא סתם, ואבא שאול ס\"ל אם נושא לשם ד\"א איכא א\"ד מ\"ה ס\"ל אם נושא סתם אסור והא דקאמר מח\"ק היינו כיון דמח\"ק מ\"ה גזרו חז\"ל אם א\"י אם נושא לשם ד\"א דאל ישא אותה כנ\"ל למ\"ש הנ\"י עוד מוכח בסוגיא זו כל שאינה עולה ליבום מדאורייתא אינה פוטרת את צרתה בביא' שלה וגם אתה עצמה אינה פוטרת בביאה זו דהא הקשה שם מבריי' אם בא עליה הפצוע קנאה ושם לא איירי דיש לה צרה ולכאור' קשה למה כתב הרמב\"ם פ\"ו אם בא על אלמנה מן נשואין לא נפטרה הצרה ת\"ל היא עצמה ג\"כ אינה פטורה ויש ליישב:","\u0003שהיא חולצת ולא מתייבמ'\u0004. וכתב המגיד אם נפלה לפניו מחזיר גרושתו וצרת' נפטר' הצרה בחליצה של זו ולא בביאת' ומדמה דין של זו לאלמנ' לכ\"ג והב\"י והכ\"מ הקשו עליו איך מדמ' אלמנ' לכ\"ג בשלמ' אלמנ' לכ\"ג איכא עשה ול\"ת אבל מ\"ג ליכא אלא לאו עוד הקשה למה הצרה נפטרה בחליצה של זו דהא בעלמא ס\"ל להרמב\"ם כשהיא מחייבי לאוין לא נפטרה הצרה בחליצה של זו, ונראה לי דכוונת המגיד הוא משום מ\"ג אסורה ליבם מק\"ו אם היא אסור' לבעלה שמותר לה להיבם שאסור לה לא כ\"ש ופרש\"י ריש סוטה דף ו' אם נאסרה למותר מחמת הנישואים של אחר מכ\"ש שנאסרה להיבם דאל יתייבם אותה לפ\"ז היא גרוע טפי מחייבי לאוין דקי\"ל מדאורייתא חזיא לביאה אלא רבנן גזרו ביאה הראשונ' אטו ביאה שני' וזו מדאורייתא לא חזיא משום דילפינן מק\"ו שאל יתייבם אותה אבל חייבי לאוין לא כתיב הלאו ביבום ומדאורייתא הוי לן למימר דאתי עשה דיבום ודחה הלאו, אבל מ\"ג מק\"ו ילפינן דאסורה ליבום א\"כ מדאורייתא אסורה ליבום תו ליכא למימר דעשה דוחה הלאו א\"כ הק\"ו למאי אתי דהא ליבם אסורה אם לא במקום מצוה ואתי הק\"ו דאסורה במקום מצוה מ\"ה דמי' לאלמנ' לכ\"ג דהיא ג\"כ מדאורייתא לא חזי' ליבם משום דאיכא עשה ול\"ת ואתי' מדרב גידל דצריכ' חליצה מדכתב ועלתה יבמתו השערה כן הוא במ\"ג דלא חזי ליבום וצריכה חליצה מ\"ה נפטרה הצרה משום דהתור' כתב בפירוש דעלתה לחליצ' וכן אלמנה לכ\"ג נפטרה הצרה, ולא כט\"ז שהאריך להקשות על המגיד והבין דמ\"ג לא גרע מחייבי לאוין וחזי' מדאורייתא ליבום אלא חז\"ל גזרו ביאה הראשונה אטו ביאה שניה וליתא אלא הק\"ו אתי' דלא חזי' לביאה וכל הסוגיא ושקל' וטרי' של ר' יוחנן במ\"ג א\"צ לומר הטעם דגזרינן ביאה הראשונה אטו ביאה שניה אלא מק\"ו ילפינן דלא חזי' לביאה, ועיין ב\"ח כתב ג\"כ הא דנפטרה הצרה מחליצה של זו משום דאתי' מקרא ועלתה יבמתו השערה מיהו מתוס' דף כ\"ו לא משמע כן דהא הקשו על פירש\"י שם דחליצה פסולה היא כל שא\"י לייבם למה חליצת מחזיר גרושתו פוטרת את צרתה ש\"מ דלא ס\"ל הסברא מדרבתה התורה לחליצה פוטרת את צרתה, מיהו לדינא לא נ\"מ וי\"ל לכ\"ע פוטרת את צרתה מדתירץ שם דף י\"א מחזיר גרושתו וצרתה או היא או צרתה חולצת ש\"מ דצרתה נפטר' בחליצה של זו דהא אף קודם שעלתה המסקנא דצרתה ראויה ליבם מ\"מ חליצת מ\"ג גרוע עכ\"פ מחליצ' צרתה אף על פי דצרה ג\"כ אסורה להיבם ותני' דנפטר' בחליצה של זו נראה לסברת המגיד נפטרה מטעם דרבתה התורה לחליצה כמ\"ש ולתוס' הטעם כיון דלא קלשה הזיק' כמ\"ש בסי' ק\"ע:","\u0003ולא מתייבמ'\u0004. אף על גב צרות חייבי לאוין מתייבמו' וזו אסורה רק מדרבנן ולא מתייבמת משום דשוי' חז\"ל חלוצה כגרוש' ואחותה שהיא ערוה והוי צרת ערוה ועיין תוס' שם דף מ\"א, וכתב הב\"י ה\"ה צרת חלוצתו מד\"ס ולכאורה אין הבנה לזה, וצ\"ל דאיירי שאחיו נשא החליצה באיסור ואסור' ג\"כ מטעם הנ\"ל שכתבו תוספות דעשאו חז\"ל כאלו נשא גרושת אחיו באיסור ואסרו הצרות גם י\"ל לדעת הרמב\"ם קאמר ועיין סי' קס\"ב, ולכאור' נרא' אם עבר ונשא חלוצה ונפל' לפני זה צריכ' היא עוד השתא חליצה מזה מחמת נישואין את זה דהא קדושין של זה תפסי בה:","\u0003זיקת שני יבמי'\u0004. עיין בתוספת וברמב\"ם כל זה אינו אלא מדרבנן ולאו דרשה גמור' היא אלא אסמכתא:","\u0003והיא וצרתה חולצת\u0004. כצ\"ל ומ\"ש בש\"ע או צרתה ט\"ס הוא והטעם מבואר בש\"ס דאם מייבם לתרוויי' אמרו ב' יבמות הבאים מבית א' מתייבמות ואם מייבם אחת ויחלוץ לאחת חיישינן שמא יחלוץ ברישא והדר מייבם לכן דוקא אם עשה מאמר בא' אז אסורות שתיהן ליבם אבל אם לא עשה מאמר אינם אסורות משום צרת זיקות שני יבמים כיון דזיקת ב' יבמי' רק מדרבנן לא אסרי' מחמת זיקה כ\"כ רש\"י דף ל' ועיין פריש':"],"\u0010g0\u0011 יְבָמָה שֶׁהִיא אֲסוּרָה לַיָּבָם, בְּלָאו \u0010r0\u0011 אוֹ בַּעֲשֵׂה אוֹ בְּאִסוּר שְׁנִיּוֹת \u0010t0\u0011 דְּרַבָּנָן, הִיא \u0010c0\u0011 חוֹלֶצֶת וְלֹא \u0010g1\u0011 \u0010r1\u0011 מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת \u0010c1\u0011 אוֹ \u0010g2\u0011 \u0010r2\u0011 מִתְיַבֶּמֶת; וְאֵין חֲלִיצָתָהּ פּוֹטֶרֶת צָרָתָהּ, אֲבָל חֲלִיצַת צָרָתָהּ פּוֹטֶרֶת אוֹתָהּ. \u0010g3\u0011 וְאִם עָבַר וּבָא עָלֶיהָ, \u0010c2\u0011 קְנָאָהּ, \u0010r3\u0011 וְנִפְטֶרֶת צָרָתָהּ. \u0010g4\u0011 וְאִם רָצָה לְהוֹצִיאָהּ, \u0010r4\u0011 מוֹצִיאָהּ בְּגֵט: \u0010g5\u0011\nהָיְתָה אֲסוּרָה לְבַעְלָהּ בְּאִסוּר לָאו אוֹ עֲשֵׂה אוֹ אִסוּר דְּרַבָּנָן, וּמֻתֶּרֶת לְיָבָם, יְכוֹלָה \u0010g6\u0011 לְהִתְיַבֵּם; חוּץ מִמַּחֲזִיר גְּרוּשָׁתוֹ מִשֶּׁנִּשֵּׂאת, וּמֵת, \u0010c3\u0011 \u0010r5\u0011 שֶׁהִיא \u0010g7\u0011 חוֹלֶצֶת וְלֹא \u0010r6\u0011 מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת אוֹ \u0010g8\u0011 מִתְיַבֶּמֶת:\nאֲחוֹת חֲלוּצָה, אֲסוּרָה מִדְּרַבָּנָן. לְפִיכָךְ, נָפְלָה לִפְנֵי יָבָם, חוֹלֶצֶת \u0010c4\u0011 \u0010g9\u0011 וְלֹא \u0010r7\u0011 מִתְיַבֶּמֶת. וְכֵן \u0010g10\u0011 צָרָתָהּ אֲסוּרָה מִדְּרַבָּנָן, וְחוֹלֶצֶת וְלֹא \u0010g11\u0011 מִתְיַבֶּמֶת:\nמִי \u0010t1\u0011 שֶׁיֵּשׁ עָלֶיהָ \u0010c5\u0011 זִקַּת שְׁנֵי יְבָמִים, \u0010c6\u0011 הִיא אוֹ צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. כֵּיצַד, שְׁלשָׁה אַחִים נְשׂוּאִים \u0010g12\u0011 שְׁלשָׁה נָכְרִיּוֹת, וּמֵת אֶחָד מֵהֶם וְעָשָׂה בָּהּ אֶחָד מֵהַנִּשְׁאָרִים מַאֲמָר בִּיבִמְתּוֹ, וּמֵת קֹדֶם שֶׁכָּנְסָהּ, חוֹלֶצֶת וְלֹא \u0010g13\u0011 מִתְיַבֶּמֶת:\nנָתַן לָהּ גֵּט, וּפֵרַשׁ שֶׁהוּא לְמַאֲמָרוֹ, הֲרֵי בָּטֵל הַמַּאֲמָר שֶׁעָשָׂה, וְאֵין עָלֶיהָ אֶלָּא זִקַּת יָבָם אֶחָד, \u0010g14\u0011 \u0010r8\u0011 וּמִתְיַבֶּמֶת. אֲבָל אִם נָתַן לָהּ הַגֵּט סְתָם, אֲסוּרָה \u0010g15\u0011 לְהִתְיַבֵּם:\nקָטָן שֶׁבָּא עַל יְבִמְתּוֹ, וּמֵת, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת; שֶׁאֵין בִּיאָתוֹ קוֹנָה קִנְיָן גָּמוּר, \u0010g16\u0011 וְיֵשׁ עָלֶיהָ זִקַּת שְׁנֵי יְבָמִים: \u0010g17\u0011\nמִי שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין שֶׁנִּתְקַדְּשָׁה לִרְאוּבֵן, וְנִשְׁתַּחְרְרָה, וְקִדְּשָׁהּ שִׁמְעוֹן אָחִיו, וּמֵתוּ שְׁנֵיהֶם, וְנָפְלָה לִפְנֵי לֵוִי אֲחִיהֶם, מִתְיַבֶּמֶת לוֹ, שֶׁאֵינָהּ אֵשֶׁת שְׁנֵי מֵתִים; שֶׁאִם קִדּוּשֵׁי רְאוּבֵן קִדּוּשִׁין אֵין קִדּוּשֵׁי שִׁמְעוֹן כְּלוּם; וְאִם קִדּוּשֵׁי שִׁמְעוֹן קִדּוּשִׁין, אֵין קִדּוּשֵׁי רְאוּבֵן כְּלוּם:",{"g":["משנ' יבמות דף ב' ע\"א וכטעמ' דרב במסקנא שם ע\"ב","טור וכ\"כ הנ\"י אמתני' ושכן אית' בירושלמי","נתבאר במ\"ש בסימן קט סעיף י\"ז","\u0003בריית' פצוע דכא וכו'\u0004 שם","ברמב\"ם פ\"ז ובטור אית' ומוציאה בגט וכן הוא בבריית' שם ואסור לקיימ' ולענ\"ד צריך להגיה כאן ומוציאה בגטה","משנה שם ד' פ\"ד ע\"א","בריי' שם דף יא ע\"ב ותירוצא בתרא הסכמת הפוסקים וכן הוא בברייתא שם ואסור לקיימא ולענ\"ד צריך להגי' התוספת'","וצרתה נפטרת בחליצ' זו אבל לא בביאת' אם עבר ובא עלי' ושכ\"כ הרשב\"א מההוא דרב גידל שם דף כ' ע\"א ה\"ה","\u0003מימרא דר\"ל כאן שנה רבי וכו'\u0004 שם ד' מא ע\"א","משנה שם","טור ממשנה ואסור בקרובת חליצתו שם דף מ' ע\"ב","משנ' שם דף לב ע\"ב ומדרבנן כדמפרש שם בגמ'","פי' נשים שאינן קרובות באיסור ערוה","מימרא דרבה שם ריש דף לב וכלישנ' בתר' הרא\"ש והרמב\"ם בפרק ז","טור שכן מוכח שם בגמ' מהא דרב' שם דף נב ע\"ב וכ\"כ הרא\"ש שם והכי דייק' לישנא דהרמב\"ם שם","משנה שם דף צ\"ו ע\"ב","מימרא דרבא שם","מימרא דרב חסדא גיטין דף מג ע\"א"],"t":["\u0003דרבנן. \u0004 קטלנית או מייבמת ע\"ל סי' מ' מש\"ש:","\u0003שיש עליה זיקת ב' יבמים היא וצרתה חולצות ולא מתייבמות. \u0004 כצ\"ל:"],"r":["\u0003או בעשה. \u0004 מטעמא דאמר שם בח\"ל משום ביאה שניה:","\u0003וצרתה כו'. \u0004 תוספתא פ\"א בד\"א באשה שאין לו בה קידושין אבל באשה שיש לו בה קידושין צרותיהן חולצות או מתייבמות:","\u0003ואין כו'. \u0004 הוא דעת הרמב\"ם אבל הפוסקים חולקין עליו וכמש\"ל סימן ק\"מ ס\"ה בהג\"ה ושי\"ח:","\u0003ונפטרה צרתה. \u0004 שם בגמ' ושם איתמר ביאת כו' תוספתא פ\"י פצוע דכא כו' אם בעלו קנו ופטרו את הצרות:","\u0003מוציא' בגט. \u0004 רש\"י שם ד\"ה ואם בעלו כו':","\u0003שהיא חולצת כן איפשיט שם מהברייתא היא וצרתה חולצת כו':\u0004 ","\u0003וצרתה כו'. \u0004 עבה\"ג והסוגיא ג\"כ דכ\"מ כא\"ד ולא איבעיא לן בצרה אליבא דרבנן כלל וכן לרנב\"י אליבא דר\"י:","\u0003וכן כו' \u0004 וחולצת כו'. במקום מצוה כפירש תוספת שם מ\"א א' ד\"ה הך כו':","\u0003אבל אם כו'. \u0004 רש\"י שם וכ\"מ נ\"ב ב' דקאמר ותיפשוט כו':"]}],["יְבָמָה שֶׁאֵינָהּ רְאוּיָה לְהִתְיַבֵּם בִּשְׁעַת נְפִילָה, מִשּׁוּם אִסוּר עֶרְוָה, אֲסוּרָה עוֹלָמִית, אֲפִלּוּ אִם יִפְקַע הָאִסוּר. כְּגוֹן שְׁנֵי אַחִים שֶׁנְּשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי הַשֵּׁנִי שֶׁנָּשׂוּי אֲחוֹתָהּ, אֲפִלּוּ אִם תָּמוּת אִשְׁתּוֹ אַחַר כָּךְ, שֶׁפָּקַע אִסוּר אֲחוֹת אִשָּׁה, אֲפִלּוּ הָכִי אֲסוּרָה. וַאֲפִלּוּ נָפְלָה לְפָנָיו פַּעַם אַחֶרֶת אַחֲרֵי מוֹת אִשְׁתּוֹ, כְּגוֹן שֶׁהָיָה לָהֶם אָח שְׁלִישִׁי שֶׁלֹּא הָיְתָה עֶרְוָה עָלָיו, וּכְּנָסָהּ, וּמֵתָה אִשְׁתּוֹ שֶׁל זֶה שֶׁהָיָה נָשׂוּי אֲחוֹתָהּ, וּמֵת הַשְּׁלִישִׁי שֶׁכְּנָסָהּ, וְחָזַר וְנָפְלָה לְפָנָיו, אֲסוּרָה לוֹ. \u0010c0\u0011 לָא שְׁנָא מֵתָה אִשְׁתּוֹ קֹדֶם שֶׁכָּנַס הַשְּׁלִישִׁי, לֹא שְׁנָא מֵתָה אַחַר שֶׁכָּנַס, אַף עַל פִּי שֶׁלֹּא הָיְתָה אֲסוּרָה עָלָיו בִּשְׁעַת נְפִילָה אַחֲרוֹנָה, אֲפִלּוּ הָכִי אֲסוּרָה לוֹ הִיא וְצָרָתָהּ, כְּגוֹן שֶׁהָיָה אִשָּׁה אַחֶרֶת לָאָח הַשְּׁלִישִׁי, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה לוֹ בִּשְׁעַת נְפִילָה רִאשׁוֹנָה. אֲבָל אִם הָיְתָה מֻתֶּרֶת לוֹ בִּשְׁעַת נְפִילָה, אֲפִלּוּ אִם תֵּאָסֵר אַחַר כָּךְ, אִם פָּקַע הָאִסוּר, חוֹזֶרֶת לְהֶתֵּרָהּ. כֵּיצַד, שְׁלשָׁה אַחִים שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנִזְקְקָה אִשְׁתּוֹ לַשְּׁלִישִׁי שֶׁאֵינוֹ נָשׂוּי אֲחוֹתָהּ, וְלֹא הִסְפִּיק לְכָנְסָהּ עַד שֶׁמֵּת הָאָח הַשֵּׁנִי שֶׁהָיָה נָשׂוּי הָאַחֶרֶת, וַהֲרֵי שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, מֵתָה הָאַחֲרוֹנָה, חָזְרָה הָרִאשׁוֹנָה לְהֶתֵּרָהּ, כֵּיוָן שֶׁהָיְתָה מֻתֶּרֶת בִּשְׁעַת נְפִילָה, אַף עַל פִּי שֶׁנֶּאֶסְרָה בֵּינְתַיִם. אֲבָל אִם מֵתָה הָרִאשׁוֹנָה, לֹא הֻתְּרָה הָאַחֲרוֹנָה, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה בִּשְׁעַת נְפִילָה. וְכֵן אִם הָיוּ שָׁם עוֹד אַחִים, וְקָדַם אֶחָד מֵהֶם \u0010c1\u0011 וְחָלַץ לָאַחֲרוֹנָה, אוֹ שֶׁהָיְתָה הָרִאשׁוֹנָה אֲסוּרָה לְאֶחָד מֵהָאַחִים, וְיִבֵּם אֶת הָאַחֲרוֹנָה, שֶׁהֲרֵי מֻתֶּרֶת לוֹ, \u0010c2\u0011 הֻתְּרָה הָרִאשׁוֹנָה לִשְׁאָר אַחִים, שֶׁהֲרֵי הָאַחֲרוֹנָה שֶׁאָסְרָה אוֹתָהּ, חָלְצָה אוֹ נִתְיַבְּמָהּ לַמֻּתָּר לָהּ. אֲבָל אִם הָאַחֲרוֹנָה אֲסוּרָה לְאֶחָד מֵהֶם מִשּׁוּם עֶרְוָה, הֲרֵי הוּא מֻתָּר לְיַבֵּם הָרִאשׁוֹנָה, וּשְׁאָר הָאַחִים אֲסוּרִים בִּשְׁתֵּיהֶן, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת:\nשְׁנַיִם מֵהָאַחִים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ שְׁנֵיהֶם, \u0010c3\u0011 וְלֹא נוֹדַע אֵיזֶה מֵהֶם מֵת רִאשׁוֹן, הוֹאִיל וְאִי אֶפְשָׁר לְיַבֵּם שְׁתֵּיהֶן, וַהֲרֵי זִקָּה נָפְלָה עַל שְׁתֵּיהֶן, חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. וַאֲפִלּוּ הָיְתָה אַחַת מֵהֶם אֲסוּרָה עַל הַיָּבָם מִשּׁוּם שְׁנִיָּה אוֹ מֵחַיָּבֵי עֲשֵׂה אוֹ מֵחַיָּבֵי לָאוִין, הֲרֵי אֵלּוּ חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. אֲבָל אִם הָיְתָה אַחַת מֵהֶם עֶרְוָה עָלָיו, הֲרֵי אֲחוֹתָהּ מֻתֶּרֶת לוֹ, רָצָה חוֹלֵץ רָצָה מְיַבֵּם, שֶׁהֲרֵי לֹא נָפְלָה זִקָּתוֹ עַל שְׁתֵּיהֶן, שֶׁאֵין זִקָּה עַל הֶעֶרְוָה:\nאַרְבַּע אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ הַנְּשׂוּאִים אֶת הָאֲחָיוֹת, אוֹ בָּזֶה אַחַר זֶה, קֹדֶם שֶׁהִסְפִּיקוּ לְיַבֵּם לָרִאשׁוֹנָה, שְׁתֵּיהֶן חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת, שֶׁאִי אֶפְשָׁר לְשׁוּם אַחַת מֵהֶן לְהִתְיַבֵּם, מִשּׁוּם אִסוּר אֲחוֹת זְקוּקָה. וְאִם קָדְמוּ וְכָנְסוּ כָּל אֶחָד אַחַת מֵהָאֲחָיוֹת, מוֹצִיאִים אוֹתָן מֵהֶם; \u0010c4\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵין מוֹצִיאִין:\nהָיְתָה אַחַת מֵהֶם אֲסוּרָה לְאֶחָד מֵהַיְבָמִין מִשּׁוּם אִסוּר עֶרְוָה, מֻתָּר בַּשְּׁנִיָּה, שֶׁהֲרֵי אֵין הָעֶרְוָה זְקוּקָה לוֹ, וְנִמְצָא שֶׁאֵין זְקוּקָה לוֹ אֶלָּא אַחַת; וְהַשֵּׁנִי, אָסוּר בִּשְׁתֵּיהֶם:\nהָיְתָה אַחַת מֵהֶן אֲסוּרָה לְזֶה מִשּׁוּם עֶרְוָה, וְהַשְּׁנִיָּה אֲסוּרָה לַשֵּׁנִי מִשּׁוּם עֶרְוָה, הָאֲסוּרָה לְזֶה מֻתֶּרֶת לְזֶה, שֶׁכָּל אֶחָד אֵין זְקוּקָה לוֹ אֶלָּא אַחַת. אֲבָל אִם אֵין אֲסוּרוֹת עֲלֵיהֶם אֶלָּא בְּאִסוּר לָאו אוֹ עֲשֵׂה, לֹא נִדְחֵית הַזִּיקָה מֵהֶם, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִין שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מִבַּעֲלֵי הָאֲחָיוֹת, וְאַחַר כָּךְ מֵת בַּעַל אֲחוֹת הַשְּׁנִיָּה, וְנָפְלָה גַּם הָאָחוֹת הַשְּׁנִיָּה לִפְנֵי הָאָח הַשְּׁלִישִׁי, שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, שֶׁהֵן צָרוֹת זוֹ לָזוֹ בְּזִקָּה, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. וְאִם עָשָׂה מַאֲמָר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נָפְלָה אֲחוֹתָהּ לְפָנָיו, יוֹצִיא בַּעֲלַת הַמַּאֲמָר בְּגֵט וַחֲלִיצָה, וְהָאַחֲרוֹנָה בַּחֲלִיצָה:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, מֵת נָשׂוּי נָכְרִית, וְכָנַס אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, וּמֵת, הָרִאשׁוֹנָה יוֹצֵאת מִשּׁוּם אֲחוֹת אִשָּׁה, וְהַשְּׁנִיָּה מִשּׁוּם צָרָתָהּ. וְאִם לֹא כְּנָסָהּ, בֵּין שֶׁעָשָׂה מַאֲמָר בַּנָּכְרִית, \u0010c5\u0011 בֵּין שֶׁלֹּא עָשָׂה בָּהּ מַאֲמָר, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, גֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אִשְׁתּוֹ, וּמֵת נָשׂוּי נָכְרִית, וּכְּנָסָהּ הַמְגָרֵשׁ, וּמֵת, מֻתֶּרֶת לָאָח הַנִּשְׁאַר. \u0010c6\u0011 אֲבָל אִם מֵת נָשׂוּי נָּכְרִית קֹדֶם שֶׁגֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, \u0010c7\u0011 אֲפִלּוּ אִם לֹא כָּנַס נָּכְרִית וָמֵת, אֲסוּרָה לָאָח הַנִּשְׁאַר, מִפְּנֵי שֶׁהָיְתָה צָרַת עֶרְוָה בְּזִקָּה, אֲפִלּוּ אִם גֵּרַשׁ הָעֶרְוָה קֹדֶם שֶׁמֵּת. \u0005 וְהוּא הַדִּין אִם הָיָה נָשׂוּי נָכְרִית, וְיֵשׁ לוֹ בָּנִים, \u0010c8\u0011 אֲסוּרָה לוֹ מִשּׁוּם זִקַּת אֵשֶׁת אָחִיו שֶׁיֵּשׁ לוֹ בָּנִים \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פ' ד' אַחִין)\u0006. אֲבָל אִם כָּנַס בַּעַל \u0005(הָאֲחָיוֹת)\u0006 [הָאָחוֹת] אֶת הַנָּכְרִית, וְגֵרַשׁ הָעֶרְוָה, וּמֵת, לָא שְׁנָא גֵּרַשׁ קֹדֶם שֶׁכָּנַס הָעֶרְוָה, לָא שְׁנָא אַחַר כָּךְ, מֻתֶּרֶת הַנָּכְרִית לָאָח הַנִּשְׁאַר:\nשְׁנֵי אַחִים פִּקְחִים נְשׂוּאִין שְׁתֵּי אֲחָיוֹת קְטַנּוֹת אוֹ חֵרְשׁוֹת, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה, שֶׁהֲרֵי נִשּׂוּאֵי שְׁתֵּיהֶן שָׁווֹת:\nהָיְתָה אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת; מֵת בַּעַל הַחֵרֶשֶׁת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַפִּקַּחַת, בַּעַל הַחֵרֶשֶׁת מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֶת אֵשֶׁת אָחִיו בַּחֲלִיצָה:\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה; מֵת בַּעַל הַקְּטַנָּה, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַגְּדוֹלָה, \u0010c9\u0011 מְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בְּבַעְלָהּ, וִייַבֵּם הַגְּדוֹלָה:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַפִּקַּחַת נְשׂוּאָה לְפִקֵּחַ, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ חֵרֵשׁ בַּעַל הַפִּקַּחַת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, הַחֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ בַּעַל הַפִּקַּחַת, מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֵשֶׁת אָחִיו אֲסוּרָה לָעוֹלָם:\nשְׁנֵי אַחִים חֵרְשִׁים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת אוֹ חֵרְשׁוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְכֵן שְׁתֵּי אֲחָיוֹת חֵרְשׁוֹת נְשוּאוֹת לִשְׁנֵי אַחִים פִּקְחִים אוֹ חֵרְשִׁים אוֹ אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. וְאִם הָיוּ נָכְרִיּוֹת, יַכְנִיסוּ; וְאִם אַחַר כָּךְ יִרְצוּ לְהוֹצִיא בְּגֵט, יוֹצִיאוּ:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וְהַחֵרֵשׁ נָשׂוּי שְׁתֵּי נָשִׁים פִּקְחוֹת, וְאַחַת מֵהֶן עֶרְוָה עַל הַפִּקֵּחַ, וּמֵת הַחֵרֵשׁ, שְׁתֵּיהֶן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִּבּוּם. הָיוּ שְׁנֵיהֶם פִּקְחִים, וְאֶחָד מֵהֶם נָשׂוּי שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַחֵרֶשֶׁת הִיא עֶרְוָה עַל אָחִיו, הַשְּׁנִיָּה הַפִּקַּחַת חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:",[],["\u0003ל\"ש מתה אשתו קודם שכנסה השלישי\u0004. אז הוי תרתי לטובה דזו אינה נדחה מהאי בית לגמרי דהא ראויה לנשוי נכרית גם בהאי נפילה אתחזי' לזה מ\"מ אסורה ש\"ס וצרתה ג\"כ אין חילוק בין אם נשא נכרית קודם שייבם את זו או אח\"כ מיהו מ\"ש הרמב\"ם דנכרית אסורה לזה כשייבם את זו נראה ל\"ד קאמר אף אם לא ייבם מ\"מ בזיקה היתה אשתו צרה לזו:","\u0003וחלץ לאחרונה\u0004. דוקא בדיעבד אבל לכתחל' חיישינן שמא יחלוץ להראשונ' ש\"ס והנה לפירוש הרמב\"ם והטור חיישינן שמא זה יחלוץ לראשונ' אבל אם חלץ כבר לא חיישינן שמא בעלמא יחלוץ לראשונ' ועיין בתוס' שם דפירשו ג\"כ אליבא דרש\"י כן, מיהו אם הראשונה אסורה לזה שכתבו ג\"כ לשון בדיעבד משמע נמי לכתחלה אסורה מטעם דאיכא למיחש שמא אתי לייבם את השניה קודם לזה ליתא אלא אף לכתחלה מותרת כמ\"ש שם דפריך וליקו החתן ליבם הך דאינה חמותה תחלה ותהוי חמותה לגבי אידך כיבמה שהותרה וכו' ש\"מ אף לכתחלה מותרת משום דל\"ד הנך חששות זה לזה דשם חשש בזה דאתי שיחלוץ להראשונה אבל לא חיישינן שאח השני אתי לייבם קודם לזה:","\u0003הותרה הראשונה\u0004. ומה שסתם ופסק כאן אם חלץ לאחרונה מותרת הראשונה היינו למ\"ד חליצה פסולה א\"צ לחזור על כל האחים, אבל למ\"ד ח\"פ צריך לחזור על כל האחים נמצא צריכה כ\"א חליצה מכל האחים דהא חליצתה פסולה היא מחמת שהיא אחות זקוקתו א\"כ א\"א לומר שמותרת הראשונה וכ\"כ תוס' שם ד\"ה איתיבי:","\u0003ולא נודע איזה מהם מת ראשון וכו'\u0004. כתב המגיד בזה ג\"כ אם קדמו וכנסו מוציאין מידם ותימא דהא בש\"ס מבואר משני אין מוציאין די\"ל הראשון ייבם השניה והשני הראשונה מייבם והוי יבמה שהותרה ונאסרה וחזרה והותרה וכן קשה בסמוך מ\"ש ומתו הנשואין האחיות או בזא\"ז וכו' מוציאים אותם מהם דהא לפי הסוגיא משמע דקי\"ל א\"א לצמצם א\"כ באמת לא מתו בפעם אחת אלא א' ולא נודע איזה מת ראשון א\"כ אין מוציאין משני ואנן קי\"ל אי אפשר לצמצם עיין בהרא\"ש פ\"ב דבכורות וכמ\"ש בי\"ד שי\"ח מסוגיא זו משמע אם בא אחד וייבם לשניה מותרת הראשונה לשני דהוי יבמה שהותרה ונאסרה וחזרה והותרה לכן אין מוציאין משני אף בספק משום די\"ל הראשון כנס השני' והוא הראשונה מכ\"ש אם הראשון ייבם השניה בודאי מיהו כל הפוסקים כתבו ואם חלץ לשניה הותרה הראשונה משמע אבל בייבם את השניה לא הותרה הראשונה, ודוקא בדיעבד אין מוציאין משני אבל לא הותרה הראשונ' לכתחלה:","\u0003ויש מי שאומר שאין מוציאין\u0004. כ\"כ הטור ועיין ב\"ח שכתב טעות סופר הוא ומה שרוצה ליישב אליבא דר' יוסי הגלילי דס\"ל אפש' לצמצם אלא דלא ידעינן הי נפלה בראשונה וכו' ע\"ש תמוה הוא לר\"י הגלילי שייך לומר אני כנסתי הראשונה מאחר שניהם בפ\"א נאסרים גם הא קי\"ל כרבנן דס\"ל א\"א לצמצם כמ\"ש בסמוך:","\u0003בין שלא עשה בה מאמר\u0004. משום היא בזיקת צרת אחות אשתו וה\"ה להיפוך שמת א' מבעלי אחיות ואח\"כ מת הנשוי נכרית:","\u0003אבל אם מת נשוי נכרית וכו'\u0004. דאז היא זקוקה לשניהם והיא בזיק' צרת אחות אשתו ומ\"מ כל זמן ששניהם בחיים מותר אחד מהן לייבם ואין איסור משום צרת אחות אשתו אא\"כ אם מת א' משנים אלו ונפלו זו ואשתו שהיא אחות אשת החי אסורה זו כמ\"ש בתוס' והרא\"ש:","\u0003אפי' אם לא כנס וכו'\u0004. הנה יש כאן מקום להאריך וראיתי בדרישה וב\"ח מאריכים בזה ואכתוב בקיצור אם מת הנשוי נכרית ולא גירש אחד מבעלי אחיות את אשתו ומת אחד מהם לכ\"ע אסורה כיון דנשארת זקוקה ולכ\"א היא בזיקת צרת אחות אשתו ואם מת הנשוי נכרית ואח\"כ גירש א' מהם אשתו אז לדעת רש\"י אם מת זה שגירש מותרת הנכרית דקי\"ל מיתה מפלת כמה דקי\"ל אם כנס הערוה ונכרי' וגירש הערוה מותרת הנכרית כן הוא דעת הראב\"ד ורשב\"א וכו' וכ\"פ הש\"ג מיהו להרי\"ף והרמב\"ם והרא\"ש אסורה אף על גב דקי\"ל בעלמא מיתה מפלת מ\"מ הכא גרע טפי מטעם המבואר בהרי\"ף דגזרינן דאתי לייבם הנכרית אף אם לא יגרש הערוה כיון דאין אסורה לו אלא מחמת הזיק' וכ\"כ הרמב\"ם טעם זה ועוד טעם אחר כיון דהנכרית בשעת נפילה באיסור זיקה קא נפלה קמיה לא מהני בה גירושין ויש כאן מקום לומר דוקא בלא כנס הנכרית אז אסורה אבל בכנס ואח\"כ גירש הערוה מותרת דאז לא שייך הגזירה הנ\"ל וכ\"כ בדרישה ומגיה בטור מ\"ש ואפילו אם לא כינס צ\"ל אם לא כינס וי\"ל הטור ס\"ל כסברא זו ולא כהרא\"ש דאוסר אפילו בכונס לפ\"ז שפיר הסוגיא בפ\"ק דהקשה אפילו כנס ולבסוף גירש ורמינהו וכו' טעמא גירש ואח\"כ כנס אבל כנס ואח\"כ גירש לא משום כאן כנס ג\"כ מותר לכן הקשה ל\"ל שגירש קודם שמת אחיו וכנס אח\"כ ת\"ל אפילו אם מת אחיו וכנס וגירש או בגירשה וכנס מותר מיהו המגיד כתב בשם הראב\"ד והרשב\"א ורמב\"ן וכן הוא מפרש דברי הרמב\"ם בכנס פשיטא דאסור' והסוגיא י\"ל באמת לפי סברת רב אשי במת הנשוי נכרית ואח\"כ גירש א' מבעלי אחיות אסורה וס\"ל דהכא גרע מטעמים שכתב הרי\"ף תו א\"צ התירוצים של ר' ירמיה ורבא בפ\"ק דף י\"ג ואפשר לדחוק ולפרש מ\"ש הטור והמחבר בסמוך אבל אם כנס בעל האחיות וכו' לא קאי על ד\"ז אם מייבם הנכרית אלא דין בעלמא קאמר אם ב\"א יש להם ב\"א וכנס א' נכרית וגירש את אחות א\"א מותר הנכרית והיינו כקושי' הרי\"ף ומחלק בין דין שכונס דרך יבום ובין הכונס שלא דרך יבום וגירש מותרת הנכרית ולכאורה נראה דמוכח כן דכנס אסור דאי אמרת כנס עדיף א\"כ למה לש\"ס למימר אליבא דרב' זו היא למעוטי מת בלא גירש דלמא מודה רבא אם מת וגירש אסור אף על גב דס\"ל מית' מפלת מ\"מ איכא למגזר כהנ\"ל משא\"כ בשאר ערוה שכנס עם נכרית והא דצריך לתרץ בפ\"ק לא זו אף זו ולא תירץ כאן גרע טפי משום גזירה משום קושיית המקשן היא בכנס אז גם כאן מותר למה תנא גירש ואח\"כ מת וכנס הא מת ואח\"כ כנס וגירש ג\"כ מותר:","\u0003אסורה לו וכו'\u0004. נראה דס\"ל הטעם דאסורה הנכרית לאחי' אף על גב דהיא צרת אחות אשתו בזיקה ואינה אסורה אלא אחר מיתת אחיו השני משום בחייהם אמרינן דאינה זקוקה להם אלא מחמת אחיו הראשון ומותרת אבל אחר מיתת השני והיתה זקוקה לו מחזי כאלו אח השלישי נושא אותה מחמת אח השני והיא היתה בזיקת צרת אחות אשתו כן ה\"נ דמחזי כאלו היה נושא אשת אחיו דיש לו בנים:","\u0003מלמדין את הקטנה שתמאן\u0004. ואם לא מיאנה והגדילה ל\"ש בא עליה לאחר שהגדילה ל\"ש לא בא עליה מוציא את אשתו ואת א\"א בחליצה דקי\"ל יש זיקה כ\"כ רי\"ו בשם הרמ\"ה וא\"ל הא דאית' פד\"א דף כ\"ט למעוטי דר\"י דאמר בדין זה דמוציא את אשתו ואת יבמתו משום דאתי' למ\"ד אין זיקה אבל למה דקי\"ל יש זיקה הלכתא כר\"י אם היא אינה רוצה למאן, ומ\"ש אפילו בא עליה לאחר שהגדילה לא פקעה זיקה של יבמתו עיין מ\"ש בש\"ס קנ\"ט בשם תוס' דלא ס\"ל כן ועיין ב\"ח מאריך בזה והביא פרש\"י דף י\"ח דדין של ר\"ג שאמר בפלוגתא זו תמתין עד שתגדיל ותצא הגדולה משום אחות אשתו אתי אפילו למ\"ד יש זיקה, ופסק אם אין רצונה למאן עבדינן כר\"ג, מיהו נראה לכאורה אף אם אתי' דין של ר\"ג אפי' למ\"ד יש זיקה מ\"מ הא אוקמא בפרק ב\"ש (יבמות דף ק\"ט) דר\"ג סבר המקדש אחות זקוקה נפטרת היבמה ואנן קי\"ל דלא נפטרה והנ\"י כתב בשם כמה פוסקים אפילו נשא אותה לא מהני לכן עיקר כפסק רי\"ו ולא מטעמי' משום יש זיקה אלא מטעם דלא נפטרה היבמה ומכ\"ש דאסור לומר לכתחלה שיעשה מעשה בקטנה כדי לדחות את הגדולה, וא\"ל אף אם תמאן הקטנ' איך מותרת הגדול' הא בעת הנפילה היתה נראית כאחות ומ\"ש מצרת בתו ממאנת דלא מהני מיאון בתו כיון שהיתה נראית בעת הנפילה כצרת בתו עיין תוס' פד\"א שם שתירצו כיון שהיא ממאנת בעוד בעלה חי עוקרת לגמרי הנשואין ועדיף ממאנת לאחר שמת בעלה:"],"\u0010g0\u0011 \u0010r0\u0011 יְבָמָה שֶׁאֵינָהּ רְאוּיָה לְהִתְיַבֵּם בִּשְׁעַת נְפִילָה, \u0010r1\u0011 מִשּׁוּם אִסוּר עֶרְוָה, אֲסוּרָה עוֹלָמִית, אֲפִלּוּ אִם יִפְקַע \u0010r2\u0011 הָאִסוּר. כְּגוֹן שְׁנֵי אַחִים שֶׁנְּשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי הַשֵּׁנִי שֶׁנָּשׂוּי אֲחוֹתָהּ, אֲפִלּוּ אִם תָּמוּת אִשְׁתּוֹ אַחַר כָּךְ, שֶׁפָּקַע אִסוּר אֲחוֹת אִשָּׁה, אֲפִלּוּ הָכִי אֲסוּרָה. \u0010r3\u0011 וַאֲפִלּוּ נָפְלָה לְפָנָיו פַּעַם אַחֶרֶת אַחֲרֵי מוֹת אִשְׁתּוֹ, \u0010r4\u0011 כְּגוֹן שֶׁהָיָה לָהֶם אָח שְׁלִישִׁי שֶׁלֹּא הָיְתָה עֶרְוָה עָלָיו, וּכְּנָסָהּ, וּמֵתָה אִשְׁתּוֹ שֶׁל זֶה שֶׁהָיָה נָשׂוּי אֲחוֹתָהּ, וּמֵת הַשְּׁלִישִׁי שֶׁכְּנָסָהּ, וְחָזַר וְנָפְלָה לְפָנָיו, אֲסוּרָה לוֹ. \u0010c0\u0011 \u0010g1\u0011 \u0010r5\u0011 לָא שְׁנָא מֵתָה אִשְׁתּוֹ קֹדֶם שֶׁכָּנַס הַשְּׁלִישִׁי, לֹא שְׁנָא מֵתָה אַחַר שֶׁכָּנַס, אַף עַל פִּי שֶׁלֹּא הָיְתָה אֲסוּרָה עָלָיו בִּשְׁעַת נְפִילָה אַחֲרוֹנָה, אֲפִלּוּ הָכִי אֲסוּרָה לוֹ הִיא \u0010g2\u0011 \u0010r6\u0011 וְצָרָתָהּ, כְּגוֹן שֶׁהָיָה אִשָּׁה אַחֶרֶת לָאָח הַשְּׁלִישִׁי, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה לוֹ בִּשְׁעַת נְפִילָה רִאשׁוֹנָה. \u0010g3\u0011 \u0010r7\u0011 אֲבָל אִם הָיְתָה מֻתֶּרֶת לוֹ בִּשְׁעַת נְפִילָה, אֲפִלּוּ אִם תֵּאָסֵר אַחַר כָּךְ, אִם פָּקַע הָאִסוּר, חוֹזֶרֶת לְהֶתֵּרָהּ. כֵּיצַד, שְׁלשָׁה אַחִים שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנִזְקְקָה אִשְׁתּוֹ לַשְּׁלִישִׁי שֶׁאֵינוֹ נָשׂוּי אֲחוֹתָהּ, וְלֹא הִסְפִּיק לְכָנְסָהּ עַד שֶׁמֵּת הָאָח הַשֵּׁנִי שֶׁהָיָה נָשׂוּי הָאַחֶרֶת, וַהֲרֵי שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, מֵתָה הָאַחֲרוֹנָה, חָזְרָה הָרִאשׁוֹנָה לְהֶתֵּרָהּ, כֵּיוָן שֶׁהָיְתָה מֻתֶּרֶת בִּשְׁעַת נְפִילָה, \u0010r8\u0011 אַף עַל פִּי שֶׁנֶּאֶסְרָה בֵּינְתַיִם. אֲבָל אִם מֵתָה הָרִאשׁוֹנָה, לֹא הֻתְּרָה הָאַחֲרוֹנָה, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה בִּשְׁעַת נְפִילָה. \u0010g4\u0011 \u0010r9\u0011 וְכֵן אִם הָיוּ שָׁם עוֹד אַחִים, \u0010g5\u0011 וְקָדַם אֶחָד מֵהֶם \u0010c1\u0011 וְחָלַץ לָאַחֲרוֹנָה, \u0010g6\u0011 \u0010r10\u0011 אוֹ שֶׁהָיְתָה הָרִאשׁוֹנָה אֲסוּרָה לְאֶחָד מֵהָאַחִים, וְיִבֵּם אֶת הָאַחֲרוֹנָה, שֶׁהֲרֵי מֻתֶּרֶת לוֹ, \u0010c2\u0011 הֻתְּרָה הָרִאשׁוֹנָה לִשְׁאָר אַחִים, שֶׁהֲרֵי הָאַחֲרוֹנָה שֶׁאָסְרָה אוֹתָהּ, חָלְצָה אוֹ נִתְיַבְּמָהּ לַמֻּתָּר לָהּ. אֲבָל אִם הָאַחֲרוֹנָה אֲסוּרָה לְאֶחָד מֵהֶם מִשּׁוּם עֶרְוָה, הֲרֵי הוּא מֻתָּר לְיַבֵּם הָרִאשׁוֹנָה, וּשְׁאָר הָאַחִים אֲסוּרִים בִּשְׁתֵּיהֶן, וְחוֹלְצוֹת וְלֹא \u0010g7\u0011 \u0010r11\u0011 מִתְיַבְּמוֹת:\nשְׁנַיִם מֵהָאַחִים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ שְׁנֵיהֶם, \u0010c3\u0011 וְלֹא נוֹדַע אֵיזֶה מֵהֶם מֵת רִאשׁוֹן, הוֹאִיל וְאִי אֶפְשָׁר לְיַבֵּם שְׁתֵּיהֶן, וַהֲרֵי זִקָּה נָפְלָה עַל שְׁתֵּיהֶן, חוֹלְצוֹת וְלֹא \u0010r12\u0011 מִתְיַבְּמוֹת. וַאֲפִלּוּ הָיְתָה אַחַת מֵהֶם אֲסוּרָה עַל הַיָּבָם מִשּׁוּם שְׁנִיָּה אוֹ מֵחַיָּבֵי עֲשֵׂה אוֹ מֵחַיָּבֵי לָאוִין, הֲרֵי אֵלּוּ חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. אֲבָל אִם הָיְתָה אַחַת מֵהֶם עֶרְוָה עָלָיו, הֲרֵי אֲחוֹתָהּ מֻתֶּרֶת לוֹ, רָצָה חוֹלֵץ רָצָה מְיַבֵּם, שֶׁהֲרֵי לֹא נָפְלָה זִקָּתוֹ עַל שְׁתֵּיהֶן, שֶׁאֵין זִקָּה עַל הֶעֶרְוָה: \u0010g8\u0011\nאַרְבַּע אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ הַנְּשׂוּאִים אֶת הָאֲחָיוֹת, \u0010r13\u0011 אוֹ בָּזֶה אַחַר זֶה, \u0010g9\u0011 קֹדֶם שֶׁהִסְפִּיקוּ לְיַבֵּם לָרִאשׁוֹנָה, שְׁתֵּיהֶן חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת, שֶׁאִי אֶפְשָׁר לְשׁוּם אַחַת מֵהֶן לְהִתְיַבֵּם, מִשּׁוּם אִסוּר אֲחוֹת זְקוּקָה. וְאִם קָדְמוּ וְכָנְסוּ כָּל אֶחָד אַחַת מֵהָאֲחָיוֹת, \u0010g10\u0011 מוֹצִיאִים אוֹתָן מֵהֶם; \u0010c4\u0011 \u0010g11\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵין \u0010g12\u0011 \u0010t0\u0011 מוֹצִיאִין:\nהָיְתָה אַחַת מֵהֶם אֲסוּרָה לְאֶחָד מֵהַיְבָמִין מִשּׁוּם אִסוּר עֶרְוָה, מֻתָּר בַּשְּׁנִיָּה, שֶׁהֲרֵי אֵין הָעֶרְוָה זְקוּקָה לוֹ, וְנִמְצָא שֶׁאֵין זְקוּקָה לוֹ אֶלָּא אַחַת; וְהַשֵּׁנִי, אָסוּר בִּשְׁתֵּיהֶם: \u0010g13\u0011\nהָיְתָה אַחַת מֵהֶן אֲסוּרָה לְזֶה מִשּׁוּם עֶרְוָה, וְהַשְּׁנִיָּה אֲסוּרָה לַשֵּׁנִי מִשּׁוּם עֶרְוָה, הָאֲסוּרָה לְזֶה מֻתֶּרֶת לְזֶה, שֶׁכָּל אֶחָד אֵין זְקוּקָה לוֹ אֶלָּא אַחַת. \u0010g14\u0011 \u0010r14\u0011 אֲבָל אִם אֵין אֲסוּרוֹת עֲלֵיהֶם אֶלָּא בְּאִסוּר לָאו אוֹ עֲשֵׂה, לֹא נִדְחֵית הַזִּיקָה מֵהֶם, וְחוֹלְצוֹת וְלֹא \u0010g15\u0011 מִתְיַבְּמוֹת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִין שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מִבַּעֲלֵי הָאֲחָיוֹת, וְאַחַר כָּךְ מֵת בַּעַל אֲחוֹת הַשְּׁנִיָּה, וְנָפְלָה גַּם הָאָחוֹת הַשְּׁנִיָּה לִפְנֵי הָאָח הַשְּׁלִישִׁי, שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, שֶׁהֵן צָרוֹת זוֹ לָזוֹ בְּזִקָּה, וְחוֹלְצוֹת וְלֹא \u0010g16\u0011 מִתְיַבְּמוֹת. וְאִם עָשָׂה מַאֲמָר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נָפְלָה אֲחוֹתָהּ לְפָנָיו, יוֹצִיא בַּעֲלַת הַמַּאֲמָר בְּגֵט וַחֲלִיצָה, וְהָאַחֲרוֹנָה בַּחֲלִיצָה: \u0010g17\u0011 \u0010r15\u0011\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, מֵת נָשׂוּי נָכְרִית, וְכָנַס אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, וּמֵת, הָרִאשׁוֹנָה יוֹצֵאת מִשּׁוּם אֲחוֹת אִשָּׁה, וְהַשְּׁנִיָּה מִשּׁוּם צָרָתָהּ. וְאִם לֹא כְּנָסָהּ, \u0010r16\u0011 בֵּין שֶׁעָשָׂה מַאֲמָר בַּנָּכְרִית, \u0010c5\u0011 \u0010g18\u0011 בֵּין שֶׁלֹּא עָשָׂה בָּהּ מַאֲמָר, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא \u0010g19\u0011 מִתְיַבֶּמֶת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, גֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אִשְׁתּוֹ, וּמֵת נָשׂוּי נָכְרִית, וּכְּנָסָהּ הַמְגָרֵשׁ, וּמֵת, מֻתֶּרֶת לָאָח הַנִּשְׁאַר. \u0010c6\u0011 \u0010g20\u0011 \u0010r17\u0011 אֲבָל אִם מֵת נָשׂוּי נָּכְרִית קֹדֶם שֶׁגֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, \u0010c7\u0011 אֲפִלּוּ אִם לֹא כָּנַס נָּכְרִית וָמֵת, אֲסוּרָה לָאָח הַנִּשְׁאַר, \u0010g21\u0011 מִפְּנֵי שֶׁהָיְתָה צָרַת עֶרְוָה בְּזִקָּה, אֲפִלּוּ אִם גֵּרַשׁ הָעֶרְוָה קֹדֶם שֶׁמֵּת. \u0005 וְהוּא הַדִּין אִם הָיָה נָשׂוּי נָכְרִית, וְיֵשׁ לוֹ בָּנִים, \u0010c8\u0011 אֲסוּרָה לוֹ מִשּׁוּם זִקַּת אֵשֶׁת אָחִיו שֶׁיֵּשׁ לוֹ בָּנִים \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פ' ד' אַחִין)\u0006. \u0010g22\u0011 \u0010r18\u0011 אֲבָל אִם כָּנַס בַּעַל \u0005(הָאֲחָיוֹת)\u0006 [הָאָחוֹת] אֶת הַנָּכְרִית, וְגֵרַשׁ הָעֶרְוָה, וּמֵת, לָא שְׁנָא גֵּרַשׁ קֹדֶם שֶׁכָּנַס הָעֶרְוָה, לָא שְׁנָא אַחַר כָּךְ, מֻתֶּרֶת הַנָּכְרִית לָאָח הַנִּשְׁאַר: \u0010g23\u0011\nשְׁנֵי אַחִים פִּקְחִים נְשׂוּאִין שְׁתֵּי אֲחָיוֹת קְטַנּוֹת אוֹ חֵרְשׁוֹת, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה, שֶׁהֲרֵי נִשּׂוּאֵי שְׁתֵּיהֶן שָׁווֹת: \u0010g24\u0011\nהָיְתָה אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת; מֵת בַּעַל הַחֵרֶשֶׁת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַפִּקַּחַת, בַּעַל הַחֵרֶשֶׁת מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֶת אֵשֶׁת אָחִיו בַּחֲלִיצָה: \u0010g25\u0011\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה; מֵת בַּעַל הַקְּטַנָּה, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַגְּדוֹלָה, \u0010c9\u0011 \u0010g26\u0011 מְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בְּבַעְלָהּ, וִייַבֵּם הַגְּדוֹלָה: \u0010g27\u0011\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַפִּקַּחַת נְשׂוּאָה לְפִקֵּחַ, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ חֵרֵשׁ בַּעַל הַפִּקַּחַת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, הַחֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ בַּעַל הַפִּקַּחַת, מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֵשֶׁת אָחִיו אֲסוּרָה לָעוֹלָם: \u0010g28\u0011\nשְׁנֵי אַחִים חֵרְשִׁים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת אוֹ חֵרְשׁוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְכֵן שְׁתֵּי אֲחָיוֹת חֵרְשׁוֹת נְשוּאוֹת לִשְׁנֵי אַחִים פִּקְחִים אוֹ חֵרְשִׁים אוֹ אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. וְאִם הָיוּ נָכְרִיּוֹת, יַכְנִיסוּ; וְאִם אַחַר כָּךְ יִרְצוּ לְהוֹצִיא בְּגֵט, יוֹצִיאוּ: \u0010g29\u0011 \u0010r19\u0011\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וְהַחֵרֵשׁ נָשׂוּי שְׁתֵּי נָשִׁים פִּקְחוֹת, וְאַחַת מֵהֶן עֶרְוָה עַל הַפִּקֵּחַ, וּמֵת הַחֵרֵשׁ, שְׁתֵּיהֶן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִּבּוּם. הָיוּ שְׁנֵיהֶם פִּקְחִים, וְאֶחָד מֵהֶם נָשׂוּי שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַחֵרֶשֶׁת הִיא עֶרְוָה עַל אָחִיו, הַשְּׁנִיָּה הַפִּקַּחַת חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:",{"g":["ל' הטור ממשנה שם דף ל' ע\"א","מימר' דרב יהודה אמר רב שם","וכ\"כ הרמב\"ם שם בפ\"ז וכ' ה\"ה דכל יבמה שאין אני קורא בה בשעת נפיל' יבמה יבא עליה הרי היא כאשת אח שיש לה בנים ואסור' כדאית' התם (דף כז ע\"ב) וצרת' ה\"ל צרת ערוה","כרבי יוחנן שם דקי\"ל רב ור\"י הלכ' כר\"י","כרבי יוחנן דא\"ל לרב חנינא אחיות איני יודע מי שנאן וכולי שם כלומר זו אינה משנה","בדיעבד אבל לכתחלה לא אמרינן להו לחלוץ השניה וליבם הראשונה דגזרינן דלמא אתי למיעבד איפכ' וכ\"כ הרמב\"ם בפ' ז' וכ\"כ התו' שם","\u0003ממשנה שם דף כו\u0004 ע\"א וגמרא שם דף כח ע\"א וכ\"כ הרמב\"ם בפ\"ז","ל' הרמב\"ם שם מהא דאמרי' ולימ' ליה דלא ידעינן הי נפיל ברישא (שם ד' כח ע\"א) משמע בהדיא דכל היכא דלא ידעינן הי נפיל בריש' חולצות ולא מתייבמות","\u0003ל' הטור ממשנה שם דף כו\u0004 ע\"א","פי' דאז כנפלו שתיהן בבת אחת דמי","כ\"כ הרמב\"ם בחיבורו בפ' הנז' כסתם מתני' שם","טור וכאבא שאול ור\"ש בבריי' שם דף כח ע\"א וכ\"פ הרמב\"ם בפי' המשנה","שם במשנה","שם במשנה","שם במשנה","משנ' שם דף כח ע\"ב","משנ' שם דף כט ע\"א וכב\"ה דאין המאמר קונה קנין גמור ונשאר על הראשונה עוד זיקת יבמים וכשנפלה אח\"כ אחותה לפניו הם נעשות צרות זו לזו בזיק'","משנה שם דף ל' ע\"א","טור בשם אביו הרא\"ש כיון שהי' צרת אחות אשה בזיק'","משנה שם","שם בגמרא","מימרא דר' אשי שם","כמ\"ש ברא\"ש שם אמימר' דרב אשי דלא שייך צרת ערוה אלא כשהיא והערו' נופלים בבת אחת וכו'","משנה שם דק\"ט ע\"א","משנה שם דף קיב ע\"ב","משנ' דף קט ע\"א","שם במשנה וכר\"א דאיפסק' הלכתא כוותי' שם דף קי ע\"א וכתב ר' ירוחם בשם הרמ\"ה שאם לא מיאנ' והגדיל' בין בא עלי' אח\"כ או לא בא עליה מוציא את אשתו בגט ואשת אחיו בחליצ' דקי\"ל יש זיקה ב\"י","משנה שם דף קיב ע\"א","שם במשנה","טור וכ\"כ הרמב\"ם ספ\"ז מהירושלמי שם"],"t":["\u0003שאין מוציאין. \u0004 עי' תוס' י\"ט פ\"ג דיבמות משנה א' מה שנתקשה בזה. ועי' ב\"ח וב\"ש:"],"r":["\u0003יבמה כולי. \u0004 מימרא דר\"י א\"ר למ\"ד א':","\u0003משום איסור ערוה. \u0004 לאפוקי נדה כמ\"ש תוספת ב' א' ד\"ה ואחות כולי:","\u0003כגון כולי \u0004 שם ול\"ב א':","\u0003ואפי' נפלה כולי. \u0004 גמ' שם ושם:","\u0003כגון כולי \u0004 מתני' למ\"ד א':","\u0003ל\"ש כולי. \u0004 גמ' שם ובדרך לא זא\"ז נקט כמ\"ש ל\"ב א' פשיטא כולי ושם ל' א' מ\"ד היכא כולי:","\u0003וצרת'. \u0004 דלכך קא' נשוי נכרית. תוספת שם וד\"ה ונאסרה כולי:","\u0003אבל אם כולי \u0004 כ\"ז ב':","\u0003אבל אם כולי. \u0004 כפירש שם:","\u0003וכן אם כולי \u0004 וקדם כולי. כ\"ח א' ולימא ליה גזירה דלמא כולי ועתוס' ד\"ה ולימא ליה דלמא כולי פר\"י כולי:","\u0003או שהיתה כולי \u0004 אבל אם כולי. שם תנן כולי אר\"פ כולי:","\u0003שנים כולי \u0004 ולא נודע כולי. דבכה\"ג אפילו מיתה אחת מהן או חלץ לה האחר בשיש עוד אח אסור בשניה מ\"מ וכמ\"ש בגמ' שם ולימא ליה דלא ידעינן כולי ובדברי הרמב\"ם מסודר שם שתחלה כתב סעיף זה ואח\"כ כ' מת א' תחלה ואח\"כ מת שני מתה האחרונה כולי וכן אם קדם וחלץ כולי כמ\"ש בס\"א:","\u0003ואפילו כולי. \u0004 אבל כולי מתני' צ\"ו א' וכמש\"ש כ\"ח ב' הכא איסור מצוה ואחותה כולי וכ\"ז כ' ג\"כ בסד\"ה אלא ששם בד' אחין וכאן בג' וממתני' דשם כ\"ח ב' וכמ\"ש א' צריכה דאי כולי:","\u0003או בזא\"ז כולי \u0004 כמ\"ש בסוגיא הנ\"ל איתיבי' ריב\"ח כולי ולימא ליה דנפיל בבת אחת כולי:","\u0003אבל אם אין כולי. \u0004 אסורות כולי. כאן השמיענו בששניהם אסורות משא\"כ בס\"ב וכמש\"ש כ\"ח ב' זו היא למעוטי כולי מ\"ד כי כולי אבל בא' מהן איסור מצוה א\"צ דכבר כ' בס\"ב וע\"ז ליכא צריכותא בגמ' שם אלא לר\"ש כמ\"ש שם הא תו ל\"ל כו':","\u0003שלשה כולי. \u0004 ולא כ' מתני' הראשונה שם שהיא יותר רבותא כמש\"ש בגמרא משום שכבר כ' בס\"א כגון שהיה להם אח שלישי כולי וצרתה כולי וג\"כ ית' בס\"ח:","\u0003בין כולי. \u0004 שם א\"ל רב אשי ה\"ה כולי הכי קי\"ל כמש\"ל סימן קע\"ג סי\"ב:","\u0003אבל אם כולי. \u0004 הנה שיטות רש\"י דרבא ורב אשי פליגי דר\"א ס\"ל דנישואין הראשונים מפילין אבל רבא ס\"ל דמיתה מפלת ואם מת ואח\"כ גירש בין כנס אח\"כ או לא מותרת אלא בלא גירש כלל ולא כנס ומ\"מ הלכה כרבא דסוגיא לקמן ק\"ט א' ומתני' ס\"ז ב' דמית' מפלת והראב\"ד פי' דל\"פ ומ\"ש בג' טעמא דגירש כולי מדברי גמ' הוא ורב אשי ל\"ק אלא זאת אומרת כו' וגמ' פירש דבריו כן לס\"ד אבל למסקנא כמו דרבא ס\"ל דר\"א כן ר\"א ס\"ל דרבא וקשה לשיטתן א\"כ מאי קאמר ולר\"נ קשיא כולי הניחא כולי הא גם אי ס\"ל דר\"א ס\"ל כר' ירמיה ס\"ל וכן למה לא פריך על ר\"א ואף לפי' (אב') מ\"מ לס\"ד קשה אבל הרמב\"ן לשיטתו דמתני' ודאי נישואים הראשונים מפילין אף לרבא דאמר זו ואצ\"ל זו שהיא משעת נישואין הראשונים וע\"ז דייק רבי אשי טעמא כולי לפי ענין המתני' דדייק נישואין הראשונים אבל זו היא קשיא לרבא דזו היא למעוטי לא שייך כיון דס\"ל לתנא דמותרת אף בכה\"ג כ\"ז לשיטת רש\"י: אבל הגאונים ור\"ח ז\"ל גורסין במילתא דרבא ג\"כ מת ואח\"כ גירש וכ\"ה גי' הרי\"ף אע\"ג דכנס ואח\"כ גירש מותר לרבא כאן שאני דכיון בשעת נפיל' היתה באיסור לא מהני בה גירושין משא\"כ בכנס נכרית דעלמא ואח\"כ גירש ול\"פ רבא ורב אשי וזה שלא הזכיר הרי\"ף מת ולא גירש וערמב\"ן שדחק עצמו לשיטת הרי\"ף ל\"ל לרבא למימר מת ולא גירש הל\"ל ג\"כ כרב אשי שדחק עצמו לומר דה\"נ קאמר מת ולא גירש בשעת כניסה אלא אח\"כ ע\"ש וא\"צ לכ\"ז כמ\"ש הרשב\"א הגי' הנ\"ל בשם הגאונים וסתר דברי רש\"י דמת ולא גירש אסורה הא בלא מת מותרת להנשא לכ\"א כמ\"ש במתני' מת נשוי נכרית וכנס א' מבעלי אחיות כולי למה יאסר אחר מיתה ואף שתוס' שם ד\"ה זאת כולי דחאו הרמב\"ן ורשב\"א דבריהם דא\"כ אתה עושה צרות לאחר מיתה וכמ\"ש בירושלמי פ\"ג הלכה א' על ענין אחר וא\"ר יודן אילו בקש לבעול את הצרה עד שלא כנס שמא אינו מותר בה בתחלה הוה מותר בה ולבסוף הוא אסור אם את אומר כן נמצאת עושה צרה לאחר מיתה ואין צרה לאחר מיתה ועוד דא\"כ במתני' השני' מת נשוי נכרית וכנס אחד מבעלי אחיות כולי צ\"ל ג\"כ עשה מאמר לאו דוקא כמו במתני' הראשונה וג\"כ לאפוקי מב\"ש ותרתי ל\"ל ובתוספתא פ\"ה מפירש דמותר בלא עבד מאמר אלא די\"ל דס\"ל אין זיק' כמ\"ש י\"ז א' ועוד הקשה דזו היא משמע למעוטי גירושין אחרים דאתא וסתר גי' רש\"י וגם פסק דמותר ופי' בדברי הרי\"ף דמיירי במת ואח\"כ גירש ואח\"כ כנס אבל בלא כנס מותר כנ\"ל וא\"ת עדיין קשה קושיא הנ\"ל בשנפלו לפניהם הי' מייבם כל א' מהן שירצה י\"ל כיון שכנס איגלי למפרע דמשעת נפיל' היתה זקוקתו לבד וה\"ה בכנס ואח\"כ גירש האסורה משום נפיל' ראשונה והא דפריך לר\"נ הניחא כולי אע\"ג דכאן אפילו לרבא אסורה היינו לרב אשי אבל לר\"נ כיון דאין זיקה הוי כנכרית דעלמא והרמב\"ן בשם המפרשים כ' דאפילו לא כנס אוסר הרי\"ף ומודה בזה לרש\"י ולדידהו כ\"ש במת ולא גירש:\nוהכלל דלרש\"י מת ואח\"כ גירש בין כנס או לא כנס שריא כרבא וכן כנס ואח\"כ גירש מותרת אבל מת ולא גירש אסור' אף בלא כנס כלל ושיטת המפרשים דברי הרי\"ף דאף מת ואח\"כ גירש בין כנס בין לא כנס או כנס ואח\"כ גירש אסורה וכ\"ש מת ולא גירש ושיטת הרשב\"א דאין אסור אלא בכנס בין גירש קודם שכנס או אח\"כ במת ולבסוף גירש אבל לא כנס מותרת בין גירש אח\"כ או לא גירש כלל והקשה הרשב\"א על שיטת הרי\"ף דא\"כ דמודה רבא כאן בכנס ולבסוף גירש דאסורה מאי קאמר זו ואצ\"ל זו קתני הא כאן אסורה כנס ואח\"כ גירש והל\"ל שאני שם דיש זיק' ושם בנכרית דעלמא וע\"כ לקחו הטוש\"ע שיטה אחרת בדברי הרי\"ף היפך מדברי הרשב\"א לגמרי דדוקא בלא כנס אסור מת ואח\"כ גירש כגי' הגאונים וכ\"ש מת ולא גירש אבל כנס בין גירש קודם שכנס בין אח\"כ מותרת כרבא דמחמת נשואין האחרונים היא זקוקה וכ\"ה דברי הרמב\"ם פ\"ו הלכה כ\"ה וז\"ש אבל אם כולי אפילו אם כולי הוא גי' רש\"י מת ולא גירש שגם הרי\"ף מודה בם לאפוקי מדעת הרשב\"א אפילו אם גירש כולי זו היא גי' הרי\"ף לאפוקי מדעת רש\"י וכ\"כ הרשב\"א:","\u0003אבל אם כנסה כולי. \u0004 כרבא לאפוקי מדעת הרשב\"א והמפ' וז\"ש ל\"ש כולי:","\u0003שני אחין כולי \u0004 תוספתא פ\"ט בתו פקחת הנשואה לאחיו חרש צרתה פטורה מן החליצה ומן הייבום ממ\"נ אם נישואי בתו נישואין נישואי צרתה נישואין אין נשואין בתו נשואין לא יהו של צרתה נשואין בתו החרשת הנשוא' לאחיו פקח צרתה חולצת ולא מתייבמת ועבה\"ג:"]}],["מִי שֶׁקִּדֵּשׁ אַחַת מִשְּׁתֵּי אֲחָיוֹת, וְאֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ, אֲפִלּוּ לֹא הֻכְּרוּ מֵעוֹלָם, שֶׁלֹּא נִתְּנוּ לְבִיאָה, הֲווֹ קִדּוּשִׁין וְצָרִיךְ גֵּט לְכָל אַחַת וְאַחַת. מֵת, וְלוֹ אָח, חוֹלֵץ לִשְׁתֵּיהֶן. הָיוּ לוֹ שְׁנֵי אַחִים, אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ שְׁנֵי הָאַחִים וְכָנְסוּ אֶת \u0010c0\u0011 שְׁתֵּיהֶן, אֵין מוֹצִיאִים אוֹתָן מִיָּדָם. וְאִם נִמְלְכוּ בְּבֵית דִּין וְאָמְרוּ לָהֶם שֶׁיַּחֲלֹץ הָאֶחָד וִיְיַבֵּם הַשֵּׁנִי, וְהָלְכוּ שְׁנֵיהֶם וְיִבְּמוּ, יוֹצִיאוּ:\nמִי שֶׁעָבַר וְיִבֵּם וַדַּאי אֲחוֹת זְקוּקָתוֹ, \u0010c1\u0011 יוֹצִיא:\nשְׁנַיִם שֶׁקִּדְּשׁוּ שְׁתֵּי אֲחָיוֹת, זֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ וְזֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ, וּמֵתוּ, לְזֶה אָח וּלְזֶה אָח, כָּל אֶחָד חוֹלֵץ לִשְׁתֵּיהֶן; וְאֵין שׁוּם אֶחָד מֵהֶם יָכוֹל לְיַבֵּם. לְזֶה אֶחָד וּלְזֶה שְׁנַיִם; הַיָּחִיד חוֹלֵץ לִשְׁתֵּיהֶן; וְהַשְּׁנַיִם, אֶחָד חוֹלֵץ לְאַחַת תְּחִלָּה, וְאַחַר כָּךְ יְיַבֵּם הַשֵּׁנִי לַשְּׁנִיָּה. וְאִם קָדְמוּ הַשְּׁנַיִם וְכָנְסוּ אַחַר שֶׁחָלַץ הַיָּחִיד, אֵין מוֹצִיאִים מִיָּדָם, אֲפִלּוּ שְׁנֵיהֶם כֹּהֲנִים. הָיוּ לְזֶה שְׁנֵי אַחִים וּלְזֶה שְׁנֵי אַחִים, אָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאַחַר כָּךְ הָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה, וָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה. אִם קָדְמוּ שְׁנֵי הָאַחִים שֶׁל הָאֶחָד וְחָלְצוּ לִשְׁתֵּיהֶן, לֹא יְיַבְּמוּ הַשְּׁנֵי אַחִים הָאֲחֵרִים שֶׁל הַשֵּׁנִי לִשְׁתֵּיהֶן, אֶלָּא אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ הַשְּׁנַיִם הָאַחֲרוֹנִים וְכָנְסוּ אַחַר שֶׁחָלְצוּ הַשְּׁנַיִם הָרִאשׁוֹנִים, אֵין מוֹצִיאִין מִיָּדָם:\nמִי שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְשָׁמְעוּ שֶׁמֵּת, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא בַּעְלָהּ, וּמֵתוּ שְׁנֵיהֶם, לְזֶה אָח וּלְזֶה אָח, אָחִיו שֶׁל זֶה וְשֶׁל זֶה \u0010c2\u0011 חוֹלְצִים וְלֹא מְיַבְּמִים. \u0005 וְדִין צָרָתָהּ, עַיֵּן לְעֵיל סִי' קע\"ג סָעִיף י\"א: \u0006\nהָאִשָּׁה שֶׁהָיוּ לָהּ בָּנִים וּלְכַלָּתָהּ בָּנִים, וְיָלְדוּ הִיא וְכַלָּתָהּ שְׁנֵי זְכָרִים בְּמַחֲבוֹא, וְנִתְעָרְבוּ הַבָּנִים, וְגָדְלוּ הַתַּעֲרוֹבוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ; בְּנֵי הַכַּלָּה חוֹלְצִין לִשְׁתֵּיהֶן תְּחִלָּה, וְלֹא מְיַבְּמִין; וּבְנֵי הַזְּקֵנָה, אַחַר חֲלִיצַת בְּנֵי הַכַּלָּה, חוֹלְצִין אוֹ מְיַבְּמִין:\nמֵתוּ הַבָּנִים הַוַּדָּאִים שֶׁל הַזְּקֵנָה וְהַכַּלָּה, וְהַסְפֵקוֹת קַיָּמִים; הַסְפֵקוֹת לִנְשֵׁי בְּנֵי הַזְּקֵנָה חוֹלְצִין וְלֹא מְיַבְּמִין; וְלִנְשֵׁי בְּנֵי הַכַּלָּה, אֶחָד מֵהַסְפֵקוֹת חוֹלֵץ לָהּ תְּחִלָּה, וְהַשֵּׁנִי מְיַבֵּם:\nמִי שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ ג' חֳדָשִׁים, וְנִשֵּׂאת וְיָלְדָה, וְאֵין יָדוּעַ אִם הוּא בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן, וְהָיוּ לָהּ בָּנִים מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי, וְגָדַל הַסָפֵק וְנָשָׂא אִשָּׁה וָמֵת; בָּנֶיהָ מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי חוֹלְצִים וְלֹא מְיַבְּמִים; וְכֵן הַסָפֵק, לִנְשׁוֹתֵיהֶם חוֹלֵץ וְלֹא מְיַבֵּם. הָיוּ לָרִאשׁוֹן וְלַשֵּׁנִי, לְכָל אֶחָד, בֵּן מֵאִשָּׁה אַחֶרֶת, וּמֵתוּ, זֶה הַסָפֵק חוֹלֵץ אוֹ מְיַבֵּם לִנְשׁוֹתֵיהֶם. מֵת הַסָפֵק, אֶחָד מִשְּׁנֵי הַבָּנִים הַוַּדָּאִים חוֹלֵץ לָהּ תְּחִלָּה, וְהַשֵּׁנִי מְיַבֵּם:\nחָמֵשּׁ נָשִׁים שֶׁהָיָה לְכָל אַחַת בֵּן יָדוּעַ, וְיָלְדוּ כֻּלָּן בְּמַחֲבוֹא, כָּל אַחַת זָכָר, נִתְעָרְבוּ חֲמִשָּׁה הַוְּלָדוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ, וְנָפְלוּ נְשׁוֹתֵיהֶם לִפְנֵי חֲמִשָּׁה הַבָּנִים הַוַּדָּאִים, אַרְבָּעָה מֵהַוַּדָּאִים יַחְלְצוּ לְאַחַת, וְאַחַר כָּךְ יִשָּׂאֶנָּה הַחֲמִישִׁי. וְכֵן עוֹשִׂים לְכָל אַחַת וְאַחַת. וְאִם מֵת אֶחָד מֵהַבָּנִים הַוַּדָּאִים, אַרְבָּעָה הַסְפֵקוֹת יַחְלְצוּ לָהּ, וְאֶחָד יְיַבֵּם. הָיוּ קְצָת הַוַּדָּאִים כֹּהֲנִים, הַכֹּהֲנִים חוֹלְצִים וְלֹא מְיַבְּמִים, וְשֶׁאֵינָם כֹּהֲנִים מְיַבְּמִים. הָיוּ לִקְצָת הַוַּדָּאִים שֶׁיֵּשׁ לָהֶם בְּאֵלּוּ הַסְפֵקוֹת אַחִים מֵהָאֵם שֶׁלֹּא מֵהָאָב, וְגַם יֵשׁ לוֹ בָּהֶם אַחִים מֵהָאָב, \u0005(אַחִים מִן הָאֵם חוֹלְצִין, אַחִים מִן הָאָב מְיַבְּמִין מִקְצָתָן כֹּהֲנִים וּמִקְצָתָן אַחִים מִן הָאֵם, אֵלּוּ וָאֵלּוּ)\u0006 חוֹלְצִים וְלֹא מְיַבְּמִים:",[],["\u0003אין מוציאין אותם מידן\u0004. משום דכ\"א יאמר אני כנסתי את היבמה ואת\"ל שלא כנס היבמה מ\"מ אחר שכנס השני פקע הזיקה ומדייק הרא\"ש דוקא כשכל א' י\"ל אני כנסתי היבמה אבל המייבם אחות זקוקתו יוציא אף לדעת תוס' דס\"ל אם כנס לחופה אל יוציא כמ\"ש בס\"ס קנ\"ט דשם בתחלה קידש אותה ולא בא עליה באיסור ואפשר לומר אפי' אם ליתא כאן אלא אח א' וכנס לאחת ולא חלץ לשני' לא יוציא די\"ל ג\"כ דידי כנסתי ואף את\"ל דלא כנס דידיה מ\"מ פקע הזיקה כיון שכנס אחותה אף על גב שכנס באיסור מ\"מ י\"ל בכה\"ג די\"ל שכנס היבמה לא יוציא מיהו למה שדייק הנ\"י במתניתין דלא תנא באח א' אם כנס לא יוציא היינו שחלץ לא' וכנס לא' לא יוציא דשמא כנס היבמה א\"כ חליצה זו לאו כלום דהא חלץ לשאינה יבמתו מזה דייק אף בכה\"ג יוציא אף על פי שהיא ספק אחות חלוצתו מ\"מ גזרו חז\"ל בחליצה כמו בגרושתו מזה נראה אם כנס בלא חליצה יוציא דאל\"כ אכתי קשה למה לא תנא אם כנס אל יוציא ונראה מכ\"ש אם כנס אחת ואח\"כ חלץ דיוציא דאל\"כ אכתי קשה למה לא תנא אל יוציא גם כאן בתחלה באיסור כנס, ואפשר השתא נמי איסור והכניס' היא אינה יבמתו א\"כ היא אחות חלוצתו ומ\"ש ב\"ח בזה אנ\"ל:","\u0003יוציא\u0004. הטעם הוא כמ\"ש בסק\"א כיון שעבר ועשה איסור מזה מוכח מ\"ש בסימן הקודם בסעיף ג' בשם הטור אין מוציאים ליתא כמ\"ש בב\"ח שם דהא הכא כתב להדיא עבר וייבם יוציא אף על גב בפרישה מחלק ביניהם אנ\"ל ואפילו אם הסכימו שניהם שייבם כ\"א אחת מ\"מ באיסור כנס ול\"ד לדינים שבכאן שנאמר בהם אל יוציא משום דיש לומר שמא דידי כנסתי:","\u0003חולצים ולא מייבמים\u0004. אחיו של הראשון חולץ מדאורייתא ואין מייבם מדרבנן דהא היא כאנוסה, ואחיו של שני חולץ מדרבנן ואין מייבם לא מדאורייתא ולא מדרבנן:"],"\u0010g0\u0011 מִי שֶׁקִּדֵּשׁ אַחַת מִשְּׁתֵּי אֲחָיוֹת, וְאֵינוֹ יוֹדֵעַ אֵיזוֹ \u0010g1\u0011 קִדֵּשׁ, אֲפִלּוּ לֹא הֻכְּרוּ מֵעוֹלָם, שֶׁלֹּא נִתְּנוּ לְבִיאָה, הֲווֹ קִדּוּשִׁין וְצָרִיךְ גֵּט לְכָל אַחַת וְאַחַת. מֵת, וְלוֹ אָח, חוֹלֵץ לִשְׁתֵּיהֶן. הָיוּ לוֹ שְׁנֵי אַחִים, אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ שְׁנֵי הָאַחִים וְכָנְסוּ אֶת \u0010c0\u0011 \u0010g2\u0011 שְׁתֵּיהֶן, אֵין מוֹצִיאִים \u0010r0\u0011 אוֹתָן מִיָּדָם. וְאִם נִמְלְכוּ בְּבֵית דִּין וְאָמְרוּ לָהֶם שֶׁיַּחֲלֹץ הָאֶחָד וִיְיַבֵּם הַשֵּׁנִי, \u0010g3\u0011 וְהָלְכוּ שְׁנֵיהֶם וְיִבְּמוּ, יוֹצִיאוּ: \u0010g4\u0011 \u0010r1\u0011\nמִי שֶׁעָבַר וְיִבֵּם וַדַּאי אֲחוֹת זְקוּקָתוֹ, \u0010c1\u0011 יוֹצִיא: \u0010g5\u0011\nשְׁנַיִם שֶׁקִּדְּשׁוּ שְׁתֵּי אֲחָיוֹת, זֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ וְזֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ, וּמֵתוּ, לְזֶה אָח וּלְזֶה אָח, כָּל אֶחָד חוֹלֵץ לִשְׁתֵּיהֶן; וְאֵין שׁוּם אֶחָד מֵהֶם יָכוֹל לְיַבֵּם. לְזֶה אֶחָד וּלְזֶה שְׁנַיִם; הַיָּחִיד חוֹלֵץ לִשְׁתֵּיהֶן; וְהַשְּׁנַיִם, אֶחָד חוֹלֵץ \u0010r2\u0011 לְאַחַת תְּחִלָּה, וְאַחַר כָּךְ יְיַבֵּם הַשֵּׁנִי לַשְּׁנִיָּה. וְאִם קָדְמוּ הַשְּׁנַיִם וְכָנְסוּ אַחַר שֶׁחָלַץ הַיָּחִיד, אֵין מוֹצִיאִים מִיָּדָם, \u0010g6\u0011 אֲפִלּוּ שְׁנֵיהֶם כֹּהֲנִים. \u0010g7\u0011 הָיוּ לְזֶה שְׁנֵי אַחִים וּלְזֶה שְׁנֵי אַחִים, אָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאַחַר כָּךְ הָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה, וָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה. אִם קָדְמוּ שְׁנֵי הָאַחִים שֶׁל הָאֶחָד וְחָלְצוּ לִשְׁתֵּיהֶן, לֹא יְיַבְּמוּ הַשְּׁנֵי אַחִים הָאֲחֵרִים שֶׁל הַשֵּׁנִי לִשְׁתֵּיהֶן, אֶלָּא אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ הַשְּׁנַיִם הָאַחֲרוֹנִים וְכָנְסוּ אַחַר שֶׁחָלְצוּ הַשְּׁנַיִם הָרִאשׁוֹנִים, אֵין מוֹצִיאִין מִיָּדָם: \u0010g8\u0011\nמִי שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְשָׁמְעוּ שֶׁמֵּת, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא בַּעְלָהּ, וּמֵתוּ שְׁנֵיהֶם, לְזֶה אָח וּלְזֶה אָח, אָחִיו שֶׁל זֶה וְשֶׁל זֶה \u0010c2\u0011 חוֹלְצִים וְלֹא מְיַבְּמִים. \u0005 וְדִין צָרָתָהּ, עַיֵּן לְעֵיל סִי' קע\"ג סָעִיף י\"א: \u0010g9\u0011 \u0006\nהָאִשָּׁה שֶׁהָיוּ לָהּ בָּנִים וּלְכַלָּתָהּ בָּנִים, וְיָלְדוּ הִיא וְכַלָּתָהּ שְׁנֵי זְכָרִים בְּמַחֲבוֹא, וְנִתְעָרְבוּ הַבָּנִים, וְגָדְלוּ הַתַּעֲרוֹבוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ; בְּנֵי הַכַּלָּה חוֹלְצִין לִשְׁתֵּיהֶן תְּחִלָּה, וְלֹא מְיַבְּמִין; וּבְנֵי הַזְּקֵנָה, אַחַר חֲלִיצַת בְּנֵי הַכַּלָּה, חוֹלְצִין אוֹ מְיַבְּמִין: \u0010g10\u0011\nמֵתוּ הַבָּנִים הַוַּדָּאִים שֶׁל הַזְּקֵנָה וְהַכַּלָּה, וְהַסְפֵקוֹת קַיָּמִים; הַסְפֵקוֹת לִנְשֵׁי בְּנֵי הַזְּקֵנָה חוֹלְצִין וְלֹא מְיַבְּמִין; וְלִנְשֵׁי בְּנֵי הַכַּלָּה, אֶחָד מֵהַסְפֵקוֹת חוֹלֵץ לָהּ \u0010r3\u0011 תְּחִלָּה, וְהַשֵּׁנִי \u0010g11\u0011 מְיַבֵּם:\nמִי שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ ג' חֳדָשִׁים, וְנִשֵּׂאת וְיָלְדָה, וְאֵין יָדוּעַ אִם הוּא בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן, וְהָיוּ לָהּ בָּנִים מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי, וְגָדַל הַסָפֵק וְנָשָׂא אִשָּׁה וָמֵת; בָּנֶיהָ מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי \u0010g12\u0011 חוֹלְצִים וְלֹא מְיַבְּמִים; וְכֵן הַסָפֵק, לִנְשׁוֹתֵיהֶם חוֹלֵץ וְלֹא מְיַבֵּם. הָיוּ לָרִאשׁוֹן וְלַשֵּׁנִי, לְכָל אֶחָד, בֵּן מֵאִשָּׁה אַחֶרֶת, וּמֵתוּ, \u0010g13\u0011 זֶה הַסָפֵק חוֹלֵץ אוֹ מְיַבֵּם לִנְשׁוֹתֵיהֶם. מֵת הַסָפֵק, אֶחָד מִשְּׁנֵי הַבָּנִים הַוַּדָּאִים חוֹלֵץ לָהּ \u0010r4\u0011 תְּחִלָּה, \u0010g14\u0011 וְהַשֵּׁנִי \u0010g15\u0011 מְיַבֵּם:\nחָמֵשּׁ נָשִׁים שֶׁהָיָה לְכָל אַחַת בֵּן יָדוּעַ, וְיָלְדוּ כֻּלָּן בְּמַחֲבוֹא, כָּל אַחַת זָכָר, נִתְעָרְבוּ חֲמִשָּׁה הַוְּלָדוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ, וְנָפְלוּ נְשׁוֹתֵיהֶם לִפְנֵי חֲמִשָּׁה הַבָּנִים הַוַּדָּאִים, אַרְבָּעָה מֵהַוַּדָּאִים יַחְלְצוּ לְאַחַת, וְאַחַר כָּךְ \u0010g16\u0011 יִשָּׂאֶנָּה הַחֲמִישִׁי. וְכֵן עוֹשִׂים לְכָל אַחַת וְאַחַת. \u0010g17\u0011 וְאִם מֵת אֶחָד מֵהַבָּנִים הַוַּדָּאִים, אַרְבָּעָה הַסְפֵקוֹת יַחְלְצוּ לָהּ, וְאֶחָד יְיַבֵּם. \u0010g18\u0011 הָיוּ קְצָת הַוַּדָּאִים כֹּהֲנִים, הַכֹּהֲנִים חוֹלְצִים וְלֹא מְיַבְּמִים, וְשֶׁאֵינָם כֹּהֲנִים \u0010g19\u0011 מְיַבְּמִים. הָיוּ לִקְצָת הַוַּדָּאִים שֶׁיֵּשׁ לָהֶם בְּאֵלּוּ הַסְפֵקוֹת אַחִים מֵהָאֵם \u0010g20\u0011 שֶׁלֹּא מֵהָאָב, וְגַם יֵשׁ לוֹ בָּהֶם אַחִים מֵהָאָב, \u0010g21\u0011 \u0005(אַחִים מִן הָאֵם חוֹלְצִין, אַחִים מִן הָאָב מְיַבְּמִין מִקְצָתָן כֹּהֲנִים וּמִקְצָתָן אַחִים מִן הָאֵם, אֵלּוּ וָאֵלּוּ)\u0006 חוֹלְצִים וְלֹא מְיַבְּמִים:",{"g":["משנה יבמות דף כג ע\"ב","אע\"ג דשם בגמרא אוקימנ' למתני' בהוכרו ולבסוף נתערבו ההוא אוקימת' אליב' דרבא הוא דאמר קידושין שאינם נמסרים לביא' לא הוו קידושין ולי' הלכתא כוותיה דקי\"ל כאביי ביע\"ל קג\"ם והא חדא מינייהו ונפשטה ממתני' הרי\"ף והרא\"ש","דכל חד וחד אמר אנא שפיר נסיבי ואי נמי הוי איפכא שהראשון ייבם אחות זקיקתו ההיא שעתא הויא ודאי אסור' ומשבא אחיו וייבם השני' שהוא יבמתו פקע זיקה מאידך למפרע","טור בשם אביו הרא\"ש בפסקיו כיון שעברו על דברי ב\"ד","שם ושם וכ\"כ התוס' שם במשנה בשם ר\"י","שם במשנ'","תני שיל' שם דף כ\"ד ע\"א וכדמפרש טעמ' שם דחלוצה דרבנן היא וקרא אסמכת' בעלמא הוא וספק חליצה לא גזרו בהו רבנן","שם במשנה","משנה שם ד' פז ע\"ב ומפרש שם בגמ' דף לא ע\"א אחיו של ראשין חולץ מדאוריית' ולא מייבם מדרבנן אחיו של שני חולץ מדרבנן ולא מייבם לא מדאוריי' ולא מדרבנן","משנ' שם דצ\"ט ע\"א ומפורש שם במשנה","שם במשנה","משנה שם דף ק' ע\"א","דלכל אחד הוא ספק אחיו מן האם ולא מן האב וזו עליהם בכרת וכן הוא לנשותיהן רש\"י","ממ\"נ אם אחיו הוא הרי טוב ואם לאו נכרית הוא אצלו וכגון שאין אח אלא הוא דליכא לספק ביבמה לשוק רש\"י","ממ\"נ אם יבמתו היא הרי טוב ואם לאו נכרי' היא ומשום יבמה לשוק ליכא שהרי חלץ לה יבמה רש\"י","משנה שם דף ע\"ב","ממ\"נ אם אשת אחיו היא הרי טוב ואם לאו הרי חלץ לה יבמה ומפרש בגמר' שם דהא דלא מייבם חד לכולהו דלמא מתרמי' לכל חד וחד יבמה דידי' ומקיימי מצות ייבום","טור","ברייתא שם כמ\"ש התוס'","שח","\u0003פי' שלא מן האב לבד האחי' שיש להם בתוכן מן האב כגון ראובן שנש' וכו'\u0004 ע' שם בפירש\"י או בטור","כצ\"ל וכן הוא שם בגמ' גם בכל הטורים שנדפסו יש שם חסרון בדין זה"],"r":["\u0003ואם נמלכו כו'. \u0004 ירושלמי גבי לקטן על השפחה א\"ל שלא יכנוס וכנס מוציאין מידו:","\u0003מי שעבר כו'. \u0004 מתניתין רפ\"ג וכמש\"ש ך\"ג ב' מ\"ש מהא כו' הכא כל חד כו' ועתוס' שם ד\"ה קדמו כו' אר\"י כו' והוצרכו לזה לפי שיטתם שפי' בד\"ה ומ\"ש כולי ואר\"י כולי. תוספת שם ולדברי רש\"י שם גמ' ערוכ' אבל לדברי תוספת שם ד\"ה ומ\"ש י\"ל דל\"ק כלל דשם יוציאו משום דכל שאין אני קורא לה יבמה יבא עליה ה\"ה כאשת אח כו' וה\"ה כאן מדרבנן משא\"כ בנכרית אבל מ\"מ החילוק בין ודאי אחות זקוקתו דיוציאו ובין ספק דיקיים אף בנופלת לייבום מבואר בגמרא כ\"ט א' בשלמא ראשונה כו' אלא כו' אבל בכה\"ג דבודאי יוציא אינו מבואר ולמד תוס' מדתנא במתניתין בסוף פ\"ק מ\"ש דבודאי יוציא ומה שכתב במתני' דריש פרק ד' אחין באשת אח הנופלת לאשמעי' כחו דר\"א אליבא דב\"ש:","\u0003תחלה גמרא שם וגם היחיד חולץ תחלה. \u0004 שם וכן בס\"א:","\u0003תחלה. \u0004 גמ' שם:","\u0003תחלה גמ' שם:\u0004 "]}],["\u0010c0\u0011 הַמְפַתֶּה בְּתוּלַת יִשְׂרָאֵל \u0005 עַד שֶׁלֹּא תִּבָּגֵר, וְהִיא מִבַּת שְׁלשָׁה וְאֵילָךְ \u0006 \u0005(טוּר הָרֹא\"שׁ)\u0006, מְשַׁלֵּם בֹּשֶת וּפְגָם וּקְנָס. \u0010c1\u0011 וְאִם אֲנָסָהּ, מְשַׁלֵּם עוֹד צַעַר. \u0005 וְאִם נְשָׂאָהּ הַמְפַתֶּה, אֵינוֹ צָרִיךְ לִתֵּן קְנָס \u0006 \u0005(טוּר)\u0006:\nאוֹנֵס וּמְפַתֶּה, דָּנִין אוֹתָהּ בִּשְׁלשָׁה דַּיָּנִים, וּבִלְבַד שֶׁיִּהְיוּ סְמוּכִים בְּאֶרֶץ יִשְׂרָאֵל. וְהָאִדָּנָא שֶׁאֵין סְמוּכִים, מְנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ; וְכַד יָהִיב לֵהּ שִׁעוּר מַאי דְּחָזֵי לְמֵיהַב, שָׁרִינָן לֵהּ. \u0005 וְהַבַּת, כָּל זְמַן שֶׁהִיא בִּרְשׁוּת אָבִיהָ, הַכֹּל לְאָבִיהָ \u0006 \u0005(גַּם זֶה שָׁם)\u0006. \u0005 וְעַיֵּן בְּטוּר סִימָן זֶה שֶׁהֶאֱרִיךְ בְּדִינִים אֵלּוּ, וְהָרַב הַמְחַבֵּר קִצֵּר בָּהֶם, שֶׁאֵינָם שְׁכִיחִין: \u0006\nהָאוֹנֵס אֶת הַבְּתוּלָה, חַיָּב לִשָּׂא אוֹתָהּ, וּבִלְבַד שֶׁהִיא וְאָבִיהָ יִהְיוּ מְרֻצִּים, אֲפִלּוּ הִיא חִגֶּרֶת אוֹ סוּמָא, וְאֵינוֹ רַשַּׁאי לְהוֹצִיאָהּ לְעוֹלָם אֶלָּא לִרְצוֹנָהּ. לְפִיכָךְ, אֵינוֹ צָרִיךְ לִכְתֹּב לָהּ כְּתֻבָּה. וְאִם עָבַר וְהוֹצִיאָהּ, כּוֹפִין אוֹתוֹ לְהַחֲזִירָהּ:\nהָיְתָה אֲסוּרָה לוֹ, \u0010c2\u0011 אֲפִלּוּ אִסוּר דְּרַבָּנָן, אֵינוֹ רַשַּׁאי לִשָּׂא אוֹתָהּ. וְכֵן אִם נְשָׂאָהּ וּמָצָא בָּהּ \u0010c3\u0011 עֶרְוַת דָּבָר, \u0010c4\u0011 יְגָרְשֶׁנָּה. \u0005 הַגָּה: יָצָא עָלֶיהָ שֵׁם רַע, כְּגוֹן שֶׁבָּאוּ שְׁנַיִם וְהֵעִידוּ עָלֶיהָ שֶׁתְּבָעָתוֹ לִזְנוּת, אֵין לָהּ קְנָס. אֲבָל מִשּׁוּם קוֹל בְּעָלְמָא עַל שֵׁם רַע שֶׁיָּצָא עָלֶיהָ, לֹא הִפְסִידָה הַקְּנָס \u0006 \u0005(טוּר)\u0006. \u0005 בָּא עָלֶיהָ \u0010c5\u0011 בְּאֹנֶס וְאַחַר כָּךְ פִּתָּה אוֹתָהּ, מִקְּרֵי מְאָנֵס, אַף עַל גַּב דְּאַחַר כָּךְ נִתְרַצֵּית לוֹ \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קכ\"ט)\u0006:\nהַנִּטְעָן עַל הַפְּנוּיָה, יֵשׁ אוֹמְרִים שֶׁלֹּא לִכְנֹס מִשּׁוּם לְזוּת שְׂפָתַיִם, שֶׁנִּרְאֶה שֶׁמַּחֲזִיקִים הַקּוֹל. וְיֵשׁ אוֹמְרִים שֶׁמִּצְוָה לִכְנֹס. \u0005 הַגָּה: וְהַסְּבָרָא רִאשׁוֹנָה עִקָּר. וּבְמָקוֹם שֶׁיֵּשׁ לָחוּשׁ שֶׁלֹּא תֵּצֵא לְתַרְבּוּת רָעָה, מֻתָּר לְכָנְסָהּ. וְכָל זֶה בְּקוֹל בְּעָלְמָא, אֲבָל אִם וַדַּאי בָּא עָלֶיהָ, מִצְוָה לְכָנְסָהּ, אֲבָל \u0010c6\u0011 אֵין כּוֹפִין עַל כָּךְ \u0006 \u0005(שָׁם)\u0006. \u0005 וְאִם נִטְעֶנֶת מִשְּׁנַיִם, מֵרִאשׁוֹן אֵינוֹ אֶלָּא קוֹל בְּעָלְמָא, וְהַשֵּׁנִי הוֹסִיף בִּפְגָמָהּ, הַשֵּׁנִי מִצְוָה לְכָנְסָהּ. וְאִם נִטְעֶנֶת מִשְּׁנֵיהֶם בְּשָׁוֶה, הָאֶחָד נָשׂוּי וְהַשֵּׁנִי אֵינוֹ נָשׂוּי, מִצְוָה עַל שֶׁאֵינוֹ נָשׂוּי לְכָנְסָהּ \u0006 \u0005(ג\"ז שָׁם)\u0006. \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב אִם הִיא נֶאֱמֶנֶת עָלָיו. \u0010c7\u0011 זוֹנָה \u0006 \u0005 שֶׁתָּבְעָה לְאֶחָד שֶׁנָּדַר לָהּ דָּבָר בְּאֶתְנָנָהּ, וְהוּא כּוֹפֵר, צָרִיךְ לִשָּׁבַע כְּמוֹ בִּשְׁאָר תְּבִיעוֹת \u0006 \u0005(רִיבָ\"שׁ סִי' מ\"א)\u0006. \u0005 זֶהוּ שֶׁחִיְּבָה תּוֹרָה לְאוֹנֵס וּמְפַתֶּה מָמוֹן, הַיְנוּ אִם כְּבָר נַעֲשָׂה הַמַּעֲשֶׂה בְּמִקְרֶה, אֲבָל אָסוּר לָאָב לִתֵּן בִּתּוֹ לִזְנוּת, וְעַל זֶה נֶאֱמַר: \"אַל תְּחַלֵּל אֶת בִּתְּךְ לְהַזְנוֹתָהּ\" \u0010c8\u0011 \u0006 \u0005(וַיִּקְרָא יט, כט)\u0006 \u0005 וְכָל הַמְּכִינָה עַצְמָהּ לִזְנוּת, בֵּין מִדַּעְתָּהּ בֵּין מִדַּעַת אָבִיהָ, הֲרֵי זוֹ קְדֵשָׁה, וְאֵין חִלּוּק בָּזֶה בֵּין בְּתוּלָה לִבְעוּלָהּ \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0005 וְרַשָּׁאִין הַבֵּית דִּין לִקְנֹס הַזּוֹנוֹת, כְּדֵי לַעֲשׂוֹת גָּדֵר. וּמַעֲשֶׂה בְּאַחַת שֶׁזָּנְתָה עִם הַכּוּתִי, וְחָתְכוּ אֶת חָטְמָהּ, כְּדֵי לְנַוְּלָהּ \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ח)\u0006:",[],["\u0003המפתה וכו'\u0004. קנס איתא דוקא בבתולה ולו תהיה לאשה משמע נמי דוקא בבתולה אבל בושת משמע ברמב\"ם אפילו בבעולה דהא כתב באו עליה שנים אחד כדרכה והשני שלא כדרכה חייב השני בבושת אף על גב דכבר היא בעולה מראשון ומפותה דקרא איירי כשמפתה לשם אישות כמ\"ש בקידושין דף מ\"ו ובמהרי\"ק שורש קכ\"ט ומ\"מ יכולה למאן וא\"צ לישא אותה ופטור ג\"כ מקנס ובושת ופגם כשהיא יתומה ולא אמרי' מחילה בטעות דנתרצה את עצמה כדי שישא אחותה ע\"ש במהרי\"ק:","\u0003ואם אנסה\u0004. עיין ברמב\"ם ובטור אם ראו עדים מרחוק שבעל אותה וא\"י אם אנוסה היא או מפותה אמרינן בשדה מסתמא אנוסה היא ובעיר מסתמא מפותה היא והט\"ז רוצה ליישב דברי הרמב\"ם דאיירי דליכא כאן העדים שראו הביאה ולא אמרינן בכה\"ג מודה בקנס פטור כיון דמודה מחמת ביעתותא כראב\"ש בפרק מרובה (בבא קמא דף ע\"ה) והלכתא כוותי' דשמואל ס\"ל כוותי' וע\"ש וליתא כי שמואל אינו מחלק בין ביעתות' אלא יבואו העדים ויעידו אלא רב מתרץ כן אנא דאמרי לראב\"ש והלכה כרב לענין מודה ואח\"כ באו עדים כמו שכתב הרמב\"ם פ\"ג מה\"ג ובפלוגת' זו מחמת ביעתותא מסתמ' הלכה כת\"ק דפטור משום הכי לא מחלק הרמב\"ם שם:","\u0003איסור דרבנן\u0004. אשה אסור' ממועט מקרא ולו תהי' לאשה אשה הראיי' לו ואם אסורה מדרבנן אף על גב מדאורייתא אשה ראויה היא מ\"מ מדכתיב ושמרתם את משמרתי מצאו חכמים מקום לאסור שניו' שפיר י\"ל דממועט מקרא ולו תהי' לאשה ובלאו הכי כיון דכל מילי דרבנן אסמכינהו אלאו לא תסיר שפיר א\"ל דשניה ממועט מקרא ולו תהי' לאשה ב\"י:","\u0003ערות דבר\u0004. היינו ערוה ממש ולאו ערות דבר כמ\"ש בסי' קי\"ט אפי' דבר בלא ערוה אלא כאן דוקא ערוה, פרישה:","\u0003יגרשנ'\u0004. כ\"כ הרמב\"ם פ\"א ומשמע דצריך לגרשה ובטור אית' יכול לגרשה משמע אם אין רוצה לגרשה לא כפינן ליה ועיין ב\"ח:","\u0003ואח\"כ פתה אותה\u0004. הן בביא' אם היתה בתחל' באונס ואח\"כ ברצון הן אם פ\"א בא עלי' באונס ואח\"כ ברצון חייב מחמת ביאה הראשונה אף על גב דנתרצית אח\"כ:","\u0003אין כופין על כך\u0004. דקי\"ל מפותה בין היא ובין הוא יכולים לעכב ואם נטען שאנס אות' דאז הוא א\"י לעכב מ\"מ אין כופין אותו כיון דאינו אלא חשד אבל אם בוודאי בא עליה כופין אותו בזה יש חילוק בין אונס למפת':","\u0003זונה שתבעה לאחד\u0004. ואם נדר לזונה שהי' לו חייבי מיתות ב\"ד אז פטור לשלם ע\"פ הדין מ\"מ אין יוצא ידי שמים עד שישלם לה ואם תפסה אין מוציאין ממנה רש\"י פ' האומנים:","\u0003וכל המכינ' עצמה וכו'\u0004. לכאור' סותר למ\"ש בסי' ט\"ז דכאן משמע דוקא כשהוא מוכנת לזנות עם כל אדם הוי קדשה ועיין מ\"ש שם:"],"\u0010c0\u0011 \u0010g0\u0011 \u0010r0\u0011 הַמְפַתֶּה \u0010r1\u0011 בְּתוּלַת \u0010t0\u0011 \u0010r2\u0011 יִשְׂרָאֵל \u0010r3\u0011 \u0005 עַד שֶׁלֹּא תִּבָּגֵר, וְהִיא מִבַּת שְׁלשָׁה וְאֵילָךְ \u0010g1\u0011 \u0006 \u0005(טוּר הָרֹא\"שׁ)\u0006, מְשַׁלֵּם בֹּשֶת וּפְגָם וּקְנָס. \u0010c1\u0011 וְאִם \u0010t1\u0011 אֲנָסָהּ, מְשַׁלֵּם עוֹד \u0010t2\u0011 צַעַר. \u0010r4\u0011 \u0005 וְאִם נְשָׂאָהּ הַמְפַתֶּה, אֵינוֹ צָרִיךְ לִתֵּן קְנָס \u0010g2\u0011 \u0010g3\u0011 \u0006 \u0005(טוּר)\u0006:\nאוֹנֵס וּמְפַתֶּה, דָּנִין אוֹתָהּ \u0010r5\u0011 בִּשְׁלשָׁה דַּיָּנִים, וּבִלְבַד שֶׁיִּהְיוּ \u0010r6\u0011 סְמוּכִים \u0010g4\u0011 \u0010r7\u0011 בְּאֶרֶץ יִשְׂרָאֵל. וְהָאִדָּנָא שֶׁאֵין סְמוּכִים, מְנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ; וְכַד יָהִיב לֵהּ שִׁעוּר מַאי דְּחָזֵי לְמֵיהַב, שָׁרִינָן \u0010r8\u0011 לֵהּ. \u0005 וְהַבַּת, כָּל זְמַן שֶׁהִיא בִּרְשׁוּת אָבִיהָ, הַכֹּל לְאָבִיהָ \u0006 \u0005(גַּם זֶה שָׁם)\u0006. \u0005 וְעַיֵּן בְּטוּר סִימָן זֶה שֶׁהֶאֱרִיךְ בְּדִינִים אֵלּוּ, וְהָרַב הַמְחַבֵּר קִצֵּר בָּהֶם, שֶׁאֵינָם שְׁכִיחִין: \u0010g5\u0011 \u0006\nהָאוֹנֵס אֶת הַבְּתוּלָה, חַיָּב לִשָּׂא אוֹתָהּ, \u0010g6\u0011 וּבִלְבַד שֶׁהִיא וְאָבִיהָ יִהְיוּ \u0010g7\u0011 מְרֻצִּים, אֲפִלּוּ הִיא חִגֶּרֶת אוֹ סוּמָא, \u0010r9\u0011 וְאֵינוֹ רַשַּׁאי לְהוֹצִיאָהּ לְעוֹלָם אֶלָּא לִרְצוֹנָהּ. \u0010g8\u0011 לְפִיכָךְ, אֵינוֹ צָרִיךְ לִכְתֹּב לָהּ \u0010g9\u0011 \u0010r10\u0011 כְּתֻבָּה. וְאִם עָבַר וְהוֹצִיאָהּ, \u0010r11\u0011 כּוֹפִין אוֹתוֹ לְהַחֲזִירָהּ: \u0010g10\u0011\nהָיְתָה אֲסוּרָה לוֹ, \u0010c2\u0011 \u0010g11\u0011 \u0010t3\u0011 \u0010r12\u0011 אֲפִלּוּ אִסוּר דְּרַבָּנָן, אֵינוֹ רַשַּׁאי לִשָּׂא אוֹתָהּ. \u0010g12\u0011 וְכֵן אִם נְשָׂאָהּ וּמָצָא בָּהּ \u0010c3\u0011 עֶרְוַת דָּבָר, \u0010c4\u0011 יְגָרְשֶׁנָּה. \u0005 הַגָּה: \u0010r13\u0011 יָצָא עָלֶיהָ שֵׁם רַע, כְּגוֹן שֶׁבָּאוּ שְׁנַיִם וְהֵעִידוּ עָלֶיהָ שֶׁתְּבָעָתוֹ לִזְנוּת, אֵין לָהּ קְנָס. אֲבָל מִשּׁוּם קוֹל בְּעָלְמָא עַל שֵׁם רַע שֶׁיָּצָא עָלֶיהָ, לֹא הִפְסִידָה הַקְּנָס \u0006 \u0005(טוּר)\u0006. \u0010r14\u0011 \u0005 בָּא עָלֶיהָ \u0010c5\u0011 בְּאֹנֶס וְאַחַר כָּךְ פִּתָּה אוֹתָהּ, מִקְּרֵי מְאָנֵס, אַף עַל גַּב דְּאַחַר כָּךְ נִתְרַצֵּית לוֹ \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קכ\"ט)\u0006: \u0010g13\u0011\nהַנִּטְעָן עַל הַפְּנוּיָה, יֵשׁ אוֹמְרִים שֶׁלֹּא לִכְנֹס מִשּׁוּם לְזוּת שְׂפָתַיִם, שֶׁנִּרְאֶה שֶׁמַּחֲזִיקִים הַקּוֹל. \u0010g14\u0011 \u0010r15\u0011 וְיֵשׁ אוֹמְרִים שֶׁמִּצְוָה לִכְנֹס. \u0005 הַגָּה: \u0010r16\u0011 וְהַסְּבָרָא רִאשׁוֹנָה \u0010r17\u0011 עִקָּר. וּבְמָקוֹם שֶׁיֵּשׁ לָחוּשׁ שֶׁלֹּא תֵּצֵא לְתַרְבּוּת רָעָה, \u0010r18\u0011 מֻתָּר לְכָנְסָהּ. וְכָל זֶה בְּקוֹל בְּעָלְמָא, אֲבָל אִם וַדַּאי בָּא עָלֶיהָ, מִצְוָה \u0010r19\u0011 לְכָנְסָהּ, אֲבָל \u0010c6\u0011 אֵין כּוֹפִין עַל כָּךְ \u0006 \u0005(שָׁם)\u0006. \u0010r20\u0011 \u0005 וְאִם נִטְעֶנֶת מִשְּׁנַיִם, מֵרִאשׁוֹן אֵינוֹ אֶלָּא קוֹל בְּעָלְמָא, וְהַשֵּׁנִי הוֹסִיף בִּפְגָמָהּ, הַשֵּׁנִי מִצְוָה \u0010r21\u0011 לְכָנְסָהּ. וְאִם נִטְעֶנֶת מִשְּׁנֵיהֶם בְּשָׁוֶה, הָאֶחָד נָשׂוּי וְהַשֵּׁנִי אֵינוֹ נָשׂוּי, מִצְוָה עַל שֶׁאֵינוֹ נָשׂוּי לְכָנְסָהּ \u0006 \u0005(ג\"ז שָׁם)\u0006. \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב אִם הִיא נֶאֱמֶנֶת עָלָיו. \u0010c7\u0011 \u0010r22\u0011 זוֹנָה \u0010t4\u0011 \u0006 \u0005 שֶׁתָּבְעָה לְאֶחָד שֶׁנָּדַר לָהּ דָּבָר בְּאֶתְנָנָהּ, וְהוּא כּוֹפֵר, צָרִיךְ לִשָּׁבַע כְּמוֹ בִּשְׁאָר תְּבִיעוֹת \u0006 \u0005(רִיבָ\"שׁ סִי' מ\"א)\u0006. \u0010r23\u0011 \u0005 זֶהוּ שֶׁחִיְּבָה תּוֹרָה לְאוֹנֵס וּמְפַתֶּה מָמוֹן, הַיְנוּ אִם כְּבָר נַעֲשָׂה הַמַּעֲשֶׂה בְּמִקְרֶה, אֲבָל אָסוּר לָאָב לִתֵּן בִּתּוֹ לִזְנוּת, וְעַל זֶה נֶאֱמַר: \"אַל תְּחַלֵּל אֶת בִּתְּךְ לְהַזְנוֹתָהּ\" \u0010c8\u0011 \u0006 \u0005(וַיִּקְרָא יט, כט)\u0006 \u0005 וְכָל הַמְּכִינָה עַצְמָהּ לִזְנוּת, בֵּין מִדַּעְתָּהּ בֵּין מִדַּעַת אָבִיהָ, הֲרֵי זוֹ קְדֵשָׁה, \u0010r24\u0011 וְאֵין חִלּוּק בָּזֶה בֵּין בְּתוּלָה לִבְעוּלָהּ \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0010r25\u0011 \u0005 וְרַשָּׁאִין הַבֵּית דִּין לִקְנֹס הַזּוֹנוֹת, כְּדֵי לַעֲשׂוֹת גָּדֵר. וּמַעֲשֶׂה בְּאַחַת שֶׁזָּנְתָה עִם הַכּוּתִי, וְחָתְכוּ אֶת חָטְמָהּ, כְּדֵי לְנַוְּלָהּ \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ח)\u0006:",{"g":["משנה כתובות דל\"ט ע\"א","וכ\"כ הרמב\"ם בפ\"א מה' נערה כחכמים בברייתא שם דף מ' ע\"ב ואע\"ג דסתם מתני' כוותיה דר\"מ הוכיח הרי\"ף דלא ס\"ל מדאמרי' בגמ' זו דברי ר\"מ וכו' ועוד שאר ראיות והעתיקו הרא\"ש בפסקיו וסיים וכמו שפסק הרי\"ף נראה דאין סתם משנה כנגד דברי האמוראי'","ממשנה ובברייתא שם ע\"א וע\"ב ובושת ופגם נותן מיד לאביה","משנה ריש סנהדרין וכדמפרש שם בגמ'","טור בשם הרי\"ף ורב צמח גאון","משנה כתובות דל\"ט ע\"ב בריי' שם","בריי' שם מ\"ב","שם במשנה","כת\"ק בבריי' שם ע\"ב דאמר ואם מת יצא כסף קנסה בכתובת'","בריית' מכות דט\"ז ע\"א","שם משנה בכתובות ולו תהיה לאשה אשה הראוי לו וגמ' ד\"מ ע\"א","טור וכ\"כ הרמב\"ם בפ\"א וכ' הנ\"מ שם שטעמו כיון דכל מלה דרבנן אסמכינהו אלאו דלא תסור שפיר איכ' למימר דשני' אמעיט' מולו תהי' לאשה","שם במשנה","\u0003טור בשם אביו הרא\"ש בפ\"ב דיבמות מימר' דר' אסי הסר ממך עקשות פה וכו'\u0004 שם דכ\"ד ע\"ב","שם וכ\"כ התוספת שם בשם ר\"י"],"t":["\u0003ישראל. \u0004 קנס איתא דוקא בבתולה. אבל בושת איתא אפי' בבעולה:","\u0003אנסה. \u0004 אם ראו עדים מרחוק שבעל אותה וא\"י אם אנוסה היא או מפותה אמרינן בשדה מסתמא אנוסה היא ובעיר מסתמא מפותה היא. הרמב\"ם. והראב\"ד חלק עליו ע\"ש ועיין כנה\"ג. ועיין בתשובת חכם צבי שאלה קמ\"ה קמ\"ו:","\u0003צער. \u0004 ראובן שקם על בת רעהו בהיותה יחידה בבית לאנסה בחיבוק ונישוק ומרוב קלונה ובשתה נפלה למטה ומתה מנדין ועונשין אותו בשביל הבושת לפי כבודה וכבוד משפחתה. בנימין זאב סי' קל\"ב:","\u0003דרבנן. \u0004 הרמב\"ם פ\"א מהלכות נערה בתולה דין ה'. ועיין מ\"ש הכ\"מ שם. לכאורה לא מקשה לפ\"ז מידי הש\"ס בכתובות דף ל\"ז ע\"א \u0005(שנה)\u0006 [שניות] מד\"ס כיון מדאוריי' חזיה ליה וכו' ע\"ש. ולפי דברי הכ\"מ ל\"ק מידי דהוי כדאורייתא. ומצאתי בתשובת שבות יעקב ח\"א סימן קל\"א שמתרץ אף על פי דגזירה דרבנן הוי כדאורייתא מ\"מ לענין קנס לא הוי כדאורייתא כדי שלא יהא חוטא נשכר ע\"ש:","\u0003שתבעה לא'. \u0004 ואם נדר לזונה שהיא לו חייבי מיתת ב\"ד אז פוטור לשלם על פי הדין מכל מקום אין יוצא ידי שמים עד שישלם לה ואם תפסה אין מוציאין ממנה. רש\"י פרק \u0005(האומנים)\u0006 [הפועלים]. ב\"ש:"],"r":["\u0003המפתה. \u0004 מתני' ל\"ט א':","\u0003בתולה ולא בעולה גמרא ל\"ח א':\u0004 ","\u0003ישראל. \u0004 לאפוקי גיורת יתרה על בנות שלש שנים ויום א' מתני' ל\"ו ב':","\u0003עד כו' \u0004 והיא כו'. כחכמים שם ך\"ט א' מ\"ב ב' וחולין ך\"ו ב' ואע\"ג דסתם מתניתין כר\"מ כיון דאומר זה דר\"מ אלמא דלא ס\"ל כן ויחידאה הוא כמ\"ש בכמה מקומות דזו זו ולא ס\"ל עד דמפ' גמרא כן בהדיא וכן ס\"ל לר\"ל שם מ\"ד ב' וכן הא דפריך ל\"ט ומי מעברה הוא כחכמים וערא\"ש ספ\"ג:","\u0003ואם נשאה כו' \u0004 קנס. לאפוקי בושת ופגם שנותן. גמרא שם:","\u0003ובלבד כו'. \u0004 שם ח' א' שלח ליה כו' וכי בושת ופגם כמ\"ש ר\"פ החובל (בבא קמא פ\"ד ב)':","\u0003בא\"י. \u0004 שם ובסנהדרין י\"ד א':","\u0003והאידנא כו' \u0004 רי\"ף פ' החובל שם מתקנת הגאונים:","\u0003והבת כו'. \u0004 מתניתין בבתו וכלתו ל\"ט א' מ\"א ב':","\u0003ואינו רשאי כו' \u0004 אלא כו' לפיכך כו'. גמרא שם מי מצי מפיק כו' רבנן סברי וריב\"י סבר כולי וקי\"ל כרבנן כן שם נ\"ד א':","\u0003ואם עבר כו'. \u0004 תמורה ה' א' כל ימיו כו' ועבה\"ג:","\u0003כופין \u0004 כו'. תוספתא פ\"ג דכתובות","\u0003אפילו איסור כו'. \u0004 ג\"כ מאותו הטעם שאמרו בגמרא שם מ\"ם א' אי אמרה דלא בעינא כו' וערש\"י ד\"ה מי כו':","\u0003יצא כו' \u0004 אביו כו'. שם ל\"ו ב':","\u0003בא כו'. \u0004 לא מיבעיא בחד ביאה כמש\"ש כ\"א ב' דקי\"ל כרבא שם דאנוס' היא בת\"כ וכ\"ש לענין ממון אלא אפילו בשתי ביאות מ\"מ לא הפסידה מה שנתחייב לה כבר בשביל שנתרצה אח\"כ לומר דלאו בת בושת היא כמ\"ש בפרק החובל (בבא קמא צ' ב)' לא אמרת כו':","\u0003וי\"א כו' \u0004 כמ\"ש ולו תהיה לאשה:","\u0003והס' כו'. \u0004 הרא\"ש שם וכתב דנהי דחייבה תורה לכונסה אחר שנפגמה ה\"מ בודאי אבל קול בעלמא אין להחזיק הקול ולפגום שניהם. ולי ל\"נ כן מדקאמר במתני' דוקא על השפחה ונכרית ופריך בגמרא אפילו לכתחלה נמי ומשני משום כו' דלא יאמרו משום כך נתגיירה מ' דוקא כה\"ג:","\u0003ובמקום כו' \u0004 דכדאי הם ר\"ת ור\"י וסמ\"ג בעלי הס' שניה לסמוך עליהם בשעת הדחק ואמרינן בפ\"ק דקידושין מוטב שיאכלו ישראל תמיתות שחוטות כו' ועפ\"ז דיבמות ס\"ו א':","\u0003וכ\"ז כו'. \u0004 כנ\"ל וכמ\"ש מהר ימהרנה כו':","\u0003אבל כופין \u0004 כו' כמ\"ש במתני' ל\"ט א' המפתה אם רצה כו' וכמ\"ש בגמרא מ\"ם א' אמר קרא מהר כו':","\u0003ואם נטענת כו'. \u0004 כמ\"ש ל\"ו ב' דכוותה הכא דנפיק כו' אלמא קלא לאו כלום וחייב השני בקנס וה\"ה לכנוס דמשם למידין:","\u0003ואם נטענת כו'. \u0004 כמ\"ש בב\"ק נ\"ג בשור ואדם שדחפו לבור דקי\"ל כר\"נ כל היכא דליכא כו' וכן כאן משום חר\"ג ואונאה ומפתה מכ\"ד אבות נזיקין הן וה\"ה לענין כניסה וכ\"ז לסברא אחרונה הנ\"ל שם:","\u0003זונה כו' \u0004 ממ\"ש בב\"ק ע' ב' אתנן כו' ואי תבעה כו' הא בשאר דלא קם ליה בדרבה מיניה חייב בדינא וכן בב\"מ צ' א' והא קי\"ל כו' אתנן כו':","\u0003זהו כו' \u0004 סנהדרין ט\"ו א' לכדתניא אל תחלל כו' ולשון הרמב\"ם אני אומר שזה שנאמר אל תחלל כולי שלא יאמר הואיל ולא חייבה תורה אונס ומפתה אלא שיתן ממון לאב הריני שוכר בתי הבתולה לזה או בחנם לכך נאמר אל תחלל את בתך שזה שחייבה תורה בשאירע במקרה שלא מדעת אביה כו' והמכין בתו לכך ה\"ה קדשה ולוקה הבועל והנבעלת משום לא תהיה קדשה ור\"ל כמ\"ש בספרי לא תהיה קדשה אזהרה למזנה כענין שנאמר לא היתה בזה קדשה ודוקא במופקרת לוקה וכמ\"ש בסימן ו' ס\"ח וכמש\"ל ר\"ס כו':","\u0003ואין חולק כו' \u0004 שם ונלמד מהנ\"ל שקנס בבתולה היא:","\u0003ורשאין כו'. \u0004 סנהדרין מ\"ו א':"]}],["הַמְקַנֵּא אֶת אִשְׁתּוֹ, וְנִסְתְּרָה, וְאֵינוֹ יוֹדֵעַ אִם נִטְמֵאָה, \u0010c0\u0011 אֲסוּרָה לוֹ. וּבִלְבַד שֶׁיְּהֵא הַקִּנּוּי וְהַסְתִירָה כָּרָאוּי, וְאָז הִפְסִידָה כְּתֻבָּתָהּ, אֲפִלּוּ מֵת קֹדֶם שֶׁגֵּרְשָׁהּ:\nכֵּיצַד הַקִּנּוּי, אוֹמֵר לָהּ בִּפְנֵי שְׁנַיִם: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, \u0010c1\u0011 אֲפִלּוּ אִם הוּא אָבִיהָ אוֹ אָחִיהָ אוֹ כּוּתִי אוֹ שָׁחוּף \u0005 פֵּרוּשׁ, שֶׁאֵינוֹ מִתְקַשֶּׁה \u0006 \u0005(טוּר)\u0006, וְהוּא שֶׁיְּהֵא גָּדוֹל. אֲבָל אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, \u0005 וְהוּא \u0006 קָטָן אוֹ בְּהֵמָה, לָא הָוֵי קִנּוּי. וּמְקַנֵּא לָהּ בֵּין אִם הִיא אֲרוּסָה בֵּין אִם הִיא נְשׂוּאָה אוֹ זְקוּקָה לְיָבָם:\nקְטַנָּה שֶׁהִשִּׂיאָהּ אָבִיהָ וְזִנְּתָה לִרְצוֹנָהּ, \u0010c2\u0011 יֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֲסוּרָה לְבַעְלָהּ. לְפִיכָךְ מְקַנְּאִין לָהּ, כְּדֵי לְהַפְסִידָהּ כְּתֻבָּתָהּ. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֵינוֹ נֶאֱסֶרֶת עַל בַּעְלָהּ, אֶלָּא אִם כֵּן הוּא כֹּהֵן. \u0005 הַגָּה: גְּדוֹלָה שֶׁזָּנְתָה בְּשׁוֹגֵג, שֶׁסָּבְרָה שֶׁבַּעְלָהּ הוּא, וְהוּא אַחֵר, מֻתֶּרֶת לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(הָרַמְבַּ\"ם פכ\"ד דְּאִשּׁוּת)\u0006. \u0005 אֲבָל \u0010c3\u0011 זָנְתָה שֶׁסָּבְרָה שֶׁמֻּתָּר \u0006 \u0005 לִזְנוֹת, הָוֵי כִּמְזִידָה וַאֲסוּרָה לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קס\"ז)\u0006. \u0005 אִשָּׁה שֶׁנִּתְיַחֲדָה עִם אֲנָשִׁים בַּדֶּרֶךְ, וּבָאָה וְאָמְרָה: נִתְיַחַדְתִּי וְנֶאֱנַסְתִּי, יֵשׁ אוֹמְרִים דְּנֶאֱמֶנֶת, בְּמִגּוֹ דְּאָמְרָה: לֹא נִבְעַלְתִּי, וְיֵשׁ אוֹמְרִים דְּאָבְדָה מִגּוֹ שֶׁלָּהּ, הוֹאִיל וְנִתְיַחֲדָה שֶׁלֹּא כַּדִּין \u0006 \u0005(שְׁנֵי הַדֵּעוֹת בְּמָרְדְּכַי פֶּרֶק שֵׁנִי דִּכְתֻבּוֹת)\u0006:\nכֵּיצַד הִיא הַסְתִירָה, שֶׁנִּסְתְּרָה בִּפְנֵי עֵדִים עִם אוֹתוֹ פְּלוֹנִי שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי טֻמְאָה, שֶׁהִיא כְּדֵי לִצְלוֹת בֵּיצָה וּלְגָמְעָהּ:\nקִנֵּא לָהּ מִשְּׁנַיִם, שֶׁאָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי וּפְלוֹנִי, וְנִסְתְּרָה עִם שְׁנֵיהֶם כְּאֶחָד, אֲפִלּוּ הֵם שְׁנֵי אַחִים [אַחֶיהָ], אוֹ אָבִיהָ וְאָחִיהָ, אֲסוּרָה:\nאָמַר לָהּ בִּפְנֵי שְׁנַיִם: אַל תְּדַבְּרִי עִם אִישׁ פְּלוֹנִי, אֵין זֶה קִנּוּי; אֲפִלּוּ נִסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה, מֻתֶּרֶת. וְכֵן אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, וְדִבְּרָה עִמּוֹ בִּפְנֵי עֵדִים, \u0010c4\u0011 מֻתֶּרֶת. וְכֵן אִם נִסְתְּרָה בִּפְנֵי עֵדִים וְשָׁהֲתָה כְּדֵי טֻמְאָה עִמּוֹ, וְלֹא קִנֵּא לָהּ בִּפְנֵי עֵדִים, מֻתֶּרֶת, שֶׁאֵין אוֹסְרִים עַל \u0010c5\u0011 הַיִּחוּד אֲפִלּוּ נִסְתְּרוּ יַחַד עַל דַּעַת עֶרְוָה, אֶלָּא אִם כֵּן קִנֵּא לָהּ תְּחִלָּה בִּפְנֵי שְׁנַיִם. וּמִכָּל מָקוֹם לֹא תִּתְיַחֵד אִשָּׁה עִם אֲנָשִׁים, כְּמוֹ שֶׁנִּתְבָּאֵר \u0005 לְעֵיל סִימָן כ\"ב: \u0006\nלֹא יֹאמַר אָדָם לְאִשְׁתּוֹ, וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, דִלְמָא קַיְמָא לָן כְּרַבִּי יוֹסִי בְּרַבִּי יְהוּדָה דְּאָמַר: קִנֵּא לָהּ בֵּינוֹ לְבֵינָהּ הָוֵי קִנּוּי, \u0005 הַגָּה: וְעַכְשָׁו אֵין לָנוּ מֵי סוֹטָה, וְאִם נִסְתְּרָה אַחַר הַקִּנּוּי, אֲסוּרָה לוֹ לְעוֹלָם \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. \u0005 וְאִם שָׁכַח וְקִנֵּא לָהּ, יִמְחַל לָהּ מִיָּד עַל הַקִּנּוּי \u0006 \u0005(א\"ז)\u0006, \u0005 כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סִימָן זֶה סָעִיף י\"ב: \u0006\nבָּא עֵד אֶחָד וְהֵעִיד לוֹ שֶׁנִּסְתְּרָה עִם אוֹתוֹ שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי \u0010c6\u0011 טֻמְאָה, אִם הוּא נֶאֱמָן בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו, יוֹצִיא וְיִתֵּן כְּתֻבָּה. וְאִם לָאו, מֻתֶּרֶת לוֹ. וְאִם הוּא בְּעַצְמוֹ רָאָה שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה, הֲרֵי זוֹ אֲסוּרָה עָלָיו וְיוֹצִיא וְיִתֵּן כְּתֻבָּה. \u0005 וְאֵין חִלּוּק לְעִנְיַן סְתִירָה שֶׁאַחַר קִנּוּי בֵּין בַּעְלָהּ בָּעִיר וּפֶתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים אוֹ לֹא \u0006 \u0005(עַיֵּן בְּמהרא\"י סִי' רמ\"ד)\u0006 \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב: \u0006\nלֹא קִנֵּא לָהּ, וּבָא עֵד אֶחָד וְאָמַר לוֹ: \u0010c7\u0011 זִנְּתָה, וְהִיא שׁוֹתֶקֶת, אִם הוּא נֶאֱמָן בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו כִּשְׁנַיִם, יוֹצִיא וְיִתֵּן כְּתֻבָּה; וְאִם לָאו, מֻתֶּרֶת לוֹ. \u0005 הַגָּה: וְהוּא הַדִּין אִם הִיא עַצְמָהּ אוֹמֶרֶת לוֹ שֶׁזָּנְתָה, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קט\"ו סָעִיף ו'. וְיֵשׁ אוֹמְרִים, דְּבַזְּמַן הַזֶּה שֶׁיֵּשׁ חֵרֶם רַבֵּנוּ גֵּרְשֹׁם שֶׁלֹּא לְגָרֵשׁ אִשָּׁה בְּעַל כָּרְחָהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִינָה אוֹ שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פכ\"ד וּמַהֲרִי\"ק שֹׁרֶשׁ ק\"י בְּשֵׁם י\"א)\u0006, \u0005 דְּחַיְשִׁינָן שֶׁמָּא עֵינָיו נָתַן בְּאַחֶרֶת, וְאוֹמֵר שֶׁמַּאֲמִינָהּ אַף עַל פִּי שֶׁאֵינוֹ מַאֲמִין; \u0010c8\u0011 וּמְנַדִּין אוֹתוֹ עַל שֶׁאוֹמֵר שֶׁמַּאֲמִינָהּ וְגָרַם לְבַטֵּל חֵרֶם רַבֵּנוּ גֵּרְשׁוֹם. וְהוּא הַדִּין בְּכָל מָקוֹם שֶׁלֹּא יוּכַל לְגָרֵשׁ בְּלֹא דַּעַת הָאִשָּׁה. וְיֵשׁ אוֹמְרִים דְּכוֹפִין אוֹתוֹ וּמְשַׁמֵּשׁ עִמָּהּ \u0006 \u0005(מָרְדְּכַי פֶּרֶק הָאוֹמֵר)\u0006, \u0005 אַף עַל פִּי שֶׁאוֹמֵר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, מֵאַחַר שֶׁהָאִשָּׁה אֵינָהּ מוֹדָה, אוֹ אֲפִלּוּ אָמְרָה בְּעַצְמָהּ: טְמֵאָה אֲנִי לְךְ, וְחָזְרָה וְנָתְנָה אֲמַתְלָא לִדְבָרֶיהָ הָרִאשׁוֹנִים, כֵּן נִרְאֶה לִי עַל פִּי סְבָרָא זוֹ. אֲבָל יֵשׁ חוֹלְקִים וּסְבִירָא לְהוּ דְּאַף בַּזְּמַן הַזֶּה, נֶאֱמָן \u0006 \u0005(שָׁם בַּמַהֲרִי\"ק, וְכֵן מַשְׁמַע מֵהָרַמְבַּ\"ם פכ\"ד)\u0006. \u0005 וְאִם הָיָה לוֹ קֶטֶט עִמָּהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, דְּוַדַּאי מֵחֲמַת שִׂנְאָה אוֹמֵר כֵּן \u0006 \u0005(שָׁם בַּמַּהֲרִי\"ק)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קט\"ו סָעִיף ז': \u0006\nמִי שֶׁהוֹצִיא קוֹל עַל אִשְׁתּוֹ, שֶׁזִּנְּתָה, וְאָמַר שֶׁנִּתְבָּרֵר לוֹ הַדָּבָר, וְאַחַר כָּךְ אָמַר אֵינוֹ אֱמֶת, אֶלָּא שֶׁמֵּחֲמַת הַכַּעַס שֶׁהִכְעִיסַתּוּ הוֹצִיא קוֹל זֶה; אִם נוֹתֵן אֲמַתְלָא לִדְבָרָיו, מֻתֶּרֶת; וְאִם לָאו, אֲסוּרָה לוֹ:\nשָׁמַע הָעָם מְרַנְּנִים אַחַר \u0010c9\u0011 הַקִּנּוּי, וְהַסְתִירָה בְּלֹא שְׁנֵי עֵדִים, עַד שֶׁהַנָּשִׁים נוֹשְׂאוֹת וְנוֹתְנוֹת בָּהּ שֶׁזִּנְּתָה מֵהָאִישׁ שֶׁקִּנֵּא לָהּ, אֲסוּרָה לוֹ, וְיוֹצִיאֶנָּה וְיִתֵּן כְּתֻבָּה:\nבַּעַל שֶׁמָּחַל עַל קִנּוּי, קֹדֶם סְתִירָה, קִנּוּיוֹ מָחוּל וּכְאִלּוּ לֹא קִנֵּא לָהּ. אֲבָל לְאַחַר סְתִירָה, אֵין קִנּוּיוֹ מָחוּל. גֵּרְשָׁהּ, הֲרֵי זֶה כְּאִלּוּ מָחַל לָהּ; וְאִם הֶחֱזִירָהּ, צָרִיךְ לְקַנֹּאת לָהּ פַּעַם אַחֶרֶת:\nמִי שֶׁנִּתְחָרֵשׁ בַּעְלָהּ אוֹ נִשְׁתַּטָּה, אוֹ הָיָה בִּמְדִינָה אַחֶרֶת, אוֹ שֶׁהָיָה חָבוּשׁ בְּבֵית הָאֲסוּרִים, וְשָׁמְעוּ בֵּית דִּין מְרַנְּנִים אַחֲרֶיהָ, קוֹרְאִים וְאוֹמְרִים לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי. וְאִם בָּאוּ עֵדִים אַחַר כָּךְ שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה כְּדֵי טֻמְאָה, אוֹסְרִים אוֹתָהּ עַל בַּעְלָהּ לְעוֹלָם, וְקוֹרְעִים כְּתֻבָּתָהּ. וּכְשֶׁיָּבֹא בַּעְלָהּ אוֹ יַבְרִיא אוֹ יֵצֵא מִבֵּית הָאֲסוּרִים, יִתֵּן לָהּ גֵּט: \u0010c10\u0011\nבָּא עֵד אֶחָד וְהֵעִיד שֶׁנִּטְמְאָה מֵאוֹתוֹ שֶׁקִּנֵּא לָהּ, תֵּצֵא בְּלֹא \u0010c11\u0011 כְּתֻבָּה. אֲפִלּוּ אִם עֵד הַטֻּמְאָה הוּא אֶחָד מֵעֵדֵי הַסְתִירָה, וַאֲפִלּוּ עֶבֶד אוֹ שִׁפְחָה אוֹ אִשָּׁה אוֹ קָרוֹב, כָּשֵׁר לְעֵדוּת:\nחָמֵשׁ נָשִׁים שֶׁשּׂוֹנְאוֹת אוֹתָהּ, נֶאֱמָנוֹת עָלֶיהָ לוֹמַר שֶׁנִּטְמֵאת אַחַר הַקִּנּוּי לְאָסְרָהּ עַל בַּעְלָהּ, אֲבָל לֹא לְהַפְסִידָהּ כְּתֻבָּתָהּ:\nמוֹצִיאִים עַל יְדֵי עֵדֵי טֻמְאָה, אֲפִלּוּ לֹא רָאוּ כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת, מֵאַחַר שֶׁרָאוּ אוֹתָם דְּבוּקִים זֶה בָּזֶה וְנוֹהֲגִים כְּדֶרֶךְ הַמְנָאֲפִים:\nכָּל אִשָּׁה שֶׁנֶּאֶסְרָה עַל בַּעְלָהּ עַל יְדֵי קִנּוּי וּסְתִירָה, אֲסוּרָה גַּם לְאוֹתוֹ שֶׁנֶּאֶסְרָה בִּשְׁבִילוֹ. וְאִם עָבַר וּנְשָׂאָהּ, מוֹצִיאִין אוֹתָהּ מִתַּחְתָּיו בְּגֵט, אֲפִלּוּ הָיוּ לָהּ כַּמָּה בָּנִים מִמֶּנּוּ. אֲבָל אִם לֹא קָדַם קִנּוּי, וּבָאוּ עֵדִים שֶׁנִּסְתְּרָה עִם אִישׁ זֶה, וּבָאוּ וּמָצְאוּ דָּבָר מְכֹעָר, נִתְבָּאֵר בְּסִי' י\" א:\nכָּל אִשָּׁה שֶׁבָּאוּ שְׁנֵי עֵדִים וְהֵעִידוּ שֶׁזִּנְּתָה עִם זֶה כְּשֶׁהָיְתָה תַּחַת בַּעְלָהּ, הֲרֵי זוֹ תֵּצֵא מִזֶּה, וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ מִמֶּנּוּ כַּמָּה בָּנִים:\nיֵשׁ אוֹמְרִים שֶׁאֵשֶׁת אִישׁ שֶׁזִּנְּתָה עִם כּוּתִי וְגֵרְשָׁהּ בַּעְלָהּ, וְנִתְגַּיֵּר הַכּוּתִי, שֶׁמֻּתֶּרֶת לַגֵּר הַזֶּה, \u0010c12\u0011 דְּלֹא שַׁיָּךְ לְמֵימַר \"אֶחָד לַבּוֹעֵל\" בְּבִיאַת הַכּוּתִי. \u0005 הַגָּה: וּמִכָּל מָקוֹם מִי שֶׁזִּנָּה עִם אֲחוֹת אִשְׁתּוֹ, וְגֵרְשָׁהּ בַּעְלָהּ, אֲסוּרָה לַבּוֹעֵל אַחַר מִיתַת אִשְׁתּוֹ. אַף עַל גַּב דִּבְלָאו הָכִי הָיְתָה אֲסוּרָה לוֹ כְּשֶׁזִּנְּתָה עִמּוֹ \u0006 \u0005(פִּסְקֵי מהרא\"י סִי' כ\"ט)\u0006:\nאֵשֶׁת אִישׁ שֶׁטּוֹעֶנֶת עַל אִישׁ אֶחָד שֶׁהוּא רוֹדֵף אַחֲרֶיהָ, וְהוּא מַכְחִישָׁהּ, אֵין לְהַאֲמִינָהּ כְּדֵי לְיַסְרוֹ; אֲבָל יִגְזְרוּ עָלָיו נִדּוּי, שֶׁלֹּא יְדַבֵּר עִמָּהּ כְּלָל, וְשֶׁלֹּא יָדוּרוּ בִּשְׁכוּנָה אַחַת. וְאִם הוּא מֻחְזָק בְּעֵינֵיהֶם לְחָשׁוּד עַל הָעֲרָיוֹת, רָאוּי לִגְעֹר בּוֹ בִּנְזִיפָה וּלְאַיֵּם עָלָיו שֶׁאִם לֹא יִתְנַהֵג כַּשּׁוּרָה יַבְדִּילוּהוּ מִבֵּינֵיהֶם לְרָעָה וְיִדְחוּהוּ בִּשְׁתֵּי יָדַיִם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵנוּ זַ\"ל: מַלְקִין עַל לֹא טוֹבָה הַשְּׁמוּעָה, וּכְמוֹ שֶׁכָּתַב הָרַמְבַּ\"ם בְּפֶרֶק כ\"ד מִסַנְהֶדְרִין:\nמִצְוַת חֲכָמִים עַל בְּנֵי יִשְׂרָאֵל \u0010c13\u0011 לְקַנְּאוֹת לִנְשׁוֹתֵיהֶם. וְכָל מִי שֶׁאֵינוֹ מַקְפִּיד עַל אִשְׁתּוֹ וְעַל בָּנָיו וּבְנֵי בֵּיתוֹ וּמַזְהִירָם וּפוֹקֵד דַּרְכֵיהֶם תָּמִיד עַד שֶׁיֵּדַע שֶׁהֵם שְׁלֵמִים מִכָּל חֵטְא וְעָוֹן, הֲרֵי זֶה חוֹטֵא, שֶׁנֶּאֱמַר: \"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא\" \u0005(אִיּוֹב ה, כד)\u0006. וְכָל הַמְקַנֵּא אֶת אִשְׁתּוֹ נִכְנְסָה בּוֹ רוּחַ טָהֳרָה. וְלֹא יְקַנֵּא לָהּ מִתּוֹךְ שְׂחוֹק, וְלֹא מִתּוֹךְ שִׂיחָה, וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ, וְלֹא מִתּוֹךְ מְרִיבָה, וְלֹא לְהָטִיל עָלֶיהָ אֵימָה. וְאִם עָבַר וְקִנֵּא לָהּ בִּפְנֵי עֵדִים מִתּוֹךְ אֶחָד מִכָּל הַדְּבָרִים הָאֵלּוּ, הֲרֵי זֶה קִנּוּי:\nאֵין רָאוּי לִקְפֹּץ וּלְקַנְּאָהּ בִּפְנֵי עֵדִים תְּחִלָּה. וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ לָא יֹאמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, כְּמוֹ שֶׁנִּתְבָּאֵר. אֶלָּא מוֹכִיחַ אוֹתָהּ בֵּינוֹ לְבֵינָהּ, בְּנַחַת וּבְדֶרֶךְ טָהֳרָה וְאַזְהָרָה, כְּדֵי לְהָסִיר הַמִּכְשׁוֹל וּלְהַדְרִיכָהּ בְּדֶרֶךְ יְשָׁרָה:",[],["\u0003אסורה לו\u0004. ואסור להתייחד עמה תשו' הרא\"ש כלל ל\"ב ועיין סי' קי\"ז:","\u0003אפילו אם הוא אביה\u0004. אף על גב יחוד מותר עם אביה מ\"מ כשמקנא לה אסור להתייחד עמו:","\u0003יש מי שאומר שאסורה לבעלה\u0004. היינו דעת הרמב\"ם וס\"ל כשהשיאה אמה ואחיה אז לא הוי קידושין מדאורייתא וכאלו זנתה כשהיא פנויה ומותרת אפילו לכהן משא\"כ כשאביה השיאה אז הוי נשואי' דאורייתא ואסורה לבעלה ישראל, ויש מי שאומר השני כן ס\"ל לרוב הפוסקים וכן הוא דעת תוס' וס\"ל פיתוי דקטנה הוי כאונס ומותרת לבעלה ישראל ואסורה לבעלה כהן ואם בא עליה באונס והבועל הוא ישראל ובעלה כהן עיין בסי' י\"א מ\"ש ועיין סימן קצ\"ט:","\u0003שסברה שמותר לזנות\u0004. דלא כתיב ומעלה מעל בה' אלא ומעלה בו מעל כל שהיא מתכוונת למעול בו אסורה ובזה מיושב דלא תקשה הא אומר מותר הוי כשוגג ועיין בט\"ז בי\"ד סי' צ\"ט, ואם זינתה ברצון כדי להציל נפשות כעובדת אסתר לאחשורוש אסורה לבעלה כיון שביאה היה ברצון שם במהרי\"ק וכן אם סבורה דלא היה קדושין מה שא' נתן לה טבעת לקידושין ועיין תשו' הרשב\"א ועיין ב\"י ס\"ס ק':","\u0003וכן אם נסתרה בפני עדים וכו'\u0004. לכאורה נשמע מבבא קמייתא כשאמר אל תדברי ונסתרה אלא די\"ל שם גילה דעתו דאין לו קפידא בסתירה:","\u0003אפילו נסתרה יחד ע\"ד ערוה\u0004. עיין מ\"ש סי' ז' סעיף י\"א בהג\"ה דפוסק אם נתייחדה לשם זנות יש להחמיר:","\u0003אם הוא נאמן בעיניו\u0004. כאן לא כתב והיא שותקת משמע אילו במכחשתו צריך להוצי' כיון דהיה קינוי ועיין פרישה:","\u0003והיא שותקת\u0004. כן הוא גירסת הב\"י ועיין סימן קט\"ז ולדעת מהרש\"ל כשהיא שותקת אפילו א\"נ בעיניו כשנים חייב להוציא' כיון דהיא שותקת אלא גירסתו והוא הבעל שותק אז אם הוא נאמן כתרי בעיניו חייב הוציאה ואם הוא אומר מנ\"ל זאת וכיוצא בו אין חייב להוציאה אלא משום לזות שפתיים עיין ב\"ח ודרישה בסימן זה ובסימן קט\"ו:","\u0003ומנדין אותו וכו'\u0004. עיין במהרי\"ק שורש ק\"י הביא ב' דיעות בזה אם מנדין אותו לדעת תוס' מנדין אותו כי הוא נאמן לומר שמאמין לדברי העד א\"כ גורם לבטל תקנות ר\"ג מ\"ה מנדין אותו אבל לדעת הפוסקי' שהביא הרב רמ\"א דאין נאמן לומר דמאמין לדברי העד א\"י מנ\"ל דמנדין אותו מאחר דליכא כאן עקירת תקנת ר\"ג:","\u0003והסתירה בלא שני עדים\u0004. כ\"כ בכ\"מ ע\"כ הסתירה לא היה בעדים דאל\"כ כבר מבואר ברמב\"ם כשהקינוי וסתירה היה בעדים תצא בלא כתובה אלא ודאי דאיירי דלא היה עדים אלא שמע מנשים הנושאות ונותנות בה ואז לא הוי כעדים על הסתירה אלא הואיל ודבר מכוער הוא תצא ויתן לה הכתובה וכן הוא לפרש\"י שם, ובתו' שם י\"ל לפי קושי' שלהם דמים לא בדקו כשנושאים ונותנים נשים בה אז א\"צ ליתן לה הכתובה לפ\"ז בזה\"ז פשיטא דפטור הוא ליתן לה הכתובה מיהו לפי תירוצים שלהם י\"ל דס\"ל נמי כרש\"י:","\u0003בא ע\"א והעיד וכו'\u0004. הואיל ויש רגלים לדבר דהיה כבר קינוי בעדים וסתירה בעדים מ\"ה ע\"א נאמן ודוקא כשמעיד שזינתה עם זה שקינא לה גם משמע מרש\"י דוקא שמעיד שזינתה באותו פעם כשנסתרה עמו ע\"פ ב' עדים, מיהו קשה למה לי עדות העד ת\"ל אם קינא ונסתרה אסורה לבעלה ואין לה כתובה בשלמא בש\"ס לק\"מ דקמ\"ל דאינה שותה אלא לפסק הש\"ע קשה מה נ\"מ מעדותו וע' ברמב\"ם ובטור דכתבו אם אחר שהעיד ע\"א שנטמאה בא ע\"א ומכחישו לא משגיחין בו דע\"א בסוטה נאמן כתרי ואין ע\"א נאמן נגד שני עדים ולכאורה קשה דהא כתב הרמב\"ם פי\"ב מה\"ג והטור בסי' י\"ז דוקא כשמעיד העד ופסקו הב\"ד על פיו אז הוי כתרי אבל כל זמן שלא פסקו על פיו לא אמרינן דהו' כתרי וכ\"כ תוס' בסוגי' דאיירי דפסקו הב\"ד ע\"פ עדותו א\"כ למה כתבו הם מיד אחר שהעיד הוי כתרי אפי' לא פסקו ע\"פ, שוב ראיתי בתוס' פ\"ב דכתובות כתבו היכא דע\"א מדאורייתא נאמן הוי כתרי אפי' לא פסקו הב\"ד ע\"פ אבל היכא דנאמן מדרבנן אז לא הוי כתרי אא\"כ פסקו על פיו בזה שפיר מ\"ש הרמב\"ם והטור כי הם ס\"ל ג\"כ כתוס' אלו ובי\"ד סי' קכ\"ז מחלק בש\"ך מסברא דעצמו כן, וע' מ\"ש ס\"ס י\"ד:","\u0003אפי' אם עד הטומאה הוא א' מעידי הסתירה\u0004. וה\"א לומר כיון שראה שנסתרו יחדיו לא דקדק היטב אם בעיל אותה וסבר בודאי בעיל קמ\"ל כ\"כ ב\"ח גם י\"ל דה\"ק אפי' אם הוא אחד מעידי סתירה ואמר שאותו פעם בעיל אותה ועד השני לא אמר שראה הביאה מיהו אינו מכחיש אותו אלא אמר שלא ראה ולא שם על לבו לראות כ\"כ אבל אם מכחיש אותו אף על גב שהיה הסתירה בודאי לא הפסידה הכתובה:","\u0003דלא שייך למימר אחד לבועל\u0004. הואיל ואסור לה בל\"ז ולא שייך בו קידושין אא\"כ אחר שנתגייר ואז הוי כגוף אחר אבל אם בא על אחות אשתו ראוי היא לו אחר שתמות אשתו שם בפסקי מהרא\"י:","\u0003לקנאות לנשותיהם\u0004. לאו קינוי ממש קאמר אלא להוכיח אותה ויזהר אותה שאל תסתיר עם אנשים בזה שפיר דלא תקשי ממ\"ש בסעיף ז' ועיין פרישה:"],"\u0010g0\u0011 הַמְקַנֵּא אֶת אִשְׁתּוֹ, וְנִסְתְּרָה, וְאֵינוֹ יוֹדֵעַ אִם נִטְמֵאָה, \u0010c0\u0011 אֲסוּרָה \u0010r0\u0011 לוֹ. \u0010t0\u0011 וּבִלְבַד שֶׁיְּהֵא הַקִּנּוּי וְהַסְתִירָה כָּרָאוּי, \u0010g1\u0011 וְאָז הִפְסִידָה \u0010t1\u0011 כְּתֻבָּתָהּ, אֲפִלּוּ מֵת קֹדֶם שֶׁגֵּרְשָׁהּ:\nכֵּיצַד \u0010g2\u0011 הַקִּנּוּי, אוֹמֵר לָהּ בִּפְנֵי שְׁנַיִם: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, \u0010c1\u0011 \u0010g3\u0011 אֲפִלּוּ אִם הוּא אָבִיהָ אוֹ אָחִיהָ \u0010g4\u0011 אוֹ כּוּתִי אוֹ \u0010g5\u0011 שָׁחוּף \u0010r1\u0011 \u0005 פֵּרוּשׁ, שֶׁאֵינוֹ מִתְקַשֶּׁה \u0006 \u0005(טוּר)\u0006, \u0010g6\u0011 וְהוּא שֶׁיְּהֵא גָּדוֹל. אֲבָל אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, \u0005 וְהוּא \u0006 קָטָן אוֹ \u0010g7\u0011 בְּהֵמָה, לָא הָוֵי קִנּוּי. וּמְקַנֵּא לָהּ \u0010r2\u0011 בֵּין אִם הִיא \u0010g8\u0011 אֲרוּסָה בֵּין אִם הִיא נְשׂוּאָה אוֹ זְקוּקָה לְיָבָם:\nקְטַנָּה שֶׁהִשִּׂיאָהּ אָבִיהָ וְזִנְּתָה לִרְצוֹנָהּ, \u0010c2\u0011 \u0010g9\u0011 \u0010r3\u0011 יֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֲסוּרָה לְבַעְלָהּ. לְפִיכָךְ מְקַנְּאִין לָהּ, כְּדֵי לְהַפְסִידָהּ \u0010g10\u0011 כְּתֻבָּתָהּ. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֵינוֹ נֶאֱסֶרֶת עַל בַּעְלָהּ, אֶלָּא אִם כֵּן הוּא \u0010t2\u0011 כֹּהֵן. \u0005 הַגָּה: \u0010r4\u0011 גְּדוֹלָה שֶׁזָּנְתָה בְּשׁוֹגֵג, שֶׁסָּבְרָה שֶׁבַּעְלָהּ הוּא, וְהוּא אַחֵר, מֻתֶּרֶת לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(הָרַמְבַּ\"ם פכ\"ד \u0010r5\u0011 דְּאִשּׁוּת)\u0006. \u0005 אֲבָל \u0010c3\u0011 זָנְתָה שֶׁסָּבְרָה \u0010t3\u0011 שֶׁמֻּתָּר \u0006 \u0005 לִזְנוֹת, הָוֵי כִּמְזִידָה וַאֲסוּרָה לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קס\"ז)\u0006. \u0005 אִשָּׁה שֶׁנִּתְיַחֲדָה עִם אֲנָשִׁים בַּדֶּרֶךְ, וּבָאָה וְאָמְרָה: נִתְיַחַדְתִּי וְנֶאֱנַסְתִּי, \u0010r6\u0011 יֵשׁ אוֹמְרִים דְּנֶאֱמֶנֶת, בְּמִגּוֹ דְּאָמְרָה: לֹא נִבְעַלְתִּי, \u0010r7\u0011 וְיֵשׁ אוֹמְרִים דְּאָבְדָה מִגּוֹ שֶׁלָּהּ, הוֹאִיל וְנִתְיַחֲדָה שֶׁלֹּא כַּדִּין \u0006 \u0005(שְׁנֵי הַדֵּעוֹת בְּמָרְדְּכַי פֶּרֶק שֵׁנִי \u0010g11\u0011 דִּכְתֻבּוֹת)\u0006:\nכֵּיצַד הִיא הַסְתִירָה, \u0010r8\u0011 שֶׁנִּסְתְּרָה בִּפְנֵי עֵדִים עִם אוֹתוֹ פְּלוֹנִי שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי \u0010g12\u0011 טֻמְאָה, שֶׁהִיא כְּדֵי לִצְלוֹת בֵּיצָה וּלְגָמְעָהּ: \u0010g13\u0011 \u0010r9\u0011\nקִנֵּא לָהּ מִשְּׁנַיִם, שֶׁאָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי וּפְלוֹנִי, וְנִסְתְּרָה עִם שְׁנֵיהֶם \u0010t4\u0011 כְּאֶחָד, \u0010g14\u0011 אֲפִלּוּ הֵם שְׁנֵי אַחִים [אַחֶיהָ], אוֹ אָבִיהָ וְאָחִיהָ, אֲסוּרָה: \u0010g15\u0011\nאָמַר לָהּ בִּפְנֵי שְׁנַיִם: אַל תְּדַבְּרִי עִם אִישׁ פְּלוֹנִי, אֵין זֶה \u0010g16\u0011 קִנּוּי; אֲפִלּוּ נִסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי \u0010g17\u0011 טֻמְאָה, מֻתֶּרֶת. וְכֵן אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, וְדִבְּרָה עִמּוֹ בִּפְנֵי עֵדִים, \u0010c4\u0011 \u0010g18\u0011 מֻתֶּרֶת. וְכֵן אִם נִסְתְּרָה בִּפְנֵי עֵדִים וְשָׁהֲתָה כְּדֵי טֻמְאָה עִמּוֹ, וְלֹא קִנֵּא לָהּ בִּפְנֵי עֵדִים, \u0010g19\u0011 מֻתֶּרֶת, שֶׁאֵין אוֹסְרִים עַל \u0010c5\u0011 \u0010g20\u0011 \u0010r10\u0011 הַיִּחוּד אֲפִלּוּ נִסְתְּרוּ יַחַד עַל דַּעַת עֶרְוָה, אֶלָּא אִם כֵּן קִנֵּא לָהּ תְּחִלָּה בִּפְנֵי שְׁנַיִם. וּמִכָּל מָקוֹם לֹא תִּתְיַחֵד אִשָּׁה עִם אֲנָשִׁים, כְּמוֹ שֶׁנִּתְבָּאֵר \u0005 לְעֵיל סִימָן כ\"ב: \u0010g21\u0011 \u0006\nלֹא יֹאמַר אָדָם לְאִשְׁתּוֹ, וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, דִלְמָא קַיְמָא לָן כְּרַבִּי יוֹסִי בְּרַבִּי יְהוּדָה דְּאָמַר: קִנֵּא לָהּ בֵּינוֹ לְבֵינָהּ הָוֵי \u0010t5\u0011 קִנּוּי, \u0005 הַגָּה: \u0010r11\u0011 וְעַכְשָׁו אֵין לָנוּ מֵי סוֹטָה, וְאִם נִסְתְּרָה אַחַר הַקִּנּוּי, אֲסוּרָה לוֹ לְעוֹלָם \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. \u0005 וְאִם שָׁכַח וְקִנֵּא לָהּ, יִמְחַל לָהּ מִיָּד עַל הַקִּנּוּי \u0006 \u0005(א\"ז)\u0006, \u0005 כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סִימָן זֶה סָעִיף י\"ב: \u0010g22\u0011 \u0006\nבָּא עֵד אֶחָד וְהֵעִיד לוֹ שֶׁנִּסְתְּרָה עִם אוֹתוֹ שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי \u0010c6\u0011 טֻמְאָה, אִם הוּא נֶאֱמָן \u0010t6\u0011 בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו, יוֹצִיא וְיִתֵּן כְּתֻבָּה. וְאִם לָאו, מֻתֶּרֶת לוֹ. \u0010g23\u0011 \u0010r12\u0011 וְאִם הוּא בְּעַצְמוֹ רָאָה שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה, הֲרֵי זוֹ אֲסוּרָה עָלָיו וְיוֹצִיא וְיִתֵּן כְּתֻבָּה. \u0005 וְאֵין חִלּוּק לְעִנְיַן סְתִירָה שֶׁאַחַר קִנּוּי בֵּין בַּעְלָהּ בָּעִיר וּפֶתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים אוֹ לֹא \u0006 \u0005(עַיֵּן בְּמהרא\"י סִי' רמ\"ד)\u0006 \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב: \u0010g24\u0011 \u0006\nלֹא קִנֵּא לָהּ, וּבָא עֵד אֶחָד וְאָמַר לוֹ: \u0010c7\u0011 זִנְּתָה, וְהִיא שׁוֹתֶקֶת, אִם הוּא נֶאֱמָן בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו כִּשְׁנַיִם, יוֹצִיא וְיִתֵּן כְּתֻבָּה; וְאִם לָאו, מֻתֶּרֶת לוֹ. \u0005 הַגָּה: וְהוּא הַדִּין אִם הִיא עַצְמָהּ אוֹמֶרֶת לוֹ שֶׁזָּנְתָה, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קט\"ו סָעִיף ו'. \u0010r13\u0011 וְיֵשׁ אוֹמְרִים, דְּבַזְּמַן הַזֶּה שֶׁיֵּשׁ חֵרֶם רַבֵּנוּ גֵּרְשֹׁם שֶׁלֹּא לְגָרֵשׁ אִשָּׁה בְּעַל כָּרְחָהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִינָה אוֹ שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פכ\"ד וּמַהֲרִי\"ק שֹׁרֶשׁ ק\"י בְּשֵׁם י\"א)\u0006, \u0005 דְּחַיְשִׁינָן שֶׁמָּא עֵינָיו נָתַן בְּאַחֶרֶת, וְאוֹמֵר שֶׁמַּאֲמִינָהּ אַף עַל פִּי שֶׁאֵינוֹ מַאֲמִין; \u0010c8\u0011 וּמְנַדִּין אוֹתוֹ עַל שֶׁאוֹמֵר שֶׁמַּאֲמִינָהּ וְגָרַם לְבַטֵּל חֵרֶם רַבֵּנוּ גֵּרְשׁוֹם. וְהוּא הַדִּין בְּכָל מָקוֹם שֶׁלֹּא יוּכַל לְגָרֵשׁ בְּלֹא דַּעַת הָאִשָּׁה. \u0010r14\u0011 וְיֵשׁ אוֹמְרִים דְּכוֹפִין אוֹתוֹ וּמְשַׁמֵּשׁ עִמָּהּ \u0006 \u0005(מָרְדְּכַי פֶּרֶק הָאוֹמֵר)\u0006, \u0005 אַף עַל פִּי שֶׁאוֹמֵר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, מֵאַחַר שֶׁהָאִשָּׁה אֵינָהּ מוֹדָה, אוֹ אֲפִלּוּ אָמְרָה בְּעַצְמָהּ: טְמֵאָה אֲנִי לְךְ, \u0010r15\u0011 וְחָזְרָה וְנָתְנָה אֲמַתְלָא לִדְבָרֶיהָ הָרִאשׁוֹנִים, כֵּן נִרְאֶה לִי עַל פִּי סְבָרָא זוֹ. אֲבָל יֵשׁ חוֹלְקִים וּסְבִירָא לְהוּ דְּאַף בַּזְּמַן הַזֶּה, נֶאֱמָן \u0006 \u0005(שָׁם בַּמַהֲרִי\"ק, וְכֵן מַשְׁמַע מֵהָרַמְבַּ\"ם פכ\"ד)\u0006. \u0010r16\u0011 \u0005 וְאִם הָיָה לוֹ קֶטֶט עִמָּהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, דְּוַדַּאי מֵחֲמַת שִׂנְאָה אוֹמֵר כֵּן \u0006 \u0005(שָׁם בַּמַּהֲרִי\"ק)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קט\"ו סָעִיף ז': \u0010g25\u0011 \u0010r17\u0011 \u0006\nמִי שֶׁהוֹצִיא קוֹל עַל אִשְׁתּוֹ, שֶׁזִּנְּתָה, וְאָמַר שֶׁנִּתְבָּרֵר לוֹ הַדָּבָר, וְאַחַר כָּךְ אָמַר אֵינוֹ אֱמֶת, אֶלָּא שֶׁמֵּחֲמַת הַכַּעַס שֶׁהִכְעִיסַתּוּ הוֹצִיא קוֹל זֶה; אִם נוֹתֵן אֲמַתְלָא לִדְבָרָיו, מֻתֶּרֶת; וְאִם לָאו, אֲסוּרָה לוֹ: \u0010g26\u0011\nשָׁמַע הָעָם מְרַנְּנִים \u0010r18\u0011 אַחַר \u0010c9\u0011 \u0010t7\u0011 הַקִּנּוּי, וְהַסְתִירָה \u0010g27\u0011 \u0010r19\u0011 בְּלֹא שְׁנֵי עֵדִים, עַד שֶׁהַנָּשִׁים נוֹשְׂאוֹת וְנוֹתְנוֹת בָּהּ שֶׁזִּנְּתָה מֵהָאִישׁ שֶׁקִּנֵּא לָהּ, אֲסוּרָה לוֹ, וְיוֹצִיאֶנָּה וְיִתֵּן \u0010g28\u0011 כְּתֻבָּה:\nבַּעַל שֶׁמָּחַל עַל קִנּוּי, קֹדֶם סְתִירָה, קִנּוּיוֹ מָחוּל וּכְאִלּוּ לֹא קִנֵּא לָהּ. אֲבָל לְאַחַר סְתִירָה, אֵין קִנּוּיוֹ מָחוּל. \u0010g29\u0011 גֵּרְשָׁהּ, הֲרֵי זֶה כְּאִלּוּ מָחַל לָהּ; וְאִם הֶחֱזִירָהּ, צָרִיךְ לְקַנֹּאת לָהּ פַּעַם אַחֶרֶת: \u0010g30\u0011\nמִי שֶׁנִּתְחָרֵשׁ בַּעְלָהּ אוֹ נִשְׁתַּטָּה, \u0010r20\u0011 אוֹ הָיָה בִּמְדִינָה אַחֶרֶת, \u0010g31\u0011 אוֹ שֶׁהָיָה חָבוּשׁ בְּבֵית הָאֲסוּרִים, וְשָׁמְעוּ בֵּית דִּין מְרַנְּנִים אַחֲרֶיהָ, קוֹרְאִים וְאוֹמְרִים לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי. וְאִם בָּאוּ עֵדִים אַחַר כָּךְ שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה כְּדֵי טֻמְאָה, אוֹסְרִים אוֹתָהּ עַל בַּעְלָהּ לְעוֹלָם, וְקוֹרְעִים כְּתֻבָּתָהּ. וּכְשֶׁיָּבֹא בַּעְלָהּ אוֹ יַבְרִיא אוֹ יֵצֵא מִבֵּית הָאֲסוּרִים, יִתֵּן לָהּ גֵּט: \u0010c10\u0011 \u0010g32\u0011\nבָּא עֵד אֶחָד וְהֵעִיד \u0010t8\u0011 שֶׁנִּטְמְאָה \u0010g33\u0011 מֵאוֹתוֹ שֶׁקִּנֵּא לָהּ, תֵּצֵא בְּלֹא \u0010c11\u0011 \u0010g34\u0011 כְּתֻבָּה. אֲפִלּוּ אִם עֵד הַטֻּמְאָה הוּא אֶחָד \u0010g35\u0011 מֵעֵדֵי הַסְתִירָה, וַאֲפִלּוּ עֶבֶד אוֹ שִׁפְחָה אוֹ אִשָּׁה אוֹ קָרוֹב, כָּשֵׁר לְעֵדוּת: \u0010g36\u0011\nחָמֵשׁ נָשִׁים שֶׁשּׂוֹנְאוֹת אוֹתָהּ, נֶאֱמָנוֹת עָלֶיהָ לוֹמַר שֶׁנִּטְמֵאת אַחַר הַקִּנּוּי לְאָסְרָהּ עַל בַּעְלָהּ, \u0010g37\u0011 אֲבָל לֹא \u0010g38\u0011 לְהַפְסִידָהּ כְּתֻבָּתָהּ:\nמוֹצִיאִים עַל יְדֵי עֵדֵי טֻמְאָה, אֲפִלּוּ לֹא רָאוּ כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת, מֵאַחַר שֶׁרָאוּ אוֹתָם דְּבוּקִים זֶה בָּזֶה וְנוֹהֲגִים כְּדֶרֶךְ הַמְנָאֲפִים: \u0010g39\u0011\nכָּל אִשָּׁה שֶׁנֶּאֶסְרָה עַל בַּעְלָהּ עַל יְדֵי קִנּוּי וּסְתִירָה, אֲסוּרָה גַּם לְאוֹתוֹ שֶׁנֶּאֶסְרָה \u0010t9\u0011 בִּשְׁבִילוֹ. \u0010g40\u0011 וְאִם עָבַר וּנְשָׂאָהּ, מוֹצִיאִין אוֹתָהּ מִתַּחְתָּיו בְּגֵט, אֲפִלּוּ הָיוּ לָהּ כַּמָּה בָּנִים מִמֶּנּוּ. אֲבָל אִם לֹא קָדַם קִנּוּי, וּבָאוּ עֵדִים שֶׁנִּסְתְּרָה עִם אִישׁ זֶה, וּבָאוּ וּמָצְאוּ דָּבָר מְכֹעָר, נִתְבָּאֵר בְּסִי' \u0010g41\u0011 י\" א:\nכָּל אִשָּׁה שֶׁבָּאוּ שְׁנֵי עֵדִים וְהֵעִידוּ שֶׁזִּנְּתָה עִם זֶה כְּשֶׁהָיְתָה תַּחַת בַּעְלָהּ, הֲרֵי זוֹ תֵּצֵא מִזֶּה, וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ מִמֶּנּוּ כַּמָּה בָּנִים: \u0010r21\u0011\nיֵשׁ אוֹמְרִים שֶׁאֵשֶׁת אִישׁ שֶׁזִּנְּתָה עִם כּוּתִי וְגֵרְשָׁהּ בַּעְלָהּ, וְנִתְגַּיֵּר הַכּוּתִי, שֶׁמֻּתֶּרֶת לַגֵּר הַזֶּה, \u0010c12\u0011 דְּלֹא שַׁיָּךְ לְמֵימַר \"אֶחָד לַבּוֹעֵל\" בְּבִיאַת הַכּוּתִי. \u0005 הַגָּה: \u0010r22\u0011 וּמִכָּל מָקוֹם מִי שֶׁזִּנָּה עִם אֲחוֹת אִשְׁתּוֹ, וְגֵרְשָׁהּ בַּעְלָהּ, אֲסוּרָה לַבּוֹעֵל אַחַר מִיתַת אִשְׁתּוֹ. אַף עַל גַּב דִּבְלָאו הָכִי הָיְתָה אֲסוּרָה לוֹ כְּשֶׁזִּנְּתָה עִמּוֹ \u0006 \u0005(פִּסְקֵי מהרא\"י סִי' כ\"ט)\u0006: \u0010g42\u0011 \u0010r23\u0011\nאֵשֶׁת אִישׁ שֶׁטּוֹעֶנֶת עַל אִישׁ אֶחָד שֶׁהוּא רוֹדֵף אַחֲרֶיהָ, וְהוּא מַכְחִישָׁהּ, אֵין לְהַאֲמִינָהּ כְּדֵי \u0010r24\u0011 לְיַסְרוֹ; אֲבָל יִגְזְרוּ עָלָיו נִדּוּי, שֶׁלֹּא יְדַבֵּר עִמָּהּ כְּלָל, וְשֶׁלֹּא יָדוּרוּ בִּשְׁכוּנָה אַחַת. וְאִם הוּא מֻחְזָק בְּעֵינֵיהֶם לְחָשׁוּד עַל הָעֲרָיוֹת, רָאוּי לִגְעֹר בּוֹ בִּנְזִיפָה וּלְאַיֵּם עָלָיו שֶׁאִם לֹא יִתְנַהֵג כַּשּׁוּרָה יַבְדִּילוּהוּ מִבֵּינֵיהֶם לְרָעָה וְיִדְחוּהוּ בִּשְׁתֵּי יָדַיִם, \u0010r25\u0011 כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵנוּ זַ\"ל: מַלְקִין עַל לֹא טוֹבָה הַשְּׁמוּעָה, וּכְמוֹ שֶׁכָּתַב הָרַמְבַּ\"ם \u0010g43\u0011 בְּפֶרֶק כ\"ד מִסַנְהֶדְרִין:\nמִצְוַת חֲכָמִים עַל בְּנֵי יִשְׂרָאֵל \u0010c13\u0011 לְקַנְּאוֹת \u0010t10\u0011 לִנְשׁוֹתֵיהֶם. \u0010r26\u0011 וְכָל מִי שֶׁאֵינוֹ מַקְפִּיד עַל אִשְׁתּוֹ וְעַל בָּנָיו וּבְנֵי בֵּיתוֹ וּמַזְהִירָם וּפוֹקֵד דַּרְכֵיהֶם תָּמִיד עַד שֶׁיֵּדַע שֶׁהֵם שְׁלֵמִים מִכָּל חֵטְא וְעָוֹן, הֲרֵי זֶה חוֹטֵא, שֶׁנֶּאֱמַר: \"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא\" \u0010r27\u0011 \u0005(אִיּוֹב ה, כד)\u0006. וְכָל הַמְקַנֵּא אֶת אִשְׁתּוֹ נִכְנְסָה בּוֹ רוּחַ טָהֳרָה. \u0010g44\u0011 \u0010r28\u0011 וְלֹא יְקַנֵּא לָהּ מִתּוֹךְ שְׂחוֹק, וְלֹא מִתּוֹךְ שִׂיחָה, וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ, \u0010g45\u0011 וְלֹא מִתּוֹךְ מְרִיבָה, וְלֹא לְהָטִיל עָלֶיהָ אֵימָה. \u0010g46\u0011 וְאִם עָבַר וְקִנֵּא לָהּ בִּפְנֵי עֵדִים מִתּוֹךְ אֶחָד מִכָּל הַדְּבָרִים הָאֵלּוּ, \u0010g47\u0011 \u0010r29\u0011 הֲרֵי זֶה קִנּוּי:\nאֵין רָאוּי לִקְפֹּץ וּלְקַנְּאָהּ בִּפְנֵי עֵדִים תְּחִלָּה. \u0010g48\u0011 וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ לָא יֹאמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, \u0010g49\u0011 כְּמוֹ שֶׁנִּתְבָּאֵר. אֶלָּא מוֹכִיחַ אוֹתָהּ \u0010g50\u0011 בֵּינוֹ לְבֵינָהּ, בְּנַחַת \u0010g51\u0011 וּבְדֶרֶךְ טָהֳרָה וְאַזְהָרָה, כְּדֵי לְהָסִיר הַמִּכְשׁוֹל וּלְהַדְרִיכָהּ בְּדֶרֶךְ יְשָׁרָה:",{"g":["משנה ריש סוטה ובזמן שבית המקדש קיים הית' אסורה עד שהביאה אל הכהן והשק' אות' מי המרי' ויבדק הדבר ובזמן חרבן ב\"ה היא אסורה לעולם","משנה שם דכ\"ד ע\"א וכב\"י","שם במשנה ריש סוטה","שם במשנה דכ\"ד ע\"א","כמימר' דרב הונא שם","כמימרא דשמואל שם דכ\"ז ע\"ב ופי' רש\"י שחוף שבשרו נשחף וכלה ויבש ואין בו כח","שם במשנה","שם בגמ' מפרש שזהו ששנינו שם וממי שאינו איש","\u0003משנה שם דכ\"ג ע\"ב וברייתא שם דכ\"ד ע\"א.\u0004 ","רמב\"ם בס\"ב מה' סוטה והחזיק הכ\"מ הראי' שהביא ה\"ה בפ\"ג מאסורי ביא' מההי' דכתובו' איבעי' אימ' באשת ישראל וכו' ד\"ט ע\"א ומ\"ש בנדה דנ\"ב ע\"א והיא לא נפסלה אסור ויש לך וכו' איירי בקטנ' שהי' בת מיאון ולא בקטנה שקדשה אבי' כפירש\"י שם וכן הוכיח התוס' שם וכמו שחילק רבינו בזה וכו'","ראב\"ד בהשגתו שם דפתויי קטנ' אונס היא","משנה ריש סוטה","כר\"ע בברייתא וכדמפרש שם בגמ' דף ד ע\"א","הרמב\"ם שם בפ\"א וכת' הכ\"מ שהוא מהירושלמי ריש סוטה וכר' יוסי וממשנ' דכריתות דף מ ע\"ב","שם ומהירושלמי שם","משנה ריש סוטה","אוקימת' דאביי שם בגמ' ד\"ה ע\"ב","שם","מימרא דר' אליעזר כתובות דף ט' ע\"א","מימרא דרב קדושין ד' פא ע\"א","טור מדברי אביו הרא\"ש בפ\"ב דיבמות מהנהו עובדי דשילהי נדרים","שם בשם סמ\"ג ממימרא דרב חנינא מסורא סוטה ד\"ב ע\"ב","טור והרמב\"ם בפ\"א מעובדא דההוא סמיא קידושין דס\"ו ע\"א","שם ושם וכתב הב\"י ופשט' הוא","שם ושם מעיבד' דההו' סמי'","שם בשם תשו' אביו הרא\"ש כלל ל\"ב סימן יג","משנה סוטה ד' לא ע\"א וכר' יהושע","כן פירש הכ\"מ דלא תקשה דהא בקינוי וסתירה תצא בלא כתוב' כמ\"ש בריש הסימן","מסקנת הגמ' שם ד' כה ע\"א","טור וכ\"כ הרמב\"ם בפ\"א מהירושלמי פ\"א דסוטה וכתבוהו התו' שם די\"ח ע\"ב","שם ושם במשנה רכ\"ד ע\"א","בריית' שם ד' נז ע\"א","משנה שם דל\"א ע\"א","טור והרמב\"ם שם","כ' הכ\"מ שם איני יודע מה מלמדינו דמהיכא תיתי שיגרע מפני שהוא אחד מעידי הסתירה והרב ב\"ח תי' דסד\"א כיון דראה הסתירה קאמר בדדמי דבכה\"ג חששו חכמים ברא' את הטביע' כמ\"ש לעיל בס\"ז וקמ\"ל דהכא לא חיישינן דאמר בדדמי","שם במשנה","שם במשנה ויליף לה שם מקראי","שם במשנה","טור בשסר\"ח ווכ\"פ הרי\"ף בפ\"ב דיבמות ושכן הסכים הרא\"ש כמימר' דשמואל ב\"מ ד' צא ע\"א ובספ\"ק דמכות ד\"ז ע\"א","משנ' סוטה דף כז ע\"ב","ציינתיו לעיל ריש סי' יא","ג\"ז ציינתיו שם סעי' ב'","טור בשם ר\"ח וכ\"כ התו' בשמו בכתובות ד\"ג ע\"ב וכ' הב\"י בשם א\"ח דאין לסמוך על ר\"ח שכל חכמי דורו נחלקו עליו קידושין דפ\"א ע\"א","תשובת הריב\"ש סימן ע\"ט","ל' הרמב\"ם שם ספ\"ג כר\"ע בבריי' סוט' ד\"ג ע\"א דיליף ליה מקר' אפשר דס\"ל דקרא אסמכתא בעלמא כ\"מ","שם מהירושלמי ריש סוטה","כ' הכ\"מ שם מה דאיתא בירושלמי אלא מתוך דבר של אימה משמע לי דרבינו גריס ולא מתיך דבר של אימה והא דקתני ולא מתוך מתון צריך ליגמ' מה הוא עכ\"ל ולענ\"ד הי' רבינו גורס ולא מתוך מדון וזהו מ\"ש ולא מתוך מריב'","שם בירושלמי פשט לה אתי' להדא ב\"מ שנאמר חוק' תורה מעכב לענ\"ד פירושו דפשט לי' ממאי דכתיב ועשה לה הכהן כל התורה הזאת המעשה מעכב ולא סדר הקנאה והכ\"מ פי' בע\"א ע\"ש ואין כאן מקום להאריך","\u0003הרמב\"ם שם וכ' הכ\"מ שלמדו מהא דא\"ר חנינ' מסור' לא לימ' וכו'\u0004 בריש סוט' ע\"ב ואינו נראה לענ\"ד דהא ר' חנינ' לא אמר אלא בזמן הזה ורבינו כ' סתמא אפילו בזמן שהיו מי סוטה למבדק' ונ\"ל שלמדו ממה דמסיק שם ריש ד\"ג אלמ' קסברי אסור לקנאות אע\"ג דאית' שם בבריי' ר\"ע אומר חוב' וקי\"ל הלכ' כר\"ע מחבירו וכמ\"ש בריש סעיף דלעיל הא מסיק שם דיליף לה ר\"ע מקינוי אחרינ' דכתיב בה וא\"כ הקנוי בפעם ראשון אינה חובה ומזה כתב רבינו אין לקפוץ וכו'","בית יוסף ממימרא דרבי חנינא דלעיל","לעיל סעי' ז' ושם ציינתיו","\u0003הרמב\"ם שם:\u0004 "],"t":["\u0003לו. \u0004 ואסור להתייחד עמה. תשובת הרא\"ש ב\"ש:","\u0003כתובתה. \u0004 אבל מה שהכניס' לו נוטלת עם תוספת שליש הנהוג בינינו. כנה\"ג בהגהת ב\"י:","\u0003כהן. \u0004 דס\"ל דפיתוי קטנה הוי כאונס. ואם בא עליה באונס והבועל הוא ישראל והבעל כהן ע\"ל סי' י\"א:","\u0003לזנות. \u0004 עיין בט\"ז י\"ד סי' נ\"ט ס\"ק ט'. ואם זינתה ברצון כדי להציל נפשות כאסתר לאחשורוש אסורה לבעלה עיין ב\"ש וע\"ל סי' ו' מש\"ש בשם שבות יעקב ח\"ב סי' קי\"ז:","\u0003כאחד. \u0004 הרמב\"ם בפ\"א מהלכות סוטה דין ג' ועיין מ\"ש הכ\"מ שם בשם הירושלמי ולכאורה דבריו שם סותרים למ\"ש בהלכות נזירות פרק ט' דין י\"ו ע\"ש ועיין מש\"ש מגדל עוז ודו\"ק:","\u0003קינוי. \u0004 וה\"ה אם קינא לה ע\"פ שליח עיין בספר באר שבע דף נ\"ט ועיין כנה\"ג בהגהות הטור:","\u0003בעיניו. \u0004 כאן לא כתב והיא שותקת משמע אפילו במכחישתו צריך להוציא כיון דהיה קינוי עיין פרישה:","\u0003והסתירה. \u0004 ל\"ד אחר הקינוי והסתירה אלא אפי' לא קדמה הסתירה כל ששמע העם מרננים אחר הקינוי אסורה לו ויוציאנה. כנה\"ג:","\u0003שנטמאה. \u0004 ואם אחר שהעיד ע\"א שנטמאת בא ע\"א ומכחישו לא משגחינן בו דע\"א בסוטה נאמן כתרי עיין ב\"ש:","\u0003בשבילו. \u0004 ואפי' נאסרה מקודם לבעל אפ\"ה נאסרה לבועל והראי' מש\"ס סנהדרין דף מ\"א. שבות יעקב ח\"א סי' צ\"ד וע\"ל סי' י\"א. ועיין כנה\"ג בהגהת הטור סעיף יו\"ד:","\u0003לנשותיהם. \u0004 לאו קינוי ממש קאמר אלא להוכיח אותה ויזהיר אותה שאל \u0005(תסתיר)\u0006 [תסתר] עם אנשים ובזה שפיר דלא תקשה ממ\"ש בסעי' ז' עיין פרישה:"],"r":["\u0003ובלבד כו'. \u0004 כמ\"ש בס\"ו:","\u0003פירוש שאינו מתקשה ואינו מוליד לשון הרמב\"ם כו'\u0004 עפר\"ח בתו' שם ד\"ה שחוף כו':","\u0003בין כו'. \u0004 גמ' משת' כו' דת\"ר כו':","\u0003יש מי כו'. \u0004 ויש מי כו' עמש\"ל סימן ו' סי\"ד:","\u0003גדולה שזינתה כו'. \u0004 כח א' ומה סוטה כו':","\u0003אבל זנתה כו'. \u0004 דלא כתוב ומעלה מעל בה' שתהא מתכוונת למעול במקום אלא למעול מעל באישה וגדולה מזו אמרי' במגלה טו א' עד עכשיו באונס כו' ובאשר כו' אע\"ג דגדולה עבירה לשמה ממצוה שלא לשמה כמ\"ש ביעל בפ\"ד דנזיר כג ב':","\u0003י\"א דנאמנת כולי. \u0004 כמ\"ש בכתובות ט\"ז א':","\u0003וי\"א כו'. \u0004 דכיון שהי' נתייחדה מרצונה אין לה טענת אונס כמש\"ש נ\"א ב' ודאי שבקינהו כו' ואע\"ג דליכא עדים לפנינו על הייחוד נמתין אם ימצא עדים כמ\"ש בקידושין י\"ב ב' האיכא סהדי כולי וכן בב\"ב קל\"ה א' וע\"כ באין ידוע שיש עדים דבידוע ל\"ל עדים בצד כולי ובירושלמי פ\"ב דקידושין ההיא איתתא דאתיא לקמיה דר' יוחנן אמרה א\"א הייתי וגרושה אני ומתירא מן דנפקח א\"ל ר' עדיה בלוד א\"ל כן אני אומר אפילו עדים בקוסטטין ימתין וראבי\"ה סתר דבריו דהא אמרינן בפ' בתרא קידושין דאין אוסרין על הייחוד ופ\"ק דכתובות אין האשה נאסרת כו' ומ\"ש גם כן נמתין על העדים מהנ\"ל ע\"תוס שם ושם שפי' שיצא קול שיש עדים אבל בלא\"ה לא וע' מרדכי שם וטס\"ז:","\u0003שנסתרה בפני עדים. \u0004 כר' יהושע במתניתין ריש סוטה:","\u0003קינא כו'. \u0004 ירושלמי פ\"א הלכה ב' מהו שיקנא לה מב' ב\"א כאחת רבי יודן אמר במחלוקת מ\"ד מקנא לה מאביה ומבנה מקנא לה מב' ב\"א כאחת ר' יוסי בעי מקנא לה ממאה ב\"א ר\"ל בעי מקני לשון רצון ופ' כר' יוסי ועוד דקי\"ל דמקנא מאבי' כנ\"ל ס\"ב ומ\"ש בכ\"מ מהא דכריתות כבר סתר במל\"מ דהתם בשנסתרה עם ב\"א לבד:","\u0003אפילו נסתרו כו'. \u0004 עמש\"ל סי' ז' סי\"א בג\"ה","\u0003ועכשיו כו'. \u0004 סיום גמרא הנ\"ל:","\u0003ואם הוא בעצמו כו'. \u0004 כ\"ש מע\"א שאין ברור מראיית עצמו ובשניהם יתן כתובה דלא קי\"ל כר\"א ריש סוטה דמשקה ע\"פ ע\"א או ע\"פ עצמו א\"כ אין לה כתובה אלא כר\"י כנ\"ל ס\"ד:","\u0003וי\"א כו' \u0004 וה\"ה כו' תוספת סוף נדרים במ\"ש במתני' גבי אשה האומרת טמאה כו' וה\"ה בזה\"ז באיש:","\u0003וי\"א דכופין כו'. \u0004 ממ\"ש תביא ראיה לדבריה אלמא דכופין אותה ומשמשתו וה\"ה עכשיו באיש:","\u0003וחזרה בה כו'. \u0004 ערא\"ש פ\"ב דיבמות ס\"ח ואל תתמה כו' מיהו אפשר כו':","\u0003ואם היה כו'. \u0004 כמ\"ש בפ' בתרא דיבמות:","\u0003מי שהוציא כו'. \u0004 כמ\"ש בפ\"ב דכתובות כ\"ב א\"ב:","\u0003אחר הקינוי והסתירה. \u0004 ירושלמי שם ר' יוחנן בשם ר' ינאי כל ההן פרקין כולי משקינא לה ונסתרה:","\u0003בלא שני כו'. \u0004 שם תו' סד\"ה מי מיהו כולי וכ\"כ רש\"י שם:","\u0003או היה במדינה אחרת. \u0004 כ\"ז א':","\u0003י\"א כו'. \u0004 דבלא\"ה אסירא וכמ\"ש כ\"ו ב' מ\"א נטמאה כולי קמ\"ל ר\"ל דמ\"מ נאסרת לבעל: ע' תוספת דכתובות ג' ב' ד\"ה ולדרוש כולי והרא\"ש שם כ' ונ\"ל לקיים פסק ר\"ת ולא מטעמיה דלא אמרינן דאסורה לבועל אלא היכא דלא היתה אסורה בלא\"ה כו' וז\"ש בהג\"ה ומ\"מ כו' דל\"ת דכאן נמי שייך טעם של הרא\"ש דגוי אינו בתורת קידושין לגמרי משא\"כ בעריות די\"ל קידושין במקום אחר. פירש מהרא\"י ועוד כ' שם לחלק דגבי אחות אשה שייך נאסרה לבועל באם תמות אשתו משא\"כ בגוי דכשמתגייר גוף אחר הוא דגר שנתגייר כו'. ומרד' פ' ד' מיתות כ' אכן ר' יחיאל עשה מעשה כר\"ת ולא מטעמיה כו' אלא משום דגר שנתגייר כקטן שנולד וההיא שעתא לאו אסורה היא ובזה אתי שפיר כ\"ז:","\u0003ומ\"מ כו'. \u0004 דלא שייך אסורה וקיימא דהא לאחר מיתה מותרת משא\"כ בנכרי דכשנתגייר כקטן שנולד דמי ומ\"ל מיתה ומ\"ל גירושין באשת איש דלא ניתוסף בבועל איסור אלא לאחר גירושין:","\u0003אשת איש כו'. \u0004 כמ\"ש בפ' הנשבעין ע\"א בהכחשה לאו כלום וכן כשהבע\"ד מכחישו כמ\"ש בפ\"ב דקידושין ובר\"פ האשה רבה:","\u0003אבל יגזרו כו'. \u0004 כמ\"ש בפ\"ה דיבמות ובפ\"ק דקידושין והא ההיא דהוה חליף כו' מידם כו' וכמ\"ש הרמב\"ם:","\u0003כמו שאמרו חז\"ל. \u0004 בסוף קידושין:","\u0003וכל מי כו'. \u0004 גיטין צ' א' תניא היה רמ\"א כו' וביבמות ס\"ג ב' וסנהדרין ע\"ו ב' והמדריך כו':","\u0003וכל המקנא כו' \u0004 סוטה ג' א':","\u0003ולא יקנא כו' \u0004 ואם כו'. ירושלמי ריש סוטה והביאו תוס' שם ב' ב' ד\"ה מ\"ט עוד בירושל' ומ\"ש ולא מתוך גיאות אלא כו' גי' הרמב\"ם ולא מתוך מדון כו' וגירסתינו הוא מתון וט\"ס ה\"א:","\u0003ה\"ז קינוי. \u0004 דבירושלמי מסיים שם א\"ר מנא כו' תורה מעכב הקינוי דא\"א חובה רי\"א רשות אתא דר\"א כב\"ש ור\"י כב\"ה דתנא בש\"א לא יגרש אדם כו' ועתוס' ג' א' ד\"ה רי\"א כו' אבל קשיא מירושלמי כו' והא צ\"ע כו'. אבל להרמב\"ם דר\"ע ג\"כ ס\"ל דאינו חובה אלא מצוה וז\"ש למעלה מצות חכמים כו' ומפ' דסגנון הירושלמי כך הוא א\"ר מנא כו' הקינוי רא\"א כולי ר\"ל דתליא בפלוגתא דלר' יהושע ע\"כ לא ס\"ל כר' מנא ואנן קי\"ל כר\"י וכב\"ה וכן ר' ישמעאל ור\"מ תרווייהו ס\"ל דאינו חובה:"]}]]};
